local VisualsTab = Window:AddTab({ Title = "Visuals", Icon = "visibility" })

-- Ambience ----------------------------------------------------------------

local Ambience = VisualsTab:AddSection("Ambience")
local ambience = {
	Enabled = false,
	Ambient = Color3.fromRGB(140, 140, 160),
	OutdoorAmbient = Color3.fromRGB(140, 140, 160),
	Brightness = 2,
	ClockTime = 14,
	Exposure = 0,
	Shadows = true,
}
local restoreLighting = nil
local applyingAmbience = false

local function setIfChanged(instance, property, value)
	if instance[property] ~= value then
		instance[property] = value
	end
end

local function applyAmbience()
	if not ambience.Enabled or applyingAmbience then
		return
	end
	applyingAmbience = true
	setIfChanged(Lighting, "Ambient", ambience.Ambient)
	setIfChanged(Lighting, "OutdoorAmbient", ambience.OutdoorAmbient)
	setIfChanged(Lighting, "Brightness", ambience.Brightness)
	setIfChanged(Lighting, "ClockTime", ambience.ClockTime)
	setIfChanged(Lighting, "ExposureCompensation", ambience.Exposure)
	setIfChanged(Lighting, "GlobalShadows", ambience.Shadows)
	applyingAmbience = false
end

Ambience:AddToggle({
	Title = "Custom ambience",
	Description = "Override the map's lighting",
	Default = false,
	Flag = "Ambience",
	Callback = function(on)
		ambience.Enabled = on
		if on then
			restoreLighting = restoreLighting or snapshot(Lighting, {
				"Ambient", "OutdoorAmbient", "Brightness", "ClockTime", "ExposureCompensation", "GlobalShadows",
			})
			applyAmbience()
		elseif restoreLighting then
			restoreLighting()
			restoreLighting = nil
		end
	end,
})
Ambience:AddColorPicker({
	Title = "Ambient",
	Default = ambience.Ambient,
	Flag = "AmbientColor",
	Callback = function(color)
		ambience.Ambient = color
		applyAmbience()
	end,
})
Ambience:AddColorPicker({
	Title = "Outdoor ambient",
	Default = ambience.OutdoorAmbient,
	Flag = "OutdoorAmbientColor",
	Callback = function(color)
		ambience.OutdoorAmbient = color
		applyAmbience()
	end,
})
Ambience:AddSlider({
	Title = "Brightness",
	Min = 0, Max = 10, Step = 0.1, Default = ambience.Brightness,
	Flag = "Brightness",
	Callback = function(value)
		ambience.Brightness = value
		applyAmbience()
	end,
})
Ambience:AddSlider({
	Title = "Clock time",
	Min = 0, Max = 24, Step = 0.25, Default = ambience.ClockTime,
	Flag = "ClockTime",
	Callback = function(value)
		ambience.ClockTime = value
		applyAmbience()
	end,
})
Ambience:AddSlider({
	Title = "Exposure compensation",
	Min = -3, Max = 3, Step = 0.05, Default = ambience.Exposure,
	Flag = "Exposure",
	Callback = function(value)
		ambience.Exposure = value
		applyAmbience()
	end,
})
Ambience:AddToggle({
	Title = "Global shadows",
	Default = true,
	Flag = "GlobalShadows",
	Callback = function(on)
		ambience.Shadows = on
		applyAmbience()
	end,
})

-- The map can reset lighting (round changes); re-apply when it does.
for _, property in { "Ambient", "OutdoorAmbient", "Brightness", "ClockTime", "ExposureCompensation", "GlobalShadows" } do
	track(Lighting:GetPropertyChangedSignal(property):Connect(function()
		if ambience.Enabled then
			task.defer(applyAmbience)
		end
	end))
end

-- Post-processing effects ------------------------------------------------
-- Each effect is our own instance in Lighting, destroyed when turned off.

local function effectSection(title, className, settings)
	local section = VisualsTab:AddSection(title)
	local state = { Enabled = false, Values = {} }
	local effect = nil

	local function apply()
		if not effect then
			return
		end
		for property, value in state.Values do
			pcall(function()
				effect[property] = value
			end)
		end
	end

	section:AddToggle({
		Title = "Enabled",
		Default = false,
		Flag = title .. "Enabled",
		Callback = function(on)
			state.Enabled = on
			if on and not effect then
				effect = Instance.new(className)
				effect.Name = PREFIX .. className
				apply()
				effect.Parent = Lighting
			elseif not on and effect then
				effect:Destroy()
				effect = nil
			end
		end,
	})

	for _, setting in settings do
		state.Values[setting.Property] = setting.Default
		local props = {
			Title = setting.Title,
			Default = setting.Default,
			Flag = title .. setting.Property,
			Callback = function(value)
				state.Values[setting.Property] = value
				apply()
			end,
		}
		if typeof(setting.Default) == "Color3" then
			section:AddColorPicker(props)
		else
			props.Min, props.Max, props.Step = setting.Min, setting.Max, setting.Step
			section:AddSlider(props)
		end
	end

	track(function()
		if effect then
			effect:Destroy()
		end
	end)
end

