-- Own scope: the main chunk is close to Luau's 200-local limit.
do
	-- Fog & atmosphere --------------------------------------------------------
	-- One place for the map's fog and its Atmosphere, so the two can't fight:
	--   Game    leaves both alone (and puts back anything changed here)
	--   No fog  clears Lighting fog and the Atmosphere's density / haze / glare
	--   Custom  drives the map's Atmosphere with the settings below (or one of
	--           ours when the map has none)

	local FogSection = VisualsTab:AddSection("Fog & Atmosphere")
	local ATMOSPHERE_PROPERTIES = { "Density", "Offset", "Haze", "Glare", "Color", "Decay" }
	local atmosphereState = {
		Mode = "Game",
		Density = 0.35,
		Offset = 0.25,
		Haze = 2,
		Glare = 0.6,
		Color = Color3.fromRGB(140, 160, 190),
		Decay = Color3.fromRGB(90, 110, 140),
	}
	local atmosphereRestores = setmetatable({}, { __mode = "k" }) -- instance -> restore function
	local ourAtmosphere = nil
	local applyingAtmosphere = false

	local function remember(instance, properties)
		if not atmosphereRestores[instance] then
			atmosphereRestores[instance] = snapshot(instance, properties)
		end
	end

	local function mapAtmosphere()
		for _, child in Lighting:GetChildren() do
			if child:IsA("Atmosphere") and child ~= ourAtmosphere then
				return child
			end
		end
		return nil
	end

	local function restoreAtmosphere()
		for _, restore in atmosphereRestores do
			restore()
		end
		table.clear(atmosphereRestores)
		if ourAtmosphere then
			ourAtmosphere:Destroy()
			ourAtmosphere = nil
		end
	end

	local function applyAtmosphere()
		local mode = atmosphereState.Mode
		if mode == "Game" or applyingAtmosphere then
			return
		end
		applyingAtmosphere = true
		local atmosphere = mapAtmosphere()
		if atmosphere then
			remember(atmosphere, ATMOSPHERE_PROPERTIES)
		elseif mode == "Custom" then
			if not ourAtmosphere then
				ourAtmosphere = own(Instance.new("Atmosphere"))
				ourAtmosphere.Name = PREFIX .. "Atmosphere"
				ourAtmosphere.Parent = Lighting
			end
			atmosphere = ourAtmosphere
		end
		if ourAtmosphere and ourAtmosphere ~= atmosphere then
			ourAtmosphere:Destroy()
			ourAtmosphere = nil
		end
		pcall(function()
			if mode == "No fog" then
				remember(Lighting, { "FogStart", "FogEnd" })
				setIfChanged(Lighting, "FogStart", 0)
				setIfChanged(Lighting, "FogEnd", 1e6)
				if atmosphere then
					setIfChanged(atmosphere, "Density", 0)
					setIfChanged(atmosphere, "Haze", 0)
					setIfChanged(atmosphere, "Glare", 0)
				end
			elseif atmosphere then
				for _, property in ATMOSPHERE_PROPERTIES do
					setIfChanged(atmosphere, property, atmosphereState[property])
				end
			end
		end)
		applyingAtmosphere = false
	end

	local function setAtmosphereMode(mode)
		restoreAtmosphere()
		atmosphereState.Mode = mode
		applyAtmosphere()
	end

	local function atmosphereSetting(key)
		return function(value)
			atmosphereState[key] = value
			applyAtmosphere()
		end
	end

	FogSection:AddDropdown({
		Title = "Mode",
		Options = { "Game", "No fog", "Custom" },
		Default = atmosphereState.Mode,
		Flag = "AtmosphereMode",
		Callback = setAtmosphereMode,
	})
	FogSection:AddSlider({ Title = "Density", Min = 0, Max = 1, Step = 0.01, Default = atmosphereState.Density, Flag = "AtmosphereDensity", Callback = atmosphereSetting("Density") })
	FogSection:AddSlider({ Title = "Offset", Min = 0, Max = 1, Step = 0.01, Default = atmosphereState.Offset, Flag = "AtmosphereOffset", Callback = atmosphereSetting("Offset") })
	FogSection:AddSlider({ Title = "Haze", Min = 0, Max = 10, Step = 0.05, Default = atmosphereState.Haze, Flag = "AtmosphereHaze", Callback = atmosphereSetting("Haze") })
	FogSection:AddSlider({ Title = "Glare", Min = 0, Max = 10, Step = 0.05, Default = atmosphereState.Glare, Flag = "AtmosphereGlare", Callback = atmosphereSetting("Glare") })
	FogSection:AddColorPicker({ Title = "Color", Default = atmosphereState.Color, Flag = "AtmosphereColor", Callback = atmosphereSetting("Color") })
	FogSection:AddColorPicker({ Title = "Decay", Default = atmosphereState.Decay, Flag = "AtmosphereDecay", Callback = atmosphereSetting("Decay") })

	-- Round changes can swap the map's Atmosphere or reset fog; re-apply.
	track(Lighting.ChildAdded:Connect(function(child)
		if child:IsA("Atmosphere") and child ~= ourAtmosphere then
			task.defer(applyAtmosphere)
		end
	end))
	for _, property in { "FogStart", "FogEnd" } do
		track(Lighting:GetPropertyChangedSignal(property):Connect(function()
			task.defer(applyAtmosphere)
		end))
	end
	local lastAtmosphereCheck = 0
	track(RunService.Heartbeat:Connect(function()
		local now = os.clock()
		if atmosphereState.Mode ~= "Game" and now - lastAtmosphereCheck >= 0.5 then
			lastAtmosphereCheck = now
			applyAtmosphere()
		end
	end))
	track(restoreAtmosphere)

	-- Shaders -------------------------------------------------------------------
	-- A cinematic preset built on the sections above: turning it on sets
	-- Ambience, Bloom, Color Grading, Depth Of Field, Sun Rays and Fog &
	-- Atmosphere to preset values (tweak them afterwards as usual), plus a few
	-- Lighting properties those sections don't cover. Turning it off puts every
	-- one of those controls back where it was.

	local ShaderSection = VisualsTab:AddSection("Shaders")
	local SHADER_PRESET = { -- { flag, value }, applied in order, undone in reverse
		{ "AmbientColor", Color3.fromRGB(20, 23, 35) },
		{ "OutdoorAmbientColor", Color3.fromRGB(88, 108, 140) },
		{ "Brightness", 2.1 },
		{ "ClockTime", function() return Lighting.ClockTime end },
		{ "Exposure", 0.2 },
		{ "GlobalShadows", true },
		{ "Ambience", true },
		{ "BloomIntensity", 0.15 },
		{ "BloomSize", 16 },
		{ "BloomThreshold", 1.85 },
		{ "BloomEnabled", true },
		{ "Color GradingBrightness", 0.02 },
		{ "Color GradingContrast", 0.2 },
		{ "Color GradingSaturation", 0.22 },
		{ "Color GradingTintColor", Color3.fromRGB(255, 249, 238) },
		{ "Color GradingEnabled", true },
		{ "Depth Of FieldFarIntensity", 0.05 },
		{ "Depth Of FieldNearIntensity", 0 },
		{ "Depth Of FieldFocusDistance", 80 },
		{ "Depth Of FieldInFocusRadius", 58 },
		{ "Depth Of FieldEnabled", true },
		{ "Sun RaysIntensity", 0.08 },
		{ "Sun RaysSpread", 0.9 },
		{ "Sun RaysEnabled", true },
		{ "AtmosphereDensity", 0.3 },
		{ "AtmosphereOffset", 0.07 },
		{ "AtmosphereHaze", 0.8 },
		{ "AtmosphereGlare", 0.15 },
		{ "AtmosphereColor", Color3.fromRGB(175, 195, 225) },
		{ "AtmosphereDecay", Color3.fromRGB(85, 125, 195) },
		{ "AtmosphereMode", "Custom" },
	}
	local SHADER_LIGHTING = {
		ShadowSoftness = 0.2,
		EnvironmentDiffuseScale = 0.95,
		EnvironmentSpecularScale = 0.98,
		ColorShift_Top = Color3.fromRGB(12, 16, 32),
		ColorShift_Bottom = Color3.fromRGB(6, 10, 25),
		Technology = Enum.Technology.Future,
	}
	local SHADER_SKY = { SunAngularSize = 7.8, MoonAngularSize = 9 }
	local shaderControls = nil -- { element, previous value } while the preset is on
	local restoreShaderExtras = nil

	local function setShaderExtras(on)
		if on and not restoreShaderExtras then
			local lightingProperties, skyProperties = {}, {}
			for property in SHADER_LIGHTING do
				table.insert(lightingProperties, property)
			end
			for property in SHADER_SKY do
				table.insert(skyProperties, property)
			end
			local restoreLightingExtras = snapshot(Lighting, lightingProperties)
			local sky = Lighting:FindFirstChildOfClass("Sky")
			local restoreSky = sky and snapshot(sky, skyProperties)
			restoreShaderExtras = function()
				restoreLightingExtras()
				if restoreSky then
					restoreSky()
				end
			end
			for property, value in SHADER_LIGHTING do
				pcall(function()
					Lighting[property] = value
				end)
			end
			if sky then
				for property, value in SHADER_SKY do
					pcall(function()
						sky[property] = value
					end)
				end
			end
		elseif not on and restoreShaderExtras then
			restoreShaderExtras()
			restoreShaderExtras = nil
		end
	end

	local function setShaders(on)
		if on and not shaderControls then
			shaderControls = {}
			for _, entry in SHADER_PRESET do
				local element = Window.Flags[entry[1]]
				if element then
					table.insert(shaderControls, { element, element.Value })
					local value = entry[2]
					if type(value) == "function" then
						value = value()
					end
					element:Set(value)
				end
			end
			setShaderExtras(true)
		elseif not on and shaderControls then
			local controls = shaderControls
			shaderControls = nil
			for index = #controls, 1, -1 do
				controls[index][1]:Set(controls[index][2])
			end
			setShaderExtras(false)
		end
	end

	local shadersToggle = ShaderSection:AddToggle({
		Title = "Shaders",
		Description = "Cinematic preset for the lighting sections above; off puts them back",
		Default = false,
		Flag = "Shaders",
		Callback = setShaders,
	})
	MD3.GearUI.press(ShaderSection, shadersToggle, { KeyTitle = "Toggle shaders", KeyFlag = "ShadersKey", ModeFlag = "ShadersMode" })
	-- On unload each section restores itself; only the extra Lighting
	-- properties are the preset's own.
	track(function()
		setShaderExtras(false)
	end)
end

-- Weather -------------------------------------------------------------------
-- A local-only emitter part that follows the camera. Never collides, never
-- blocks raycasts, and isn't replicated to anyone else.

-- Weather & skybox: scoped in a do-block so its locals stay under Luau's 200-register limit.
do
	local WeatherSection = VisualsTab:AddSection("Weather")
	local SPARKLE_TEXTURE = "rbxasset://textures/particles/sparkles_main.dds"
	local WEATHER_PRESETS = {
		Rain = { Rate = 700, Speed = 70, Size = 0.12, Squash = 3, Orientation = Enum.ParticleOrientation.VelocityParallel },
		["Light rain"] = { Rate = 500, Speed = 40, Size = 0.2, Squash = 0, Orientation = Enum.ParticleOrientation.FacingCameraWorldUp },
		Snow = { Rate = 250, Speed = 8, Size = 0.35, Squash = 0, Orientation = Enum.ParticleOrientation.FacingCamera, Drift = true },
		Stars = { Rate = 250, Speed = 8, Size = 0.35, Squash = 0, Orientation = Enum.ParticleOrientation.FacingCamera, Drift = true, Texture = "rbxassetid://6822501679" },
		Hearts = { Rate = 250, Speed = 8, Size = 0.35, Squash = 0, Orientation = Enum.ParticleOrientation.FacingCamera, Drift = true, Texture = "rbxassetid://36721240" },
	}
	local weather = {
		Enabled = false,
		Type = "Rain",
		Color = Color3.fromRGB(190, 210, 255),
		Rate = 1,
		Speed = 1,
		Size = 1,
		Glow = 0.3,
		Spread = 1,
		Height = 40,
		WindStrength = 0,
		WindAngle = 0,
	}
	local weatherPart, weatherEmitter = nil, nil

	local function applyWeather()
		if not weatherEmitter then
			return
		end
		local preset = WEATHER_PRESETS[weather.Type] or WEATHER_PRESETS.Rain
		local speed = preset.Speed * weather.Speed
		local size = preset.Size * weather.Size
		local windAngle = math.rad(weather.WindAngle)

		weatherPart.Size = Vector3.new(90 * weather.Spread, 1, 90 * weather.Spread)
		weatherEmitter.Texture = preset.Texture or SPARKLE_TEXTURE
		weatherEmitter.Color = ColorSequence.new(weather.Color)
		weatherEmitter.Rate = preset.Rate * weather.Rate
		weatherEmitter.Speed = NumberRange.new(speed * 0.9, speed * 1.1)
		weatherEmitter.Size = NumberSequence.new(size)
		weatherEmitter.Squash = NumberSequence.new(preset.Squash)
		weatherEmitter.Orientation = preset.Orientation
		weatherEmitter.LightEmission = weather.Glow
		weatherEmitter.Lifetime = NumberRange.new((weather.Height * 1.6) / math.max(speed, 1))
		weatherEmitter.Acceleration = Vector3.new(math.cos(windAngle), 0, math.sin(windAngle)) * weather.WindStrength
		weatherEmitter.RotSpeed = preset.Drift and NumberRange.new(-90, 90) or NumberRange.new(0)
		weatherEmitter.SpreadAngle = preset.Drift and Vector2.new(15, 15) or Vector2.new(0, 0)
	end

	local function setWeather(on)
		weather.Enabled = on
		if on and not weatherPart then
			weatherPart = own(Instance.new("Part"))
			weatherPart.Name = MD3.Env.RandomName()
			weatherPart.Anchored = true
			weatherPart.CanCollide = false
			weatherPart.CanQuery = false
			weatherPart.CanTouch = false
			weatherPart.CastShadow = false
			weatherPart.Transparency = 1

			weatherEmitter = Instance.new("ParticleEmitter")
			weatherEmitter.EmissionDirection = Enum.NormalId.Bottom
			weatherEmitter.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(0.1, 0.2),
				NumberSequenceKeypoint.new(0.85, 0.2),
				NumberSequenceKeypoint.new(1, 1),
			})
			weatherEmitter.Parent = weatherPart
			applyWeather()
			weatherPart.Parent = camera()
		elseif not on and weatherPart then
			weatherPart:Destroy()
			weatherPart, weatherEmitter = nil, nil
		end
	end

	local function weatherSetting(key)
		return function(value)
			weather[key] = value
			applyWeather()
		end
	end

	WeatherSection:AddToggle({ Title = "Enabled", Description = "Only you can see it", Default = false, Flag = "Weather", Callback = setWeather })
	WeatherSection:AddDropdown({ Title = "Type", Options = { "Rain", "Light rain", "Snow", "Stars", "Hearts" }, Default = weather.Type, Flag = "WeatherType", Callback = weatherSetting("Type") })
	WeatherSection:AddColorPicker({ Title = "Color", Default = weather.Color, Flag = "WeatherColor", Callback = weatherSetting("Color") })
	WeatherSection:AddSlider({ Title = "Rate", Min = 0, Max = 3, Step = 0.05, Default = weather.Rate, Suffix = "x", Flag = "WeatherRate", Callback = weatherSetting("Rate") })
	WeatherSection:AddSlider({ Title = "Speed", Min = 0.5, Max = 3, Step = 0.05, Default = weather.Speed, Suffix = "x", Flag = "WeatherSpeed", Callback = weatherSetting("Speed") })
	WeatherSection:AddSlider({ Title = "Size", Min = 0.5, Max = 2, Step = 0.05, Default = weather.Size, Suffix = "x", Flag = "WeatherSize", Callback = weatherSetting("Size") })
	WeatherSection:AddSlider({ Title = "Glow", Min = 0, Max = 1, Step = 0.01, Default = weather.Glow, Flag = "WeatherGlow", Callback = weatherSetting("Glow") })
	WeatherSection:AddSlider({ Title = "Spread", Min = 0.25, Max = 3, Step = 0.05, Default = weather.Spread, Suffix = "x", Flag = "WeatherSpread", Callback = weatherSetting("Spread") })
	WeatherSection:AddSlider({ Title = "Height", Min = 10, Max = 100, Step = 1, Default = weather.Height, Suffix = " studs", Flag = "WeatherHeight", Callback = weatherSetting("Height") })
	WeatherSection:AddSlider({ Title = "Wind strength", Min = 0, Max = 20, Step = 0.1, Default = weather.WindStrength, Flag = "WeatherWind", Callback = weatherSetting("WindStrength") })
	WeatherSection:AddSlider({ Title = "Wind angle", Min = 0, Max = 360, Step = 1, Default = weather.WindAngle, Suffix = "°", Flag = "WeatherWindAngle", Callback = weatherSetting("WindAngle") })

	track(RunService.RenderStepped:Connect(function()
		if not weatherPart then
			return
		end
		local cam = camera()
		if not cam then
			return
		end
		if weatherPart.Parent ~= cam then
			weatherPart.Parent = cam
		end
		weatherPart.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, weather.Height, 0))
	end))
	track(function()
		setWeather(false)
	end)

	-- Skybox --------------------------------------------------------------------

	local SkySection = VisualsTab:AddSection("Skybox")
	local SKY_FACES = {
		{ Title = "Front", Property = "SkyboxFt" },
		{ Title = "Back", Property = "SkyboxBk" },
		{ Title = "Left", Property = "SkyboxLf" },
		{ Title = "Right", Property = "SkyboxRt" },
		{ Title = "Up", Property = "SkyboxUp" },
		{ Title = "Down", Property = "SkyboxDn" },
	}
	local sky = { Enabled = false, Preset = "Custom", All = "", Faces = {}, Celestial = true, Stars = 3000 }
	local customSky = nil
	local hiddenSkies = {}

	-- Bk, Dn, Ft, Lf, Rt, Up
	local SKY_PRESETS = {
		["Among Us"] = { 5752463190, 5752463190, 5752463190, 5752463190, 5752463190, 5752463190 },
		Aurora = { 340908398, 340908450, 340908468, 340908504, 340908530, 340908586 },
		["Blue Aurora"] = { 12063984, 12064107, 12064152, 12064121, 12064115, 12064131 },
		["Blue Stars"] = { 149397684, 149397686, 149397688, 149397692, 149397697, 149397702 },
		Chill = { 5084575798, 5084575916, 5103949679, 5103948542, 5103948784, 5084576400 },
		Clouds = { 570557514, 570557775, 570557559, 570557620, 570557672, 570557727 },
		DaBaby = { 7245418472, 7245418472, 7245418472, 7245418472, 7245418472, 7245418472 },
		Default = { 91458024, 91457980, 91458024, 91458024, 91458024, 91458002 },
		Gloomy = { 5346760450, 5346760689, 5346760919, 5346761102, 5346761335, 5346761509 },
		Jungle = { 214399891, 214399887, 214399894, 214405668, 214399899, 214399889 },
		Minecraft = { 1876545003, 1876544331, 1876542941, 1876543392, 1876543764, 1876544642 },
		["Mountain Scape"] = { 12474836637, 12474837052, 12474836748, 12474836935, 12474836446, 12474835757 },
		Nebula = { 159454299, 159454296, 159454293, 159454286, 159454300, 159454288 },
		["Nebula Purple"] = { 129876530632297, 108406529909981, 104400530594543, 73372229972523, 87408857415924, 13781740568136 },
		Neptune = { 218955819, 218953419, 218954524, 218958493, 218957134, 218950090 },
		Realistic = { 144933338, 144931530, 144933262, 144933244, 144933299, 144931564 },
		Redshift = { 401664839, 401664862, 401664960, 401664881, 401664901, 401664936 },
		Spongebob = { 15962101128, 15970246218, 15962101128, 15962101128, 15962101128, 15962901054 },
		["Stars Shader"] = { 169210090, 169210108, 169210121, 169210133, 169210143, 169210149 },
		Stormy = { 255027929, 255027967, 255027923, 255027938, 255027946, 255027960 },
		Twilight = { 264908339, 264907909, 264909420, 264909758, 264908886, 264907379 },
		Vaporwave = { 1417494030, 1417494146, 1417494253, 1417494402, 1417494499, 1417494643 },
		["Winter Mountain"] = { 402229526, 402229596, 402229293, 402229368, 402229417, 402229564 },
		["Yellowy Cloud"] = { 252760981, 252763035, 252761439, 252760980, 252760986, 252762652 },
	}
	local SKY_PRESET_FACES = { "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" }
	local SKY_PRESET_NAMES = { "Custom", "Nazuna" } -- Nazuna: downloaded from engnyg/123f1 on first use
	for name in SKY_PRESETS do
		table.insert(SKY_PRESET_NAMES, name)
	end
	table.sort(SKY_PRESET_NAMES, function(a, b)
		return a == "Custom" or (b ~= "Custom" and a < b)
	end)

	-- Accepts an asset id, rbxassetid://, or an image URL (downloaded via MD3.Assets).
	local function resolveSkyImage(source)
		source = tostring(source or ""):gsub("^%s+", ""):gsub("%s+$", "")
		if source == "" then
			return nil
		end
		local asset = MD3.Assets.Resolve(source)
		return asset ~= "" and asset or nil
	end

	-- The Nazuna faces (engnyg/123f1, skybox/Nazuna) are downloaded once through MD3.Assets, which
	-- keeps them in the workspace; later uses (and later sessions) reuse the files.
	local NAZUNA_URL = "https://raw.githubusercontent.com/engnyg/123f1/main/skybox/Nazuna/sky512_%s.png"
	local nazunaAssets, nazunaLoading = nil, false
	local function nazunaFaces()
		if nazunaAssets then
			return nazunaAssets
		end
		local assets = {}
		for _, key in { "Bk", "Dn", "Ft", "Lf", "Rt", "Up" } do
			local lower = string.lower(key)
			local asset = MD3.Assets.FromUrl(string.format(NAZUNA_URL, lower), "Nazuna_" .. lower .. ".jpg")
			if not asset then
				return nil
			end
			assets[key] = asset
		end
		nazunaAssets = assets
		return assets
	end

	local function applySky()
		if not customSky then
			return
		end
		local preset = SKY_PRESETS[sky.Preset]
		if sky.Preset == "Nazuna" then
			if nazunaAssets then
				for _, property in SKY_PRESET_FACES do
					customSky[property] = nazunaAssets[string.sub(property, 7)]
				end
			elseif not nazunaLoading then
				-- six downloads: do them off the caller, then apply
				nazunaLoading = true
				task.spawn(function()
					local faces = nazunaFaces()
					nazunaLoading = false
					if faces then
						applySky()
					else
						Window:Notify({ Title = "Skybox", Content = "Could not download the Nazuna sky (needs HTTP, writefile and getcustomasset)", Icon = "error" })
					end
				end)
			end
		elseif preset then
			for index, property in SKY_PRESET_FACES do
				customSky[property] = "rbxassetid://" .. preset[index]
			end
		else
			local all = resolveSkyImage(sky.All)
			for _, face in SKY_FACES do
				local image = resolveSkyImage(sky.Faces[face.Property]) or all
				if image then
					customSky[face.Property] = image
				end
			end
		end
		customSky.CelestialBodiesShown = sky.Celestial
		customSky.StarCount = sky.Stars
	end

	-- Keeps the custom sky in place while it is on. A new map (leaving the practice range, joining
	-- a match) clears Lighting or adds its own Sky, and the custom one was gone / overridden. Only
	-- one Sky may be active: the map's own ones are parked, ours is recreated when it vanished.
	--
	-- If something keeps putting its Sky back, parking it again would loop forever (and error
	-- with "re-entrancy depth exceeded"): at most 12 parkings per 10 seconds, then we leave it.
	local parked, parkSince = 0, 0
	local function keepSky()
		if not sky.Enabled then
			return
		end
		local missing = customSky == nil or customSky.Parent ~= Lighting
		for _, child in Lighting:GetChildren() do
			if child:IsA("Sky") and child ~= customSky then
				if os.clock() - parkSince > 10 then
					parked, parkSince = 0, os.clock()
				end
				if parked < 12 then
					parked += 1
					table.insert(hiddenSkies, child)
					if #hiddenSkies > 8 then
						table.remove(hiddenSkies, 1)
					end
					child.Parent = nil
				end
			end
		end
		if missing then
			if customSky then
				pcall(function()
					customSky:Destroy()
				end)
			end
			customSky = Instance.new("Sky")
			customSky.Name = PREFIX .. "Sky"
			applySky()
			customSky.Parent = Lighting
		end
	end

	local function setSky(on)
		sky.Enabled = on
		if on then
			keepSky()
		elseif customSky then
			customSky:Destroy()
			customSky = nil
			for _, original in hiddenSkies do
				pcall(function()
					original.Parent = Lighting
				end)
			end
			table.clear(hiddenSkies)
		end
	end

	-- one keepSky at a time, at most every 0.25 s (task.defer chains would stack up)
	local skyScheduled = false
	local function scheduleKeepSky()
		if skyScheduled then
			return
		end
		skyScheduled = true
		task.delay(0.25, function()
			skyScheduled = false
			keepSky()
		end)
	end
	track(Lighting.ChildAdded:Connect(function(child)
		if sky.Enabled and child:IsA("Sky") and child ~= customSky then
			scheduleKeepSky()
		end
	end))
	track(Lighting.ChildRemoved:Connect(function(child)
		if sky.Enabled and child == customSky then
			scheduleKeepSky()
		end
	end))
	do
		local elapsed = 0
		track(RunService.Heartbeat:Connect(function(dt)
			elapsed += dt
			if elapsed >= 1 then
				elapsed = 0
				keepSky()
			end
		end))
	end

	SkySection:AddToggle({
		Title = "Custom skybox",
		Description = "Pick a preset, or fill in the image ids below (Preset = Custom)",
		Default = false,
		Flag = "CustomSky",
		Callback = setSky,
	})
	SkySection:AddDropdown({
		Title = "Preset",
		Options = SKY_PRESET_NAMES,
		Default = sky.Preset,
		Flag = "SkyPreset",
		Callback = function(name)
			sky.Preset = name
			applySky()
		end,
	})
	SkySection:AddInput({
		Title = "All faces",
		Description = "One image for every side (overridden by the fields below)",
		Placeholder = "Asset id or image URL",
		Flag = "SkyAll",
		Callback = function(text)
			sky.All = text
			applySky()
		end,
	})
	for _, face in SKY_FACES do
		SkySection:AddInput({
			Title = face.Title,
			Placeholder = "Asset id or image URL",
			Flag = "Sky" .. face.Title,
			Callback = function(text)
				sky.Faces[face.Property] = text
				applySky()
			end,
		})
	end
	SkySection:AddToggle({
		Title = "Sun & moon",
		Default = sky.Celestial,
		Flag = "SkyCelestial",
		Callback = function(on)
			sky.Celestial = on
			applySky()
		end,
	})
	SkySection:AddSlider({
		Title = "Stars",
		Min = 0, Max = 5000, Step = 100, Default = sky.Stars,
		Flag = "SkyStars",
		Callback = function(value)
			sky.Stars = value
			applySky()
		end,
	})
	track(function()
		setSky(false)
	end)
end

-- Low graphics --------------------------------------------------------------

local Performance = VisualsTab:AddSection("Performance")
local restoreTextures = nil

local function stripTextures()
	local restorers = {}
	for _, descendant in workspace:GetDescendants() do
		if descendant:IsA("BasePart") and not descendant:IsA("Terrain") then
			table.insert(restorers, snapshot(descendant, { "Material", "Reflectance" }))
			descendant.Material = Enum.Material.SmoothPlastic
			descendant.Reflectance = 0
		elseif descendant:IsA("Texture") or descendant:IsA("Decal") then
			table.insert(restorers, snapshot(descendant, { "Transparency" }))
			descendant.Transparency = 1
		end
	end
	return function()
		for _, restore in restorers do
			restore()
		end
	end
end

Performance:AddToggle({
	Title = "Strip textures",
	Description = "Smooth plastic everywhere; hides decals (FPS boost)",
	Default = false,
	Flag = "StripTextures",
	Callback = function(on)
		if on then
			restoreTextures = restoreTextures or stripTextures()
		elseif restoreTextures then
			restoreTextures()
			restoreTextures = nil
		end
	end,
})

if type(setfpscap) == "function" then
	Performance:AddSlider({
		Title = "FPS cap",
		Description = "0 = unlimited",
		Min = 0, Max = 360, Step = 5, Default = 0,
		Flag = "FPSCap",
		Callback = function(value)
			setfpscap(value)
		end,
	})
end

--==========================================================================--
--== Camera: FOV & stretched resolution                                   ==--
--==========================================================================--

local CameraTab = Window:AddTab({ Title = "Camera", Icon = "videocam" })

local FovSection = CameraTab:AddSection("Camera FOV")
local fov = { Enabled = false, Value = 90, Original = nil }

FovSection:AddToggle({
	Title = "Custom FOV",
	Default = false,
	Flag = "CustomFOV",
	Callback = function(on)
		fov.Enabled = on
		local cam = camera()
		if on then
			fov.Original = fov.Original or cam.FieldOfView
		elseif fov.Original then
			cam.FieldOfView = fov.Original
			fov.Original = nil
		end
	end,
})
FovSection:AddSlider({
	Title = "Field of view",
	Min = 30, Max = 120, Step = 1, Default = fov.Value, Suffix = "°",
	Flag = "FOV",
	Callback = function(value)
		fov.Value = value
	end,
})

local Stretch = CameraTab:AddSection("Stretched Resolution")
local stretch = { Enabled = false, X = 1, Y = 0.75 }

Stretch:AddToggle({
	Title = "Enabled",
	Description = "Squash the image like a stretched 4:3 resolution",
	Default = false,
	Flag = "Stretch",
	Callback = function(on)
		stretch.Enabled = on
	end,
})
Stretch:AddSlider({
	Title = "X ratio",
	Min = 0.3, Max = 1.5, Step = 0.01, Default = stretch.X,
	Flag = "StretchX",
	Callback = function(value)
		stretch.X = value
	end,
})
Stretch:AddSlider({
	Title = "Y ratio",
	Min = 0.3, Max = 1.5, Step = 0.01, Default = stretch.Y,
	Flag = "StretchY",
	Callback = function(value)
		stretch.Y = value
	end,
})

-- Runs after the game's camera script so our changes win every frame.
local CAMERA_STEP = PREFIX .. "Camera"
RunService:BindToRenderStep(CAMERA_STEP, Enum.RenderPriority.Camera.Value + 1, function()
	local cam = camera()
	if not cam then
		return
	end
	if fov.Enabled then
		cam.FieldOfView = fov.Value
	end
	if stretch.Enabled then
		cam.CFrame = cam.CFrame * CFrame.new(0, 0, 0, stretch.X, 0, 0, 0, stretch.Y, 0, 0, 0, 1)
	end
end)
track(function()
	RunService:UnbindFromRenderStep(CAMERA_STEP)
	if fov.Original then
		camera().FieldOfView = fov.Original
	end
end)

-- Game hooks ------------------------------------------------------------------
-- The camera / weapon modifiers below patch the same RIVALS modules LY-broken's
-- ItemModifiers do: PlayerScripts.Controllers.CameraController and the
-- ClientFighter / ClientViewModel classes. Everything is put back on unload.

do
	local function noop() end

	local function writeField(tbl, key, value)
		local frozen = type(isreadonly) == "function" and isreadonly(tbl)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, false)
		end
		local ok = pcall(rawset, tbl, key, value)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, true)
		end
		return ok
	end

	local function requireGameModule(name)
		local roots = { LocalPlayer:FindFirstChild("PlayerScripts"), cloneref(game:GetService("ReplicatedStorage")) }
		for _, root in roots do
			local module = root and root:FindFirstChild(name, true)
			if module and module:IsA("ModuleScript") then
				local ok, result = pcall(require, module)
				if ok then
					return result
				end
			end
		end
		return nil
	end

	-- The table that actually holds `method`: the module itself or its class
	-- (metatable / __index). Falls back to the Lua heap when the module isn't
	-- where we expect it.
	local function findClass(moduleName, method)
		local function holder(value)
			if type(value) ~= "table" then
				return nil
			end
			if type(rawget(value, method)) == "function" then
				return value
			end
			local meta = getmetatable(value)
			if type(meta) == "table" then
				if type(rawget(meta, method)) == "function" then
					return meta
				end
				local index = rawget(meta, "__index")
				if type(index) == "table" and type(rawget(index, method)) == "function" then
					return index
				end
			end
			return nil
		end
		local found = holder(requireGameModule(moduleName))
		if found or type(getgc) ~= "function" then
			return found
		end
		local ok, objects = pcall(getgc, true)
		if ok then
			for _, object in objects do
				if type(object) == "table" and type(rawget(object, method)) == "function" then
					return object
				end
			end
		end
		return nil
	end

	local function hasDebug(...)
		for _, name in { ... } do
			if type(debug[name]) ~= "function" then
				return false
			end
		end
		return true
	end

	local function patchToggle(section, options)
		local toggle
		toggle = section:AddToggle({
			Title = options.Title,
			Description = options.Description,
			Default = false,
			Flag = options.Flag,
			Callback = function(on)
				if not options.Set(on) and on then
					Window:Notify({ Title = options.Title, Content = options.Failure, Icon = "error" })
					task.defer(function()
						toggle:Set(false, true)
					end)
				end
			end,
		})
		track(function()
			options.Set(false)
		end)
		return toggle
	end

	-- Camera shake ----------------------------------------------------------------
	-- CameraController:ShakeOnce / :Shake both go through self._camera_shaker.
	-- Like LY-broken, the "_camera_shaker" constant in those two methods is
	-- redirected to a key holding a do-nothing shaker. Executors without
	-- debug.setconstant get the methods swapped for no-ops instead.

	local ShakeSection = CameraTab:AddSection("Camera Shake")
	local SHAKE_METHODS = { "ShakeOnce", "Shake" }
	local SHAKER_KEY = "_camera_shaker"
	local SHAKER_PROXY_KEY = PREFIX .. "camera_shaker"
	local shakeRestores = nil

	local function setNoShake(on)
		if not on then
			if shakeRestores then
				for _, restore in shakeRestores do
					pcall(restore)
				end
				shakeRestores = nil
			end
			return true
		end
		if shakeRestores then
			return true
		end
		local prototype = findClass("CameraController", "ShakeOnce")
		if not prototype then
			return false
		end
		local restores = {}
		if hasDebug("getconstants", "setconstant") then
			writeField(prototype, SHAKER_PROXY_KEY, { ShakeOnce = noop, Shake = noop })
			for _, name in SHAKE_METHODS do
				local method = rawget(prototype, name)
				if type(method) == "function" then
					local ok, constants = pcall(debug.getconstants, method)
					if ok then
						for index, constant in constants do
							if constant == SHAKER_KEY then
								if pcall(debug.setconstant, method, index, SHAKER_PROXY_KEY) then
									table.insert(restores, function()
										debug.setconstant(method, index, SHAKER_KEY)
									end)
								end
								break
							end
						end
					end
				end
			end
			if #restores > 0 then
				table.insert(restores, function()
					writeField(prototype, SHAKER_PROXY_KEY, nil)
				end)
			else
				writeField(prototype, SHAKER_PROXY_KEY, nil)
			end
		end
		if #restores == 0 then
			for _, name in SHAKE_METHODS do
				local original = rawget(prototype, name)
				if type(original) == "function" and writeField(prototype, name, noop) then
					table.insert(restores, function()
						writeField(prototype, name, original)
					end)
				end
			end
		end
		if #restores == 0 then
			return false
		end
		shakeRestores = restores
		return true
	end

	patchToggle(ShakeSection, {
		Title = "No camera shake",
		Description = "Stops explosions and hits from shaking your camera",
		Flag = "NoCameraShake",
		Set = setNoShake,
		Failure = "Couldn't find the game's camera shake code",
	})

	-- Camera sway -----------------------------------------------------------------
	-- ClientFighter:GetCameraSway only sways while CameraController reports first
	-- person. Like LY-broken, the CameraController that GetCameraSway sees (one of
	-- its upvalues, or a table held in one) is swapped for a proxy whose
	-- GetPublicState always says "ThirdPerson"; everything else passes through.

	local swayRestore = nil

	local function thirdPersonProxy(controller)
		local proxy = {}
		function proxy.GetPublicState()
			return "ThirdPerson"
		end
		return setmetatable(proxy, { __index = controller, __newindex = controller })
	end

	local function setNoSway(on)
		if not on then
			if swayRestore then
				pcall(swayRestore)
				swayRestore = nil
			end
			return true
		end
		if swayRestore then
			return true
		end
		if not hasDebug("getupvalues", "setupvalue") then
			return false
		end
		local fighter = findClass("ClientFighter", "GetCameraSway")
		local getCameraSway = fighter and rawget(fighter, "GetCameraSway")
		if type(getCameraSway) ~= "function" then
			return false
		end
		local controller = requireGameModule("CameraController")
		local function isController(value)
			if controller ~= nil then
				return rawequal(value, controller)
			end
			if type(value) ~= "table" then
				return false
			end
			local ok, method = pcall(function()
				return value.GetPublicState
			end)
			return ok and type(method) == "function"
		end
		local ok, upvalues = pcall(debug.getupvalues, getCameraSway)
		if not ok then
			return false
		end
		for index, upvalue in upvalues do
			if isController(upvalue) then
				debug.setupvalue(getCameraSway, index, thirdPersonProxy(upvalue))
				swayRestore = function()
					debug.setupvalue(getCameraSway, index, upvalue)
				end
				return true
			end
			if type(upvalue) == "table" then
				for key, value in next, upvalue do
					if isController(value) and writeField(upvalue, key, thirdPersonProxy(value)) then
						swayRestore = function()
							writeField(upvalue, key, value)
						end
						return true
					end
				end
			end
		end
		return false
	end

	patchToggle(ShakeSection, {
		Title = "No camera sway",
		Description = "Stops the first-person camera from swaying while you move",
		Flag = "NoCameraSway",
		Set = setNoSway,
		Failure = "Couldn't find the game's camera sway code",
	})

	-- Weapon motion ---------------------------------------------------------------
	-- Each ClientViewModel drives its bob / tilt / landing / recoil offsets from
	-- the springs below, reading spring.Value (computed in the Spring module's
	-- __index). Like LY-broken, a raw Value field is put on each spring so it
	-- always reads as at rest; clearing that field restores the real spring.
	-- A new viewmodel is made on every equip, so they're caught under the camera.

	local WeaponSection = CameraTab:AddSection("Weapon")
	local MOTION_SPRINGS = {
		_sliding_spring = 0,
		_sprinting_spring = 0,
		_bobbing_speed_spring = 0,
		_bobbing_value_spring = Vector2.zero,
		_landing_spring = 0,
		_jump_spring = 0,
		_tilt_spring = Vector2.zero,
		_impulse_position_spring = Vector3.zero,
		_recoil_spring = Vector3.zero,
		_unrecoil_spring = Vector3.zero,
	}
	local motion = { Enabled = false, Connections = {} }
	local frozenSprings = setmetatable({}, { __mode = "k" })

	local function isLocalItem(viewModel)
		local ok, isLocal = pcall(function()
			return viewModel.ClientItem.ClientFighter.IsLocalPlayer
		end)
		return ok and isLocal == true
	end

	local function freezeViewModel(viewModel)
		for field, rest in MOTION_SPRINGS do
			local spring = rawget(viewModel, field)
			if type(spring) == "table" and writeField(spring, "Value", rest) then
				frozenSprings[spring] = true
			end
		end
	end

	local function freezeViewModels()
		if type(getgc) ~= "function" then
			return false
		end
		local ok, objects = pcall(getgc, true)
		if not ok then
			return false
		end
		local found = false
		for _, object in objects do
			-- CameraController has bobbing / sliding springs too; only viewmodels have
			-- a recoil spring and a ClientItem. Other players' items have viewmodels
			-- as well, so only your own are touched.
			if type(object) == "table" and type(rawget(object, "_recoil_spring")) == "table"
				and rawget(object, "ClientItem") ~= nil and isLocalItem(object)
			then
				freezeViewModel(object)
				found = true
			end
		end
		return found
	end

	local function restoreViewModels()
		for spring in frozenSprings do
			writeField(spring, "Value", nil)
			frozenSprings[spring] = nil
		end
	end

	local function watchViewModels()
		for _, connection in motion.Connections do
			connection:Disconnect()
		end
		table.clear(motion.Connections)
		if not motion.Enabled then
			return
		end
		for _, folder in viewmodelFolders() do
			table.insert(motion.Connections, folder.ChildAdded:Connect(function(child)
				if child:IsA("Model") and not owned[child] then
					task.defer(freezeViewModels)
				end
			end))
		end
	end
	track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(watchViewModels))

	local function setNoMotion(on)
		motion.Enabled = on
		watchViewModels()
		if not on then
			restoreViewModels()
			return true
		end
		if type(getgc) ~= "function" then
			motion.Enabled = false
			watchViewModels()
			return false
		end
		freezeViewModels() -- nothing yet is fine: the next equip gets caught
		return true
	end

	patchToggle(WeaponSection, {
		Title = "No weapon motion",
		Description = "Removes gun bob, tilt, landing and recoil motion from your viewmodel",
		Flag = "NoMotion",
		Set = setNoMotion,
		Failure = "Your executor doesn't support getgc",
	})

	-- Viewmodel animations --------------------------------------------------------
	-- Shoot / sprint / equip / reload: like LY-broken, ViewModelAnimator:
	-- PlayAnimation(key, ...) is hooked (equip and sprint are played by the
	-- animator itself, so the ClientViewModel wrapper would miss them). For a
	-- suppressed key on your own viewmodel the track in _animation_tracks is
	-- swapped for one whose Play / Stop do nothing, the original still runs (so
	-- the game's state updates), then the real track goes back.
	-- Idle / crouch / aim, and the four above when the hook can't be installed,
	-- fall back to stopping matching tracks on the viewmodel's Animators each
	-- frame (matched by track / animation name and id).

	local animations = { Sprint = false, Shoot = false, Equip = false, Reload = false }
	local animationPatch = nil
	local silentTrack = { Play = noop, Stop = noop }

	local function shouldSuppress(animator, key)
		if type(key) ~= "string" then
			return false
		end
		return (animations.Sprint and key == rawget(animator, "_sprint_animation"))
			or (animations.Equip and key == rawget(animator, "_equip_animation"))
			or (animations.Shoot and (key:find("Shoot", 1, true) ~= nil or key == "QuickShot"))
			or (animations.Reload and key:find("Reload", 1, true) ~= nil)
	end

	local function isLocalAnimator(animator)
		local ok, isLocal = pcall(function()
			return animator.ClientViewModel.ClientItem.ClientFighter.IsLocalPlayer
		end)
		return ok and isLocal == true
	end

	local function installAnimationPatch()
		if animationPatch then
			return true
		end
		local class = findClass("ViewModelAnimator", "PlayAnimation")
		local original = class and rawget(class, "PlayAnimation")
		if type(original) ~= "function" then
			return false
		end
		local function playAnimation(animator, key, ...)
			local tracks = type(animator) == "table" and rawget(animator, "_animation_tracks")
			if type(tracks) ~= "table" or rawget(tracks, key) == nil
				or not shouldSuppress(animator, key) or not isLocalAnimator(animator)
			then
				return original(animator, key, ...)
			end
			local realTrack = rawget(tracks, key)
			rawset(tracks, key, silentTrack)
			local results = table.pack(pcall(original, animator, key, ...))
			rawset(tracks, key, realTrack)
			if not results[1] then
				error(results[2], 0)
			end
			return table.unpack(results, 2, results.n)
		end
		if not writeField(class, "PlayAnimation", playAnimation) then
			return false
		end
		animationPatch = { Class = class, Original = original }
		return true
	end

	local function removeAnimationPatch()
		if animationPatch then
			writeField(animationPatch.Class, "PlayAnimation", animationPatch.Original)
			animationPatch = nil
		end
	end

	local TRACK_PATTERNS = {
		Shoot = { "shoot", "fire", "shot" },
		Sprint = { "sprint" },
		Equip = { "equip" },
		Reload = { "reload" },
		Idle = { "idle" },
		Crouch = { "crouch" },
		Aim = { "aim", "ads", "scope" },
	}
	local stoppedKinds = {} -- kind -> true while handled by stopping tracks
	local trackStopper = nil

	local function trackLabel(animTrack)
		local label = animTrack.Name
		local anim = animTrack.Animation
		if anim then
			label ..= " " .. anim.Name .. " " .. anim.AnimationId
		end
		return label:lower()
	end

	local function shouldStopTrack(animTrack)
		local ok, label = pcall(trackLabel, animTrack)
		if not ok then
			return false
		end
		for kind in stoppedKinds do
			for _, pattern in TRACK_PATTERNS[kind] do
				if label:find(pattern, 1, true) then
					return true
				end
			end
		end
		return false
	end

	local function updateTrackStopper()
		if next(stoppedKinds) == nil then
			if trackStopper then
				trackStopper:Disconnect()
				trackStopper = nil
			end
			return
		end
		if trackStopper then
			return
		end
		trackStopper = RunService.RenderStepped:Connect(function()
			for _, folder in viewmodelFolders() do
				for _, descendant in folder:GetDescendants() do
					if descendant:IsA("Animator") and not owned[descendant] then
						for _, animTrack in descendant:GetPlayingAnimationTracks() do
							if shouldStopTrack(animTrack) then
								pcall(animTrack.Stop, animTrack, 0)
							end
						end
					end
				end
			end
		end)
	end

	local function setAnimationDisabled(kind, on)
		stoppedKinds[kind] = nil
		if animations[kind] ~= nil then
			animations[kind] = on
			local any = animations.Sprint or animations.Shoot or animations.Equip or animations.Reload
			if not any then
				removeAnimationPatch()
			elseif not installAnimationPatch() then
				-- No hook available: stop the tracks instead.
				animations[kind] = false
				stoppedKinds[kind] = on or nil
			end
		else
			stoppedKinds[kind] = on or nil
		end
		updateTrackStopper()
		return true
	end

	for _, entry in {
		{ Kind = "Shoot", Title = "No shoot animation", Description = "Your gun doesn't play its firing animation" },
		{ Kind = "Sprint", Title = "No sprint animation", Description = "Your viewmodel doesn't play the sprint animation" },
		{ Kind = "Equip", Title = "No equip animation", Description = "Skip the draw animation when you switch weapons" },
		{ Kind = "Reload", Title = "No reload animation", Description = "Your viewmodel doesn't play the reload animation" },
		{ Kind = "Idle", Title = "No idle animation", Description = "Your viewmodel stays still while idle" },
		{ Kind = "Crouch", Title = "No crouch animation", Description = "Your viewmodel doesn't play the crouch animation" },
		{ Kind = "Aim", Title = "No aim animation", Description = "Your viewmodel doesn't play the aim-down-sights animation" },
	} do
		patchToggle(WeaponSection, {
			Title = entry.Title,
			Description = entry.Description,
			Flag = "No" .. entry.Kind .. "Animation",
			Set = function(on)
				return setAnimationDisabled(entry.Kind, on)
			end,
		})
	end
end

-- Viewmodel -----------------------------------------------------------------------
-- The first-person arms + gun are Models in viewmodelFolders().
-- Offset is applied after the game positions them each frame; chams swap the
-- parts' look and put the originals back when turned off.

-- Own block: keeps the main chunk under Luau's 200 local registers.
local viewmodel, muzzle
do
local ViewmodelSection = CameraTab:AddSection("Viewmodel")
local MATERIAL_NAMES = { "ForceField", "Neon", "Glass", "SmoothPlastic", "Plastic", "Metal", "Foil" }
viewmodel = {
	Offset = false, X = 0, Y = 0, Z = 0,
	-- Arms and gun are chammed separately.
	Arm = {
		Enabled = false, Material = "ForceField", Color = Color3.fromRGB(120, 170, 255), Transparency = 0,
		Wireframe = false, WireWidth = 0.02, WireAngle = 0, WireMaterial = "Neon",
	},
	Gun = {
		Enabled = false, Material = "Neon", Color = Color3.fromRGB(255, 255, 255), Transparency = 0,
		Wireframe = false, WireWidth = 0.02, WireAngle = 0, WireMaterial = "Neon",
	},
}
local chamRestores = setmetatable({}, { __mode = "k" }) -- part -> restore function
local chamKinds = setmetatable({}, { __mode = "k" }) -- part -> "Arm" | "Gun" | false

-- Arm / gun detection: arm models are named like "<Weapon> - Arms"; inside a
-- gun model, arm parts are found by name or by an arm-ish ancestor folder.
local CHAM_EXCLUDED_PARTS = {
	ChamOutlineShell = true, ChamOutlineGlow = true, ChamOutlineBloom = true,
	WeaponWireframeCore = true, WeaponWireframeGlow = true, WeaponWireframeBloom = true,
	GunChamNeonGlow = true,
	ChamMeshProxy = true,
}
local ARM_PART_SKIP = { "hitbox", "collision", "trigger", "proxy", "handguard", "handle", "foregrip", "charm", "armor" }
local ARM_PART_WORDS = {
	"leftarm", "rightarm", "left arm", "right arm", "forearm", "upperarm", "lowerarm",
	"glove", "sleeve", "finger", "wrist", "palm", "thumb", "hand",
}

local function isHelperPart(part)
	local name = part.Name:lower()
	return name:find("hitbox", 1, true) or name:find("collision", 1, true)
		or name:find("trigger", 1, true) or name:find("proxy", 1, true)
end

local function isArmViewModel(model)
	local segments = {}
	for segment in model.Name:gmatch("[^-]+") do
		table.insert(segments, segment:match("^%s*(.-)%s*$"):lower())
	end
	if #segments >= 2 then
		local tag = segments[2]
		if tag:find("glove", 1, true) then
			return true
		end
		return tag:find("arm", 1, true) ~= nil and not tag:find("charm", 1, true) and not tag:find("armor", 1, true)
	end
	local name = model.Name:lower()
	return name:find("arms", 1, true) ~= nil or name:find("glove", 1, true) ~= nil
end

local function isArmNamedPart(partName)
	local name = partName:lower()
	for _, skip in ARM_PART_SKIP do
		if name:find(skip, 1, true) then
			return false
		end
	end
	if name == "larm" or name == "rarm" then
		return true
	end
	for _, word in ARM_PART_WORDS do
		if name:find(word, 1, true) then
			return true
		end
	end
	return false
end

local function hasArmAncestor(part, model)
	local node = part.Parent
	while node and node ~= model do
		local name = node.Name:lower()
		if name == "hands" or name:find("glove", 1, true) or name:find("sleeve", 1, true) then
			return true
		end
		if name:find("arm", 1, true) and not name:find("armor", 1, true) and not name:find("charm", 1, true)
			and not name:find("handguard", 1, true) and not name:find("foregrip", 1, true) then
			return true
		end
		node = node.Parent
	end
	return false
end

-- "Arm", "Gun", or false for parts that are never chammed.
local function chamKind(part, model)
	local kind = chamKinds[part]
	if kind ~= nil then
		return kind
	end
	if CHAM_EXCLUDED_PARTS[part.Name] or part.Transparency >= 0.99 or isHelperPart(part) then
		kind = false
	elseif isArmViewModel(model) or hasArmAncestor(part, model) or isArmNamedPart(part.Name) then
		kind = "Arm"
	else
		kind = "Gun"
	end
	-- A hidden part may be shown later, so don't remember that answer.
	if part.Transparency < 0.99 then
		chamKinds[part] = kind
	end
	return kind
end

local function viewmodels()
	local list = {}
	for _, folder in viewmodelFolders() do
		for _, child in folder:GetChildren() do
			if child:IsA("Model") and not owned[child] then
				table.insert(list, child)
			end
		end
	end
	return list
end

-- Proxies: a MeshPart welded over a viewmodel part that shows the cham while
-- the original is hidden.
--  * Materials don't render on a Part shaped by a SpecialMesh (the arms), so
--    those get a MeshPart copy of their mesh; otherwise only the color showed.
--  * Wireframe: every edge of the mesh is rebuilt as a thin two-sided strip
--    (an EditableMesh), so the part's material and color land on the lines.
local chamMesh = {
	Proxies = setmetatable({}, { __mode = "k" }), -- part -> proxy MeshPart
	Keys = setmetatable({}, { __mode = "k" }), -- part -> template key of its proxy
	Templates = {}, -- key -> MeshPart, or false while loading / if it failed
	WireGeneration = 0, -- bumped when a line width changes; stale builds are dropped
}

-- MeshId, scale from mesh units to studs, and offset of what a part draws.
local function meshSource(part)
	if part:IsA("MeshPart") then
		local ok, size = pcall(function()
			return part.MeshSize
		end)
		if part.MeshId == "" or not ok or size.X <= 0 or size.Y <= 0 or size.Z <= 0 then
			return nil
		end
		return part.MeshId, part.Size / size, CFrame.new()
	end
	local mesh = part:FindFirstChildOfClass("SpecialMesh")
	if mesh and mesh.MeshType == Enum.MeshType.FileMesh and mesh.MeshId ~= "" then
		return mesh.MeshId, mesh.Scale, CFrame.new(mesh.Offset)
	end
	return nil
end

-- Reading a mesh's triangles needs the Roblox-only UGCValidationService calls.
local function asRobloxScript(fn)
	local get, set = getthreadidentity, setthreadidentity
	if type(get) ~= "function" or type(set) ~= "function" then
		return fn()
	end
	local previous = get()
	set(8)
	local ok, result = pcall(fn)
	set(previous)
	if not ok then
		error(result, 0)
	end
	return result
end

local function buildWireMesh(meshId, width, minAngle)
	local ugc = cloneref(game:GetService("UGCValidationService"))
	local mesh = ugc:CreateEditableMeshFromBinaryStringRobloxOnly(ugc:GetMeshDataBinaryString(meshId))
	local faces, original = {}, mesh:GetFaces()
	for _, face in original do
		local verts = mesh:GetFaceVertices(face)
		if #verts >= 3 then
			local points = {}
			for index, vertex in verts do
				points[index] = mesh:GetPosition(vertex)
			end
			local normal = (points[2] - points[1]):Cross(points[3] - points[1])
			if normal.Magnitude > 1e-6 then
				table.insert(faces, { Verts = verts, Points = points, Normal = normal.Unit })
			end
		end
	end
	for _, face in original do
		mesh:RemoveFace(face)
	end
	mesh:RemoveUnused()

	-- A mesh may not be wider than 2048 in any direction (some models are modelled huge and
	-- shown tiny, e.g. Blast X): shrink the lines to fit; the caller scales the part back up.
	local low, high = Vector3.one * math.huge, Vector3.one * -math.huge
	for _, face in faces do
		for _, point in face.Points do
			low, high = low:Min(point), high:Max(point)
		end
	end
	local span = math.max((high - low).X, (high - low).Y, (high - low).Z)
	local factor = if span > 1800 then 1800 / span else 1
	if factor ~= 1 then
		for _, face in faces do
			for index, point in face.Points do
				face.Points[index] = point * factor
			end
		end
		width *= factor
	end

	-- Edges keyed by position: meshes split vertices along UV / normal seams,
	-- which would draw a seam edge twice and hide its neighbouring face.
	local function pointKey(point)
		return string.format("%.4f,%.4f,%.4f", point.X, point.Y, point.Z)
	end
	local edges, order = {}, {}
	for _, face in faces do
		local count = #face.Points
		for i = 1, count do
			local p, q = face.Points[i], face.Points[i % count + 1]
			local kp, kq = pointKey(p), pointKey(q)
			local key = if kp < kq then kp .. "|" .. kq else kq .. "|" .. kp
			local edge = edges[key]
			if edge then
				table.insert(edge.Normals, face.Normal)
			elseif (q - p).Magnitude > 1e-6 then
				edge = { P = p, Q = q, Normals = { face.Normal } }
				edges[key] = edge
				table.insert(order, edge)
			end
		end
	end

	-- minAngle > 0 keeps only edges whose faces meet at least that sharply
	-- (open edges always stay), so flat surfaces lose their triangle lines.
	-- A mesh can't hold more than 20000 triangles and every line costs four, so a model with more
	-- edges than that keeps its sharpest ones (this is why the detailed guns had no wireframe).
	local MAX_LINES = 4900
	local kept = {}
	for _, edge in order do
		local sharp = 180 -- an open edge counts as the sharpest
		if #edge.Normals > 1 then
			sharp = 0
			for a = 1, #edge.Normals - 1 do
				for b = a + 1, #edge.Normals do
					sharp = math.max(sharp, math.deg(math.acos(math.clamp(edge.Normals[a]:Dot(edge.Normals[b]), -1, 1))))
				end
			end
		end
		edge.Sharp = sharp
		if minAngle <= 0 or sharp >= minAngle then
			table.insert(kept, edge)
		end
	end
	if #kept > MAX_LINES then
		table.sort(kept, function(left, right)
			return left.Sharp > right.Sharp
		end)
		kept = table.move(kept, 1, MAX_LINES, 1, {})
	end

	local white = mesh:AddColor(Color3.new(1, 1, 1), 1)
	local half = width / 2
	for _, edge in kept do
		local normal = edge.Normals[1]
		local side = normal:Cross(edge.Q - edge.P)
		if side.Magnitude > 1e-6 then
			local p, q = edge.P, edge.Q
			local lift = normal * 0.001 -- just off the surface
			side = side.Unit * half
			local v1 = mesh:AddVertex(p - side + lift)
			local v2 = mesh:AddVertex(p + side + lift)
			local v3 = mesh:AddVertex(q + side + lift)
			local v4 = mesh:AddVertex(q - side + lift)
			local up, down = mesh:AddNormal(normal), mesh:AddNormal(-normal)
			-- Both windings, so the lines show from either side.
			for _, tri in { { v1, v2, v3, up }, { v1, v3, v4, up }, { v3, v2, v1, down }, { v4, v3, v1, down } } do
				local triangle = mesh:AddTriangle(tri[1], tri[2], tri[3])
				mesh:SetFaceNormals(triangle, { tri[4], tri[4], tri[4] })
				mesh:SetFaceColors(triangle, { white, white, white })
			end
		end
	end
	return mesh, factor
end

-- Template MeshPart for a key, built in the background (it yields); nil until ready.
local function templateFor(key, create, generation)
	local template = chamMesh.Templates[key]
	if template ~= nil then
		return template or nil
	end
	chamMesh.Templates[key] = false
	task.spawn(function()
		local ok, created = pcall(create)
		if generation and generation ~= chamMesh.WireGeneration then
			if ok and created then
				created:Destroy()
			end
			chamMesh.Templates[key] = nil
			return
		end
		chamMesh.Templates[key] = ok and created or false
	end)
	return nil
end

local function dropProxy(part)
	local proxy = chamMesh.Proxies[part]
	if proxy then
		proxy:Destroy()
	end
	chamMesh.Proxies[part] = nil
	chamMesh.Keys[part] = nil
end

-- The part's proxy for `key`; keeps showing the previous one until it's built.
local function proxyFor(part, key, create, scale, offset, generation)
	local current = chamMesh.Proxies[part]
	if current and not current.Parent then
		current = nil
	end
	if current and chamMesh.Keys[part] == key then
		return current
	end
	local template = templateFor(key, create, generation)
	if not template then
		return current
	end
	local proxy = template:Clone()
	proxy.Name = "ChamMeshProxy"
	proxy.Anchored = false
	proxy.Massless = true
	proxy.CanCollide = false
	proxy.CanQuery = false
	proxy.CanTouch = false
	proxy.CastShadow = false
	proxy.Size = template.MeshSize * scale / (template:GetAttribute("WireFactor") or 1)
	local weld = Instance.new("Weld")
	weld.Part0 = part
	weld.Part1 = proxy
	weld.C0 = offset
	weld.Parent = proxy
	proxy.CFrame = part.CFrame * offset
	proxy.Parent = part
	dropProxy(part)
	chamMesh.Proxies[part] = proxy
	chamMesh.Keys[part] = key
	return proxy
end

local function applyCham(part, settings)
	if not chamRestores[part] then
		-- Viewmodel arms wear a ShirtTexture decal over the whole mesh, which
		-- hid most materials and the color; the decals are hidden while chammed.
		-- (The game resets a decal's Transparency every frame, not its
		-- LocalTransparencyModifier.)
		local restores = { snapshot(part, { "Material", "Color", "Transparency", "LocalTransparencyModifier" }) }
		for _, child in part:GetChildren() do
			if child:IsA("Decal") then -- Texture is a Decal too
				table.insert(restores, snapshot(child, { "LocalTransparencyModifier" }))
			end
		end
		chamRestores[part] = function()
			for _, restore in restores do
				restore()
			end
		end
	end
	for _, child in part:GetChildren() do
		if child:IsA("Decal") then
			child.LocalTransparencyModifier = 1
		end
	end

	local wire = settings.Wireframe
	local meshId, scale, offset = meshSource(part)
	local proxy = nil
	if wire and meshId then
		local width = settings.WireWidth / ((scale.X + scale.Y + scale.Z) / 3) -- studs -> mesh units
		local generation = chamMesh.WireGeneration
		local angle = settings.WireAngle
		proxy = proxyFor(part, string.format("wire|%s|%.5f|%d", meshId, width, angle), function()
			return asRobloxScript(function()
				local mesh, factor = buildWireMesh(meshId, width, angle)
				local template = game:GetService("AssetService"):CreateMeshPartAsync(Content.fromObject(mesh))
				template:SetAttribute("WireFactor", factor)
				return template
			end)
		end, scale, offset, generation)
	elseif not wire and meshId and not part:IsA("MeshPart") then
		proxy = proxyFor(part, "cham|" .. meshId, function()
			return game:GetService("AssetService"):CreateMeshPartAsync(meshId)
		end, scale, offset)
	else
		dropProxy(part)
	end

	local material = Enum.Material[if wire then settings.WireMaterial else settings.Material]
	local color = settings.Color -- the lines use the arm / gun color too
	local transparency = if wire then 0 else settings.Transparency
	if proxy then
		part.LocalTransparencyModifier = 1
		proxy.Material = material
		proxy.Color = color
		proxy.Transparency = transparency
	elseif not wire then
		part.LocalTransparencyModifier = 0
		part.Material = material
		part.Color = color
		part.Transparency = transparency
	end
end

local function restoreCham(part)
	dropProxy(part)
	local restore = chamRestores[part]
	if restore then
		restore()
		chamRestores[part] = nil
	end
end

local function clearChams()
	for part in chamRestores do
		restoreCham(part)
	end
end

local function chamsActive()
	return viewmodel.Arm.Enabled or viewmodel.Gun.Enabled or viewmodel.Arm.Wireframe or viewmodel.Gun.Wireframe
end

local function refreshChams()
	if not chamsActive() then
		clearChams()
		return
	end
	for _, model in viewmodels() do
		for _, descendant in model:GetDescendants() do
			if descendant:IsA("BasePart") then
				local kind = chamKind(descendant, model)
				local settings = kind and viewmodel[kind]
				if settings and (settings.Enabled or settings.Wireframe) then
					applyCham(descendant, settings)
				else
					restoreCham(descendant)
				end
			end
		end
	end
end

ViewmodelSection:AddToggle({
	Title = "Viewmodel offset",
	Description = "Move your first-person arms and gun",
	Default = false,
	Flag = "ViewmodelOffset",
	Callback = function(on)
		viewmodel.Offset = on
	end,
})
for _, axis in { "X", "Y", "Z" } do
	ViewmodelSection:AddSlider({
		Title = axis .. " offset",
		Min = -3, Max = 3, Step = 0.05, Default = 0,
		Flag = "Viewmodel" .. axis,
		Callback = function(value)
			viewmodel[axis] = value
		end,
	})
end
-- Lines are baked into the mesh: drop the old builds, they get rebuilt.
local function rebuildWires()
	chamMesh.WireGeneration += 1
	for key, template in chamMesh.Templates do
		if key:sub(1, 5) == "wire|" then
			if template then
				template:Destroy()
			end
			chamMesh.Templates[key] = nil
		end
	end
	refreshChams()
end

for _, kind in { "Arm", "Gun" } do
	local settings = viewmodel[kind]
	ViewmodelSection:AddToggle({
		Title = kind .. " chams",
		Description = kind == "Arm" and "Change the look of your first-person arms / hands"
			or "Change the look of your first-person gun",
		Default = false,
		Flag = "Viewmodel" .. kind .. "Chams",
		Callback = function(on)
			settings.Enabled = on
			refreshChams()
		end,
	})
	ViewmodelSection:AddDropdown({
		Title = kind .. " material",
		Options = MATERIAL_NAMES,
		Default = settings.Material,
		Flag = "Viewmodel" .. kind .. "Material",
		Callback = function(name)
			settings.Material = name
			refreshChams()
		end,
	})
	ViewmodelSection:AddColorPicker({
		Title = kind .. " color",
		Default = settings.Color,
		Flag = "Viewmodel" .. kind .. "Color",
		Callback = function(color)
			settings.Color = color
			refreshChams()
		end,
	})
	ViewmodelSection:AddSlider({
		Title = kind .. " transparency",
		Min = 0, Max = 0.95, Step = 0.05, Default = 0,
		Flag = "Viewmodel" .. kind .. "Transparency",
		Callback = function(value)
			settings.Transparency = value
			refreshChams()
		end,
	})
	ViewmodelSection:AddToggle({
		Title = kind .. " wireframe",
		Description = kind == "Arm" and "Draw your first-person arms as lines along their mesh edges"
			or "Draw your first-person gun as lines along its mesh edges",
		Default = false,
		Flag = "Viewmodel" .. kind .. "Wireframe",
		Callback = function(on)
			settings.Wireframe = on
			refreshChams()
		end,
	})
	ViewmodelSection:AddSlider({
		Title = kind .. " line thickness",
		Min = 0.005, Max = 0.15, Step = 0.005, Default = settings.WireWidth, Suffix = " studs",
		Flag = "Viewmodel" .. kind .. "WireWidth",
		Callback = function(value)
			settings.WireWidth = value
			rebuildWires()
		end,
	})
	ViewmodelSection:AddSlider({
		Title = kind .. " line reduction",
		Min = 0, Max = 90, Step = 1, Default = settings.WireAngle, Suffix = "°",
		Flag = "Viewmodel" .. kind .. "WireAngle",
		Callback = function(value)
			-- 0 draws every edge; higher keeps only edges this sharp, so fewer lines.
			settings.WireAngle = value
			rebuildWires()
		end,
	})
	ViewmodelSection:AddDropdown({
		Title = kind .. " line material",
		Options = MATERIAL_NAMES,
		Default = settings.WireMaterial,
		Flag = "Viewmodel" .. kind .. "WireMaterial",
		Callback = function(name)
			settings.WireMaterial = name
			refreshChams()
		end,
	})
end

-- No muzzle flash: hides flash effects on your own viewmodel. Emitters are made
-- invisible (Emit() ignores Enabled), lights / beams are switched off.
muzzle = { Enabled = false, AllEffects = false }
local muzzleRestores = setmetatable({}, { __mode = "k" }) -- effect -> restore function
local INVISIBLE = NumberSequence.new(1)
local EFFECT_CLASSES = { "ParticleEmitter", "PointLight", "SpotLight", "SurfaceLight", "Beam", "Trail", "Fire", "Smoke", "Sparkles" }

local function isEffect(instance)
	for _, className in EFFECT_CLASSES do
		if instance:IsA(className) then
			return true
		end
	end
	return false
end

local function inViewmodel(instance)
	local folders = viewmodelFolders()
	local node = instance
	while node and not table.find(folders, node.Parent) do
		node = node.Parent
	end
	return node ~= nil and node:IsA("Model") and not owned[node]
end

local function looksLikeMuzzle(instance)
	local node = instance
	for _ = 1, 4 do
		if not node then
			break
		end
		local name = node.Name:lower()
		if name:find("muzzle") or name:find("flash") then
			return true
		end
		node = node.Parent
	end
	return false
end

local function hideEffect(effect)
	if muzzleRestores[effect] or not (muzzle.AllEffects or looksLikeMuzzle(effect)) then
		return
	end
	if effect:IsA("ParticleEmitter") then
		muzzleRestores[effect] = snapshot(effect, { "Transparency" })
		effect.Transparency = INVISIBLE
	else
		muzzleRestores[effect] = snapshot(effect, { "Enabled" })
		effect.Enabled = false
	end
end

local function restoreEffects()
	for effect, restore in muzzleRestores do
		restore()
		muzzleRestores[effect] = nil
	end
end

local function hideAllEffects()
	for _, model in viewmodels() do
		for _, descendant in model:GetDescendants() do
			if isEffect(descendant) then
				hideEffect(descendant)
			end
		end
	end
end

local function setNoMuzzleFlash(on)
	muzzle.Enabled = on
	restoreEffects()
	if on then
		hideAllEffects()
	end
end

-- Flashes are often cloned in per shot, so catch them the moment they appear.
local muzzleConnections = {}
local function watchViewmodelEffects()
	for _, connection in muzzleConnections do
		connection:Disconnect()
	end
	table.clear(muzzleConnections)
	for _, folder in viewmodelFolders() do
		table.insert(muzzleConnections, folder.DescendantAdded:Connect(function(descendant)
			if muzzle.Enabled and isEffect(descendant) and inViewmodel(descendant) then
				hideEffect(descendant)
			end
		end))
	end
end
watchViewmodelEffects()
track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(watchViewmodelEffects))
track(function()
	for _, connection in muzzleConnections do
		connection:Disconnect()
	end
	restoreEffects()
end)

ViewmodelSection:AddToggle({
	Title = "No muzzle flash",
	Description = "Hide the flash on your own gun",
	Default = false,
	Flag = "NoMuzzleFlash",
	Callback = setNoMuzzleFlash,
})
ViewmodelSection:AddToggle({
	Title = "Hide all viewmodel effects",
	Description = "Also hide effects that aren't named muzzle / flash",
	Default = false,
	Flag = "HideViewmodelEffects",
	Callback = function(on)
		muzzle.AllEffects = on
		if muzzle.Enabled then
			setNoMuzzleFlash(true)
		end
	end,
})

local VIEWMODEL_STEP = PREFIX .. "Viewmodel"
local lastChamScan = 0
local offsetPivots = setmetatable({}, { __mode = "k" }) -- model -> pivot we last set
RunService:BindToRenderStep(VIEWMODEL_STEP, Enum.RenderPriority.Last.Value, function()
	if viewmodel.Offset then
		local offset = CFrame.new(viewmodel.X, viewmodel.Y, viewmodel.Z)
		for _, model in viewmodels() do
			local pivot = model:GetPivot()
			-- Only offset once per game update, so a frame the game skips can't drift it.
			if offsetPivots[model] ~= pivot then
				local moved = pivot * offset
				model:PivotTo(moved)
				offsetPivots[model] = moved
			end
		end
	end
	-- Weapon swaps bring in new parts; pick them up a few times a second.
	local now = os.clock()
	if chamsActive() and now - lastChamScan > 0.25 then
		lastChamScan = now
		refreshChams()
	end
end)
track(function()
	RunService:UnbindFromRenderStep(VIEWMODEL_STEP)
	clearChams()
end)
end


