}

local crosshairGui = Instance.new("ScreenGui")
crosshairGui.Name = MD3.Env.RandomName()
crosshairGui.IgnoreGuiInset = true
crosshairGui.ResetOnSpawn = false
crosshairGui.DisplayOrder = 1000
crosshairGui.Enabled = false
MD3.Env.ProtectGui(crosshairGui)
crosshairGui.Parent = MD3.Env.GetGuiParent()
track(own(crosshairGui))

local crosshairRoot = Instance.new("Frame")
crosshairRoot.BackgroundTransparency = 1
crosshairRoot.AnchorPoint = Vector2.new(0.5, 0.5)
crosshairRoot.Position = UDim2.fromScale(0.5, 0.5)
crosshairRoot.Size = UDim2.fromOffset(0, 0)
crosshairRoot.Parent = crosshairGui

local function newBar()
	local bar = Instance.new("Frame")
	bar.AnchorPoint = Vector2.new(0.5, 0.5)
	bar.BorderSizePixel = 0
	local stroke = Instance.new("UIStroke")
	stroke.Color = Color3.new(0, 0, 0)
	stroke.Thickness = 1
	stroke.Parent = bar
	bar.Parent = crosshairRoot
	return bar, stroke
end

-- Up, down, left, right, center dot.
local bars = {}
for index = 1, 5 do
	local bar, stroke = newBar()
	bars[index] = { Frame = bar, Stroke = stroke }
end

local function layoutCrosshair()
	crosshairGui.Enabled = crosshair.Enabled
	local length, gap, thickness = crosshair.Length, crosshair.Gap, crosshair.Thickness
	local offset = gap + length / 2
	local layout = {
		{ UDim2.fromOffset(0, -offset), UDim2.fromOffset(thickness, length) },
		{ UDim2.fromOffset(0, offset), UDim2.fromOffset(thickness, length) },
		{ UDim2.fromOffset(-offset, 0), UDim2.fromOffset(length, thickness) },
		{ UDim2.fromOffset(offset, 0), UDim2.fromOffset(length, thickness) },
		{ UDim2.fromOffset(0, 0), UDim2.fromOffset(thickness, thickness) },
	}
	for index, bar in bars do
		bar.Frame.Position = layout[index][1]
		bar.Frame.Size = layout[index][2]
		bar.Frame.BackgroundColor3 = crosshair.Color
		bar.Frame.BackgroundTransparency = crosshair.Transparency
		bar.Frame.Visible = index < 5 or crosshair.Dot
		bar.Stroke.Enabled = crosshair.Outline
		bar.Stroke.Transparency = crosshair.Transparency
	end
end

local CrosshairSection = CrosshairTab:AddSection("Crosshair")
local function crosshairSetting(key)
	return function(value)
		crosshair[key] = value
		layoutCrosshair()
	end
end

