CrosshairSection:AddSlider({ Title = "Thickness", Min = 1, Max = 8, Step = 1, Default = crosshair.Thickness, Suffix = "px", Flag = "CrosshairThickness", Callback = crosshairSetting("Thickness") })
CrosshairSection:AddSlider({ Title = "Transparency", Min = 0, Max = 0.9, Step = 0.05, Default = crosshair.Transparency, Flag = "CrosshairTransparency", Callback = crosshairSetting("Transparency") })
