HitSection:AddSlider({ Title = "Hitmarker size", Min = 4, Max = 30, Step = 1, Default = hitSettings.MarkerSize, Suffix = "px", Flag = "HitMarkerSize", Callback = setHit("MarkerSize") })
HitSection:AddSlider({ Title = "Hitmarker duration", Min = 0.05, Max = 1.5, Step = 0.05, Default = hitSettings.MarkerDuration, Suffix = "s", Flag = "HitMarkerDuration", Callback = setHit("MarkerDuration") })

local KillSection = FeedbackTab:AddSection("Kill Feedback")
