-- Removables: game overlays the hooks above can skip (flashbang lives in
-- Misc ??Miscellaneous as Anti Flashbang).
local RemovableSection = FeedbackTab:AddSection("Removables")
for _, entry in {
	{ Key = "NoScopeOverlay", Title = "No scope overlay", Description = "Scoping in doesn't draw the black scope UI" },
	{ Key = "NoScopeReticle", Title = "No scope reticle", Description = "Hide the scope's crosshair lines" },
	{ Key = "NoADSVignette", Title = "No ADS vignette", Description = "Remove the dark edges while aiming" },
	{ Key = "NoBurnEffect", Title = "No burn effect", Description = "Skip the on-fire screen effect" },
	{ Key = "NoHitmarker", Title = "No game hitmarker", Description = "Hide the game's own hitmarker (Lin67's still shows)" },
} do
	RemovableSection:AddToggle({
		Title = entry.Title,
		Description = entry.Description,
		Default = false,
		Flag = entry.Key,
		Callback = function(on)
			removables[entry.Key] = on
		end,
	})
end

