	or (fluxus and fluxus.queue_on_teleport)
-- The queued loader is added once, as soon as the toggle is on (the game
-- teleports you into matches itself, which doesn't always fire OnTeleport).
-- It reads the URL from a file when it runs, so turning the toggle off or
-- changing the URL later still counts even though the queue can't be undone.
local AUTOEXEC_FILE = "Lin67Hub/autoexecute.txt"
local AUTOEXEC_LOADER = [[
-- Only one copy may run per server: the loader gets queued once per hub load, so several
-- queued copies can fire together after a teleport. The first one claims this server.
local _env = (getgenv and getgenv()) or _G
local _job = tostring(game.JobId)
if _job ~= "" and _env.__LYAutoExecJob == _job then return end
_env.__LYAutoExecJob = _job

-- Waits until the game is really done loading, not just joined: DataModel, character,
-- the game's own controllers + main UI, the player's data, and no pending asset loads.
-- Each wait has a timeout so a broken join can't block the queue forever.
local function waitFor(cond, timeout)
	local t0 = tick()
	while not cond() and tick() - t0 < timeout do
		task.wait(0.25)
	end
	return cond()
end

-- 1. DataModel.
if not game:IsLoaded() then game.Loaded:Wait() end

local _lp = game:GetService("Players").LocalPlayer
if not _lp then
	repeat task.wait() _lp = game:GetService("Players").LocalPlayer until _lp
end

-- 2. Character with a live Humanoid and root part.
waitFor(function()
	local c = _lp.Character
	return c and c:FindFirstChildOfClass("Humanoid") and c:FindFirstChild("HumanoidRootPart")
end, 60)

-- 3. Server session: Remotes replicated.
local _rs = game:GetService("ReplicatedStorage")
waitFor(function() return _rs:FindFirstChild("Remotes") end, 30)

-- 4. The game's client: controllers started, main UI built, player data received.
waitFor(function()
	local scripts = _lp:FindFirstChild("PlayerScripts")
	local controllers = scripts and scripts:FindFirstChild("Controllers")
	local gui = _lp:FindFirstChild("PlayerGui")
	return controllers
		and controllers:FindFirstChild("FighterController")
		and controllers:FindFirstChild("MechanicsController")
		and gui and gui:FindFirstChild("MainGui")
		and _lp:GetAttribute("Level") ~= nil
end, 45)

-- 5. The game's own scripts have really run: their controller modules are loaded
--    (via getloadedmodules where the executor has it).
waitFor(function()
	if type(getloadedmodules) ~= "function" then return true end
	local ok, list = pcall(getloadedmodules)
	if not ok or type(list) ~= "table" then return true end
	local found = { FighterController = false, MechanicsController = false, MiscellaneousController = false, PreloadController = false }
	for _, module in ipairs(list) do
		if found[module.Name] == false then found[module.Name] = true end
	end
	for _, present in pairs(found) do
		if not present then return false end
	end
	return true
end, 45)

-- 6. No assets still being fetched (loading screen / preload), steady for 1.5 s.
local _cp = game:GetService("ContentProvider")
local _quiet = 0
local _t0 = tick()
while _quiet < 6 and tick() - _t0 < 40 do
	if _cp.RequestQueueSize == 0 then _quiet += 1 else _quiet = 0 end
	task.wait(0.25)
end

-- 7. Let the game's own loading screen finish and the first frames settle.
task.wait(2)

local ok, url = pcall(readfile, %q)
url = ok and type(url) == "string" and url:match("^%%s*(.-)%%s*$") or ""
if url ~= "" then loadstring(game:HttpGet(url))() end
]]
local autoExecute = {
	Enabled = false,
	Url = "https://lua.lystore.lol/O5BmHqMr1QPdpZXWf2vLEDKSdrclP6f7/loader.luau",
	Queued = false,
}

local function syncAutoExecute()
	local url = autoExecute.Enabled and trim(tostring(autoExecute.Url)) or ""
	MD3.Env.MakeFolder("Lin67Hub")
	if not MD3.Env.WriteFile(AUTOEXEC_FILE, url) then
		return false
	end
	if url ~= "" and not autoExecute.Queued then
		-- A hub instance that was itself started by the queue (or reloaded in the same server)
		-- has already queued once for this teleport: don't stack another copy.
		local env = getgenv and getgenv() or _G
		local job = tostring(game.JobId)
		if job ~= "" and env.__LYAutoExecQueuedFor == job then
			autoExecute.Queued = true
		else
			autoExecute.Queued = pcall(queueOnTeleport, AUTOEXEC_LOADER:format(AUTOEXEC_FILE))
			if autoExecute.Queued then env.__LYAutoExecQueuedFor = job end
		end
	end
	return true
end

if type(queueOnTeleport) == "function" then
	local autoExecuteToggle
	autoExecuteToggle = AutoExecute:AddToggle({
		Title = "Re-run after teleport",
		Description = "Loads Lin67 Hub again in the next server (Rejoin, Server hop, joining a match)",
		Default = false,
		Flag = "AutoExecute",
		Callback = function(on)
			autoExecute.Enabled = on
			if not syncAutoExecute() and on then
				Window:Notify({ Title = "Auto Execute", Content = "Your executor can't write files", Icon = "error" })
				task.defer(function()
					autoExecuteToggle:Set(false, true)
				end)
			end
		end,
	})
	-- A queue only lasts one teleport; queue again for the next one.
	track(LocalPlayer.OnTeleport:Connect(function(state)
		if state == Enum.TeleportState.Failed then
			return
		end
		if state == Enum.TeleportState.Started and autoExecute.Enabled and not autoExecute.Queued then
			syncAutoExecute()
		end
	end))
else
	AutoExecute:AddParagraph({
		Title = "Not supported",
		Content = "Your executor has no queue_on_teleport.",
	})
end

-- Interface: streamer mode & hide HUD ------------------------------------------------

local InterfaceSection = MiscTab:AddSection("Interface")
local StarterGui = cloneref(game:GetService("StarterGui"))
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

-- Hide HUD: turns off the game's ScreenGuis and Roblox's core UI (not Lin67 Hub).
local hiddenGuis = nil
local coreGuiStates = nil

local function setHudHidden(on)
	if on and not hiddenGuis then
		hiddenGuis = {}
		for _, gui in PlayerGui:GetChildren() do
			if gui:IsA("ScreenGui") and gui.Enabled and not owned[gui] then
				gui.Enabled = false
				table.insert(hiddenGuis, gui)
			end
		end
		coreGuiStates = {}
		for _, coreType in Enum.CoreGuiType:GetEnumItems() do
			if coreType ~= Enum.CoreGuiType.All then
				local ok, enabled = pcall(StarterGui.GetCoreGuiEnabled, StarterGui, coreType)
				if ok then
					coreGuiStates[coreType] = enabled
				end
			end
		end
		pcall(StarterGui.SetCoreGuiEnabled, StarterGui, Enum.CoreGuiType.All, false)
	elseif not on and hiddenGuis then
		for _, gui in hiddenGuis do
			pcall(function()
				gui.Enabled = true
			end)
		end
		hiddenGuis = nil
		for coreType, enabled in coreGuiStates do
			pcall(StarterGui.SetCoreGuiEnabled, StarterGui, coreType, enabled)
		end
		coreGuiStates = nil
	end
end

local hideHudToggle = InterfaceSection:AddToggle({
	Title = "Hide HUD",
	Description = "Hide the game's UI for clean screenshots / clips",
	Default = false,
	Flag = "HideHUD",
	Callback = setHudHidden,
})
MD3.GearUI.press(InterfaceSection, hideHudToggle, { KeyTitle = "Toggle HUD", KeyFlag = "HideHUDKey", ModeFlag = "HideHUDMode" })
-- Game UI that gets re-created (e.g. on respawn) stays hidden too.
track(PlayerGui.ChildAdded:Connect(function(gui)
	if hiddenGuis and gui:IsA("ScreenGui") and not owned[gui] then
		task.defer(function()
			if hiddenGuis and gui.Enabled then
				gui.Enabled = false
				table.insert(hiddenGuis, gui)
			end
		end)
	end
end))
track(function()
	setHudHidden(false)
end)

-- Auto respawn ------------------------------------------------------------------
-- RIVALS lets you skip the death screen through a "respawn now" remote in
-- ReplicatedStorage.Remotes. After you die, fire it (a few tries) once the
-- delay has passed.

local MatchSection = MiscTab:AddSection("Match")
local ReplicatedStorage = cloneref(game:GetService("ReplicatedStorage"))
local autoRespawn = { Enabled = false, Warned = false, Generation = 0 }

local function findRespawnRemote()
	local remotes = ReplicatedStorage:FindFirstChild("Remotes")
	if not remotes then
		return nil
	end
	for _, child in remotes:GetDescendants() do
		if child:IsA("RemoteEvent") and child.Name:lower():find("respawn") then
			return child
		end
	end
	return nil
end

-- Try to click a button via whichever method the executor supports.
local function fireButton(button)
	if type(fireclick) == "function" then
		pcall(fireclick, button)
		return
	end
	-- Signal:Fire() works on some executors.
	pcall(function()
		button.MouseButton1Click:Fire()
	end)
	-- getconnections fallback: call each handler directly.
	if type(getconnections) == "function" then
		local ok, conns = pcall(getconnections, button.MouseButton1Click)
		if ok and conns then
			for _, conn in conns do
				if type(conn.Function) == "function" then
					pcall(conn.Function)
				end
			end
		end
	end
end

-- Walk a GUI tree looking for a visible "respawn now"-style button.
-- Returns the first match, or nil.
local RESPAWN_TEXTS = { "respawn", "skip" }
local function findRespawnButton(root)
	local candidates = {}
	for _, descendant in root:GetDescendants() do
		if (descendant:IsA("TextButton") or descendant:IsA("ImageButton"))
			and descendant.Visible
			and descendant.Active
			and not owned[descendant]
		then
			local text = ""
			pcall(function()
				text = tostring(descendant.Text):lower()
			end)
			for _, keyword in RESPAWN_TEXTS do
				if text:find(keyword) then
					return descendant
				end
			end
			table.insert(candidates, descendant)
		end
	end
	-- ?�畫?��??��?一顆可點�??��??��??�能被混淆�?，直?��?�?
	if #candidates == 1 then
		return candidates[1]
	end
	return nil
end

local function onDied()
	if not autoRespawn.Enabled then
		return
	end
	autoRespawn.Generation += 1
	local generation = autoRespawn.Generation
	local diedCharacter = LocalPlayer.Character

	task.spawn(function()
		if not autoRespawn.Enabled or generation ~= autoRespawn.Generation then
			return
		end
		if LocalPlayer.Character ~= diedCharacter then
			return -- already respawned without our help
		end

		-- Strategy 1: fire the respawn remote directly (works when the name is readable).
		local remote = findRespawnRemote()
		if remote then
			for _ = 1, 5 do
				if LocalPlayer.Character ~= diedCharacter or not autoRespawn.Enabled then
					return
				end
				pcall(remote.FireServer, remote)
				task.wait(0.1)
			end
			return
		end

		-- Strategy 2: simulate a click on the death-screen "Respawn Now" button.
		-- RIVALS shows a death screen GUI in PlayerGui; scan it for the button.
		local function tryScreens()
			for _, gui in PlayerGui:GetChildren() do
				if gui:IsA("ScreenGui") and gui.Enabled and not owned[gui] then
					local button = findRespawnButton(gui)
					if button then
						fireButton(button)
						return true
					end
				end
			end
			return false
		end

		if tryScreens() then
			return
		end

		-- Screen may not have appeared yet ??watch for it.
		local watchConn
		local function cleanup()
			if watchConn then
				watchConn:Disconnect()
				watchConn = nil
			end
		end
		watchConn = PlayerGui.ChildAdded:Connect(function(child)
			if not autoRespawn.Enabled or generation ~= autoRespawn.Generation then
				cleanup()
				return
			end
			if child:IsA("ScreenGui") then
				task.defer(function()
					if tryScreens() then
						cleanup()
					end
				end)
			end
		end)
		-- Give up after 8 s to avoid leaking the connection.
		task.delay(8, cleanup)
	end)
end

local diedConnection = nil
local function watchOwnHumanoid(character)
	if diedConnection then
		diedConnection:Disconnect()
		diedConnection = nil
	end
	local humanoid = character and (character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10))
	if humanoid and LocalPlayer.Character == character then
		diedConnection = humanoid.Died:Connect(onDied)
	end
end
if LocalPlayer.Character then
	task.spawn(watchOwnHumanoid, LocalPlayer.Character)
end
track(LocalPlayer.CharacterAdded:Connect(watchOwnHumanoid))
track(function()
	autoRespawn.Enabled = false
	if diedConnection then
		diedConnection:Disconnect()
	end
end)

MatchSection:AddToggle({
	Title = "Auto respawn",
	Description = "Skip the death screen and respawn right away",
	Default = false,
	Flag = "AutoRespawn",
	Callback = function(on)
		autoRespawn.Enabled = on
		autoRespawn.Warned = false
	end,
})

-- Movement recorder -------------------------------------------------------------
-- Records your own path and replays it as a local ghost of your character
-- (only you see it; your real character is never moved). Recordings can be
-- saved to / loaded from Lin67Hub/recordings.

-- Cosmetics -------------------------------------------------------------------
-- Client-side only, following LY-broken's cosmetics unlocker:
--  * Unlock All wraps PlayerDataController.CurrentData.Data so its
--    CosmeticInventory field lists every cosmetic; the menus then show them
--    all as owned.
--  * Skins picked below are laid over your weapon data
--    (PlayerDataController:GetWeaponData, used by the lobby and menus) and over
--    the replicated data a ClientItem is built from (your guns in a match).
-- Nothing is sent to the server, so other players still see your real skins.

-- A function, not a do-block, so its locals don't count toward the main
-- chunk's 200-local limit.
local function setupCosmetics()
	local COSMETICS_FOLDER = "Lin67Hub"
	local COSMETICS_FILE = COSMETICS_FOLDER .. "/cosmetics.json"
	local SLOTS = { "Skin", "Wrap", "Charm", "Finisher" }
	local NONE = "None"

	local function writeField(tbl, key, value)
		local frozen = type(isreadonly) == "function" and isreadonly(tbl)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, false)
		end
		local ok = pcall(rawset, tbl, key, value)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, true)
		end
		return ok
	end

	local moduleCache = {}
	local function requireModule(name)
		if moduleCache[name] ~= nil then
			return moduleCache[name]
		end
		local roots = { LocalPlayer:FindFirstChild("PlayerScripts"), ReplicatedStorage }
		for _, root in roots do
			-- FindFirstChild returns only the first match, which can be a same-named
			-- non-module (e.g. the CosmeticViewportFrame UI template), so scan for a module.
			local module = root and root:FindFirstChild(name, true)
			if root and not (module and module:IsA("ModuleScript")) then
				module = nil
				for _, descendant in root:GetDescendants() do
					if descendant.Name == name and descendant:IsA("ModuleScript") then
						module = descendant
						break
					end
				end
			end
			if module then
				local ok, result = pcall(require, module)
				if ok and result ~= nil then
					moduleCache[name] = result
					return result
				end
			end
		end
		return nil
	end

	-- The game's WrapController asks every WrapGroupObject whether its ancestry is
	-- visible each frame. That walk climbs past our hidden-UI container and throws
	-- "lacking capability Plugin" (~200 logged errors/s, the 250ms hitch every 3s)
	-- for every wrap preview in the Cosmetics tab. Answer for our own GUI ourselves.
	local wrapVisibilityFixed = false
	local function fixWrapVisibility()
		if wrapVisibilityFixed then
			return
		end
		wrapVisibilityFixed = true
		local group = requireModule("WrapGroupObject")
		local original = type(group) == "table" and rawget(group, "_IsAncestryVisible")
		if type(original) ~= "function" then
			return
		end
		-- The controller's thread cannot touch instances under our hidden GUI at all
		-- (even IsDescendantOf throws), so don't inspect them: try the game's check
		-- once, and treat an object it cannot read as inactive (cached, weak).
		local blocked = setmetatable({}, { __mode = "k" })
		local function wrapped(self, ...)
			if blocked[self] then
				return false
			end
			local ok, result = pcall(original, self, ...)
			if ok then
				return result
			end
			blocked[self] = true
			return false
		end
		local frozen = table.isfrozen(group)
		if frozen and type(setreadonly) == "function" then
			setreadonly(group, false)
		end
		pcall(function()
			group._IsAncestryVisible = wrapped
		end)
		if frozen and type(setreadonly) == "function" then
			setreadonly(group, true)
		end
	end

	local function index(value, key)
		local ok, result = pcall(function()
			return value[key]
		end)
		return ok and result or nil
	end

	-- Skins that a custom-skin loader adds to CosmeticLibrary (Contraband rarity,
	-- viewmodels built on the fly). Listed here so they sit under their weapon like
	-- any other skin even when the loader hasn't run yet: name = { weapon, image,
	-- high-res image } (a skin with no picture of its own uses its weapon's).
	do
		local daggers, jumpPad, satchel, flashbang, tripmine = 91885384580845, 79459600453621, 82237471151891, 17160801529, 17160799418
		local elixir = { 123677194704684, 96734141776078 }
		local scepter = { 99183402177823, 89220212871603 }
		MD3.LYExtraSkins = {
			["Araxys"] = { "Assault Rifle", 100630038137131, 100630038137131 },
			["Blast X"] = { "Assault Rifle", 77451936943002, 77451936943002 },
			["Champions"] = { "Assault Rifle", 111893221945915, 111893221945915 },
			["Prelude"] = { "Assault Rifle", 116112016858097, 116112016858097 },
			["Vandal"] = { "Assault Rifle", 132934285639653, 132934285639653 },
			["Sova"] = { "Bow", 95113702895543, 95113702895543 },
			["Jett"] = { "Daggers", daggers, daggers },
			["Arcane"] = { "Revolver", 86963409317171, 86963409317171 },
			["Oni Shotgun"] = { "Shotgun", 123737682294040, 123737682294040 },
			["RPG Raze"] = { "RPG", 98661318587721, 98661318587721 },
			["Camera"] = { "Jump Pad", jumpPad, jumpPad },
			["Diamond Sword"] = { "Knife", 108830479771369, 108830479771369 },
			["Raze Grenade"] = { "Grenade", 133631375454811, 133631375454811 },
			["Raze"] = { "Satchel", satchel, satchel },
			["Reaver"] = { "Knife", 128587109500034, 128587109500034 },
			["Sky"] = { "Flashbang", flashbang, flashbang },
			["Chamber"] = { "Sniper", 105309540778092, 105309540778092 },
			["Operator"] = { "Sniper", 133689329349303, 133689329349303 },
			["Spike"] = { "Subspace Tripmine", tripmine, tripmine },
			["Subspace Tripmine (Custom Skin)"] = { "Subspace Tripmine", 98372867049331, 75601061529918 },
			["Glass Shard"] = { "Knife", 102980815872652, 136181940429732 },
			["Grenade (Custom Skin)"] = { "Grenade", elixir[1], elixir[2] },
			["Handgun (Custom Skin)"] = { "Handgun", 138882843694218, 82999887306387 },
			["Katana (Custom Skin)"] = { "Katana", scepter[1], scepter[2] },
			["Medkit (Custom Skin)"] = { "Medkit", 98372867049331, 75601061529918 },
			["Molotov (Custom Skin)"] = { "Molotov", elixir[1], elixir[2] },
			["Satchel (Custom Skin)"] = { "Satchel", elixir[1], elixir[2] },
			["Scythe (Custom Skin)"] = { "Scythe", scepter[1], scepter[2] },
			["Smoke Grenade (Custom Skin)"] = { "Smoke Grenade", elixir[1], elixir[2] },
			["Spear (Custom Skin)"] = { "Spear", scepter[1], scepter[2] },
			["Warpstone (Custom Skin)"] = { "Warpstone", elixir[1], elixir[2] },
		}
	end

	-- The game finds a viewmodel with Utility:LookThrough: a Model that is a direct child of
	-- the ViewModels folder or of a Folder inside it (never a part nested inside another model,
	-- e.g. the many "Chamber" models inside guns). Ours must resolve the same way.
	-- what a weapon's default viewmodel class waits for (ItemModel:WaitForChild(a):WaitForChild(b))
	MD3.LYBuildVersion = 2 -- bump when the built models change, so older ones are rebuilt
	MD3.LYClassNeeds = {
		Bow = { { "Arrow", "Feather" }, { "Arrow", "Stick" }, { "Arrow", "Tip" } },
		Daggers = { { "LeftBody", "MeshPart1" }, { "LeftBody", "MeshPart2" }, { "RightBody", "MeshPart1" }, { "RightBody", "MeshPart2" } },
		RPG = { { "Rocket", "Head" }, { "Rocket", "Neck" } },
		Satchel = { { "Body", "Beep" } },
	}

	MD3.LYLookThrough = function(parent, name)
		for _, child in parent:GetChildren() do
			if child:IsA("Model") and child.Name == name then
				return child
			end
			if child:IsA("Folder") then
				local found = MD3.LYLookThrough(child, name)
				if found then
					return found
				end
			end
		end
		return nil
	end

	-- Generic skin builder: a skin = the stock viewmodel (data.src) plus what a custom-skin
	-- loader changed on it (data.del removed parts, data.set property changes, data.add new
	-- parts). Paths are "Name#n/Name#n" (n-th child of that name). CFrames of parts are stored
	-- relative to the model's Primary part. Data: MD3.Lin67SkinData[name] (JSON, ' for ").
	do
		-- Generic custom-skin builder. data = { src, del = {paths}, set = {{path, p, a}}, add = {{parent, node}}, il, cos }
		local Builder = {}
		do
			local ENUM = {
				Material = Enum.Material,
				TextureMode = Enum.TextureMode,
				EmissionDirection = Enum.NormalId,
				Orientation = Enum.ParticleOrientation,
				MeshType = Enum.MeshType,
				Face = Enum.NormalId,
			}
			local VEC3 = { Scale = true, Offset = true, VertexColor = true, Acceleration = true }
			local RANGE = { Lifetime = true, Speed = true, Rotation = true, RotSpeed = true }
			local SEQUENCE = { Transparency = true, WidthScale = true, Squash = true }
			local HANDLED = { rel = true, ref = true, sc = true, scz = true, a0 = true, a1 = true, p0 = true, p1 = true, MeshId = true, TextureID = true }

			local function numberSequence(points)
				local keys = {}
				for _, k in points do
					table.insert(keys, NumberSequenceKeypoint.new(k[1], k[2], k[3]))
				end
				return NumberSequence.new(keys)
			end

			local function colorSequence(points)
				local keys = {}
				for _, k in points do
					table.insert(keys, ColorSequenceKeypoint.new(k[1], Color3.new(k[2][1], k[2][2], k[2][3])))
				end
				return ColorSequence.new(keys)
			end

			local function decode(inst, key, value)
				if type(value) == "string" then
					local enum = ENUM[key]
					return enum and enum[value] or value
				elseif type(value) ~= "table" then
					return value
				end
				if key == "CFrame" then
					return CFrame.new(table.unpack(value))
				elseif key == "Color" then
					if inst:IsA("BasePart") then
						-- parts keep 8-bit colours: round instead of truncating
						return Color3.fromRGB(math.floor(value[1] * 255 + 0.5), math.floor(value[2] * 255 + 0.5), math.floor(value[3] * 255 + 0.5))
					end
					return colorSequence(value)
				elseif key == "Color3" then
					return Color3.new(value[1], value[2], value[3])
				elseif VEC3[key] or (key == "Size" and inst:IsA("BasePart")) then
					return Vector3.new(value[1], value[2], value[3])
				elseif key == "SpreadAngle" then
					return Vector2.new(value[1], value[2])
				elseif RANGE[key] then
					return NumberRange.new(value[1], value[2])
				elseif SEQUENCE[key] or key == "Size" then
					return numberSequence(value)
				end
				return value
			end

			local function pathOf(inst, top)
				local parts = {}
				local current = inst
				while current and current ~= top do
					local ordinal = 1
					for _, child in current.Parent:GetChildren() do
						if child == current then
							break
						end
						if child.Name == current.Name then
							ordinal += 1
						end
					end
					table.insert(parts, 1, current.Name .. "#" .. ordinal)
					current = current.Parent
				end
				return table.concat(parts, "/")
			end

			local function mapTree(top)
				local map = {}
				for _, descendant in top:GetDescendants() do
					map[pathOf(descendant, top)] = descendant
				end
				return map
			end

			local function isPrimary(part)
				return part.Name == "Primary" or string.sub(part.Name, -7) == "Primary"
			end

			local function refOf(inst, top)
				local current = inst.Parent
				while current do
					if current:IsA("Model") then
						for _, child in current:GetChildren() do
							if child:IsA("BasePart") and child ~= inst and isPrimary(child) then
								return child
							end
						end
						if current.PrimaryPart and current.PrimaryPart ~= inst then
							return current.PrimaryPart
						end
					end
					if current == top then
						break
					end
					current = current.Parent
				end
				for _, descendant in top:GetDescendants() do
					if descendant:IsA("BasePart") and descendant ~= inst and isPrimary(descendant) then
						return descendant
					end
				end
				return nil
			end

			local function setMeshSize(part, scale)
				local base = part.MeshSize
				if base.X < 1e-6 then
					base = Vector3.one
				end
				part.Size = base * scale
			end

			-- Meshes are fetched in parallel (prefetch) and cached; a slow connection (phones) can
			-- take a while per mesh, so waits are generous. Only a real error falls back to an
			-- empty MeshPart whose MeshId is assigned in applyProps (what the loader does).
			local meshCache = {}
			local function fetchMesh(meshId)
				local entry = meshCache[meshId]
				if entry then
					return entry
				end
				entry = { done = false }
				meshCache[meshId] = entry
				task.spawn(function()
					local ok, value = pcall(function()
						return game:GetService("AssetService"):CreateMeshPartAsync(meshId)
					end)
					if not (ok and value) then
						local number = tonumber(string.match(meshId, "%d+$"))
						if number and Content and Content.fromAssetId then
							ok, value = pcall(function()
								return game:GetService("AssetService"):CreateMeshPartAsync(Content.fromAssetId(number))
							end)
						end
					end
					entry.part = ok and value or nil
					entry.done = true
				end)
				return entry
			end

			local function prefetch(value)
				if type(value) ~= "table" then
					return
				end
				for key, item in value do
					if key == "MeshId" and type(item) == "string" and item ~= "" then
						fetchMesh(item)
					else
						prefetch(item)
					end
				end
			end

			local function newMeshPart(meshId)
				if type(meshId) == "string" and meshId ~= "" then
					local entry = fetchMesh(meshId)
					local deadline = os.clock() + 90
					while not entry.done and os.clock() < deadline do
						task.wait()
					end
					if entry.part then
						return entry.part:Clone()
					end
				end
				return Instance.new("MeshPart")
			end

			-- MeshParts / SpecialMeshes that must end up with a given mesh (checked at the end)
			local expected = nil

			local function applyProps(inst, props, byPath, top, pending)
				for key, value in props do
					if not HANDLED[key] then
						pcall(function()
							inst[key] = decode(inst, key, value)
						end)
					end
				end
				if inst:IsA("MeshPart") then
					if props.TextureID ~= nil then
						pcall(function()
							inst.TextureID = props.TextureID
						end)
					end
					if props.MeshId ~= nil and props.MeshId ~= "" then
						if inst.MeshId ~= props.MeshId then
							pcall(function()
								inst.MeshId = props.MeshId
							end)
						end
						if expected then
							table.insert(expected, { inst, props.MeshId })
						end
					end
					if props.MeshId == "" then
						-- hidden anchors: the loader empties their mesh; if that's refused they're still invisible
						pcall(function()
							inst.MeshId = ""
						end)
					end
					if props.sc ~= nil then
						pcall(function()
							setMeshSize(inst, props.sc)
						end)
					end
				elseif props.MeshId ~= nil then
					pcall(function()
						inst.MeshId = props.MeshId
					end)
					if expected and props.MeshId ~= "" then
						table.insert(expected, { inst, props.MeshId })
					end
				end
				if props.rel and inst:IsA("BasePart") then
					local ref = props.ref and byPath[props.ref] or refOf(inst, top)
					if ref then
						inst.CFrame = ref.CFrame * CFrame.new(table.unpack(props.rel))
					end
				end
				if pending then
					for key, field in { a0 = "Attachment0", a1 = "Attachment1", p0 = "Part0", p1 = "Part1" } do
						if props[key] then
							table.insert(pending, { inst, field, props[key] })
						end
					end
				end
			end

			local function applyAttributes(inst, attributes)
				for key, value in attributes do
					inst:SetAttribute(key, value)
				end
			end

			-- a MeshPart's mesh can't be swapped in place: make a new one and move everything over
			local function swapMesh(old, meshId)
				local new = newMeshPart(meshId)
				new.Name = old.Name
				new.CFrame = old.CFrame
				for _, key in { "Anchored", "CanCollide", "CanQuery", "CanTouch", "Massless", "CastShadow", "Material", "Color", "Reflectance", "Transparency" } do
					new[key] = old[key]
				end
				for key, value in old:GetAttributes() do
					new:SetAttribute(key, value)
				end
				for _, child in old:GetChildren() do
					child.Parent = new
				end
				new.Parent = old.Parent
				old:Destroy()
				return new
			end

			local function createNode(node, parent, byPath, top, pending)
				local inst
				if node.c == "MeshPart" then
					inst = newMeshPart(node.p and node.p.MeshId)
				else
					inst = Instance.new(node.c)
				end
				inst.Name = node.n
				if node.p then
					applyProps(inst, node.p, byPath, top, pending)
				end
				if node.a then
					applyAttributes(inst, node.a)
				end
				inst.Parent = parent
				for _, child in node.k or {} do
					createNode(child, inst, byPath, top, pending)
				end
				return inst
			end

			local function findModel(root, name)
				return MD3.LYLookThrough(root, name)
			end

			-- Builds the skin's model from the stock one. Yields (mesh loading).
			function Builder.Build(name, data, root)
				local source = findModel(root, data.src)
				if not source then
					return nil, "source model missing: " .. tostring(data.src)
				end
				prefetch(data)
				local model = source:Clone()
				model.Name = name
				model:SetAttribute("__LYBuild", MD3.LYBuildVersion)
				expected = {}
				local byPath = mapTree(model)
				for _, path in data.del do
					local inst = byPath[path]
					if inst then
						inst:Destroy()
					end
				end
				for _, entry in data.set do
					local inst = byPath[entry.path]
					if inst then
						local p = entry.p
						if p and p.MeshId and p.MeshId ~= "" and inst:IsA("MeshPart") and inst.MeshId ~= p.MeshId then
							inst = swapMesh(inst, p.MeshId)
							byPath[entry.path] = inst
						end
						if p then
							applyProps(inst, p, byPath, model, nil)
						end
						if entry.a then
							applyAttributes(inst, entry.a)
						end
					end
				end
				local pending = {}
				for _, entry in data.add do
					local parent = entry.parent == "" and model or byPath[entry.parent]
					if parent then
						createNode(entry.node, parent, byPath, model, pending)
					end
				end
				local finalMap = mapTree(model)
				for _, item in pending do
					local target = finalMap[item[3]]
					if target then
						pcall(function()
							item[1][item[2]] = target
						end)
					end
				end
				-- every custom mesh must really be on its part: if the executor refused, give up
				-- before anything is hidden in the game
				-- A skin the game has no class of its own for is run by the weapon's default class,
				-- which waits for parts the stock skins it was written for have (and ours may lack).
				-- Waiting for a missing part never ends, so add tiny hidden stand-ins.
				local needs = MD3.LYClassNeeds[data.cos and data.cos.ItemName or ""]
				if needs then
					for _, need in needs do
						local holder = model:FindFirstChild(need[1])
						if holder and not holder:FindFirstChild(need[2]) then
							local stand = Instance.new("Part")
							stand.Name = need[2]
							stand.Size = Vector3.new(0.001, 0.001, 0.001)
							stand.Transparency = 1
							stand.CanCollide = false
							stand.CanQuery = false
							stand.CanTouch = false
							stand.Massless = true
							stand.CastShadow = false
							stand.Anchored = true
							local origin = holder:FindFirstChild("Primary")
							if origin and origin:IsA("BasePart") then
								stand.CFrame = origin.CFrame
							end
							stand:SetAttribute("IgnoreObject", true)
							stand:SetAttribute("IgnoreTransparency", true)
							stand.Parent = holder
						end
					end
				end
				local checks = expected
				expected = nil
				for _, check in checks do
					-- compare the asset numbers: the engine may print the same id in another form
					if string.match(check[1].MeshId, "%d+") ~= string.match(check[2], "%d+") then
						model:Destroy()
						return nil, "mesh " .. check[2] .. " could not be applied (MeshId stayed '" .. tostring(check[1].MeshId) .. "')"
					end
				end
				return model
			end

			Builder.MapTree = mapTree
			Builder.PathOf = pathOf
		end
		MD3.LYSkinBuilder = Builder
	end

	-- Assault Rifle skins, built here on the stock AK-47 viewmodel so they work without
	-- the loader. The game finds a skin's model with ItemLibrary.ViewModels[name] (data)
	-- and a model of that name anywhere under PlayerScripts.Assets.ViewModels.
	-- The numbers are the loader's own, decoded from its signatures and checked
	-- against its finished models: the AK-47's original meshes are hidden and the
	-- custom ones laid over them.
	--   anchor = first MeshPart of the Body model
	--   body = anchor * (A + K) * C       magazine = body * B
	--   reload magazine = body's position + W (in the anchor's axes), body's rotation
	-- Mesh size = the mesh's own size * scale. C is in degrees (XYZ).
	do
		local K = Vector3.new(-0.008, 0.0424, 0)
		local W = Vector3.new(-0.0016, -0.371, -0.538)
		local specs = {
			["Araxys"] = { body = { 133589602939606, 138578940980140 }, mag = { 74451574145397, 138578940980140 }, scale = 0.041, A = { -0.347, -0.256, 0.025 }, B = { -0.037, -0.219, 0.207 }, C = { -0.7, -90, -2.2 } },
			["Blast X"] = { body = { 136741358636207, 98325082951137 }, mag = { 88565897839187, 98325082951137 }, scale = 0.003, A = { -0.463, -0.38, 0.083 }, B = { 0.318, -0.07, -0.025 }, C = { 0, 0, 0 } },
			["Champions"] = { body = { 82974461105308, 92353937404179 }, scale = 4.162, A = { -0.017, -0.273, 0 }, C = { 0, 90, 0 } },
			["Prelude"] = { body = { 83623764990838, 140002013666794 }, mag = { 106237786919950, 109170034379159 }, scale = 4.02, A = { 0, -0.24, 0.01 }, B = { -0.135, -0.2, -0.03 }, C = { 0, 0, 0 } },
			["Vandal"] = { body = { 138100951261312, 84167100219585 }, mag = { 92935167277909, 84167100219585 }, scale = 0.4, A = { 0.1, -0.25, 0.04 }, B = { -0.135, -0.2, -0.03 }, C = { 0, 0, 0 } },
		}
		MD3.LYSkinSpecs = specs

		local building = {}

		local function assetsRoot()
			local scripts = Players.LocalPlayer and Players.LocalPlayer:FindFirstChild("PlayerScripts")
			local assets = scripts and scripts:FindFirstChild("Assets")
			return assets and assets:FindFirstChild("ViewModels")
		end

		local function findModel(root, name)
			return MD3.LYLookThrough(root, name)
		end

		local function hide(part)
			part.Transparency = 1
			part.CastShadow = false
			part:SetAttribute("IgnoreObject", true)
			part:SetAttribute("IgnoreTransparency", true)
		end

		local function customPart(entry, scale, name)
			local part = game:GetService("AssetService"):CreateMeshPartAsync("rbxassetid://" .. entry[1])
			part.Name = name
			part.TextureID = "rbxassetid://" .. entry[2]
			part.Size = part.MeshSize * scale
			part.Anchored = true
			part.CanCollide = false
			part.CanTouch = false
			part.Massless = false
			part.CastShadow = true
			part.Material = Enum.Material.SmoothPlastic
			part.Color = Color3.new(1, 1, 1)
			part:SetAttribute("IgnoreTransparency", true)
			part:SetAttribute("WrapGroup", 2)
			part:SetAttribute("__LYCustomMesh", true)
			return part
		end

		local function buildModel(name, spec, root)
			local source = findModel(root, "AK-47")
			if not source then
				return nil
			end
			local model = source:Clone()
			model.Name = name
			local body, bolt, magazine, reload = model.Body, model.Bolt, model.Magazine, model.ReloadMagazine
			local anchor = body:FindFirstChildWhichIsA("MeshPart")
			if not anchor then
				model:Destroy()
				return nil
			end
			local anchorCFrame = anchor.CFrame
			for _, folder in { body, bolt, magazine, reload } do
				for _, child in folder:GetChildren() do
					if child:IsA("MeshPart") then
						hide(child)
					end
				end
			end
			local A, C = spec.A, spec.C
			local bodyCFrame = anchorCFrame * CFrame.new(Vector3.new(A[1], A[2], A[3]) + K)
				* CFrame.Angles(math.rad(C[1]), math.rad(C[2]), math.rad(C[3]))
			local bodyPart = customPart(spec.body, spec.scale, "__LYCustomAssaultRifleBody")
			bodyPart.CFrame = bodyCFrame
			bodyPart.Parent = body
			if spec.mag then
				local B = spec.B
				local magazinePart = customPart(spec.mag, spec.scale, "__LYCustomAssaultRifleMagazine")
				magazinePart.CFrame = bodyCFrame * CFrame.new(B[1], B[2], B[3])
				magazinePart.Parent = magazine
				local reloadPart = magazinePart:Clone()
				reloadPart.Name = "__LYCustomAssaultRifleReloadMagazine"
				reloadPart.CFrame = CFrame.new(bodyCFrame.Position + anchorCFrame:VectorToWorldSpace(W))
					* bodyCFrame.Rotation
				reloadPart.Parent = reload
			end
			return model
		end

		-- true when the skin is already usable (nothing to build)
		-- Fire sounds the loader gives some skins (read from the running game): skin -> { sound id,
		-- volume }. The game plays sounds from a callback attached to the shoot animation's name, so a
		-- skin gets its own shoot animation entry (same animation, its own callback).
		-- Rifle skins: the game's rifle shot is played at volume 0.875; the loader multiplies it
		-- (its ShootSoundVolumeMult; Blast X has none).
		local RIFLE_VOLUME = 0.875
		MD3.LYFireSounds = {
			["Champions"] = { 87090279180730, RIFLE_VOLUME * 1.79 },
			["Vandal"] = { 87090279180730, RIFLE_VOLUME * 1.8 },
			["Prelude"] = { 108688689190270, RIFLE_VOLUME * 1.5 },
			["Araxys"] = { 113636085902025, RIFLE_VOLUME * 1.7 },
			["Blast X"] = { 92756525424950, RIFLE_VOLUME },
		}

		-- Sniper / shotgun / revolver skins: the loader keeps the stock shot and swaps its FIRST sound for its own
		-- (recorded while firing: Operator 121523370790516 replaces 13270206222 of sniper_shoot1,
		-- Chamber 108153762026790 replaces 115657023572170 of sniper_keyper_shoot1; the rest of the
		-- shot - bolt, shell - plays as usual). The stock callback is wrapped once per animation and
		-- only changes anything for these skins' viewmodels.
		-- { sound id, volume multiplier (the loader's ShootSoundVolumeMult, applied to the volume the
		-- stock call used) }
		local swapsByAnimation = {
			sniper_shoot1 = { Operator = { 121523370790516, 1 } },
			sniper_keyper_shoot1 = { Chamber = { 108153762026790, 1.3 } },
			shotgun_shoot1 = { ["Oni Shotgun"] = { 113174731622393, 1.3 } }, -- replaces 13479562219
			revolver_sheriff_shoot1 = { Arcane = { 105841267616589, 2.3 } }, -- replaces 137835445333923
		}
		local wrapped = {}
		local function applySoundSwaps()
			local infos = index(requireModule("AnimationLibrary"), "Info")
			if type(infos) ~= "table" then
				return
			end
			for animation, swaps in swapsByAnimation do
				local info = infos[animation]
				local original = type(info) == "table" and info.SoundCallback
				if type(original) == "function" and not wrapped[animation] then
					wrapped[animation] = true
					info.SoundCallback = function(viewModel, speed, hash)
						local swap = swaps[viewModel.Name]
						if not swap then
							return original(viewModel, speed, hash)
						end
						local first = true
						local proxy = setmetatable({
							CreateSound = function(_, id, volume, ...)
								if first then
									first = false
									return viewModel:CreateSound("rbxassetid://" .. swap[1], volume * swap[2], ...)
								end
								return viewModel:CreateSound(id, volume, ...)
							end,
						}, { __index = viewModel })
						return original(proxy, speed, hash)
					end
				end
			end
		end

		local function applyFireSound(name, info)
			local sound = MD3.LYFireSounds[name]
			local library = requireModule("AnimationLibrary")
			local infos = index(library, "Info")
			local animations = type(info) == "table" and info.Animations
			local baseName = type(animations) == "table" and animations.Shoot1
			local base = sound and type(infos) == "table" and baseName and infos[baseName]
			if not base then
				return
			end
			local newName = "ly_" .. string.lower(string.gsub(name, "%W", "")) .. "_shoot1"
			local entry = table.clone(base)
			local assetId = "rbxassetid://" .. sound[1]
			entry.SoundCallback = function(viewModel)
				viewModel:CreateSound(assetId, sound[2], 1 + 0.2 * math.random(), true, 5)
			end
			infos[newName] = entry
			local sounds = index(requireModule("SoundLibrary"), "AnimationSounds")
			if type(sounds) == "table" then
				sounds[newName] = { assetId }
			end
			info.Animations = table.clone(animations)
			info.Animations.Shoot1 = newName
		end

		-- The game runs a viewmodel with a Lua class found by the skin's name (ViewModels/<weapon>/<skin>),
		-- else the weapon's default class. Keyper, for one, has a class that turns its bullet trail on and
		-- draws its orange tracers; a skin built on it ("Chamber") needs the same class under its own name.
		MD3.LYCloneViewModelClass = function(name, sourceName)
			local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
			local modules = scripts and scripts:FindFirstChild("Modules")
			local classes = modules and modules:FindFirstChild("ViewModels")
			local original = classes and classes:FindFirstChild(sourceName, true)
			if original and original:IsA("ModuleScript") and not original.Parent:FindFirstChild(name) then
				local copy = original:Clone()
				copy.Name = name
				copy.Parent = original.Parent
			end
		end

		MD3.LYSkinReady = function(name)
			local viewModels = index(requireModule("ItemLibrary"), "ViewModels")
			local root = assetsRoot()
			return type(viewModels) == "table" and root ~= nil and viewModels[name] ~= nil
				and MD3.LYLookThrough(root, name) ~= nil
		end

		-- true when the game has the skin's data and model (built here if need be)
		MD3.LYEnsureSkin = function(name)
			local viewModels = index(requireModule("ItemLibrary"), "ViewModels")
			local root = assetsRoot()
			if type(viewModels) ~= "table" or not root then
				return false
			end
			local existing = MD3.LYLookThrough(root, name)
			if existing and MD3.Lin67SkinData[name] then
				local built = existing:GetAttribute("__LYBuild")
				if built == nil then
					-- built by an older Lin67 (before the version tag): its parts carry "__LY?? attributes
					for _, descendant in existing:GetDescendants() do
						for key in descendant:GetAttributes() do
							if string.sub(key, 1, 4) == "__LY" then
								built = 0
								break
							end
						end
						if built ~= nil then
							break
						end
					end
				end
				if built ~= nil and built ~= MD3.LYBuildVersion then
					existing:Destroy()
					existing = nil
				end
			end
			local hasData, hasModel = viewModels[name] ~= nil, existing ~= nil
			-- (before the early return: a skin built by an earlier run still needs its class)
			local sourceName = MD3.Lin67SkinData[name] and string.match(MD3.Lin67SkinData[name], "'src':'([^']+)'")
			if sourceName then
				pcall(MD3.LYCloneViewModelClass, name, sourceName)
			end
			if hasData and hasModel then
				return true
			end
			local spec, json = specs[name], MD3.Lin67SkinData[name]
			if not (spec or json) or building[name] then
				return false
			end
			building[name] = true
			local ok, result = pcall(function()
				local data = json and HttpService:JSONDecode((string.gsub(json, "'", '"')))
				if data then
					MD3.LYCloneViewModelClass(name, data.src)
				end
				if not hasModel then
					local model, reason
					if data then
						model, reason = MD3.LYSkinBuilder.Build(name, data, root)
					else
						model = buildModel(name, spec, root)
					end
					if not model then
						error(reason or "source model missing")
					end
					model.Parent = root
				end
				local entry = MD3.LYExtraSkins[name]
				if not hasData then
					local source = viewModels[data and data.src or "AK-47"]
					local info = type(source) == "table" and table.clone(source) or {}
					if data then
						for key, value in data.il do
							info[key] = key == "RootPartOffset" and CFrame.new(table.unpack(value)) or value
						end
					else
						info.Image = "rbxassetid://" .. entry[2]
						info.ImageHighResolution = "rbxassetid://" .. entry[3]
					end
					applyFireSound(name, info)
					applySoundSwaps()
					viewModels[name] = info
				end
				local library = requireModule("CosmeticLibrary")
				local cosmetics = index(library, "Cosmetics")
				if type(cosmetics) == "table" and cosmetics[name] == nil then
					local rarities = index(library, "Rarities")
					if data then
						local cosmetic = table.clone(data.cos)
						-- the loader adds its own "Contraband" rarity; use one the game has
						if type(rarities) ~= "table" or rarities[cosmetic.Rarity] == nil then
							cosmetic.Rarity = "Unobtainable"
						end
						cosmetics[name] = cosmetic
					else
						cosmetics[name] = {
							DisplayName = name,
							Image = "rbxassetid://" .. entry[2],
							ImageHighResolution = "rbxassetid://" .. entry[3],
							ImageScale = 3,
							ItemName = entry[1],
							Locked = false,
							Owned = true,
							Rarity = "Unobtainable",
							SourceViewModelName = "AK-47",
							Type = "Skin",
							Unlocked = true,
							ViewModelName = name,
							WorldViewModelName = "AK-47",
						}
					end
				end
			end)
			building[name] = nil
			if not ok then
				MD3.LYLastError = tostring(result)
				warn("Lin67 skin " .. name .. ": " .. tostring(result))
			end
			return ok
		end
	end

	-- Every cosmetic in CosmeticLibrary, in the game's own CosmeticInventory
	-- format (CosmeticLibrary:OwnsCosmetic): `name = true` for skins / emotes,
	-- `{ IsUniversal = true }` for wraps / charms / finishers (any weapon).
	local catalog = nil
	local function getCatalog(force)
		if catalog and not force then
			return catalog
		end
		local cosmetics = index(requireModule("CosmeticLibrary"), "Cosmetics")
		if type(cosmetics) ~= "table" then
			return nil
		end
		local universal = { IsUniversal = true }
		local built = { Inventory = {}, Skins = {}, SkinWeapon = {}, Weapons = {}, Wrap = {}, Charm = {}, Finisher = {} }
		for name, cosmetic in cosmetics do
			local kind = index(cosmetic, "Type")
			if kind == "Skin" then
				local itemName = index(cosmetic, "ItemName")
				if type(itemName) == "string" then
					if not built.Skins[itemName] then
						built.Skins[itemName] = {}
						table.insert(built.Weapons, itemName)
					end
					table.insert(built.Skins[itemName], name)
					built.SkinWeapon[name] = itemName
					built.Inventory[name] = true
				end
			elseif kind == "Wrap" or kind == "Charm" or kind == "Finisher" then
				table.insert(built[kind], name)
				built.Inventory[name] = universal
			elseif kind == "Emote" then
				built.Inventory[name] = true
			end
		end
		for name, entry in MD3.LYExtraSkins do
			if built.SkinWeapon[name] == nil then
				local itemName = entry[1]
				if not built.Skins[itemName] then
					built.Skins[itemName] = {}
					table.insert(built.Weapons, itemName)
				end
				table.insert(built.Skins[itemName], name)
				built.SkinWeapon[name] = itemName
				built.Inventory[name] = true
			end
		end
		table.sort(built.Weapons)
		for _, list in built.Skins do
			table.sort(list)
		end
		table.sort(built.Wrap)
		table.sort(built.Charm)
		table.sort(built.Finisher)
		catalog = built
		return built
	end

	-- weapon name -> { Skin, Wrap, WrapInverted, Charm, Finisher }
	local selections = {}

	local function saveSelections()
		MD3.Env.MakeFolder(COSMETICS_FOLDER)
		MD3.Env.WriteFile(COSMETICS_FILE, HttpService:JSONEncode(selections))
	end

	do
		local text = MD3.Env.IsFile(COSMETICS_FILE) and MD3.Env.ReadFile(COSMETICS_FILE)
		local ok, saved = pcall(function()
			return HttpService:JSONDecode(text)
		end)
		if ok and type(saved) == "table" then
			selections = saved
		end
	end

	-- PlayerDataController.CurrentData.Data proxy --------------------------
	local dataHook = { Spoofed = {}, Current = nil, Real = nil, Connection = nil }

	local function controller()
		return requireModule("PlayerDataController")
	end

	local function fireDataChanged(field)
		local current = dataHook.Current or index(controller(), "CurrentData")
		if current == nil then
			return
		end
		local ok, signal = pcall(function()
			return current:GetDataChangedSignal(field)
		end)
		if not ok or signal == nil then
			return
		end
		local meta = getmetatable(signal)
		local methods = type(meta) == "table" and rawget(meta, "__index")
		local fire = type(methods) == "table" and rawget(methods, "Fire")
		if type(fire) == "function" then
			task.spawn(fire, signal)
		else
			task.spawn(pcall, function()
				signal:Fire()
			end)
		end
	end

	local function unhookData()
		local current, real = dataHook.Current, dataHook.Real
		dataHook.Current, dataHook.Real = nil, nil
		if current and real and not pcall(function()
			current.Data = real
		end) then
			writeField(current, "Data", real)
		end
	end

	local function hookData(current)
		if current == nil or current == dataHook.Current then
			return
		end
		unhookData()
		local real = index(current, "Data")
		if type(real) ~= "table" then
			return
		end
		local spoofed = dataHook.Spoofed
		local proxy = setmetatable({}, {
			__index = function(_, key)
				local get = spoofed[key]
				if get then
					return get()
				end
				return real[key]
			end,
			__newindex = function(_, key, value)
				real[key] = value
			end,
			__iter = function()
				return function(_, key)
					local nextKey, value = next(real, key)
					if nextKey ~= nil and spoofed[nextKey] then
						value = spoofed[nextKey]()
					end
					return nextKey, value
				end
			end,
			__len = function()
				return #real
			end,
		})
		if not pcall(function()
			current.Data = proxy
		end) and not writeField(current, "Data", proxy) then
			return
		end
		dataHook.Current, dataHook.Real = current, real
	end

	local function setSpoofed(field, getter)
		dataHook.Spoofed[field] = getter
		if next(dataHook.Spoofed) == nil then
			if dataHook.Connection then
				dataHook.Connection:Disconnect()
				dataHook.Connection = nil
			end
			unhookData()
			fireDataChanged(field)
			return true
		end
		local playerData = controller()
		if playerData == nil then
			dataHook.Spoofed[field] = nil
			return false
		end
		if not dataHook.Connection then
			local added = index(playerData, "PlayerDataAdded")
			local ok, connection = pcall(function()
				return added:Connect(function()
					hookData(index(playerData, "CurrentData"))
				end)
			end)
			if ok then
				dataHook.Connection = connection
			end
		end
		hookData(index(playerData, "CurrentData"))
		fireDataChanged(field)
		return true
	end

	-- Shared with the player spoofer further down (a different function scope).
	MD3.LYData = {
		Set = setSpoofed,
		Real = function(field)
			local real = dataHook.Real
			return type(real) == "table" and real[field] or nil
		end,
		Changed = fireDataChanged,
	}
	MD3.LYRequire = requireModule

	local function setUnlockAll(on)
		if not on then
			return setSpoofed("CosmeticInventory", nil)
		end
		local built = getCatalog()
		if not built then
			return false
		end
		return setSpoofed("CosmeticInventory", function()
			return built.Inventory
		end)
	end

	-- Laying your picks over weapon data ----------------------------------
	local function hasSelection()
		return next(selections) ~= nil
	end

	local function overlay(weaponName, data)
		local selection = selections[weaponName]
		if type(selection) ~= "table" then
			return data
		end
		if type(data) ~= "table" then
			-- The game has no weapon data for guns you don't own (the weapon picker then
			-- shows the default icon); give it a minimal record so the picked look shows.
			if selection.Skin == nil and selection.Wrap == nil and selection.Charm == nil then
				return data
			end
			data = { Name = weaponName }
		end
		local patched = table.clone(data)
		for _, slot in SLOTS do
			local name = selection[slot]
			if type(name) == "string" then
				patched[slot] = { Name = name, Inverted = slot == "Wrap" and selection.WrapInverted == true or nil }
			elseif name == false then
				patched[slot] = nil
			end
		end
		return patched
	end

	local function ownerOf(value)
		if typeof(value) == "Instance" and value:IsA("Player") then
			return value
		end
		if type(value) == "table" then
			local player = index(value, "Player")
			if typeof(player) == "Instance" and player:IsA("Player") then
				return player
			end
		end
		return nil
	end

	-- Lobby / menus: PlayerDataController:GetWeaponData.
	local weaponDataPatch = nil
	local function hookWeaponData()
		if weaponDataPatch then
			return true
		end
		local playerData = controller()
		local meta = playerData and getmetatable(playerData)
		local class = type(meta) == "table" and type(rawget(meta, "__index")) == "table" and rawget(meta, "__index") or playerData
		local original = type(class) == "table" and rawget(class, "GetWeaponData")
		if type(original) ~= "function" then
			return false
		end
		-- Returns (weaponData, inventoryIndex); only the data is replaced.
		local function getWeaponData(self, ...)
			local result, inventoryIndex = original(self, ...)
			local weaponName, owner = nil, nil
			for position = 1, select("#", ...) do
				local argument = select(position, ...)
				if type(argument) == "string" and selections[argument] then
					weaponName = argument
				else
					owner = owner or ownerOf(argument)
				end
			end
			if weaponName == nil or (owner ~= nil and owner ~= LocalPlayer) then
				return result, inventoryIndex
			end
			return overlay(weaponName, result), inventoryIndex
		end
		if not writeField(class, "GetWeaponData", getWeaponData) then
			return false
		end
		weaponDataPatch = { Class = class, Original = original }
		return true
	end

	-- Matches: ClientItem.new(replicated, clientFighter) builds each gun from
	-- replicated[ViewModel][Data], which ClientViewModel reads as Name / Wrap /
	-- Charm. The gun model is PlayerScripts.Assets.ViewModels[Name] (a skin is
	-- simply its own Name, e.g. "AKEY-47"); wraps and charms are { Name = ... }
	-- entries. Top-level keys are compressed through EnumLibrary._to_enum
	-- (LY-broken's Codec); an entry's own fields stay plain.
	local itemPatch = nil
	local realLooks = {} -- weapon -> { Name, Wrap, Charm } as the server sent them

	local function encoder()
		local toEnum = index(requireModule("EnumLibrary"), "_to_enum")
		return function(name)
			local encoded = type(toEnum) == "table" and index(toEnum, name)
			return encoded ~= nil and encoded or name
		end
	end

	local function weaponOf(name)
		local built = getCatalog()
		return built and built.SkinWeapon[name] or name
	end

	-- Your pick for each part, else what the server sent.
	local function lookFor(weaponName, real)
		local look = { Name = real.Name, Wrap = real.Wrap or nil, Charm = real.Charm or nil }
		local selection = selections[weaponName]
		if type(selection) == "table" then
			if type(selection.Skin) == "string" then
				look.Name = selection.Skin
			elseif selection.Skin == false then
				look.Name = weaponName
			end
			if type(selection.Wrap) == "string" then
				look.Wrap = { Name = selection.Wrap, Inverted = selection.WrapInverted == true or nil }
			elseif selection.Wrap == false then
				look.Wrap = nil
			end
			if type(selection.Charm) == "string" then
				look.Charm = { Name = selection.Charm }
			elseif selection.Charm == false then
				look.Charm = nil
			end
		end
		return look
	end

	local function findViewModelData(encode, replicated)
		local viewModel = type(replicated) == "table" and rawget(replicated, encode("ViewModel"))
		local data = type(viewModel) == "table" and rawget(viewModel, encode("Data"))
		if type(data) ~= "table" or type(rawget(data, encode("Name"))) ~= "string" then
			return nil
		end
		return data
	end

	local function hookClientItems()
		if itemPatch then
			return true
		end
		local class = requireModule("ClientItem")
		local original = type(class) == "table" and rawget(class, "new")
		if type(original) ~= "function" then
			return false
		end
		local encode = encoder()
		local function new(...)
			if not itemPatch or itemPatch.Broken then
				return original(...)
			end
			local replicated, fighter = ...
			if ownerOf(fighter) ~= LocalPlayer then
				return original(...)
			end
			local data = findViewModelData(encode, replicated)
			if not data then
				return original(...)
			end
			local nameKey, wrapKey, charmKey = encode("Name"), encode("Wrap"), encode("Charm")
			local real = { Name = rawget(data, nameKey), Wrap = rawget(data, wrapKey), Charm = rawget(data, charmKey) }
			local weaponName = weaponOf(real.Name)
			realLooks[weaponName] = real
			if selections[weaponName] == nil then
				return original(...)
			end
			local look = lookFor(weaponName, real)
			rawset(data, nameKey, look.Name)
			rawset(data, wrapKey, look.Wrap)
			rawset(data, charmKey, look.Charm)
			-- A half-built item can't be rebuilt, so on failure stop touching
			-- items for the rest of the session and let the error through.
			local results = table.pack(pcall(original, ...))
			if not results[1] then
				itemPatch.Broken = true
				MD3.LYLastError = tostring(results[2])
				warn("Lin67 cosmetic (" .. tostring(real.Name) .. " -> " .. tostring(look.Name) .. "): " .. MD3.LYLastError)
				-- notify from our own Heartbeat connection: this thread belongs to the game and can't create UI
				local connection
				connection = RunService.Heartbeat:Connect(function()
					connection:Disconnect()
					Window:Notify({ Title = "Cosmetics", Content = "The game rejected " .. tostring(look.Name) .. ": " .. MD3.LYLastError:sub(1, 140), Icon = "error", Duration = 12 })
				end)
				error(results[2], 0)
			end
			return table.unpack(results, 2, results.n)
		end
		if not writeField(class, "new", new) then
			return false
		end
		itemPatch = { Class = class, Original = original, Broken = false }
		return true
	end

	-- Runs a game method the way LY-broken's ViewModelReloader does: on a fresh
	-- thread at the game scripts' identity (2).
	local function asGame(fn, ...)
		local args = table.pack(...)
		local results, finished, thread = nil, false, nil
		task.spawn(function()
			thread = coroutine.running()
			if type(getthreadidentity) == "function" and type(setthreadidentity) == "function" then
				setthreadidentity(2)
			end
			results = table.pack(pcall(fn, table.unpack(args, 1, args.n)))
			finished = true
		end)
		-- the game's functions can yield (loading animations / sounds): wait for the result
		local deadline = os.clock() + 20
		while not finished and os.clock() < deadline do
			task.wait()
		end
		if not finished then
			-- say where it is stuck, and stop it so it can't finish later behind our back
			local where = "?"
			if thread then
				local okTrace, trace = pcall(debug.traceback, thread)
				if okTrace and type(trace) == "string" then
					where = string.gsub(trace, "\n", " | ")
				end
				pcall(task.cancel, thread)
			end
			return false, "timed out, stuck at: " .. where
		end
		return table.unpack(results, 1, results.n)
	end

	-- Rebuilds your gun(s) for a weapon with the current picks, without
	-- respawning (LY-broken's ViewModelReloader): destroy the viewmodel, create
	-- a new one from ClientItem:_CreateViewModel, and put it back in your hands.
	local function reloadWeapon(weaponName)
		local viewModelClass = requireModule("ClientViewModel")
		local itemClass = requireModule("ClientItem")
		local create = type(itemClass) == "table" and rawget(itemClass, "_CreateViewModel")
		local destroy = type(viewModelClass) == "table" and rawget(viewModelClass, "Destroy")
		if type(create) ~= "function" or type(destroy) ~= "function" or type(getgc) ~= "function" then
			return 0
		end
		local ok, objects = pcall(getgc, true)
		if not ok then
			return 0
		end
		local targets = {}
		for _, object in objects do
			if type(object) == "table" and type(rawget(object, "_recoil_spring")) == "table" then
				local item = rawget(object, "ClientItem")
				local okLocal, isLocal = pcall(function()
					return item.ClientFighter.IsLocalPlayer
				end)
				if okLocal and isLocal == true and rawget(item, "ViewModel") == object
					and weaponOf(rawget(object, "Name")) == weaponName
				then
					table.insert(targets, { Item = item, ViewModel = object })
				end
			end
		end
		local encode = encoder()
		local rebuilt = 0
		for _, target in targets do
			local item, viewModel = target.Item, target.ViewModel
			local current = rawget(viewModel, "Data")
			if type(current) == "table" then
				local real = realLooks[weaponName] or { Name = current.Name, Wrap = current.Wrap, Charm = current.Charm }
				realLooks[weaponName] = real
				local look = lookFor(weaponName, real)
				local encoded = {}
				for key, value in next, current do
					encoded[encode(key)] = value
				end
				encoded[encode("Name")] = look.Name
				encoded[encode("Wrap")] = look.Wrap
				encoded[encode("Charm")] = look.Charm
				local wasEquipped = index(item, "IsEquipped") == true
				asGame(destroy, viewModel)
				local created, newViewModel = asGame(create, item, { [encode("Data")] = encoded })
				if not (created and type(newViewModel) == "table") then
					-- the game refused to build the new viewmodel: say why, and put the real one back
					-- so the weapon isn't left without any
					MD3.LYLastError = tostring(newViewModel)
					warn("Lin67 cosmetic (" .. tostring(look.Name) .. "): " .. MD3.LYLastError)
					encoded[encode("Name")] = real.Name
					encoded[encode("Wrap")] = real.Wrap
					encoded[encode("Charm")] = real.Charm
					created, newViewModel = asGame(create, item, { [encode("Data")] = encoded })
					local failedName, failedText = look.Name, MD3.LYLastError
					local connection
					connection = RunService.Heartbeat:Connect(function()
						connection:Disconnect()
						Window:Notify({ Title = "Cosmetics", Content = "The game couldn't build " .. tostring(failedName) .. ": " .. failedText:sub(1, 320), Icon = "error", Duration = 15 })
					end)
				end
				if created and type(newViewModel) == "table" then
					rawset(item, "ViewModel", newViewModel)
					local arms = table.pack(pcall(function()
						return item.ClientFighter:GetArmsData()
					end))
					if arms[1] then
						asGame(viewModelClass.SetArmsData, newViewModel, table.unpack(arms, 2, arms.n))
					end
					if wasEquipped then
						asGame(viewModelClass.Equip, newViewModel, true)
					end
					rebuilt += 1
				end
			end
		end
		return rebuilt
	end

	-- Finishers: the server tells every client to play one through
	-- ClientEntity:ReplicateFromServer("FinisherEffect", ...), which calls
	-- self:_PlayFinisher(name, isFinalFinisher, eliminator, serial) and that
	-- runs require(Modules.Finishers[name]).new(subject, isFinal, eliminator).
	-- The eliminator is the killing Player, so when it's you the name is
	-- swapped for the finisher picked for the gun in your hands.
	local finisherPatch = nil

	local function pickedFinisher()
		local fighter = index(requireModule("FighterController"), "LocalFighter")
		local item = fighter and index(fighter, "EquippedItem")
		local itemName = item and index(item, "Name")
		local selection = type(itemName) == "string" and selections[weaponOf(itemName)]
		local name = type(selection) == "table" and selection.Finisher
		return type(name) == "string" and name or nil
	end

	local function hookFinishers()
		if finisherPatch then
			return true
		end
		local class = requireModule("ClientEntity")
		local original = type(class) == "table" and rawget(class, "_PlayFinisher")
		local modules = ReplicatedStorage:FindFirstChild("Modules")
		local folder = modules and modules:FindFirstChild("Finishers")
		if type(original) ~= "function" or folder == nil then
			return false
		end
		local function playFinisher(self, name, isFinal, eliminator, ...)
			if finisherPatch and eliminator == LocalPlayer then
				local ok, picked = pcall(pickedFinisher)
				if ok and picked and picked ~= name and folder:FindFirstChild(picked) then
					name = picked
				end
			end
			return original(self, name, isFinal, eliminator, ...)
		end
		if not writeField(class, "_PlayFinisher", playFinisher) then
			return false
		end
		finisherPatch = { Class = class, Original = original }
		return true
	end

	local function unhookSkins()
		if finisherPatch then
			writeField(finisherPatch.Class, "_PlayFinisher", finisherPatch.Original)
			finisherPatch = nil
		end
		if weaponDataPatch then
			writeField(weaponDataPatch.Class, "GetWeaponData", weaponDataPatch.Original)
			weaponDataPatch = nil
		end
		if itemPatch then
			writeField(itemPatch.Class, "new", itemPatch.Original)
			itemPatch = nil
		end
	end

	local function refreshWeapons()
		fireDataChanged("WeaponInventory")
		fireDataChanged("WeaponData")
	end

	local function applySkinHooks()
		if not hasSelection() then
			unhookSkins()
			refreshWeapons()
			return true
		end
		-- Skins Lin67 builds itself (Assault Rifle ones) have to exist before the game
		-- makes the viewmodel; building yields, so it runs on its own thread.
		for _, selection in selections do
			local skin = type(selection) == "table" and selection.Skin
			if type(skin) == "string" and (MD3.LYSkinSpecs[skin] or MD3.Lin67SkinData[skin]) then
				task.spawn(MD3.LYEnsureSkin, skin)
			end
		end
		local lobby = hookWeaponData()
		local match = hookClientItems()
		local finishers = hookFinishers()
		refreshWeapons()
		return lobby or match or finishers
	end

	-- Equipping from the game's own menus ---------------------------------
	-- Every equip in the Customize UI goes through
	-- Remotes.Data.EquipCosmetic:FireServer(weapon, type, name?, options?).
	-- While Unlock All is on, a cosmetic you don't really own is kept as a local
	-- pick instead (the server would refuse it); the menu then redraws its
	-- "equipped" marks from GetWeaponData. Owned cosmetics and "none" still go
	-- to the server as usual.
	local equipHook = { Installed = false }
	local onLocalEquip = nil -- set once the picker exists

	local function reallyOwns(weaponName, name)
		local library = requireModule("CosmeticLibrary")
		local inventory = dataHook.Real and dataHook.Real.CosmeticInventory
		if type(library) ~= "table" or type(inventory) ~= "table" then
			return true
		end
		local ok, owns = pcall(library.OwnsCosmetic, library, inventory, name, weaponName)
		return not ok or (owns and true or false)
	end

	local function afterLocalEquip(weaponName)
		task.defer(function()
			saveSelections()
			applySkinHooks()
			reloadWeapon(weaponName)
			if onLocalEquip then
				onLocalEquip(weaponName)
			end
		end)
	end

	-- Returns true when the equip was kept locally (so it isn't sent).
	local function handleEquip(weaponName, kind, name, options)
		if dataHook.Spoofed.CosmeticInventory == nil or type(weaponName) ~= "string" or not table.find(SLOTS, kind) then
			return false
		end
		local selection = selections[weaponName]
		if name == nil or reallyOwns(weaponName, name) then
			if selection and selection[kind] ~= nil then
				selection[kind] = nil
				if kind == "Wrap" then
					selection.WrapInverted = nil
				end
				if next(selection) == nil then
					selections[weaponName] = nil
				end
				afterLocalEquip(weaponName)
			end
			return false
		end
		selection = selection or {}
		selection[kind] = name
		if kind == "Wrap" then
			selection.WrapInverted = type(options) == "table" and options.IsInverted == true or nil
		end
		selections[weaponName] = selection
		afterLocalEquip(weaponName)
		return true
	end

	local function installEquipHook()
		if equipHook.Installed then
			return true
		end
		if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
			return false
		end
		local wrap = type(newcclosure) == "function" and newcclosure or function(fn)
			return fn
		end
		local original
		original = hookmetamethod(game, "__namecall", wrap(function(self, ...)
			-- Read the method first: any other namecall would overwrite it.
			if getnamecallmethod() == "FireServer" and equipHook.Installed
				and typeof(self) == "Instance" and self.Name == "EquipCosmetic"
				and not (type(checkcaller) == "function" and checkcaller())
			then
				local ok, handled = pcall(handleEquip, ...)
				if ok and handled then
					return
				end
			end
			return original(self, ...)
		end))
		equipHook.Installed = true
		return true
	end

	-- UI ------------------------------------------------------------------
	-- One "Cosmetics" tab: Presets / Overview / Skins / Wraps / Charms / Finishers
	-- sub-tabs. Each catalog sub-tab has an "Apply To" weapon picker and a searchable
	-- grid of cards; clicking a card applies it to that weapon right away.
	-- A slot value is a cosmetic name, `false` ("None": force it empty) or nil
	-- ("Unselected": leave the game's own value).
	local CosmeticsTab = Window:AddTab({ Title = "Cosmetics", Icon = "checkroom" })
	MD3.LYCosmeticsTab = CosmeticsTab -- the Rank Charm override adds its own sub-tab here
	local PAGE_SIZE = 48
	local PRESETS_FILE = COSMETICS_FOLDER .. "/cosmetic_presets.json"
	local WARN_COLOR = Color3.fromRGB(255, 196, 92)
	local ui = {
		Weapon = nil,
		Search = {},
		Shown = {},
		Catalogs = {},
		WeaponDropdowns = {},
		Statuses = {},
		Presets = {},
		PresetName = "",
		PresetPick = nil,
	}
	local refreshAll
	local setWeaponBackground

	local function new(class, props)
		local instance = Instance.new(class)
		for key, value in props do
			if key ~= "Parent" then
				instance[key] = value
			end
		end
		instance.Parent = props.Parent
		return instance
	end

	local function rounded(instance, radius)
		new("UICorner", { CornerRadius = UDim.new(0, radius), Parent = instance })
	end

	local function themeColors()
		return Window.Theme.Colors
	end

	local function cosmeticInfo(name)
		local cosmetics = index(requireModule("CosmeticLibrary"), "Cosmetics")
		local info = type(cosmetics) == "table" and index(cosmetics, name) or nil
		if info == nil and MD3.LYExtraSkins[name] then
			-- Not registered by the loader yet: same shape as the game's entry.
			local entry = MD3.LYExtraSkins[name]
			return {
				Type = "Skin",
				ItemName = entry[1],
				Rarity = "Contraband",
				Image = "rbxassetid://" .. entry[2],
				ImageHighResolution = "rbxassetid://" .. entry[3],
			}
		end
		return info
	end

	-- The skins above need a viewmodel in the game: Lin67 builds it from the stock one
	-- (MD3.LYEnsureSkin, takes a few seconds the first time). Picking one the game has
	-- no model for would leave the weapon without a model.
	local function skinAvailable(name)
		if not MD3.LYExtraSkins[name] then
			return true
		end
		return MD3.LYEnsureSkin(name)
	end

	-- Cheap check for the random pick: the skin works, or Lin67 can build it.
	local function skinProvidable(name)
		if not MD3.LYExtraSkins[name] then
			return true
		end
		if MD3.LYSkinSpecs[name] or MD3.Lin67SkinData[name] then
			return true
		end
		local viewModels = index(requireModule("ItemLibrary"), "ViewModels")
		return type(viewModels) == "table" and viewModels[name] ~= nil
	end

	local function rarityColor(info)
		local rarities = index(requireModule("CosmeticLibrary"), "Rarities")
		local entry = type(rarities) == "table" and info and index(rarities, index(info, "Rarity"))
		local color = entry and index(entry, "Color")
		return typeof(color) == "Color3" and color or Color3.fromRGB(255, 255, 255)
	end

	local function currentValue(slot)
		local selection = ui.Weapon and selections[ui.Weapon]
		if type(selection) ~= "table" then
			return nil
		end
		return selection[slot]
	end

	-- Writes one slot of one weapon and applies it. Returns false when the game's
	-- data couldn't be hooked.
	local function setSlot(weaponName, slot, value)
		local selection = selections[weaponName] or {}
		selection[slot] = value
		if slot == "Wrap" and type(value) ~= "string" then
			selection.WrapInverted = nil
		end
		local empty = true
		for _, name in SLOTS do
			if selection[name] ~= nil then
				empty = false
			end
		end
		selections[weaponName] = not empty and selection or nil
		saveSelections()
		local ok = applySkinHooks()
		if slot ~= "Finisher" then
			reloadWeapon(weaponName)
		end
		return ok
	end

	local function describe(weaponName)
		local selection = selections[weaponName]
		local parts = {}
		for _, slot in SLOTS do
			local value = type(selection) == "table" and selection[slot]
			table.insert(parts, slot .. " " .. (type(value) == "string" and value or (value == false and "None" or "-")))
		end
		return weaponName .. ": " .. table.concat(parts, " · ")
	end

	local function statusText(slot)
		if not ui.Weapon then
			return "Pick a weapon in Apply To first."
		end
		local value = currentValue(slot)
		if value == nil then
			return ui.Weapon .. ": " .. slot .. " unselected (game default)."
		elseif value == false then
			return ui.Weapon .. ": " .. slot .. " set to None."
		end
		return ui.Weapon .. ": " .. slot .. " = " .. value
	end

	-- Catalog grid ----------------------------------------------------------
	local function itemList(slot)
		local built = getCatalog()
		if not built then
			return {}
		end
		if slot == "Skin" then
			return ui.Weapon and built.Skins[ui.Weapon] or {}
		end
		return built[slot] or {}
	end

	local function filtered(slot)
		local query = string.lower(ui.Search[slot] or "")
		local out = {}
		for _, name in itemList(slot) do
			if query == "" or string.find(string.lower(name), query, 1, true) then
				table.insert(out, name)
			end
		end
		return out
	end

	local function paintCard(card, selected)
		local colors = themeColors()
		card.Button.BackgroundColor3 = selected and (colors.SecondaryContainer or Color3.fromRGB(96, 96, 110))
			or (colors.SurfaceContainerHighest or colors.SurfaceContainer or Color3.fromRGB(60, 60, 64))
		card.Name.TextColor3 = selected and (colors.OnSecondaryContainer or Color3.new(1, 1, 1))
			or (colors.OnSurfaceVariant or Color3.fromRGB(190, 190, 195))
		card.Check.Visible = selected
	end

	local function cardSelected(card)
		local value = currentValue(card.Slot)
		if card.Kind == "unselected" then
			return ui.Weapon ~= nil and value == nil
		elseif card.Kind == "none" then
			return value == false
		elseif card.Kind == "item" then
			return value == card.Item
		end
		return false
	end

	local function refreshMarks(slot)
		local catalog = ui.Catalogs[slot]
		for _, card in catalog.Cards do
			paintCard(card, cardSelected(card))
		end
		local status = ui.Statuses[slot]
		if status then
			local text = statusText(slot)
			if next(selections) ~= nil then
				text = "Custom loadout is ready.  " .. text
			end
			status:Set(text, true)
		end
	end

	local function drawSpecialArt(art, kind)
		local colors = themeColors()
		local ink = colors.OnSurface or Color3.new(1, 1, 1)
		if kind == "random" then
			new("TextLabel", {
				BackgroundTransparency = 1,
				Size = UDim2.fromScale(1, 1),
				Text = "?",
				TextSize = 42,
				Font = Enum.Font.GothamBold,
				TextColor3 = ink,
				Parent = art,
			})
			return
		end
		local ring = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(46, 46),
			BackgroundTransparency = 1,
			Parent = art,
		})
		new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = ring })
		new("UIStroke", { Color = ink, Thickness = 5, Parent = ring })
		local slash = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(6, 46),
			Rotation = 45,
			BackgroundColor3 = ink,
			BorderSizePixel = 0,
			Parent = ring,
		})
		rounded(slash, 3)
	end

	local function makeCard(catalog, slot, kind, item, order)
		local colors = themeColors()
		local button = new("TextButton", {
			AutoButtonColor = false,
			Text = "",
			BackgroundColor3 = colors.SurfaceContainerHighest or colors.SurfaceContainer or Color3.fromRGB(60, 60, 64),
			BorderSizePixel = 0,
			LayoutOrder = order,
			Parent = catalog.Grid,
		})
		rounded(button, 8)
		local art = new("Frame", {
			Position = UDim2.fromOffset(6, 6),
			Size = UDim2.new(1, -12, 0, 92),
			BackgroundColor3 = colors.SurfaceContainer or Color3.fromRGB(40, 40, 44),
			BorderSizePixel = 0,
			Parent = button,
		})
		rounded(art, 6)
		local info = kind == "item" and cosmeticInfo(item) or nil
		if kind == "item" then
			local image = info and index(info, "Image")
			if type(image) == "string" and image ~= "" then
				new("ImageLabel", {
					BackgroundTransparency = 1,
					Size = UDim2.fromScale(1, 1),
					Image = image,
					ScaleType = Enum.ScaleType.Fit,
					Parent = art,
				})
			else
				-- Wraps and charms have no icon: the game draws them in a viewport.
				local cosmeticType = info and index(info, "Type")
				if cosmeticType == "Wrap" or cosmeticType == "Charm" then
					pcall(fixWrapVisibility)
					pcall(function()
						-- The game's constructor leaves this thread without the capability to
						-- touch instances (Potassium); the identity is put back right after it.
						local identity = type(getthreadidentity) == "function" and getthreadidentity()
						local built, viewport = pcall(function()
							return requireModule("CosmeticViewportFrame").new(item, false)
						end)
						if identity and type(setthreadidentity) == "function" then
							setthreadidentity(identity)
						end
						if not built then
							error(viewport, 0)
						end
						local frame = viewport.Frame
						-- The game's template is anchored at its center.
						frame.AnchorPoint = Vector2.zero
						frame.Position = UDim2.new()
						frame.Size = UDim2.fromScale(1, 1)
						art.ClipsDescendants = true
						frame.BackgroundTransparency = 1
						frame.Parent = art
					end)
				end
			end
			local bar = new("Frame", {
				AnchorPoint = Vector2.new(0.5, 1),
				Position = UDim2.new(0.5, 0, 1, -4),
				Size = UDim2.new(0.62, 0, 0, 5),
				BackgroundColor3 = rarityColor(info),
				BorderSizePixel = 0,
				Parent = art,
			})
			rounded(bar, 3)
		else
			drawSpecialArt(art, kind)
		end
		local title = kind == "item" and item or (kind == "unselected" and "Unselected" or (kind == "none" and "None" or "Random"))
		local label = new("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(4, 100),
			Size = UDim2.new(1, -8, 0, 32),
			Text = title,
			TextWrapped = true,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Font = Enum.Font.GothamMedium,
			TextSize = 12,
			Parent = button,
		})
		local check = new("Frame", {
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -10, 0, 10),
			Size = UDim2.fromOffset(20, 20),
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			Visible = false,
			ZIndex = 5,
			Parent = button,
		})
		new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = check })
		local card = { Button = button, Name = label, Check = check, Kind = kind, Item = item, Slot = slot }
		button.Activated:Connect(function()
			if not ui.Weapon then
				Window:Notify({ Title = "Cosmetics", Content = "Pick a weapon in Apply To first", Icon = "error" })
				return
			end
			local value = nil
			if kind == "none" then
				value = false
			elseif kind == "item" then
				value = item
			elseif kind == "random" then
				local list = {}
				for _, name in filtered(slot) do
					if slot ~= "Skin" or skinProvidable(name) then
						table.insert(list, name)
					end
				end
				if #list == 0 then
					return
				end
				value = list[math.random(#list)]
			end
			if slot == "Skin" and type(value) == "string" and MD3.LYExtraSkins[value] and not MD3.LYSkinReady(value) then
				Window:Notify({ Title = "Cosmetics", Content = "Preparing " .. value .. " (a few seconds the first time)", Icon = "refresh" })
			end
			if slot == "Skin" and type(value) == "string" and not skinAvailable(value) then
				Window:Notify({ Title = "Cosmetics", Content = "Couldn't build " .. value .. ": " .. tostring(MD3.LYLastError or "unknown"):sub(1, 140), Icon = "error" })
				return
			end
			if not setSlot(ui.Weapon, slot, value) then
				Window:Notify({ Title = "Cosmetics", Content = "Couldn't hook the game's weapon data", Icon = "error" })
			end
			refreshAll()
		end)
		table.insert(catalog.Cards, card)
		paintCard(card, cardSelected(card))
		return card
	end

	local function renderCatalog(slot)
		local catalog = ui.Catalogs[slot]
		for _, instance in catalog.Instances do
			instance:Destroy()
		end
		table.clear(catalog.Instances)
		table.clear(catalog.Cards)
		local order = 0
		local function nextOrder()
			order += 1
			return order
		end
		makeCard(catalog, slot, "unselected", nil, nextOrder())
		if slot ~= "Finisher" then
			makeCard(catalog, slot, "none", nil, nextOrder())
		end
		makeCard(catalog, slot, "random", nil, nextOrder())
		local list = filtered(slot)
		local limit = ui.Shown[slot] or PAGE_SIZE
		for i = 1, math.min(#list, limit) do
			makeCard(catalog, slot, "item", list[i], nextOrder())
		end
		if #list > limit then
			local more = new("TextButton", {
				AutoButtonColor = false,
				Text = string.format("Show more (%d left)", #list - limit),
				Font = Enum.Font.GothamMedium,
				TextSize = 12,
				TextColor3 = themeColors().OnSurfaceVariant or Color3.new(1, 1, 1),
				BackgroundColor3 = themeColors().SurfaceContainer or Color3.fromRGB(40, 40, 44),
				BorderSizePixel = 0,
				LayoutOrder = nextOrder(),
				Parent = catalog.Grid,
			})
			rounded(more, 8)
			more.Activated:Connect(function()
				ui.Shown[slot] = limit + PAGE_SIZE
				renderCatalog(slot)
			end)
			table.insert(catalog.Instances, more)
		end
		for _, card in catalog.Cards do
			table.insert(catalog.Instances, card.Button)
		end
		refreshMarks(slot)
	end

	function refreshAll()
		for _, slot in SLOTS do
			refreshMarks(slot)
		end
		if ui.OverviewLabel then
			local lines = {}
			for weaponName in selections do
				table.insert(lines, describe(weaponName))
			end
			table.sort(lines)
			ui.OverviewLabel:Set(#lines > 0 and table.concat(lines, "\n") or "No custom cosmetics yet.", true)
		end
	end

	local function setWeapon(name)
		ui.Weapon = name
		for _, dropdown in ui.WeaponDropdowns do
			dropdown:Set(name, true)
		end
		table.clear(ui.Shown)
		for _, slot in SLOTS do
			renderCatalog(slot)
		end
		refreshAll()
	end
	onLocalEquip = function(weaponName)
		if ui.Weapon == weaponName then
			refreshAll()
		end
	end

	-- Sub-tabs ----------------------------------------------------------------
	local subs = {}
	for _, name in { "Presets", "Overview", "Skins", "Wraps", "Charms", "Finishers" } do
		subs[name] = CosmeticsTab:AddSubTab(name, { Columns = 1 })
	end

	local SLOT_TABS = { Skin = "Skins", Wrap = "Wraps", Charm = "Charms", Finisher = "Finishers" }
	local SLOT_TITLES = { Skin = "Skin Catalog", Wrap = "Wrap Catalog", Charm = "Charm Catalog", Finisher = "Finisher Catalog" }
	for _, slot in SLOTS do
		local sub = subs[SLOT_TABS[slot]]
		local applySection = sub:AddSection("Apply To")
		table.insert(ui.WeaponDropdowns, applySection:AddDropdown({
			Title = "Apply To",
			Options = {},
			Callback = function(name)
				if type(name) == "string" and name ~= ui.Weapon then
					setWeapon(name)
				end
			end,
		}))
		local status = applySection:AddLabel({ Text = "Pick a weapon in Apply To first." })
		if status.Instance then
			status.Instance.TextColor3 = WARN_COLOR
		end
		ui.Statuses[slot] = status
		if slot == "Wrap" then
			applySection:AddToggle({
				Title = "Invert wrap",
				Default = false,
				Callback = function(on)
					local weaponName = ui.Weapon
					local selection = weaponName and selections[weaponName]
					if type(selection) == "table" and type(selection.Wrap) == "string" then
						selection.WrapInverted = on or nil
						saveSelections()
						applySkinHooks()
						reloadWeapon(weaponName)
					end
				end,
			})
		end

		local catalogSection = sub:AddSection(SLOT_TITLES[slot])
		catalogSection:AddInput({
			Title = "Search " .. SLOT_TABS[slot],
			Placeholder = "Input here...",
			Finished = false,
			Callback = function(text)
				ui.Search[slot] = tostring(text or "")
				ui.Shown[slot] = nil
				renderCatalog(slot)
			end,
		})
		local grid = new("Frame", {
			Name = "CosmeticGrid",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = catalogSection:_nextOrder(),
			Parent = catalogSection._holder,
		})
		new("UIGridLayout", {
			CellSize = UDim2.fromOffset(146, 136),
			CellPadding = UDim2.fromOffset(8, 8),
			SortOrder = Enum.SortOrder.LayoutOrder,
			HorizontalAlignment = Enum.HorizontalAlignment.Left,
			Parent = grid,
		})
		ui.Catalogs[slot] = { Grid = grid, Cards = {}, Instances = {} }
	end

	-- Overview ------------------------------------------------------------------
	local overview = subs.Overview:AddSection("Loadout")
	local unlockToggle
	unlockToggle = overview:AddToggle({
		Title = "Unlock All",
		Description = "Every skin, wrap, charm, finisher and emote shows as owned, and weapon cosmetics can be equipped from the game's menus (only on your screen)",
		Default = false,
		Flag = "UnlockAll",
		Callback = function(on)
			if not setUnlockAll(on) then
				if on then
					Window:Notify({ Title = "Unlock All", Content = "Couldn't find the game's player data ??try again once you're in the lobby", Icon = "error" })
					task.defer(function()
						unlockToggle:Set(false, true)
					end)
				end
				return
			end
			if on and not installEquipHook() then
				Window:Notify({ Title = "Unlock All", Content = "Your executor can't hook remotes ??use the Skins / Wraps / Charms tabs to equip", Icon = "error" })
			end
		end,
	})
	ui.OverviewLabel = overview:AddLabel({ Text = "No custom cosmetics yet." })

	-- Weapon background: the weapon picker / hotbar tint follows the weapon's Status
	-- in ItemLibrary.Items (Standard = gray, Prime = yellow, Contraband = purple).
	-- Client-side only. ItemLibrary.Items has an anti-hook trap on missing keys, so it
	-- is only ever walked with next / rawget.
	local statusOriginals = {}
	local BACKGROUNDS = { ["Default"] = "Default", ["Prime (yellow)"] = "Prime", ["Contraband (purple)"] = "Contraband" }
	function setWeaponBackground(mode)
		local library = requireModule("ItemLibrary")
		local items = type(library) == "table" and rawget(library, "Items")
		if type(items) ~= "table" then
			return false
		end
		for name, item in next, items do
			if type(item) == "table" then
				if statusOriginals[name] == nil then
					statusOriginals[name] = rawget(item, "Status") or false
				end
				local value = mode == "Default" and statusOriginals[name] or mode
				if value then
					writeField(item, "Status", value)
				end
			end
		end
		return true
	end
	overview:AddDropdown({
		Title = "Weapon background",
		Description = "Tint every weapon card in the weapon picker (only on your screen)",
		Options = { "Default", "Prime (yellow)", "Contraband (purple)" },
		Default = "Default",
		Flag = "WeaponBackground",
		Callback = function(name)
			local mode = BACKGROUNDS[name] or "Default"
			if not setWeaponBackground(mode) and mode ~= "Default" then
				Window:Notify({ Title = "Cosmetics", Content = "Couldn't read the game's item list ??try again once you're in the lobby", Icon = "error" })
			end
		end,
	})

	local function loadCatalog()
		local built = getCatalog(true)
		if not built then
			Window:Notify({ Title = "Cosmetics", Content = "Couldn't read the game's cosmetic list ??try again once you're in the lobby", Icon = "error" })
			return false
		end
		for _, dropdown in ui.WeaponDropdowns do
			dropdown:SetOptions(built.Weapons)
			if ui.Weapon then
				dropdown:Set(ui.Weapon, true)
			end
		end
		for _, slot in SLOTS do
			renderCatalog(slot)
		end
		refreshAll()
		return true
	end

	overview:AddButton({ Title = "Load cosmetic list", Icon = "refresh", Callback = loadCatalog })
	-- Sound recorder: lists the Sound objects that appear while it's on (a shot, a reload ...),
	-- to see which sounds a skin really plays. Only watches; changes nothing.
	local soundLog, soundConnection = {}, nil
	overview:AddButton({
		Title = "Record sounds (tap again to stop)",
		Icon = "mic",
		Callback = function()
			if soundConnection then
				soundConnection:Disconnect()
				soundConnection = nil
				Window:Notify({ Title = "Sounds", Content = "Stopped (" .. #soundLog .. " recorded). Tap \"Show sound log\".", Icon = "info" })
				return
			end
			table.clear(soundLog)
			soundConnection = game.DescendantAdded:Connect(function(instance)
				if instance:IsA("Sound") then
					task.defer(function()
						local ok, line = pcall(function()
							return string.format("%s vol %.2f in %s", string.match(instance.SoundId, "%d+") or instance.SoundId, instance.Volume, instance.Parent and instance.Parent.Name or "nil")
						end)
						if ok then
							table.insert(soundLog, line)
							if #soundLog > 200 then
								table.remove(soundLog, 1)
							end
						end
					end)
				end
			end)
			Window:Notify({ Title = "Sounds", Content = "Recording: fire / reload / equip, then tap again to stop", Icon = "mic" })
		end,
	})
	overview:AddButton({
		Title = "Show sound log",
		Icon = "list",
		Callback = function()
			local shown, seen = {}, {}
			for index = #soundLog, 1, -1 do
				if not seen[soundLog[index]] and #shown < 8 then
					seen[soundLog[index]] = true
					table.insert(shown, soundLog[index])
				end
			end
			local text = #shown > 0 and table.concat(shown, "\n") or "nothing recorded"
			warn("Lin67 sound log\n" .. table.concat(soundLog, "\n"))
			Window:Notify({ Title = "Sound log", Content = text, Icon = "info", Duration = 25 })
		end,
	})
	-- Effects report: the trails / particles on the viewmodel you're holding, as they are right now.
	overview:AddButton({
		Title = "Effects report",
		Icon = "auto_awesome",
		Callback = function()
			local lines = {}
			local viewModels = workspace:FindFirstChild("ViewModels")
			local first = viewModels and viewModels:FindFirstChild("FirstPerson")
			local found = 0
			if first then
				for _, model in first:GetChildren() do
					if string.find(model.Name, LocalPlayer.Name, 1, true) == 1 then
						found += 1
						table.insert(lines, model.Name)
						for _, d in model:GetDescendants() do
							if d:IsA("Trail") or d:IsA("ParticleEmitter") then
								local part = d:FindFirstAncestorWhichIsA("BasePart")
								local info = ""
								if d:IsA("Trail") and d.Attachment0 and d.Attachment1 then
									info = string.format(" len=%.2f", (d.Attachment0.WorldPosition - d.Attachment1.WorldPosition).Magnitude)
								end
								table.insert(lines, string.format("%s %s on %s: on=%s ltm=%.1f anch=%s%s", d.ClassName:sub(1, 5), d.Name, part and part.Parent.Name .. "." .. part.Name or "?", tostring(d.Enabled), d.LocalTransparencyModifier, tostring(part and part.Anchored), info))
							end
						end
					end
				end
			end
			if found == 0 then
				table.insert(lines, "no first-person viewmodel found (equip a weapon first)")
			end
			local text = table.concat(lines, "\n")
			warn("Lin67 effects report\n" .. text)
			Window:Notify({ Title = "Effects report", Content = text:sub(1, 900), Icon = "info", Duration = 30 })
		end,
	})
	overview:AddButton({
		Title = "Skin report",
		Icon = "bug_report",
		Callback = function()
			local lines = {}
			local viewModels = index(requireModule("ItemLibrary"), "ViewModels")
			local cosmetics = index(requireModule("CosmeticLibrary"), "Cosmetics")
			local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
			local assets = scripts and scripts:FindFirstChild("Assets")
			local root = assets and assets:FindFirstChild("ViewModels")
			for weaponName, selection in selections do
				local skin = type(selection) == "table" and selection.Skin
				if type(skin) == "string" and (MD3.LYSkinSpecs[skin] or MD3.Lin67SkinData[skin]) then
					local model = root and MD3.LYLookThrough(root, skin)
					local meshes, empty = 0, 0
					if model then
						for _, d in model:GetDescendants() do
							if d:IsA("MeshPart") or d:IsA("SpecialMesh") then
								if d.MeshId ~= "" then meshes += 1 else empty += 1 end
							end
						end
					end
					table.insert(lines, string.format("%s/%s: model=%s (meshes %d, hidden %d) vm=%s cos=%s", weaponName, skin, tostring(model ~= nil), meshes, empty, tostring(type(viewModels) == "table" and viewModels[skin] ~= nil), tostring(type(cosmetics) == "table" and cosmetics[skin] ~= nil)))
				end
			end
			table.insert(lines, "itemPatch=" .. (itemPatch and (itemPatch.Broken and "BROKEN" or "ok") or "off") .. " last=" .. tostring(MD3.LYLastError or "-"):sub(1, 330))
			local text = table.concat(lines, "\n")
			warn("Lin67 skin report\n" .. text)
			Window:Notify({ Title = "Skin report", Content = text, Icon = "info", Duration = 20 })
		end,
	})
	overview:AddButton({
		Title = "Clear weapon",
		Icon = "delete",
		Callback = function()
			local weaponName = ui.Weapon
			if not weaponName then
				Window:Notify({ Title = "Cosmetics", Content = "Pick a weapon first", Icon = "error" })
				return
			end
			selections[weaponName] = nil
			saveSelections()
			applySkinHooks()
			reloadWeapon(weaponName)
			refreshAll()
		end,
	})
	overview:AddButton({
		Title = "Clear all weapons",
		Icon = "delete",
		Callback = function()
			local changed = {}
			for weaponName in selections do
				table.insert(changed, weaponName)
			end
			table.clear(selections)
			saveSelections()
			applySkinHooks()
			for _, weaponName in changed do
				reloadWeapon(weaponName)
			end
			refreshAll()
		end,
	})

	-- Presets -------------------------------------------------------------------
	do
		local text = MD3.Env.IsFile(PRESETS_FILE) and MD3.Env.ReadFile(PRESETS_FILE)
		if type(text) == "string" then
			local ok, saved = pcall(function()
				return HttpService:JSONDecode(text)
			end)
			if ok and type(saved) == "table" then
				ui.Presets = saved
			end
		end
	end
	local function savePresets()
		MD3.Env.MakeFolder(COSMETICS_FOLDER)
		MD3.Env.WriteFile(PRESETS_FILE, HttpService:JSONEncode(ui.Presets))
	end
	local function presetNames()
		local names = {}
		for name in ui.Presets do
			table.insert(names, name)
		end
		table.sort(names)
		return names
	end

	local presets = subs.Presets:AddSection("Presets")
	local presetDropdown
	presets:AddInput({
		Title = "Preset name",
		Placeholder = "Name for the current loadout",
		Callback = function(text)
			ui.PresetName = tostring(text or "")
		end,
	})
	presets:AddButton({
		Title = "Save current loadout",
		Icon = "save",
		Callback = function()
			local name = ui.PresetName
			if name == "" then
				Window:Notify({ Title = "Presets", Content = "Type a preset name first", Icon = "error" })
				return
			end
			ui.Presets[name] = HttpService:JSONDecode(HttpService:JSONEncode(selections))
			savePresets()
			presetDropdown:SetOptions(presetNames())
			presetDropdown:Set(name, true)
			ui.PresetPick = name
			Window:Notify({ Title = "Presets", Content = "Saved \"" .. name .. "\"", Icon = "check" })
		end,
	})
	presetDropdown = presets:AddDropdown({
		Title = "Saved presets",
		Options = presetNames(),
		Callback = function(name)
			ui.PresetPick = name
		end,
	})
	presets:AddButton({
		Title = "Load preset",
		Icon = "download",
		Callback = function()
			local preset = ui.PresetPick and ui.Presets[ui.PresetPick]
			if type(preset) ~= "table" then
				Window:Notify({ Title = "Presets", Content = "Pick a saved preset first", Icon = "error" })
				return
			end
			local affected = {}
			for weaponName in selections do
				affected[weaponName] = true
			end
			for weaponName in preset do
				affected[weaponName] = true
			end
			table.clear(selections)
			for weaponName, selection in HttpService:JSONDecode(HttpService:JSONEncode(preset)) do
				selections[weaponName] = selection
			end
			saveSelections()
			applySkinHooks()
			for weaponName in affected do
				reloadWeapon(weaponName)
			end
			refreshAll()
			Window:Notify({ Title = "Presets", Content = "Loaded \"" .. ui.PresetPick .. "\"", Icon = "check" })
		end,
	})
	presets:AddButton({
		Title = "Delete preset",
		Icon = "delete",
		Callback = function()
			if ui.PresetPick and ui.Presets[ui.PresetPick] then
				ui.Presets[ui.PresetPick] = nil
				savePresets()
				presetDropdown:SetOptions(presetNames())
				ui.PresetPick = nil
			end
		end,
	})

	CosmeticsTab:SelectSubTab("Skins")

	task.defer(function()
		if getCatalog() then
			loadCatalog()
		end
		if hasSelection() then
			applySkinHooks()
		end
	end)

	-- Build every custom skin at load (one after another, in the background) so picking one is
	-- instant and its model, viewmodel class and sounds are all in place before you equip it.
	task.spawn(function()
		local names = {}
		for name in MD3.LYExtraSkins do
			if MD3.LYSkinSpecs[name] or MD3.Lin67SkinData[name] then
				table.insert(names, name)
			end
		end
		table.sort(names)
		local deadline = os.clock() + 40
		while os.clock() < deadline do
			local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
			local assets = scripts and scripts:FindFirstChild("Assets")
			if assets and assets:FindFirstChild("ViewModels") then
				break
			end
			task.wait(0.5)
		end
		local built, failed = 0, 0
		for _, name in names do
			if MD3.LYSkinReady(name) then
				pcall(MD3.LYEnsureSkin, name) -- also makes sure its viewmodel class is there
				built += 1
			elseif pcall(MD3.LYEnsureSkin, name) and MD3.LYSkinReady(name) then
				built += 1
			else
				failed += 1
			end
			task.wait(0.1)
		end
		pcall(refreshAll)
		Window:Notify({
			Title = "Cosmetics",
			Content = string.format("Custom skins ready: %d / %d%s", built, #names, failed > 0 and (" (" .. failed .. " failed, see Skin report)") or ""),
			Icon = failed > 0 and "error" or "check_circle",
		})
	end)

	track(function()
		equipHook.Installed = false -- the namecall hook stays but only passes calls through
		unhookSkins()
		setWeaponBackground("Default")
		table.clear(dataHook.Spoofed)
		if dataHook.Connection then
			dataHook.Connection:Disconnect()
			dataHook.Connection = nil
		end
		unhookData()
		refreshWeapons()
		fireDataChanged("CosmeticInventory")
	end)
end
setupCosmetics()

-- A tab button decides at creation whether it has room for an icon. Icons that live on a later
-- sprite-sheet page appear after the button was built without that room, and then sat on top of
-- the title (Combat). Once such an icon shows up, move the title over and widen the button.
MD3.LYFixTabIcons = function(window)
	for _, tab in window.Tabs do
		local icon, label, button = tab._icon, tab._label, tab._button
		if icon and label and button then
			local function fit()
				if not icon.Visible or label.Position.X.Offset >= 30 then
					return
				end
				label.Position = UDim2.new(0, 34, 0, 0)
				label.Size = UDim2.new(1, -40, 1, 0)
				button.Size = UDim2.new(0, math.clamp(button.Size.X.Offset + 18, 80, 160), 0, button.Size.Y.Offset)
			end
			track(icon:GetPropertyChangedSignal("Visible"):Connect(fit))
			fit()
		end
	end
end
pcall(MD3.LYFixTabIcons, Window)

-- Movement recorder, the other hub's way: it records what you DO (move direction, look
-- direction, jumps, crouch / slide, equipping, shooting) relative to the map, not where you
-- were, and a replay drives your real character through the game's own input paths:
--   * movement: the active controller's GetMoveVector is replaced while replaying,
--   * look: CameraController.SetRotation,
--   * actions: ClientFighter EquipItem / Input and MechanicsController jumps,
--     crouch and slide.
-- A replay stops itself if you die, leave the match, drift more than the divergence limit
-- from the recorded path, press Stop, or unload the hub; the movement hook is always put back.
-- Scoped in a do-block so its locals stay under Luau's 200-register limit.
do
	local RecorderSection = MiscTab:AddSection("Movement Recorder")
	local RECORDINGS_FOLDER = "Lin67Hub/recordings"
	local settings = { Loop = false, LookSmoothing = 35, AlignSpeed = 180, SnapDistance = 0.2, Diverge = 15, Name = "" }
	local state = { Kind = "Idle" }
	local recording = nil -- the recording last made or loaded
	local session = nil   -- the live recorder / replayer
	local recorderStatus

	local function notify(text, icon)
		Window:Notify({ Title = "Movement Recorder", Content = text, Icon = icon or "info" })
	end

	-- Game access ------------------------------------------------------------------------
	local function controllerModule(name)
		local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
		local folder = scripts and scripts:FindFirstChild("Controllers")
		local module = folder and folder:FindFirstChild(name)
		if module and module:IsA("ModuleScript") then
			local ok, result = pcall(require, module)
			if ok and type(result) == "table" then return result end
		end
		return nil
	end
	local function fighter()
		local controller = controllerModule("FighterController")
		return controller and controller.LocalFighter or nil
	end
	local function mechanics() return controllerModule("MechanicsController") end
	local function cameraRotation()
		local cf = workspace.CurrentCamera.CFrame
		local pitch, yaw = cf:ToOrientation()
		return Vector2.new(pitch, yaw)
	end
	local function setCameraRotation(rotation)
		local controller = controllerModule("CameraController")
		local meta = controller and getmetatable(controller)
		local methods = type(meta) == "table" and rawget(meta, "__index")
		local setRotation = type(methods) == "table" and rawget(methods, "SetRotation")
		if type(setRotation) == "function" then
			coroutine.wrap(pcall)(setRotation, controller, rotation)
		end
	end
	local cachedControls
	local function activeController()
		if not cachedControls then
			local ok, controls = pcall(function()
				return require(LocalPlayer.PlayerScripts:WaitForChild("PlayerModule", 2)):GetControls()
			end)
			if not ok or not controls then return nil, nil end
			cachedControls = controls
		end
		return rawget(cachedControls, "activeController") or cachedControls.activeController, cachedControls
	end
	local function currentMoveVector()
		local _, controls = activeController()
		if not controls then return Vector3.zero end
		local ok, vector = pcall(controls.GetMoveVector, controls)
		return ok and vector or Vector3.zero
	end
	local function rootPart()
		local character = LocalPlayer.Character
		return character and character:FindFirstChild("HumanoidRootPart")
	end
	local function alive()
		local character = LocalPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		return humanoid ~= nil and humanoid.Health > 0
	end
	local function inMatch()
		return LocalPlayer:GetAttribute("EnvironmentID") ~= nil
	end
	-- The map's pivot, so a recording replays on any copy of the map. Outside a match
	-- (nothing tagged) the world itself is the anchor.
	local function mapAnchor()
		local env = LocalPlayer:GetAttribute("EnvironmentID")
		if env ~= nil then
			local tagged = game:GetService("CollectionService"):GetTagged("RaycastWhitelist" .. tostring(env))[1]
			local node = tagged
			while node and node ~= workspace do
				if node.ClassName == "Model" or node:GetAttribute("EnvironmentID") == env then
					return node:GetPivot(), node.Name
				end
				node = node.Parent
			end
		end
		return CFrame.new(), "world"
	end
	local function equippedIndex()
		local lf = fighter()
		local items = lf and (rawget(lf, "Items") or lf.Items)
		local equipped = lf and lf.EquippedItem
		return items and equipped and table.find(items, equipped) or nil
	end
	local function flat(vector)
		return Vector3.new(vector.X, 0, vector.Z)
	end
	-- A world direction expressed as the move vector the controller returns (camera space).
	local function toControlSpace(worldDirection)
		local cf = workspace.CurrentCamera.CFrame
		local look, right = flat(cf.LookVector), flat(cf.RightVector)
		if look.Magnitude < 1e-4 or right.Magnitude < 1e-4 then return Vector3.zero end
		return Vector3.new(worldDirection:Dot(right.Unit), 0, -worldDirection:Dot(look.Unit))
	end

	-- Hooks that see the game's item inputs while recording ----------------------------------
	local function stand(realInstance, overrides)
		return setmetatable({}, { __index = function(_, key)
			local override = overrides[key]
			if override ~= nil then return override end
			local value = realInstance[key]
			if type(value) == "function" then
				return function(_, ...) return value(realInstance, ...) end
			end
			return value
		end })
	end
	local function replaceStorageUpvalue(func, replacement)
		if not (debug and debug.getupvalues) then return nil end
		for _, upvalue in pairs(debug.getupvalues(func)) do
			if type(upvalue) == "table" then
				for key, value in pairs(upvalue) do
					if typeof(value) == "Instance" and pcall(value.IsA, value, "ReplicatedStorage") and value:IsA("ReplicatedStorage") then
						local okSet = pcall(function() upvalue[key] = replacement end)
						if okSet then
							return function() pcall(function() upvalue[key] = value end) end
						end
					end
				end
			end
		end
		return nil
	end
	local function useItemHook(onInput)
		local restore
		pcall(function()
			local class = MD3.LYRequire and MD3.LYRequire("ClientItem")
			local input = class and (rawget(class, "Input") or class.Input)
			if type(input) ~= "function" then return end
			local remote = ReplicatedStorage.Remotes.Replication.Fighter.UseItem
			local replication = stand(ReplicatedStorage.Remotes.Replication, {
				Fighter = stand(ReplicatedStorage.Remotes.Replication.Fighter, {
					UseItem = { FireServer = function(_, objectId, encodedType, args, ...)
						pcall(onInput, objectId, encodedType, args)
						return remote:FireServer(objectId, encodedType, args, ...)
					end },
				}),
			})
			local fake = stand(ReplicatedStorage, { Remotes = stand(ReplicatedStorage.Remotes, { Replication = replication }) })
			restore = replaceStorageUpvalue(input, fake)
		end)
		return restore
	end
	-- The game's EnumLibrary turns names into the bytes the UseItem remote carries (and back).
	local inputNames = { "StartShooting", "StartAiming", "StartReloading" }
	local function decodeInput(encoded)
		local ok, library = pcall(function()
			return require(ReplicatedStorage.Modules.EnumLibrary)
		end)
		if not ok or type(library) ~= "table" then return nil end
		if type(library.FromEnum) == "function" then
			local decoded, name = pcall(function() return library:FromEnum(encoded) end)
			if decoded and type(name) == "string" then return name end
		end
		for _, name in inputNames do
			local made, value = pcall(function() return library:ToEnum(name) end)
			if made and value == encoded then return name end
		end
		return nil
	end

	-- Recording ------------------------------------------------------------------------------
	local function beginRecording()
		local root = rootPart()
		if not (root and alive()) then
			notify("No character", "error")
			return nil
		end
		local anchor, mapName = mapAnchor()
		local inverse = anchor:Inverse()
		local rotation = cameraRotation()
		local rec = {
			MapName = mapName,
			StartCFrame = inverse * root.CFrame,
			StartEquippedIndex = equippedIndex(),
			Keypoints = { { Offset = 0, Action = { Kind = "Look", CFrame = inverse * CFrame.fromOrientation(rotation.X, rotation.Y, 0) } } },
			Positions = {},
		}
		local started = os.clock()
		local last = {
			move = Vector3.zero, camera = rotation, equipped = rec.StartEquippedIndex,
			crouching = false, sliding = false, position = -1,
		}
		local function offset() return os.clock() - started end
		local function record(action)
			table.insert(rec.Keypoints, { Offset = offset(), Action = action })
		end
		local connections = {}
		table.insert(connections, UserInputService.JumpRequest:Connect(function()
			record({ Kind = "Jump" })
		end))
		local restores = {
			useItemHook(function(_, encodedType)
				local name = decodeInput(encodedType)
				if name then record({ Kind = "ItemInput", InputType = name }) end
			end),
		}
		local function update()
			local move = currentMoveVector()
			if move ~= last.move then last.move = move; record({ Kind = "Move", Direction = move }) end
			local camera = cameraRotation()
			if (camera - last.camera).Magnitude > 1e-4 then
				last.camera = camera
				record({ Kind = "Look", CFrame = inverse * CFrame.fromOrientation(camera.X, camera.Y, 0) })
			end
			local equipped = equippedIndex()
			if equipped ~= last.equipped then
				last.equipped = equipped
				if equipped ~= nil then record({ Kind = "Equip", Index = equipped }) end
			end
			local mech = mechanics()
			if mech then
				local crouching = rawget(mech, "IsCrouching") == true or mech.IsCrouching == true
				if crouching ~= last.crouching then last.crouching = crouching; record({ Kind = "Crouch", Crouching = crouching }) end
				local sliding = rawget(mech, "IsSliding") == true or mech.IsSliding == true
				if sliding ~= last.sliding then
					last.sliding = sliding
					if sliding then record({ Kind = "Slide" }) end
				end
			end
			local now = os.clock()
			if now - last.position >= 0.1 and rootPart() then
				last.position = now
				table.insert(rec.Positions, { Offset = offset(), Position = inverse * rootPart().Position })
			end
		end
		return {
			Kind = "Recording",
			Update = update,
			Finish = function()
				for _, connection in connections do connection:Disconnect() end
				for _, restore in restores do if restore then restore() end end
				return rec
			end,
			Duration = function() return offset() end,
			Count = function() return #rec.Keypoints end,
		}
	end

	-- Replaying ------------------------------------------------------------------------------
	local function beginReplay(rec)
		local anchor, mapName = mapAnchor()
		if rec.MapName ~= mapName then
			notify(("Recording is for %s, not %s"):format(tostring(rec.MapName), tostring(mapName)), "error")
			return nil
		end
		local controller = activeController()
		if not controller then
			notify("No active controller to drive", "error")
			return nil
		end
		local lf = fighter()
		local mech = mechanics()
		local moveVector = Vector3.zero
		local previousMove = rawget(controller, "GetMoveVector")
		rawset(controller, "GetMoveVector", function() return moveVector end)
		if rec.StartEquippedIndex and lf and type(lf.EquipItem) == "function" then
			task.spawn(pcall, lf.EquipItem, lf, rec.StartEquippedIndex)
		end
		local startLook
		for _, keypoint in rec.Keypoints do
			if keypoint.Action.Kind == "Look" then
				local pitch, yaw = (anchor * keypoint.Action.CFrame):ToOrientation()
				startLook = Vector2.new(pitch, yaw)
				break
			end
		end
		local phase = { Kind = "Aligning", Elapsed = 0, Stuck = 0, Best = math.huge }
		local look = nil
		local index, positionIndex, offset = 1, 1, 0
		local finished = false

		local function angleDelta(from, to)
			return Vector2.new(to.X - from.X, (to.Y - from.Y + math.pi) % (math.pi * 2) - math.pi)
		end
		local function lerpLook(from, to, dt)
			local alpha = 1 - math.exp(-dt / math.max(settings.LookSmoothing / 100 * 0.3, 1e-4))
			local delta = angleDelta(from, to)
			return Vector2.new(from.X + delta.X * alpha, from.Y + delta.Y * alpha)
		end
		local function stop(reason)
			if finished then return end
			finished = true
			rawset(controller, "GetMoveVector", previousMove)
			if mech and type(mech.SetCrouching) == "function" then pcall(mech.SetCrouching, mech, false) end
			session = nil
			state.Kind = "Idle"
			if recorderStatus then recorderStatus:Set("Status: Idle") end
			notify(reason, reason == "Completed" and "check_circle" or "info")
		end
		local function diverged(at)
			local positions = rec.Positions
			if #positions == 0 then return false end
			while positionIndex < #positions and positions[positionIndex + 1].Offset <= at do
				positionIndex += 1
			end
			local from, to = positions[positionIndex], positions[positionIndex + 1]
			local expected = from.Position
			if to and to.Offset > from.Offset then
				expected = from.Position:Lerp(to.Position, math.clamp((at - from.Offset) / (to.Offset - from.Offset), 0, 1))
			end
			local root = rootPart()
			return root ~= nil and (anchor:PointToWorldSpace(expected) - root.Position).Magnitude > settings.Diverge
		end
		local function perform(action)
			if action.Kind == "Move" then
				moveVector = action.Direction
			elseif action.Kind == "Look" then
				local pitch, yaw = (anchor * action.CFrame):ToOrientation()
				look = Vector2.new(pitch, yaw)
			elseif action.Kind == "Equip" and lf and type(lf.EquipItem) == "function" then
				task.spawn(pcall, lf.EquipItem, lf, action.Index)
			elseif action.Kind == "ItemInput" and lf and type(lf.Input) == "function" then
				task.spawn(pcall, lf.Input, lf, action.InputType)
			elseif action.Kind == "QuickAttack" and lf and type(lf.QuickAttack) == "function" then
				task.spawn(pcall, lf.QuickAttack, lf, action.AttackType)
			elseif action.Kind == "Jump" and mech then
				if rawget(mech, "IsSliding") == true and type(mech.HighJump) == "function" then
					pcall(mech.HighJump, mech)
				else
					if type(mech.DoubleJumpRequest) == "function" then pcall(mech.DoubleJumpRequest, mech) end
					if type(mech.JumpRequest) == "function" then pcall(mech.JumpRequest, mech) end
				end
			elseif action.Kind == "Crouch" and mech and type(mech.SetCrouching) == "function" then
				pcall(mech.SetCrouching, mech, action.Crouching)
			elseif action.Kind == "Slide" and mech and type(mech.Slide) == "function" then
				task.spawn(pcall, mech.Slide, mech)
			end
		end
		local function update(dt)
			if finished then return end
			if not (alive() and inMatch() == (mapName ~= "world")) then
				stop("Stopped (not alive or left the match)")
				return
			end
			local root = rootPart()
			if not root then stop("Stopped") return end
			if phase.Kind == "Aligning" then
				phase.Elapsed += dt
				local cameraAligned = true
				if startLook then
					local current = cameraRotation()
					local delta = angleDelta(current, startLook)
					local step = math.rad(settings.AlignSpeed) * dt
					local magnitude = delta.Magnitude
					if magnitude <= 0.0017453292519943296 then
						cameraAligned = true
						setCameraRotation(startLook)
					else
						cameraAligned = false
						setCameraRotation(current + delta.Unit * math.min(magnitude * (1 - math.exp(-dt / math.max(settings.LookSmoothing / 100 * 0.3, 1e-4))), step))
					end
				end
				local toStart = flat((anchor * rec.StartCFrame).Position - root.Position)
				local distance = toStart.Magnitude
				local close = distance <= settings.SnapDistance
				moveVector = close and Vector3.zero or toControlSpace(toStart.Unit)
				if distance < phase.Best - 0.01 then phase.Best, phase.Stuck = distance, 0 else phase.Stuck += dt end
				if (close and cameraAligned) or phase.Stuck >= 1 then
					moveVector = Vector3.zero
					if phase.Elapsed >= 0.5 then phase = { Kind = "Playing" } offset = 0 end
				end
				if phase.Elapsed > 8 then stop("Couldn't reach the start of the recording") end
				return
			end
			offset += dt
			if diverged(offset) then stop("Diverged from the recorded path") return end
			local keypoints = rec.Keypoints
			while index <= #keypoints and offset >= keypoints[index].Offset do
				perform(keypoints[index].Action)
				index += 1
			end
			if look then
				setCameraRotation(lerpLook(cameraRotation(), look, dt))
			end
			if index > #keypoints then
				moveVector = Vector3.zero
				if settings.Loop then
					stop("Completed")
					task.defer(function()
						if state.Kind == "Idle" then
							local again = beginReplay(rec)
							if again then session = again; state.Kind = "Replaying" end
						end
					end)
				else
					stop("Completed")
				end
			end
		end
		return { Kind = "Replaying", Update = update, Finish = function() stop("Stopped") end }
	end

	-- Controls ---------------------------------------------------------------------------------
	local function setStatus(text)
		if recorderStatus then recorderStatus:Set(text) end
	end
	local function stopAll()
		if session then
			local live = session
			session = nil
			if live.Kind == "Recording" then
				recording = live.Finish()
				notify(("Recorded %d actions, %.1fs"):format(#recording.Keypoints, live.Duration()), "check_circle")
			else
				live.Finish()
			end
		end
		state.Kind = "Idle"
		setStatus("Status: Idle")
	end
	local function startRecordingNow()
		stopAll()
		local live = beginRecording()
		if live then
			session = live
			state.Kind = "Recording"
			setStatus("Status: Recording")
		end
	end
	local function startReplayNow()
		if not recording or #recording.Keypoints < 2 then
			notify("Record or load something first", "error")
			return
		end
		stopAll()
		local live = beginReplay(recording)
		if live then
			session = live
			state.Kind = "Replaying"
			setStatus("Status: Replaying")
		end
	end
	track(RunService.Heartbeat:Connect(function(dt)
		local live = session
		if not live then return end
		local ok, err = pcall(live.Update, dt)
		if not ok then
			warn("Lin67 Hub movement recorder:", err)
			stopAll()
		end
	end))
	track(stopAll)

	-- Saving ------------------------------------------------------------------------------------
	local function recordingPath(name)
		return ("%s/%s.json"):format(RECORDINGS_FOLDER, name)
	end
	local function listRecordings()
		local names = {}
		for _, path in MD3.Env.ListFiles(RECORDINGS_FOLDER) do
			local name = path:gsub("\\", "/"):match("([^/]+)%.json$")
			if name then table.insert(names, name) end
		end
		table.sort(names)
		return names
	end
	local recordingDropdown
	local function refreshRecordings()
		if recordingDropdown then recordingDropdown:SetOptions(listRecordings()) end
	end
	local function packVector(vector) return { vector.X, vector.Y, vector.Z } end
	local function serialize(rec)
		local keypoints = {}
		for _, keypoint in rec.Keypoints do
			local action, packed = keypoint.Action, { Kind = keypoint.Action.Kind }
			if action.Kind == "Move" then packed.Direction = packVector(action.Direction)
			elseif action.Kind == "Look" then packed.CFrame = { action.CFrame:GetComponents() }
			elseif action.Kind == "Equip" then packed.Index = action.Index
			elseif action.Kind == "ItemInput" then packed.InputType = action.InputType
			elseif action.Kind == "QuickAttack" then packed.AttackType = action.AttackType
			elseif action.Kind == "Crouch" then packed.Crouching = action.Crouching end
			table.insert(keypoints, { keypoint.Offset, packed })
		end
		local positions = {}
		for _, position in rec.Positions do
			table.insert(positions, { position.Offset, position.Position.X, position.Position.Y, position.Position.Z })
		end
		return HttpService:JSONEncode({
			Version = 2, MapName = rec.MapName, StartCFrame = { rec.StartCFrame:GetComponents() },
			StartEquippedIndex = rec.StartEquippedIndex, Keypoints = keypoints, Positions = positions,
		})
	end
	local function deserialize(text)
		local ok, data = pcall(function() return HttpService:JSONDecode(text) end)
		if not ok or type(data) ~= "table" or data.Version ~= 2 then return nil end
		local rec = {
			MapName = data.MapName, StartCFrame = CFrame.new(table.unpack(data.StartCFrame)),
			StartEquippedIndex = data.StartEquippedIndex, Keypoints = {}, Positions = {},
		}
		for _, entry in data.Keypoints do
			local packed, action = entry[2], { Kind = entry[2].Kind }
			if packed.Kind == "Move" then action.Direction = Vector3.new(table.unpack(packed.Direction))
			elseif packed.Kind == "Look" then action.CFrame = CFrame.new(table.unpack(packed.CFrame))
			elseif packed.Kind == "Equip" then action.Index = packed.Index
			elseif packed.Kind == "ItemInput" then action.InputType = packed.InputType
			elseif packed.Kind == "QuickAttack" then action.AttackType = packed.AttackType
			elseif packed.Kind == "Crouch" then action.Crouching = packed.Crouching end
			table.insert(rec.Keypoints, { Offset = entry[1], Action = action })
		end
		for _, entry in data.Positions do
			table.insert(rec.Positions, { Offset = entry[1], Position = Vector3.new(entry[2], entry[3], entry[4]) })
		end
		return rec
	end
	local function saveRecording()
		local name = trim(settings.Name):gsub("[^%w%-_ ]", "")
		if name == "" then notify("Enter a recording name first", "error") return end
		if not recording or #recording.Keypoints < 2 then notify("Nothing recorded yet", "error") return end
		MD3.Env.MakeFolder(RECORDINGS_FOLDER)
		local ok = MD3.Env.WriteFile(recordingPath(name), serialize(recording))
		notify(ok and ("Saved " .. name) or "Your executor can't write files", ok and "save" or "error")
		refreshRecordings()
	end
	local function loadRecording(name)
		local text = name and MD3.Env.ReadFile(recordingPath(name))
		local rec = text and deserialize(text)
		if not rec then notify("Couldn't read " .. tostring(name) .. " (old format recordings can't be used)", "error") return end
		stopAll()
		recording = rec
		notify(("Loaded %s (%d actions, map %s)"):format(name, #rec.Keypoints, tostring(rec.MapName)), "folder_open")
	end

	recorderStatus = RecorderSection:AddLabel("Status: Idle")
	RecorderSection:AddKeybind({
		Title = "Record", Description = "Start / stop recording your movement", Mode = "Press", Flag = "RecordKey",
		Callback = function() if state.Kind == "Recording" then stopAll() else startRecordingNow() end end,
	})
	RecorderSection:AddKeybind({
		Title = "Replay", Description = "Start / stop replaying the recording with your character", Mode = "Press", Flag = "ReplayKey",
		Callback = function() if state.Kind == "Replaying" then stopAll() else startReplayNow() end end,
	})
	RecorderSection:AddButton({ Title = "Record", Icon = "radio_button_checked", IconColor = "Error", Callback = startRecordingNow })
	RecorderSection:AddButton({ Title = "Replay", Icon = "play_arrow", Callback = startReplayNow })
	RecorderSection:AddButton({ Title = "Stop", Icon = "stop", Callback = stopAll })
	RecorderSection:AddToggle({ Title = "Loop replay", Default = settings.Loop, Flag = "ReplayLoop", Callback = function(on) settings.Loop = on end })
	RecorderSection:AddSlider({
		Title = "Look smoothing", Min = 0, Max = 100, Step = 1, Default = settings.LookSmoothing, Flag = "ReplayLookSmoothing",
		Callback = function(value) settings.LookSmoothing = value end,
	})
	RecorderSection:AddSlider({
		Title = "Align speed", Min = 30, Max = 720, Step = 10, Default = settings.AlignSpeed, Suffix = "°/s", Flag = "ReplayAlignSpeed",
		Callback = function(value) settings.AlignSpeed = value end,
	})
	RecorderSection:AddSlider({
		Title = "Snap distance", Min = 0.05, Max = 2, Step = 0.05, Default = settings.SnapDistance, Suffix = " studs", Flag = "ReplaySnapDistance",
		Callback = function(value) settings.SnapDistance = value end,
	})
	RecorderSection:AddSlider({
		Title = "Divergence limit", Min = 3, Max = 40, Step = 1, Default = settings.Diverge, Suffix = " studs", Flag = "ReplayDivergence",
		Callback = function(value) settings.Diverge = value end,
	})
	RecorderSection:AddInput({ Title = "Recording name", Placeholder = "e.g. arena-route", Flag = "RecordingName", Callback = function(text) settings.Name = text end })
	RecorderSection:AddButton({ Title = "Save recording", Icon = "save", Callback = saveRecording })
	recordingDropdown = RecorderSection:AddDropdown({ Title = "Saved recordings", Options = listRecordings() })
	RecorderSection:AddButton({ Title = "Load selected", Icon = "folder", Callback = function() loadRecording(recordingDropdown:Get()) end })
	RecorderSection:AddButton({
		Title = "Delete selected", Icon = "delete", IconColor = "Error",
		Callback = function()
			local name = recordingDropdown:Get()
			if name and MD3.Env.DeleteFile(recordingPath(name)) then notify("Deleted " .. name, "delete") end
			refreshRecordings()
		end,
	})
end

local Server = MiscTab:AddSection("Server")

Server:AddButton({
	Title = "Rejoin",
	Description = "Teleport back into this server",
	Icon = "refresh",
	Callback = function()
		TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
	end,
})

Server:AddButton({
	Title = "Server hop",
	Description = "Join a different public server",
	Icon = "swap_horiz",
	Callback = function()
		local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100"):format(game.PlaceId)
		local body = MD3.Env.HttpGet(url)
		local ok, data = pcall(function()
			return HttpService:JSONDecode(body)
		end)
		if not ok or type(data) ~= "table" or type(data.data) ~= "table" then
			Window:Notify({ Title = "Server hop failed", Content = "Couldn't read the server list", Icon = "error" })
			return
		end
		local candidates = {}
		for _, server in data.data do
			if server.id ~= game.JobId and (server.playing or 0) < (server.maxPlayers or 0) then
				table.insert(candidates, server.id)
			end
		end
		if #candidates == 0 then
			Window:Notify({ Title = "Server hop", Content = "No other open servers found", Icon = "info" })
			return
		end
		TeleportService:TeleportToPlaceInstance(game.PlaceId, candidates[math.random(#candidates)], LocalPlayer)
	end,
})

-- Every open public server (all pages), except this one.
local function openServers()
	local servers, cursor = {}, nil
	repeat
		local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(game.PlaceId)
		if cursor then
			url ..= "&cursor=" .. cursor
		end
		local ok, data = pcall(function()
			return HttpService:JSONDecode(MD3.Env.HttpGet(url))
		end)
		if not ok or type(data) ~= "table" or type(data.data) ~= "table" then
			break
		end
		for _, server in data.data do
			if server.id ~= game.JobId and (server.playing or 0) < (server.maxPlayers or 0) then
				table.insert(servers, server)
			end
		end
		cursor = data.nextPageCursor
	until not cursor
	return servers
end

local function joinServerBy(better, label)
	local servers = openServers()
	if #servers == 0 then
		Window:Notify({ Title = "Server hop", Content = "No other open servers found", Icon = "info" })
		return
	end
	table.sort(servers, function(a, b)
		return better(a.playing, b.playing)
	end)
	local server = servers[1]
	Window:Notify({ Title = label, Content = ("%d / %d players"):format(server.playing, server.maxPlayers), Icon = "swap_horiz" })
	TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, LocalPlayer)
end

Server:AddButton({
	Title = "Join smallest server",
	Description = "The open server with the fewest players",
	Icon = "swap_horiz",
	Callback = function()
		joinServerBy(function(a, b)
			return a < b
		end, "Joining smallest server")
	end,
})

Server:AddButton({
	Title = "Join biggest server",
	Description = "The open server with the most players",
	Icon = "swap_horiz",
	Callback = function()
		joinServerBy(function(a, b)
			return a > b
		end, "Joining biggest server")
	end,
})

Server:AddButton({
	Title = "Copy JobId",
	Icon = "content_copy",
	Callback = function()
		local ok = MD3.Env.SetClipboard(game.JobId)
		Window:Notify({ Title = ok and "Copied" or "Clipboard unavailable", Content = game.JobId, Icon = "content_copy" })
	end,
})

--==========================================================================--
--== Combat, ESP, Character and more (ported)                             ==--
--==========================================================================--

-- Combat > Gun. Created by the ported features; the weapon tweaks below add to it.
local GunSection = nil

-- A function of its own so its locals don't count against the main chunk's.
local function loadPortedFeatures()
	-- A small Linoria-style front over MD3 sections (Toggles / Options,
	-- groupbox:AddToggle(idx, info), :AddColorPicker, :AddKeyPicker, dependency
	-- boxes), so the ported code keeps its original shape. Every element is saved
	-- under its Linoria index as the MD3 Flag.

	local Toggles, Options = {}, {}
	local connections = {}
	local unloaders = {}
	local guis = setmetatable({}, { __mode = "k" })
	local drawings = setmetatable({}, { __mode = "k" })
	local boxes = {}

	local Port = {
		Unloaded = false,
		GuiParent = MD3.Env.GetGuiParent(),
	}

	Port.Holder = own(Instance.new("Folder"))
	Port.Holder.Name = MD3.Env.RandomName()
	Port.Holder.Parent = Port.GuiParent

	function Port.Track(connection)
		table.insert(connections, connection)
		return connection
	end

	function Port.OnUnload(fn)
		table.insert(unloaders, fn)
	end

	function Port.Gui(gui)
		gui.Name = MD3.Env.RandomName()
		gui.ResetOnSpawn = false
		MD3.Env.ProtectGui(gui)
		gui.Parent = Port.GuiParent
		guis[own(gui)] = true
		return gui
	end

	-- Drawing objects are removed on unload too.
	local drawingNew = Drawing and Drawing.new
	local Drawing = drawingNew and setmetatable({
		new = function(kind)
			local object = drawingNew(kind)
			drawings[object] = true
			return object
		end,
	}, { __index = Drawing }) or nil

	local INSTANCE_GAMEPLAY_OVERLAY_ORDER = 10

	-- Lin67 never hides gameplay overlays while its window is open.
	local function isInstanceMenuOpen()
		return false
	end
	local shouldSuppressGameplayOverlays = isInstanceMenuOpen

	local function instanceSafeRequire(module, timeout)
		local deadline = os.clock() + (timeout or 10)
		local lastError
		repeat
			local ok, result = pcall(require, module)
			if ok then
				return result
			end
			lastError = result
			task.wait(0.1)
		until os.clock() > deadline
		error("Lin67 Hub: couldn't load " .. module:GetFullName() .. " (" .. tostring(lastError) .. ")")
	end

	getgenv().InstanceConfigLoading = false

	local function titleCase(text)
		text = tostring(text or ""):gsub("[:%s]+$", "")
		if text == "enable" or text == "enabled" then
			return "Enabled"
		end
		return (text:gsub("^%l", string.upper))
	end

	local function refreshBoxes()
		for _, box in boxes do
			local visible = box.Parent == nil or box.Parent.Visible
			if visible then
				for _, dependency in box.Dependencies do
					if dependency[1].Value ~= dependency[2] then
						visible = false
						break
					end
				end
			end
			box.Visible = visible
			for _, member in box.Members do
				member:SetVisible(visible)
			end
		end
	end

	local Library = {
		Unloaded = false,
		MainColor = Color3.fromRGB(28, 28, 28),
		BackgroundColor = Color3.fromRGB(20, 20, 20),
		OutlineColor = Color3.fromRGB(50, 50, 50),
		FontColor = Color3.new(1, 1, 1),
		ScreenGui = Port.Gui(Instance.new("ScreenGui")),
	}
	Library.ScreenGui.IgnoreGuiInset = true
	Library.ScreenGui.DisplayOrder = 998

	function Library:Notify(text, duration)
		Window:Notify({ Title = "Lin67 Hub", Content = tostring(text), Icon = "info", Duration = duration })
	end

	function Library:Create(className, props)
		local instance = Instance.new(className)
		for property, value in props do
			if property ~= "Parent" then
				instance[property] = value
			end
		end
		instance.Parent = props.Parent
		return instance
	end

	function Library:CreateLabel(props)
		local label = Library:Create("TextLabel", { BackgroundTransparency = 1 })
		for property, value in props do
			if property ~= "Parent" then
				label[property] = value
			end
		end
		label.Parent = props.Parent
		return label
	end

	function Library:AddToRegistry() end

	function Library:UpdateDependencyBoxes()
		refreshBoxes()
	end

	-- Elements -------------------------------------------------------------------

	local Element = {}
	Element.__index = Element

	function Element:_fire(raw)
		local value = if self._fromMD3 then self._fromMD3(raw) else raw
		self.Value = value
		for _, addon in self.Addons do
			if addon.SyncToggleState then
				addon.Toggled = value == true
				addon._md3:SetState(addon.Toggled)
			end
		end
		-- Color pickers also hand over the end of their gradient as a second value.
		local second = nil
		if self.Type == "ColorPicker" and self._md3 and self._md3.GetColor2 then
			second = self._md3:GetColor2()
		end
		if self._callback then
			self._callback(value, second)
		end
		for _, fn in self._changed do
			local ok, err = pcall(fn, value, second)
			if not ok then
				warn("Lin67 Hub:", err)
			end
		end
		refreshBoxes()
	end

	function Element:SetValue(value)
		self._md3:Set(value)
	end

	function Element:OnChanged(fn)
		table.insert(self._changed, fn)
		fn(self.Value)
	end

	function Element:SetValues(values)
		self.Values = values
		self._md3:SetOptions(values)
	end

	function Element:SetVisible(visible)
		self._md3:SetVisible(visible)
	end

	function Element:AddColorPicker(idx, info)
		self._group:_colorPicker(idx, info, self)
		return self
	end

	function Element:AddKeyPicker(idx, info)
		self._group:_keyPicker(idx, info, self)
		return self
	end

	local KeyPicker = setmetatable({}, { __index = Element })
	KeyPicker.__index = KeyPicker

	function KeyPicker:GetState()
		if self.Mode == "Always" then
			return true
		elseif self.Mode == "Hold" then
			return self.Held
		end
		return self.Toggled
	end

	-- The MD3 keybind runs in Hold mode (press and release both arrive here);
	-- Toggle / Hold behave like Linoria's key picker on top of that.
	function KeyPicker:_key(down)
		if self.Mode == "Always" then
			return
		end
		if self.Mode == "Hold" then
			local was = self.Held
			self.Held = down
			if was ~= down then
				local parent = self._parent
				if self.SyncToggleState and parent and parent.Type == "Toggle" then
					parent:SetValue(down)
				elseif self._callback and self._holdCallback then
					self._callback(down)
				end
			end
			self._md3:SetState(down)
			return
		end
		if self.Mode == "Toggle" and down then
			local parent = self._parent
			if self.SyncToggleState and parent and parent.Type == "Toggle" then
				parent:SetValue(not parent.Value)
			else
				self.Toggled = not self.Toggled
			end
			if self._callback then
				self._callback(self.Toggled)
			end
		end
		self._md3:SetState(self.Toggled)
	end

	local Group = {}
	Group.__index = Group

	local function newGroup(section, box)
		return setmetatable({ _section = section, _box = box }, Group)
	end

	function Port.Section(tab, title)
		return newGroup(tab:AddSection(title), nil)
	end

	function Group:_add(md3Element)
		if self._box then
			table.insert(self._box.Members, md3Element)
			md3Element:SetVisible(self._box.Visible)
		end
		return md3Element
	end

	function Group:_wrap(kind, info, class)
		local element = setmetatable({
			Type = kind,
			Text = info.Text,
			Addons = {},
			_group = self,
			_changed = {},
			_callback = info.Callback,
		}, class or Element)
		return element, function(value)
			element:_fire(value)
		end
	end

	function Group:AddToggle(idx, info)
		local element, fire = self:_wrap("Toggle", info)
		element.Value = info.Default == true
		element._md3 = self:_add(self._section:AddToggle({
			Title = titleCase(info.Text),
			Description = info.Tooltip,
			Default = element.Value,
			Flag = idx,
			Callback = fire,
		}))
		Toggles[idx] = element
		return element
	end

	function Group:AddSlider(idx, info)
		local element, fire = self:_wrap("Slider", info)
		local min, max = info.Min or 0, info.Max or 100
		element.Value = math.clamp(tonumber(info.Default) or min, min, max)
		element._md3 = self:_add(self._section:AddSlider({
			Title = titleCase(info.Text),
			Min = min,
			Max = max,
			Step = 10 ^ -(info.Rounding or 0),
			Default = element.Value,
			Suffix = info.Suffix,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:AddDualSlider(leftIdx, rightIdx, leftInfo, rightInfo)
		return self:AddSlider(leftIdx, leftInfo), self:AddSlider(rightIdx, rightInfo)
	end

	local function toSet(list)
		local set = {}
		for key, value in list or {} do
			if type(key) == "number" then
				set[value] = true
			elseif value == true then
				set[key] = true
			end
		end
		return set
	end

	function Group:AddDropdown(idx, info)
		local element, fire = self:_wrap("Dropdown", info)
		local values = info.Values or {}
		local default = info.Default
		if info.Multi then
			local list = {}
			for name in toSet(type(default) == "table" and default or {}) do
				table.insert(list, name)
			end
			default = list
			element._fromMD3 = toSet
			element.Value = toSet(list)
		else
			if type(default) == "number" then
				default = values[default]
			end
			element.Value = default
		end
		element.Values = values
		element.Multi = info.Multi == true
		element._md3 = self:_add(self._section:AddDropdown({
			Title = titleCase(info.Text or idx),
			Options = values,
			Default = default,
			Multi = info.Multi == true,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:AddInput(idx, info)
		local element, fire = self:_wrap("Input", info)
		element.Value = tostring(info.Default or "")
		element._md3 = self:_add(self._section:AddInput({
			Title = titleCase(info.Text),
			Default = element.Value,
			Placeholder = info.Placeholder,
			Numeric = info.Numeric == true,
			Finished = info.Finished ~= false,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:_colorPicker(idx, info, parent)
		local element, fire = self:_wrap("ColorPicker", info)
		local title = info.Title and titleCase(info.Title)
			or (parent and titleCase(parent.Text) .. " color")
			or titleCase(idx)
		element.Value = info.Default or Color3.new(1, 1, 1)
		local default = element.Value
		if typeof(info.Default2) == "Color3" then
			-- A pair of colors becomes a two-stop gradient (flat when both match).
			default = {
				Color = element.Value,
				Mode = info.Default2 ~= element.Value and "Gradient" or "Solid",
				Anim = "None",
				Speed = 1,
				Stops = { { Pos = 0, Color = element.Value }, { Pos = 1, Color = info.Default2 } },
			}
		end
		element._md3 = self:_add(self._section:AddColorPicker({
			Title = title,
			Default = default,
			Flag = idx,
			Callback = fire,
		}))
		Options[idx] = element
		return element
	end

	function Group:_keyPicker(idx, info, parent)
		local picker = self:_wrap("KeyPicker", info, KeyPicker)
		picker.Mode = if info.SyncToggleState then "Toggle" else info.Mode or "Toggle"
		picker.SyncToggleState = info.SyncToggleState == true
		picker.Toggled = false
		picker.Held = false
		picker.Value = info.Default or "None"
		picker._parent = parent
		local name = titleCase(info.Text or (parent and parent.Text) or idx)
		picker._md3 = self:_add(self._section:AddKeybind({
			Title = name .. " key",
			Default = info.Default,
			Mode = "Hold",
			Notify = false,
			Flag = idx,
			Callback = function(down)
				picker:_key(down)
			end,
			ChangedCallback = function(key)
				picker.Value = key and key.Name or "None"
			end,
		}))
		if parent then
			table.insert(parent.Addons, picker)
		end
		local onToggle = parent and parent.Type == "Toggle" and parent._md3 ~= nil
		if onToggle and not (info.Modes and #info.Modes > 1) then
			-- Every key on a toggle can run as Always / Hold / Toggle. Callbacks that
			-- only know on/off (Callback(state)) also get the Hold state.
			info.Modes = { "Always", "Hold", "Toggle" }
			picker._holdCallback = true
		end
		if info.Modes and #info.Modes > 1 then
			local modes = self:AddDropdown(idx .. "Mode", {
				Text = name .. " key mode",
				Values = info.Modes,
				Default = picker.Mode,
				Callback = function(mode)
					picker.Mode = mode
					picker.Toggled = false
					picker.Held = false
					picker._md3:SetState(false)
				end,
			})
			picker.Modes = modes
		end
		-- On a toggle: the key (and mode) move into the toggle's gear popup instead of
		-- taking rows of their own.
		if parent and parent.Type == "Toggle" and parent._md3 then
			local ok, attached = pcall(MD3.GearUI.attach, {
				Section = self._section,
				Toggle = parent._md3,
				Key = picker._md3,
				Modes = picker.Modes and {
					Values = info.Modes,
					Get = function() return picker.Mode end,
					Set = function(mode) picker.Modes:SetValue(mode) end,
				} or nil,
			})
			if ok and attached and picker.Modes and picker.Modes._md3 then
				-- keep the mode dropdown out of the section (it is driven from the popup)
				local row = picker.Modes._md3.Instance
				local holder = Window.Gui and Window.Gui:FindFirstChild("KeyGearHolder")
				if row and holder then
					row.Parent = holder
				end
			end
		end
		Options[idx] = picker
		return picker
	end

	function Group:AddKeyPicker(idx, info)
		return self:_keyPicker(idx, info, nil)
	end

	function Group:AddButton(text, callback)
		if type(text) == "table" then
			text, callback = text.Text, text.Func or text.Callback
		end
		return self:_add(self._section:AddButton({ Title = titleCase(text), Callback = callback }))
	end

	function Group:AddLabel(text)
		return self:_add(self._section:AddLabel(tostring(text)))
	end

	function Group:AddDivider()
		return self:_add(self._section:AddDivider())
	end

	function Group:AddDependencyBox()
		local box = { Members = {}, Dependencies = {}, Visible = true, Parent = self._box }
		table.insert(boxes, box)
		local group = newGroup(self._section, box)
		function group:SetupDependencies(dependencies)
			box.Dependencies = dependencies
			refreshBoxes()
		end
		return group
	end

	-- Unload: switch every feature off through its own callback (that's what
	-- restores what it changed), then drop connections, GUIs and drawings.
	track(function()
		Port.Unloaded = true
		Library.Unloaded = true
		for _, element in Toggles do
			if element.Value == true and element._callback then
				pcall(element._callback, false)
			end
		end
		for _, element in Options do
			if element.Type == "KeyPicker" and (element.Toggled or element.Held) then
				element.Toggled, element.Held = false, false
				if element._callback then
					pcall(element._callback, false)
				end
			end
		end
		for _, connection in connections do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(connections)
		for index = #unloaders, 1, -1 do
			pcall(unloaders[index])
		end
		for gui in guis do
			pcall(function()
				gui:Destroy()
			end)
		end
		for object in drawings do
			pcall(function()
				object:Remove()
			end)
		end
		Port.Holder:Destroy()
	end)

	-- Connections made per event (a sound, a character) pile up; forget the
	-- ones that are already gone.
	task.spawn(function()
		while not Port.Unloaded do
			task.wait(30)
			for index = #connections, 1, -1 do
				if not connections[index].Connected then
					table.remove(connections, index)
				end
			end
		end
	end)

