			Default = 0,
			Min = 0,
			Max = 1,
			Rounding = 2,
			Suffix = "x",
			Callback = function(val)
				getgenv().CombatMods.FireCooldownMult = val
			end
		})

		LeftGroup:AddToggle("NoSpread", {
			Text = "no spread",
			-- The camera data has no spread (identical every call); the server rolls the
			-- spread using the packet's aiming flag, so no spread = always report "aiming".
			Description = "Report every shot as aimed so the server uses the weapon's aim spread (0 for most guns); also straightens your tracers",
			Default = false,
			Callback = function(val)
				getgenv().CombatMods.NoSpread = val
			end
		})

		LeftGroup:AddToggle("NoRecoil", {
			Text = "no recoil",
			Default = false,
			Callback = function(val)
				getgenv().CombatMods.NoRecoil = val
			end
		})

		LeftGroup:AddToggle("MaxAccuracy", {
			Text = "max accuracy",
			Default = false,
			Callback = function(val)
				getgenv().CombatMods.MaxAccuracy = val
			end
		})

		LeftGroup:AddToggle("RapidAttack", {
			Text = "rapid attack",
			Default = false,
			Callback = function(val)
				getgenv().CombatMods.RapidAttack = val
			end
		})

		LeftGroup:AddSlider("RapidAttackCooldown", {
			Text = "attack cooldown",
			Default = 0,
			Min = 0,
			Max = 1,
			Rounding = 2,
			Suffix = "x",
			Callback = function(val)
				getgenv().CombatMods.AttackCooldownMult = val
			end
		})

		LeftGroup:AddToggle("DisableGunSounds", {
			Text = "disable gun sounds",
			Default = _G.Features.DisableGunSounds,
			Callback = function(val)
				_G.Features.DisableGunSounds = val
				if val then
					refreshGunSoundMute()
