		local hitNotifPosDepBox = hitNotifDepBox:AddDependencyBox()
		hitNotifPosDepBox:AddSlider('HitNotifOffsetX', {
			Text = 'custom x',
			Default = rbHitCfg.offsetX,
			Min = 0,
			Max = 1200,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.offsetX = val
				if ragebot.applyHitNotifRootPosition then
					ragebot.applyHitNotifRootPosition()
				end
			end
		})
		hitNotifPosDepBox:AddSlider('HitNotifOffsetY', {
			Text = 'custom y',
			Default = rbHitCfg.offsetY,
			Min = 0,
			Max = 800,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.offsetY = val
				if ragebot.applyHitNotifRootPosition then
					ragebot.applyHitNotifRootPosition()
				end
			end
		})
		hitNotifPosDepBox:SetupDependencies({
			{ hitNotifPositionDropdown, 'Custom' },
		})

		hitNotifDepBox:AddSlider('HitNotifStackGap', {
			Text = 'stack gap',
			Default = rbHitCfg.stackGap,
			Min = 2,
			Max = 24,
			Rounding = 0,
			Compact = true,
			Callback = function(val)
				rbHitCfg.stackGap = val
			end
		})
		local hitNotifAnimStyles = ragebot.hitNotifAnimStyles or {
			"fade", "slide left", "slide right", "slide down", "bounce", "fade bounce", "scale",
		}
		hitNotifDepBox:AddDropdown('HitNotifInAnim', {
			Text = 'in animation',
			Default = rbHitCfg.inAnimation,
			Values = hitNotifAnimStyles,
			Callback = function(val)
				rbHitCfg.inAnimation = val
			end
		})
		hitNotifDepBox:AddDropdown('HitNotifOutAnim', {
			Text = 'out animation',
			Default = rbHitCfg.outAnimation,
			Values = hitNotifAnimStyles,
			Callback = function(val)
				rbHitCfg.outAnimation = val
			end
		})
		hitNotifDepBox:AddSlider('HitNotifInSpeed', {
			Text = 'in speed',
			Default = rbHitCfg.animInDuration,
			Min = 0.15,
			Max = 1.5,
			Rounding = 2,
			Compact = true,
			Suffix = 's',
			Callback = function(val)
				rbHitCfg.animInDuration = val
			end
		})
		hitNotifDepBox:AddSlider('HitNotifOutSpeed', {
			Text = 'out speed',
			Default = rbHitCfg.animOutDuration,
			Min = 0.15,
			Max = 1.5,
			Rounding = 2,
			Compact = true,
			Suffix = 's',
			Callback = function(val)
				rbHitCfg.animOutDuration = val
			end
		})
		hitNotifDepBox:SetupDependencies({
			{ hitNotificationsToggle, true }
		})
	end

	-- Character: profile / name / outfit / fps / ping / region spoof, movement, self material
	do
		local frame = Port.Section(CharacterTab, "Profile Spoof")

		local config = {}
		if not config.profile then
			config.profile = {
				level = { enabled = false, value = 9999 },
				winstreak = { enabled = false, value = 9999 }
			}
		end

		-- Player spoofer. Values are "guarded" (the way the other hub does it): the spoofed
		-- value is written to the player's attribute / leaderstat, and whenever the game
		-- changes it back it is written again, so it sticks. The real value is remembered
		-- and restored when a spoof is switched off or the hub is unloaded. The same
		-- fields can be spoofed for you ("local") and for every other player ("others").
		local Players = game:GetService("Players")
		local me = Players.LocalPlayer
		local spoofs = {}
		for _, scope in { "local", "others" } do
			spoofs[scope] = {
				level      = { enabled = false, value = 9999 },
				streak     = { enabled = false, value = 9999 },
				elo        = { enabled = false, value = 3600 },
				status     = { enabled = false, value = "Prime" },
				influencer = { enabled = false },
				employee   = { enabled = false },
				team       = { enabled = false },
			}
		end
		-- level / streak keep their old config entries, which the flags below fill in.
		spoofs["local"].level, spoofs["local"].streak = config.profile.level, config.profile.winstreak

		local guards = setmetatable({}, { __mode = "k" }) -- player -> { [key] = guard }
		local function guardFor(player, key, read, write, signal)
			local byKey = guards[player]
			if not byKey then
				byKey = {}
				guards[player] = byKey
			end
			local guard = byKey[key]
			if guard then
				return guard
			end
			guard = { original = read(), spoofed = nil, writing = false }
			guard.connection = signal():Connect(function()
				if guard.writing then return end
				guard.original = read()
				if guard.spoofed ~= nil then
					guard.writing = true
					write(guard.spoofed)
					guard.writing = false
				end
			end)
			guard.write = write
			byKey[key] = guard
			return guard
		end
		local function release(player, key)
			local byKey = guards[player]
			local guard = byKey and byKey[key]
			if not guard then return end
			guard.connection:Disconnect()
			byKey[key] = nil
			guard.writing = true
			pcall(guard.write, guard.original)
			guard.writing = false
		end
		local function setAttribute(player, name, enabled, value)
			if not enabled or value == nil then
				release(player, "a:" .. name)
				return
			end
			local guard = guardFor(player, "a:" .. name,
				function() return player:GetAttribute(name) end,
				function(v) player:SetAttribute(name, v) end,
				function() return player:GetAttributeChangedSignal(name) end)
			guard.spoofed = value
			guard.writing = true
			player:SetAttribute(name, value)
			guard.writing = false
		end
		local function setLeaderstat(player, name, enabled, value)
			local stats = player:FindFirstChild("CustomLeaderstats")
			local object = stats and stats:FindFirstChild(name)
			if not object or not object:IsA("ValueBase") then
				return
			end
			if not enabled or value == nil then
				release(player, "s:" .. name)
				return
			end
			local guard = guardFor(player, "s:" .. name,
				function() return object.Value end,
				function(v) object.Value = v end,
				function() return object:GetPropertyChangedSignal("Value") end)
			guard.spoofed = value
			guard.writing = true
			object.Value = value
			guard.writing = false
		end

		local function applyPlayer(player)
			local set = spoofs[player == me and "local" or "others"]
			setAttribute(player, "Level", set.level.enabled, set.level.value)
			setLeaderstat(player, "Level", set.level.enabled, set.level.value)
			setAttribute(player, "StatisticDuelsWinStreak", set.streak.enabled, set.streak.value)
			setLeaderstat(player, "Win Streak", set.streak.enabled, set.streak.value)
			setAttribute(player, "DisplayELO", set.elo.enabled, set.elo.value)
			setLeaderstat(player, "Current ELO", set.elo.enabled, set.elo.value)
			setAttribute(player, "PlayerStatus", set.status.enabled, set.status.value)
			setAttribute(player, "IsInfluencer", set.influencer.enabled, true)
			setAttribute(player, "IsRobloxEmployee", set.employee.enabled, true)
			setAttribute(player, "GroupRank", set.team.enabled, 255)
		end
		local function applyAll()
			for _, player in ipairs(Players:GetPlayers()) do
				pcall(applyPlayer, player)
			end
		end
		Port.Track(Players.PlayerAdded:Connect(function(player)
			task.delay(1, function() pcall(applyPlayer, player) end) -- leaderstats appear a moment later
		end))
		Port.Track(Players.PlayerRemoving:Connect(function(player)
			guards[player] = nil
		end))
		Port.OnUnload(function()
			for player, byKey in pairs(guards) do
				for key in pairs(byKey) do
					release(player, key)
				end
			end
		end)
		-- Leaderstat folders show up after the player does: re-apply now and then.
		task.spawn(function()
			while not Port.Unloaded do
				task.wait(3)
				applyAll()
			end
		end)

		local function spoofControls(scope, prefix, title)
			local set = spoofs[scope]
			local function numberField(key, flagStem, label, default)
				frame:AddToggle(prefix .. flagStem .. "Spoof", {
					Text = label, Default = false,
					Callback = function(on) set[key].enabled = on; applyAll() end,
				})
				frame:AddInput(prefix .. flagStem .. "Value", {
					Text = label, Default = tostring(default), Numeric = true, Finished = false, Placeholder = tostring(default),
					Callback = function(text) set[key].value = tonumber(text) or default; applyAll() end,
				})
			end
			return numberField
		end

		-- You (flags keep the old names so saved configs still load).
		local localField = spoofControls("local", "", "")
		frame:AddToggle("LevelSpoof", {
			Tooltip = "Only you see the spoofed values",
			Text = "level", Default = false,
			Callback = function(val) config.profile.level.enabled = val; applyAll() end,
		})
		frame:AddInput("LevelValue", {
			Text = "level", Default = "9999", Numeric = true, Finished = false, Placeholder = "9999",
			Callback = function(val) config.profile.level.value = tonumber(val) or 9999; applyAll() end,
		})
		frame:AddToggle("WinStreakSpoof", {
			Text = "win streak", Default = false,
			Callback = function(val) config.profile.winstreak.enabled = val; applyAll() end,
		})
		frame:AddInput("WinStreakValue", {
			Text = "win streak", Default = "9999", Numeric = true, Finished = false, Placeholder = "9999",
			Callback = function(val) config.profile.winstreak.value = tonumber(val) or 9999; applyAll() end,
		})
		localField("elo", "Elo", "ranked elo", 3600)
		frame:AddToggle("StatusSpoof", {
			Text = "nametag status", Default = false,
			Callback = function(on) spoofs["local"].status.enabled = on; applyAll() end,
		})
		frame:AddInput("StatusValue", {
			Text = "nametag status", Default = "Prime", Placeholder = "Prime", Finished = true,
			Callback = function(text) spoofs["local"].status.value = (text ~= "" and text) or "Prime"; applyAll() end,
		})
		for key, label in { influencer = "influencer badge", employee = "roblox employee badge", team = "team badge" } do
			frame:AddToggle("Spoof_" .. key, {
				Text = label, Default = false,
				Callback = function(on) spoofs["local"][key].enabled = on; applyAll() end,
			})
		end

		-- Other players (what you see them as).
		local otherField = spoofControls("others", "Other", "")
		otherField("level", "Level", "others: level", 0)
		otherField("streak", "Streak", "others: win streak", 0)
		otherField("elo", "Elo", "others: ranked elo", 0)
		frame:AddToggle("OtherStatusSpoof", {
			Text = "others: nametag status", Default = false,
			Callback = function(on) spoofs["others"].status.enabled = on; applyAll() end,
		})
		frame:AddInput("OtherStatusValue", {
			Text = "others: nametag status", Default = "Prime", Placeholder = "Prime", Finished = true,
			Callback = function(text) spoofs["others"].status.value = (text ~= "" and text) or "Prime"; applyAll() end,
		})

		-- Name / display name / avatar spoofing for you and for every other player, the way
		-- the other hub does it: the real names are replaced in the text of the game's UI
		-- (and in overhead name tags), character models get the spoofed user's clothes and
		-- accessories (the originals are stashed and put back), the game's own avatar loader
		-- is pointed at the spoofed user, and avatar thumbnails in the UI are swapped.
		-- Only you see any of it; everything is undone when a spoof is turned off.
		MD3.LYIdentitySpoof = function(frame)
			local Players = game:GetService("Players")
			local me = Players.LocalPlayer
			local cfg = {}
			for _, scope in { "local", "others" } do
				cfg[scope] = {
					name    = { enabled = false, value = "Player" },
					display = { enabled = false, value = "Player" },
					avatar  = { enabled = false, value = "1" },
					verified = { enabled = false },
					premium  = { enabled = false },
				}
			end
			local function scopeOf(player)
				return player == me and "local" or "others"
			end
			-- Roblox's verified / premium badge glyphs, added after the name.
			local BADGE_VERIFIED = utf8.char(0xE000)
			local BADGE_PREMIUM = utf8.char(0xE001)
			local function badgeSuffix(set)
				return (set.premium.enabled and BADGE_PREMIUM or "") .. (set.verified.enabled and BADGE_VERIFIED or "")
			end
			local function presented(player)
				local set = cfg[scopeOf(player)]
				local name = set.name.enabled and set.name.value ~= "" and set.name.value or player.Name
				local display = set.display.enabled and set.display.value ~= "" and set.display.value or player.DisplayName
				local suffix = badgeSuffix(set)
				if suffix ~= "" then
					name, display = name .. suffix, display .. suffix
				end
				return name, display
			end
			MD3.LYPresentedName = function()
				local _, display = presented(me)
				return display
			end
			local function avatarId(player)
				local set = cfg[scopeOf(player)].avatar
				if set.enabled then
					return tonumber(set.value)
				end
				return nil
			end

			-- Text: replace real names with the presented ones in labels ---------------
			local texts = setmetatable({}, { __mode = "k" }) -- object -> { original, shown }
			local hooks = setmetatable({}, { __mode = "k" })
			local function plainReplace(text, find, replace)
				if find == "" or find == replace then return text end
				local out, position = {}, 1
				while true do
					local from, to = text:find(find, position, true)
					if not from then break end
					table.insert(out, text:sub(position, from - 1))
					table.insert(out, replace)
					position = to + 1
				end
				if position == 1 then return text end
				table.insert(out, text:sub(position))
				return table.concat(out)
			end
			local function spoofText(text)
				for _, player in ipairs(Players:GetPlayers()) do
					local name, display = presented(player)
					text = plainReplace(text, player.DisplayName, display)
					text = plainReplace(text, player.Name, name)
				end
				return text
			end
			local function anyNameSpoof()
				for _, scope in { "local", "others" } do
					local set = cfg[scope]
					if set.name.enabled or set.display.enabled or set.verified.enabled or set.premium.enabled then return true end
				end
				return false
			end
			local function isOurs(inst)
				return Window.Gui ~= nil and inst:IsDescendantOf(Window.Gui)
			end
			local function syncText(inst)
				if isOurs(inst) then return end
				local record = texts[inst]
				if not record then
					record = {}
					texts[inst] = record
				end
				local now = inst.Text
				if record.shown == nil or now ~= record.shown then
					record.original = now
				end
				local shown = anyNameSpoof() and spoofText(record.original) or record.original
				record.shown = shown
				if inst.Text ~= shown then
					inst.Text = shown
				end
			end
			local function hookText(inst)
				if hooks[inst] or not (inst:IsA("TextLabel") or inst:IsA("TextButton")) then return end
				hooks[inst] = inst:GetPropertyChangedSignal("Text"):Connect(function()
					pcall(syncText, inst)
				end)
				pcall(syncText, inst)
			end
			local roots = {}
			local function watchRoot(root)
				if not root or roots[root] then return end
				roots[root] = true
				Port.Track(root.DescendantAdded:Connect(function(inst)
					if anyNameSpoof() then task.defer(hookText, inst) end
				end))
			end
			local function sweepText()
				local gui = me:FindFirstChild("PlayerGui")
				watchRoot(gui)
				watchRoot(workspace) -- new name tags only (event); the map itself is never scanned
				local scan = { gui }
				for _, other in ipairs(Players:GetPlayers()) do
					if other.Character then table.insert(scan, other.Character) end
				end
				local count = 0
				for _, root in scan do
					if root then
						for _, inst in ipairs(root:GetDescendants()) do
							if inst:IsA("TextLabel") or inst:IsA("TextButton") then
								if anyNameSpoof() then
									hookText(inst)
								else
									local connection = hooks[inst]
									if connection then
										connection:Disconnect()
										hooks[inst] = nil
										pcall(syncText, inst) -- restores the original
										texts[inst] = nil
									end
								end
							end
							count += 1
							if count % 400 == 0 then task.wait() end
						end
					end
				end
			end
			-- Humanoid overhead names.
			local displayNames = setmetatable({}, { __mode = "k" })
			local function syncHumanoids()
				for _, player in ipairs(Players:GetPlayers()) do
					local character = player.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if humanoid then
						local _, display = presented(player)
						local set = cfg[scopeOf(player)]
						local spoofing = set.display.enabled or set.verified.enabled or set.premium.enabled
						if spoofing then
							if displayNames[humanoid] == nil then displayNames[humanoid] = humanoid.DisplayName end
							if humanoid.DisplayName ~= display then humanoid.DisplayName = display end
						elseif displayNames[humanoid] ~= nil then
							humanoid.DisplayName = displayNames[humanoid]
							displayNames[humanoid] = nil
						end
					end
				end
			end

			-- Avatar decorator: any character model of a player gets the spoofed user's look.
			-- Per model: the originals (accessories, clothes, face decals) are stashed and
			-- anything the game adds later is stashed too; the spoofed user's accessories are
			-- welded on through their attachments, clothes / body colors / head are copied; all
			-- of it is undone on restore. Descriptions and source models are cached per user.
			local STASH = { "Accessory", "Shirt", "Pants", "ShirtGraphic" }
			local HEAD_DECOR = { "Decal", "SurfaceAppearance", "SpecialMesh" }
			local function isAny(inst, classes)
				for _, class in classes do
					if inst:IsA(class) then return true end
				end
				return false
			end
			local descriptions = {}  -- userId -> HumanoidDescription | false
			local sources = {}       -- userId:rig -> model | false
			local function sourceModel(userId, rigType)
				local key = tostring(userId) .. ":" .. tostring(rigType)
				if sources[key] ~= nil then return sources[key] or nil end
				if descriptions[userId] == nil then
					local ok, description = pcall(function()
						return Players:GetHumanoidDescriptionFromUserIdAsync(userId)
					end)
					descriptions[userId] = ok and description or false
				end
				sources[key] = false
				if descriptions[userId] then
					local made, model = pcall(function()
						if Players.CreateHumanoidModelFromDescriptionAsync then
							return Players:CreateHumanoidModelFromDescriptionAsync(descriptions[userId], rigType)
						end
						return Players:CreateHumanoidModelFromDescription(descriptions[userId], rigType)
					end)
					if made and model then sources[key] = model end
				end
				return sources[key] or nil
			end
			local function firstAttachment(part)
				for _, child in ipairs(part:GetChildren()) do
					if child:IsA("Attachment") then return child end
				end
				return nil
			end
			local function findAttachment(character, name)
				for _, child in ipairs(character:GetChildren()) do
					if child:IsA("BasePart") then
						local attachment = child:FindFirstChild(name)
						if attachment and attachment:IsA("Attachment") then return attachment end
					end
				end
				return nil
			end
			-- Welds an accessory onto the character through its attachments (no Humanoid needed).
			local function attachAccessory(accessory, character)
				local handle = accessory:FindFirstChild("Handle")
				if handle and handle:IsA("BasePart") then
					for _, child in ipairs(handle:GetChildren()) do
						if child:IsA("Weld") or child:IsA("WeldConstraint") or child:IsA("ManualWeld") then
							child:Destroy()
						end
					end
					local own = firstAttachment(handle)
					local target = own and findAttachment(character, own.Name)
					if own and target then
						handle.Anchored = false
						local weld = Instance.new("Weld")
						weld.Name = "AccessoryWeld"
						weld.Part0, weld.Part1 = handle, target.Parent
						weld.C0, weld.C1 = own.CFrame, target.CFrame
						weld.Parent = handle
					end
				end
				accessory.Parent = character
			end
			local decorated = setmetatable({}, { __mode = "k" }) -- model -> state
			local function restoreModel(model)
				local state = decorated[model]
				if not state then return end
				decorated[model] = nil
				state.cancelled = true
				for _, connection in ipairs(state.connections) do connection:Disconnect() end
				for _, clone in ipairs(state.clones) do pcall(clone.Destroy, clone) end
				if model.Parent then
					for _, item in ipairs(state.stashed) do
						if item:IsA("Accessory") then attachAccessory(item, model) else item.Parent = model end
					end
					for part, color in pairs(state.colors) do
						if part.Parent then part.Color = color end
					end
					local head = model:FindFirstChild("Head")
					if head then
						for _, item in ipairs(state.headStashed) do item.Parent = head end
						if state.head then
							head.Transparency = state.head.Transparency
							if state.head.MeshId and head:IsA("MeshPart") then
								head.MeshId, head.TextureID = state.head.MeshId, state.head.TextureID
							end
						end
					end
				else
					for _, item in ipairs(state.stashed) do pcall(item.Destroy, item) end
					for _, item in ipairs(state.headStashed) do pcall(item.Destroy, item) end
				end
			end
			-- Waits (up to `timeout`) for the model to have what the source has: the body
			-- parts, and for every accessory the part its attachment sits on.
			local function modelReady(model, source)
				for _, child in ipairs(source:GetChildren()) do
					if child:IsA("BasePart") and not model:FindFirstChild(child.Name) then return false end
					if child:IsA("Accessory") then
						local handle = child:FindFirstChild("Handle")
						local own = handle and handle:IsA("BasePart") and firstAttachment(handle)
						if own and not findAttachment(model, own.Name) then return false end
					end
				end
				return true
			end
			local function decorate(model, userId)
				restoreModel(model)
				local state = { clones = {}, stashed = {}, headStashed = {}, colors = {}, connections = {}, cancelled = false }
				decorated[model] = state
				local humanoid = model:FindFirstChildOfClass("Humanoid") or model:WaitForChild("Humanoid", 10)
				if state.cancelled or not humanoid then return end
				local source = sourceModel(userId, humanoid.RigType)
				if state.cancelled or not source then return end
				local waited = 0
				while not modelReady(model, source) and waited < 10 and not state.cancelled and model.Parent do
					task.wait(0.1)
					waited += 0.1
				end
				if state.cancelled or not model.Parent then return end
				local spoofed = {}
				local function stash(child)
					if spoofed[child] or child.Parent ~= model then return end
					child.Parent = nil
					table.insert(state.stashed, child)
				end
				-- Stash the originals now and whatever the game adds later.
				for _, child in ipairs(model:GetChildren()) do
					if isAny(child, STASH) then stash(child) end
				end
				table.insert(state.connections, model.ChildAdded:Connect(function(child)
					if isAny(child, STASH) and not spoofed[child] then
						task.defer(stash, child)
					end
				end))
				for _, item in ipairs(source:GetChildren()) do
					if item:IsA("Accessory") then
						local clone = item:Clone()
						spoofed[clone] = true
						table.insert(state.clones, clone)
						attachAccessory(clone, model)
					elseif item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") then
						local clone = item:Clone()
						spoofed[clone] = true
						table.insert(state.clones, clone)
						clone.Parent = model
					elseif item:IsA("BasePart") then
						local target = model:FindFirstChild(item.Name)
						if target and target:IsA("BasePart") then
							state.colors[target] = target.Color
							target.Color = item.Color
						end
					end
				end
				local head, from = model:FindFirstChild("Head"), source:FindFirstChild("Head")
				if head and from and head:IsA("BasePart") and from:IsA("BasePart") then
					for _, child in ipairs(head:GetChildren()) do
						if isAny(child, HEAD_DECOR) then
							child.Parent = nil
							table.insert(state.headStashed, child)
						end
					end
					for _, child in ipairs(from:GetChildren()) do
						if isAny(child, HEAD_DECOR) then
							local clone = child:Clone()
							table.insert(state.clones, clone)
							clone.Parent = head
						end
					end
					state.head = { Transparency = head.Transparency }
					head.Transparency = from.Transparency
					if head:IsA("MeshPart") and from:IsA("MeshPart") then
						state.head.MeshId, state.head.TextureID = head.MeshId, head.TextureID
						head.MeshId, head.TextureID = from.MeshId, from.TextureID
					end
				end
			end
			-- Every character model that belongs to a player (their Character, plus models the
			-- game builds for matches, found by name).
			local modelOwner = setmetatable({}, { __mode = "k" }) -- model -> player
			local function playerForModel(model)
				for _, player in ipairs(Players:GetPlayers()) do
					if player.Character == model or model.Name == player.Name then return player end
				end
				return nil
			end
			local function trackModel(model)
				if not model:IsA("Model") or modelOwner[model] then return end
				local player = playerForModel(model)
				if player then
					modelOwner[model] = player
					local userId = avatarId(player)
					if userId then task.spawn(decorate, model, userId) end
				end
			end
			local function syncAvatar(player)
				if player.Character then trackModel(player.Character) end
				for model, owner in pairs(modelOwner) do
					if owner == player and model.Parent then
						local userId = avatarId(player)
						if userId then
							if not decorated[model] or decorated[model].userId ~= userId then
								task.spawn(function()
									decorate(model, userId)
									if decorated[model] then decorated[model].userId = userId end
								end)
							end
						else
							restoreModel(model)
						end
					end
				end
			end
			local function bindPlayer(player)
				Port.Track(player.CharacterAdded:Connect(function(character)
					task.wait(0.6)
					modelOwner[character] = nil
					trackModel(character)
				end))
			end
			for _, player in ipairs(Players:GetPlayers()) do bindPlayer(player) end
			Port.Track(Players.PlayerAdded:Connect(bindPlayer))
			Port.Track(workspace.DescendantAdded:Connect(function(inst)
				if inst:IsA("Humanoid") and inst.Parent then
					task.defer(function()
						if inst.Parent then trackModel(inst.Parent) end
					end)
				end
			end))
			for _, child in ipairs(workspace:GetChildren()) do
				if child:IsA("Model") then trackModel(child) end
			end

			-- The game's own avatar loader (spectated / preloaded duelers) ------------------
			local loaderRestore
			local function installLoader()
				if loaderRestore or not (debug and debug.getupvalues and debug.setupvalue) then return end
				local dueler = MD3.LYRequire and MD3.LYRequire("ClientDueler")
				local method = type(dueler) == "table" and rawget(dueler, "_PreloadCharacterModel")
				if type(method) ~= "function" then return end
				local index, original
				for slot, value in debug.getupvalues(method) do
					if typeof(value) == "Instance" and pcall(value.IsA, value, "Players") and value:IsA("Players") then
						index, original = slot, value
						break
					end
				end
				if not index then return end
				local stand = setmetatable({}, { __index = function(_, key)
					if key == "GetHumanoidDescriptionFromUserIdAsync" then
						return function(_, userId)
							for _, player in ipairs(Players:GetPlayers()) do
								if player.UserId == userId and avatarId(player) then
									return Players:GetHumanoidDescriptionFromUserIdAsync(avatarId(player))
								end
							end
							return Players:GetHumanoidDescriptionFromUserIdAsync(userId)
						end
					end
					local value = Players[key]
					if type(value) == "function" then
						return function(_, ...) return value(Players, ...) end
					end
					return value
				end })
				if pcall(debug.setupvalue, method, index, stand) then
					loaderRestore = function() pcall(debug.setupvalue, method, index, original) end
				end
			end

			-- Thumbnails in the UI ------------------------------------------------------------
			local images = setmetatable({}, { __mode = "k" })
			local function swapImage(text)
				for _, player in ipairs(Players:GetPlayers()) do
					local target = avatarId(player)
					if target then
						local id = tostring(player.UserId)
						text = text:gsub("([%?&]id=)" .. id, "%1" .. tostring(target))
						text = text:gsub("(userId=)" .. id, "%1" .. tostring(target))
					end
				end
				return text
			end
			local function sweepImages()
				local gui = me:FindFirstChild("PlayerGui")
				if not gui then return end
				local anyAvatar = cfg["local"].avatar.enabled or cfg["others"].avatar.enabled
				local count = 0
				for _, inst in ipairs(gui:GetDescendants()) do
					if (inst:IsA("ImageLabel") or inst:IsA("ImageButton")) and not isOurs(inst) then
						local record = images[inst]
						local image = inst.Image
						if record and image ~= record.shown then record.original = image end
						if anyAvatar then
							if not record then
								record = { original = image }
								images[inst] = record
							end
							local shown = swapImage(record.original)
							record.shown = shown
							if inst.Image ~= shown then inst.Image = shown end
						elseif record then
							inst.Image = record.original
							images[inst] = nil
						end
					end
					count += 1
					if count % 400 == 0 then task.wait() end
				end
			end

			local function refresh()
				pcall(sweepText)
				pcall(syncHumanoids)
				for _, player in ipairs(Players:GetPlayers()) do pcall(syncAvatar, player) end
				if cfg["local"].avatar.enabled or cfg["others"].avatar.enabled then pcall(installLoader) end
				pcall(sweepImages)
			end
			local refreshing = false
			local function requestRefresh()
				if refreshing then return end
				refreshing = true
				task.defer(function()
					refresh()
					refreshing = false
				end)
			end
			task.spawn(function()
				while not Port.Unloaded do
					task.wait(4)
					if anyNameSpoof() or cfg["local"].avatar.enabled or cfg["others"].avatar.enabled then
						pcall(function() pcall(sweepText); pcall(syncHumanoids); pcall(sweepImages) end)
					end
				end
			end)
			Port.OnUnload(function()
				for _, scope in { "local", "others" } do
					for _, key in { "name", "display", "avatar", "verified", "premium" } do cfg[scope][key].enabled = false end
				end
				pcall(refresh)
				if loaderRestore then loaderRestore() end
			end)

			-- Controls ---------------------------------------------------------------------
			local function field(prefix, key, label, target, default, numeric)
				frame:AddToggle(prefix .. key .. "Spoof", {
					Text = label, Default = false,
					Callback = function(on) target.enabled = on; requestRefresh() end,
				})
				frame:AddInput(prefix .. key .. "Value", {
					Text = label, Default = default, Placeholder = default,
					Numeric = numeric == true, Finished = true,
					Callback = function(value) target.value = (value ~= "" and value) or default; requestRefresh() end,
				})
			end
			local mine = cfg["local"]
			field("My", "Name", "my name", mine.name, "Player")
			field("My", "Display", "my display name", mine.display, "Player")
			field("My", "Avatar", "my avatar (user id)", mine.avatar, "1", true)
			local function badge(prefix, key, label, target, description)
				frame:AddToggle(prefix .. key .. "Spoof", {
					Text = label, Tooltip = description, Default = false,
					Callback = function(on) target.enabled = on; requestRefresh() end,
				})
			end
			badge("My", "Verified", "verified badge", mine.verified, "Add the verified checkmark after your name")
			badge("My", "Premium", "premium badge", mine.premium, "Add the Premium icon after your name")
			local others = cfg["others"]
			field("Others", "Name", "others: name", others.name, "Player")
			field("Others", "Display", "others: display name", others.display, "Player")
			field("Others", "Avatar", "others: avatar (user id)", others.avatar, "1", true)
			badge("Others", "Verified", "others: verified badge", others.verified, "Add the verified checkmark after other players' names")
			badge("Others", "Premium", "others: premium badge", others.premium, "Add the Premium icon after other players' names")
		end

		-- More of the player spoofer, done the way the other hub does it:
		--  * profile page (clicking a player): ViewProfile.Fetch asks the server through
		--    ReplicatedStorage; its upvalue is swapped for a stand-in that makes the real
		--    request and then edits the returned data (wins, win %, elo, level, favorite map),
		--  * keys / event currency / seasons: fields of the game's own player data,
		--  * leaderboard rank: the game's ranking lookup and the board list are redirected,
		--  * ping: the upvalue `Players` of Utility.GetLocalConnectionPing is swapped.
		-- Every hook is optional: if a game function / upvalue is not found, that spoof
		-- just does nothing. They are all undone when the hub is unloaded.
		MD3.LYSpoofExtras = function(frame, spoofs)
			local Players = game:GetService("Players")
			local ReplicatedStorage = game:GetService("ReplicatedStorage")
			local me = Players.LocalPlayer
			local extra = {}
			for _, scope in { "local", "others" } do
				extra[scope] = {
					casualWins   = { enabled = false, value = 0 },
					rankedWins   = { enabled = false, value = 0 },
					casualPct    = { enabled = false, value = 0 },
					rankedPct    = { enabled = false, value = 0 },
					favoriteMap  = { enabled = false, value = "Arena" },
				}
			end
			local keys        = { enabled = false, value = 999 }
			local event       = { enabled = false, value = 9999 }
			local board       = { enabled = false, value = 1 }
			local ping        = { enabled = false, value = "Low" }

			local function scopeOf(player)
				if player == me or player == me.UserId then return "local" end
				return "others"
			end

			-- Profile page ------------------------------------------------------------
			local profile = { installed = false, restore = nil }
			local function editProfile(player, data)
				if type(data) ~= "table" then return data end
				local scope = scopeOf(player)
				local base, more = spoofs[scope], extra[scope]
				if base.level.enabled then data.Level = base.level.value end
				if more.casualWins.enabled then data.CasualWins = more.casualWins.value end
				if more.rankedWins.enabled then data.RankedWins = more.rankedWins.value end
				if more.casualPct.enabled then data.CasualWinPercent = more.casualPct.value / 100 end
				if more.rankedPct.enabled then data.RankedWinPercent = more.rankedPct.value / 100 end
				if base.elo.enabled then data.RankedCurrentELO = base.elo.value end
				if more.favoriteMap.enabled then data.FavoriteMap = more.favoriteMap.value end
				return data
			end
			local function installProfileHook()
				if profile.installed or not (debug and debug.getupvalues and debug.setupvalue) then return end
				local viewProfile = MD3.LYRequire and MD3.LYRequire("ViewProfile")
				local meta = viewProfile and getmetatable(viewProfile)
				local methods = type(meta) == "table" and rawget(meta, "__index")
				local fetch = type(methods) == "table" and rawget(methods, "Fetch")
				if type(fetch) ~= "function" then return end
				local index, original
				for slot, value in debug.getupvalues(fetch) do
					if typeof(value) == "Instance" and pcall(value.IsA, value, "ReplicatedStorage") and value:IsA("ReplicatedStorage") then
						index, original = slot, value
					end
				end
				if not index then return end
				local request
				pcall(function() request = ReplicatedStorage.Remotes.Misc.RequestProfile end)
				if not request then return end
				local stand = setmetatable({}, { __index = function()
					return { Misc = { RequestProfile = { InvokeServer = function(_, player)
						local ok, data = pcall(request.InvokeServer, request, player)
						if not ok then return nil end
						return editProfile(player, data)
					end } } }
				end })
				if pcall(debug.setupvalue, fetch, index, stand) then
					profile.installed = true
					profile.restore = function() pcall(debug.setupvalue, fetch, index, original) end
				end
			end

			-- Player-data fields: keys, event currency, season elo --------------------
			local function dataSet(field, getter)
				if MD3.LYData then pcall(MD3.LYData.Set, field, getter) end
			end
			local function seasonsWithElo()
				local original = MD3.LYData and MD3.LYData.Real("Seasons")
				local library = MD3.LYRequire and MD3.LYRequire("SeasonLibrary")
				local current = type(library) == "table" and library.CurrentSeason
				if type(original) ~= "table" or type(current) ~= "table" or not spoofs["local"].elo.enabled then
					return original
				end
				local name = current.Name
				local universal = library.UNIVERSAL_ELO_NAME
				local clone = table.clone(original)
				local season = table.clone(clone[name] or {})
				local performances = table.clone(season.RankedPerformances or {})
				local entry = table.clone(performances[universal] or {})
				entry.CurrentELO = spoofs["local"].elo.value
				performances[universal] = entry
				season.RankedPerformances = performances
				clone[name] = season
				return clone
			end
			local function applyData()
				dataSet("WeaponKeys", keys.enabled and function() return keys.value end or nil)
				dataSet("EventCurrency", event.enabled and function() return event.value end or nil)
				dataSet("Seasons", spoofs["local"].elo.enabled and seasonsWithElo or nil)
			end

			-- Leaderboard rank ----------------------------------------------------------
			local boardHook = { restore = nil }
			local function installBoard()
				if boardHook.restore or not (debug and debug.getconstants and debug.setconstant) then return end
				local controller = MD3.LYRequire and MD3.LYRequire("LeaderboardController")
				local library = MD3.LYRequire and MD3.LYRequire("SeasonLibrary")
				if type(controller) ~= "table" or type(library) ~= "table" then return end
				local meta = getmetatable(controller)
				local methods = type(meta) == "table" and rawget(meta, "__index")
				local ranking = type(methods) == "table" and rawget(methods, "GetRankingByUserID")
				local highest = rawget(library, "GetHighestELOLeaderboardRanking")
				if type(ranking) ~= "function" or type(highest) ~= "function" then return end
				local constantIndex
				for slot, value in debug.getconstants(highest) do
					if value == "GetRankingByUserID" then constantIndex = slot break end
				end
				if not constantIndex then return end
				local alias = "GetRankingByUserID\\0ly"
				pcall(debug.setconstant, highest, constantIndex, alias)
				pcall(rawset, controller, alias, function(self, kind, userId)
					if board.enabled and kind == "Highest ELO" and userId ~= nil
						and (userId == me.UserId or tostring(userId) == tostring(me.UserId)) then
						return board.value
					end
					return ranking(self, kind, userId)
				end)
				boardHook.restore = function()
					pcall(debug.setconstant, highest, constantIndex, "GetRankingByUserID")
					pcall(rawset, controller, alias, nil)
				end
			end

			-- Ping ----------------------------------------------------------------------
			local pingHook = { restore = nil }
			local PING = { Low = { 150, 160 }, Medium = { 60, 75 }, High = { 17, 25 } }
			local function installPing()
				if pingHook.restore or not (debug and debug.getupvalues and debug.setupvalue) then return end
				local utility
				pcall(function() utility = require(ReplicatedStorage.Modules.Utility) end)
				local meta = utility and getmetatable(utility)
				local methods = type(meta) == "table" and rawget(meta, "__index")
				local fn = type(methods) == "table" and rawget(methods, "GetLocalConnectionPing")
				if type(fn) ~= "function" then return end
				local index, original
				for slot, value in debug.getupvalues(fn) do
					if typeof(value) == "Instance" and pcall(value.IsA, value, "Players") and value:IsA("Players") then index, original = slot, value end
				end
				if not index then return end
				local stand = { LocalPlayer = { GetNetworkPing = function()
					if not ping.enabled then return me:GetNetworkPing() end
					local range = PING[ping.value] or PING.Low
					return math.random(range[1], range[2]) / 1000
				end } }
				if pcall(debug.setupvalue, fn, index, stand) then
					pingHook.restore = function() pcall(debug.setupvalue, fn, index, original) end
				end
			end

			Port.OnUnload(function()
				if profile.restore then profile.restore() end
				if boardHook.restore then boardHook.restore() end
				if pingHook.restore then pingHook.restore() end
				pcall(function()
					if MD3.LYData then
						MD3.LYData.Set("WeaponKeys", nil)
						MD3.LYData.Set("EventCurrency", nil)
						MD3.LYData.Set("Seasons", nil)
					end
				end)
			end)

			-- Controls --------------------------------------------------------------------
			local function field(prefix, key, label, target, default, onChange, text)
				frame:AddToggle(prefix .. key .. "Spoof", {
					Text = label, Default = false,
					Callback = function(on) target.enabled = on; onChange() end,
				})
				frame:AddInput(prefix .. key .. "Value", {
					Text = label, Default = tostring(default), Placeholder = tostring(default),
					Numeric = not text, Finished = text == true,
					Callback = function(value)
						if text then
							target.value = (value ~= "" and value) or default
						else
							target.value = tonumber(value) or default
						end
						onChange()
					end,
				})
			end
			local function refreshProfile() installProfileHook() end
			local function refreshData() installProfileHook(); applyData() end
			local function refreshBoard()
				installBoard()
			end

			field("", "Keys", "keys", keys, 999, refreshData)
			field("", "EventCurrency", "event currency", event, 9999, refreshData)
			field("", "LeaderboardRank", "leaderboard rank", board, 1, refreshBoard)
			frame:AddToggle("PingSpoof2", {
				Text = "ping (menu)", Default = false,
				Callback = function(on) ping.enabled = on; installPing() end,
			})
			frame:AddDropdown("PingSpoof2Type", {
				Text = "ping level", Default = "Low", Values = { "Low", "Medium", "High" },
				Callback = function(value) ping.value = value or "Low"; installPing() end,
			})
			local mine = extra["local"]
			field("", "CasualWins", "casual wins", mine.casualWins, 99999, refreshProfile)
			field("", "RankedWins", "ranked wins", mine.rankedWins, 9999, refreshProfile)
			field("", "CasualPct", "casual win %", mine.casualPct, 100, refreshProfile)
			field("", "RankedPct", "ranked win %", mine.rankedPct, 100, refreshProfile)
			field("", "FavoriteMap", "favorite map", mine.favoriteMap, "Arena", refreshProfile, true)
			local others = extra["others"]
			field("Other", "CasualWins", "others: casual wins", others.casualWins, 0, refreshProfile)
			field("Other", "RankedWins", "others: ranked wins", others.rankedWins, 0, refreshProfile)
			field("Other", "CasualPct", "others: casual win %", others.casualPct, 0, refreshProfile)
			field("Other", "RankedPct", "others: ranked win %", others.rankedPct, 0, refreshProfile)
			field("Other", "FavoriteMap", "others: favorite map", others.favoriteMap, "", refreshProfile, true)

			-- The level / elo toggles above feed the profile page and the seasons too.
			local function recheck()
				refreshData()
				installBoard()
			end
			task.spawn(function()
				while not Port.Unloaded do
					task.wait(2)
					if spoofs["local"].elo.enabled or spoofs["local"].level.enabled
						or spoofs["others"].level.enabled or spoofs["others"].elo.enabled then
						pcall(recheck)
					end
				end
			end)
		end

		MD3.LYSpoofExtras(frame, spoofs)

		MD3.LYIdentitySpoof(frame)

