		local enabled = false
		local weapon1 = "Riot Shield"
		local weapon2 = "Katana"
		local thread = nil

		local storage = game:GetService("ReplicatedStorage")
		local remote = nil
		task.spawn(function()
			local remotes = storage:WaitForChild("Remotes", 30)
			local duels = remotes and remotes:WaitForChild("Duels", 30)
			remote = duels and duels:WaitForChild("Vote", 30)
		end)

		local start
		local function stop()
			if thread then
				thread = nil
			end
		end

		start = function()
			stop()

			thread = task.spawn(function()
				while enabled and task.wait(1) do
					local list = {}

					if weapon1 and weapon1 ~= "" then
						table.insert(list, weapon1)
					end

					if weapon2 and weapon2 ~= "" then
						table.insert(list, weapon2)
					end

					if #list > 0 and remote then
						local i = 1
						while enabled do
							remote:FireServer(list[i])

							i = i % #list + 1

							task.wait(1)

							if not thread then
								break
							end
						end
					end
				end
			end)
		end

