			Text = 'mod detector',
			Default = _G.Features.ModDetector.Enabled,
			Callback = function(Value)
				_G.Features.ModDetector.Enabled = Value
				updmoddetector()
			end
		})

		if _G.Features.ModDetector.Enabled then
			moddetector()
		end

