	-- ESP: thrown utilities
	;(function()

	local worldToEspScreen = getgenv().InstanceWorldToScreenEsp or getgenv().InstanceWorldToScreen
	local utilfonts = {}
	local utilfontok = pcall(function()
		local fontid = "util_font.ttf"
		if not isfile(fontid) then
			writefile(fontid, game:HttpGet("https://github.com/i77lhm/storage/raw/refs/heads/main/fonts/smallest_pixel-7.ttf"))
		end
		utilfonts.path = fontid
	end)

	local utilconfig = {
		enable = false,
		color = Color3.fromRGB(255, 255, 255),
		color2 = Color3.fromRGB(255, 255, 255),
		selected = {},
		distance = false,
		images = false,
	}

	local UTIL_IMG_SIZE = 36
	local UTIL_NAME_GAP = 14
	local UTIL_DIST_GAP = 6

	local replicated_storage = game:GetService("ReplicatedStorage")
	local item_library
	pcall(function()
		item_library = require(replicated_storage.Modules.ItemLibrary)
	end)

	local utilimagename = {
		Grenade = "Grenade",
		SubspaceTripmineHitbox = "Subspace Tripmine",
		Flashbang = "Flashbang",
		Satchel = "Satchel",
		Warpstone = "Warpstone",
		Molotov = "Molotov",
		["Smoke Grenade"] = "Smoke Grenade",
	}

	local utilimagecache = {}
	local utilimagefallback = {
		Grenade = "rbxassetid://6603835352",
		Flashbang = "rbxassetid://243660364",
		Satchel = "rbxassetid://446111271",
		Warpstone = "rbxassetid://12781852245",
		Molotov = "rbxassetid://1084982556",
		["Smoke Grenade"] = "rbxassetid://241650108",
		["Subspace Tripmine"] = "rbxassetid://120777973",
	}

	local function normUtilImageId(id)
		if not id or id == "" then return "" end
		id = tostring(id)
		if tonumber(id) then
			return "rbxassetid://" .. id
		end
		return id
	end

	local function resolveUtilImage(modelName)
		if utilimagecache[modelName] ~= nil then
			return utilimagecache[modelName]
		end
		local imageId = ""
		local libNames = {}
		local mapped = utilimagename[modelName]
		if mapped then
			libNames[#libNames + 1] = mapped
		end
		if modelName == "SubspaceTripmineHitbox" then
			libNames[#libNames + 1] = "Subspace Tripmine"
		end
		libNames[#libNames + 1] = modelName
		pcall(function()
			for _, libName in ipairs(libNames) do
				if imageId ~= "" then break end
				-- The game's own images: ItemLibrary.ViewModels[name].Image (the old calls to
				-- GetWeaponImage / GetImageFromWeaponData do not exist in this game, so the
				-- hard-coded fallbacks below were always used and showed the wrong pictures).
				if item_library then
					local viewModel = item_library.ViewModels and item_library.ViewModels[libName]
					if type(viewModel) == "table" then
						local image = viewModel.Image
						if type(image) ~= "string" or image == "" then
							image = viewModel.ImageHighResolution
						end
						if type(image) == "string" then
							imageId = image
						end
					end
					if imageId == "" and item_library.GetViewModelImage then
						imageId = item_library:GetViewModelImage(libName, nil, false) or ""
					end
				end
			end
		end)
		imageId = normUtilImageId(imageId)
		if imageId == "" then
			imageId = utilimagefallback[modelName] or utilimagefallback[utilimagename[modelName]] or ""
		end
		utilimagecache[modelName] = imageId
		return imageId
	end

	local utilmap = {
		["grenade"]           = "Grenade",
		["subspace tripmine"] = "SubspaceTripmineHitbox",
		["flashbang"]         = "Flashbang",
		["satchel"]           = "Satchel",
		["warpstone"]         = "Warpstone",
		["molotov"]           = "Molotov",
		["smoke grenade"]     = "Smoke Grenade"
	}

	local utildisplay = {}
	for label, realname in pairs(utilmap) do
		utildisplay[realname] = label
	end

	-- A thrown utility is a clone of Throwables[<skin name>], so a skinned grenade is called
	-- "Soul Grenade" / "Frozen Grenade" ..., not "Grenade", and was never matched. Skins are in
	-- CosmeticLibrary.Cosmetics[skin].ItemName = the weapon they belong to.
	local cosmetic_library
	pcall(function()
		cosmetic_library = require(replicated_storage.Modules.CosmeticLibrary)
	end)
	local utilcanon = setmetatable({}, { __mode = "k" })
	local function utilResolve(name)
		if type(name) ~= "string" then return nil end
		if utildisplay[name] then return name end
		local cached = utilcanon[name]
		if cached ~= nil then return cached or nil end
		local resolved = false
		pcall(function()
			local cosmetic = cosmetic_library and cosmetic_library.Cosmetics and cosmetic_library.Cosmetics[name]
			if type(cosmetic) == "table" and cosmetic.Type == "Skin" and type(cosmetic.ItemName) == "string" then
				resolved = utilmap[string.lower(cosmetic.ItemName)] or false
			end
		end)
		utilcanon[name] = resolved
		return resolved or nil
	end

	local function utilHasSelection()
		for label in pairs(utilmap) do
			if utilconfig.selected[label] then
				return true
			end
		end
		return false
	end

	local function isselected(realname)
		if not utilHasSelection() then
			for _, rname in pairs(utilmap) do
				if rname == realname then
					return true
				end
			end
			return false
		end
		for label, rname in pairs(utilmap) do
			if rname == realname and utilconfig.selected[label] then
				return true
			end
		end
		return false
	end

	local function trackUtilDrawingText(obj)
		if getgenv().InstanceTrackDrawingText then
			return getgenv().InstanceTrackDrawingText(obj)
		end
		return obj
	end

	local utilespobjects = {}

	-- Text for the utility labels is a GUI TextLabel behind a Drawing-like interface (Text /
	-- Color / Size / Visible / Position / Outline / Remove): Drawing text isn't rendered by every
	-- executor, which left the whole Utility ESP blank.
	local utilFace
	do
		local okFont, face = pcall(Font.new, "rbxasset://fonts/families/Inconsolata.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
		utilFace = okFont and face or Font.fromEnum(Enum.Font.Code)
	end
	local function makedrawtext(text, color)
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.BorderSizePixel = 0
		label.AnchorPoint = Vector2.new(0.5, 0)
		label.Size = UDim2.fromOffset(240, 20)
		label.TextXAlignment = Enum.TextXAlignment.Center
		label.TextYAlignment = Enum.TextYAlignment.Top
		label.FontFace = utilFace
		label.TextSize = 15
		label.TextColor3 = color
		label.Text = text
		label.TextStrokeTransparency = 0
		label.TextStrokeColor3 = Color3.new(0, 0, 0)
		label.ZIndex = 10
		label.Visible = false
		label.Parent = espgui
		return setmetatable({}, {
			__newindex = function(_, key, value)
				if key == "Text" then label.Text = value
				elseif key == "Color" then label.TextColor3 = value
				elseif key == "Size" then label.TextSize = value
				elseif key == "Visible" then label.Visible = value
				elseif key == "Position" then label.Position = UDim2.fromOffset(value.X, value.Y)
				end
			end,
			__index = function(_, key)
				if key == "Text" then return label.Text end
				if key == "Visible" then return label.Visible end
				if key == "Remove" or key == "Destroy" then
					return function() label:Destroy() end
				end
				return nil
			end,
		})
	end

	local function makedrawimage(imageId)
		local img = Instance.new("ImageLabel")
		img.BackgroundTransparency = 1
		img.BorderSizePixel = 0
		img.Image = imageId or ""
		img.ImageTransparency = 0
		img.Size = UDim2.fromOffset(UTIL_IMG_SIZE, UTIL_IMG_SIZE)
		img.Visible = false
		img.ZIndex = 10
		img.Parent = espgui
		return img
	end

	local function getUtilTrackTarget(obj)
		if not obj then return nil, nil end
		if obj:IsA("Model") then
			local root = obj.PrimaryPart or obj:FindFirstChild("Hitbox") or obj:FindFirstChildWhichIsA("BasePart")
			return obj, root
		end
		if obj:IsA("BasePart") then
			local model = obj.Parent and obj.Parent:IsA("Model") and obj.Parent or nil
			return model or obj, obj
		end
		return nil, nil
	end

	local function utilMatchesFilter(obj)
		local model, root = getUtilTrackTarget(obj)
		if not model or not root then return false end
		local rawname = model:IsA("Model") and model.Name or obj.Name
		local realname = utilResolve(rawname)
		return realname ~= nil and isselected(realname)
	end

	local function removeespobjsfor(model)
		if utilespobjects[model] then
			for _, d in ipairs(utilespobjects[model].drawings) do
				pcall(function() d:Remove() end)
			end
			if utilespobjects[model].image then
				pcall(function()
					if typeof(utilespobjects[model].image) == "Instance" and utilespobjects[model].image:IsA("GuiObject") then
						utilespobjects[model].image:Destroy()
					else
						utilespobjects[model].image:Remove()
					end
				end)
			end
			if utilespobjects[model].conn then
				utilespobjects[model].conn:Disconnect()
			end
			utilespobjects[model] = nil
		end
	end

	local function clearutilesp()
		for model, _ in pairs(utilespobjects) do
			removeespobjsfor(model)
		end
	end

	local function addutilesp(obj)
		local model, rootpart = getUtilTrackTarget(obj)
		if not model or not rootpart then return end
		if utilespobjects[model] then return end

		local rawname = model:IsA("Model") and model.Name or tostring(model)
		local realname = utilResolve(rawname) or rawname
		local nametext = utildisplay[realname] or string.lower(realname)
		-- Always the plain (un-skinned) item's picture, whatever skin was thrown.
		local function skinImage()
			local image = resolveUtilImage(realname)
			if image == "" and realname ~= rawname then
				image = resolveUtilImage(rawname)
			end
			return image
		end
		local namedraw = makedrawtext(nametext, utilconfig.color)
		local distdraw = makedrawtext("", utilconfig.color)
		local imgdraw = makedrawimage(skinImage())
		if not namedraw and not distdraw then return end

		utilespobjects[model] = {
			drawings = {},
			image = imgdraw,
			conn = nil,
			root = rootpart,
		}
		if namedraw then utilespobjects[model].drawings[#utilespobjects[model].drawings + 1] = namedraw end
		if distdraw then utilespobjects[model].drawings[#utilespobjects[model].drawings + 1] = distdraw end

		local conn = Port.Track(game:GetService("RunService").RenderStepped:Connect(function()
			pcall(function()
				local trackRoot = utilespobjects[model] and utilespobjects[model].root
				if not trackRoot or not trackRoot.Parent then
					removeespobjsfor(model)
					return
				end

				local cam = workspace.CurrentCamera
				if not cam or not worldToEspScreen then return end
				local pos, onScreen = worldToEspScreen(trackRoot.Position)

				if onScreen and utilconfig.enable and isselected(realname) then
					if utilconfig.images and imgdraw and (not imgdraw.Image or imgdraw.Image == "") then
						local loaded = skinImage()
						if loaded ~= "" then
							imgdraw.Image = loaded
						end
					end
					local showImg = utilconfig.images and imgdraw and imgdraw.Image and imgdraw.Image ~= ""
					local halfImg = UTIL_IMG_SIZE * 0.5

					if namedraw then
						if showImg then
							namedraw.Position = Vector2.new(pos.X, pos.Y - halfImg - UTIL_NAME_GAP)
						else
							namedraw.Position = Vector2.new(pos.X, pos.Y - 8)
						end
						namedraw.Visible = true
					end

					if imgdraw then
						if showImg then
							imgdraw.Position = UDim2.new(0, pos.X - halfImg, 0, pos.Y - halfImg)
							imgdraw.Visible = true
						else
							imgdraw.Visible = false
						end
					end

					if distdraw then
						if utilconfig.distance then
							local dist = math.floor((cam.CFrame.Position - trackRoot.Position).Magnitude)
							distdraw.Text = string.format("%d studs", dist)
							if showImg then
								distdraw.Position = Vector2.new(pos.X, pos.Y + halfImg + UTIL_DIST_GAP)
							else
								distdraw.Position = Vector2.new(pos.X, pos.Y + 6)
							end
							distdraw.Visible = true
						else
							distdraw.Visible = false
						end
					end
				else
					if namedraw then namedraw.Visible = false end
					if distdraw then distdraw.Visible = false end
					if imgdraw then imgdraw.Visible = false end
				end
			end)
		end))

		utilespobjects[model].conn = conn

		Port.Track(model.AncestryChanged:Connect(function(_, parent)
			if not parent then
				removeespobjsfor(model)
			end
		end))
	end

	-- No match environment (lobby): nothing is tracked at all. The lobby's weapon display
	-- models share the utilities' names and used to be picked up.
	local function utilInMatch()
		return LocalPlayer:GetAttribute("EnvironmentID") ~= nil
	end

	local function refreshutilesp()
		clearutilesp()
		if not utilconfig.enable or not utilInMatch() then return end
		for _, obj in ipairs(workspace:GetDescendants()) do
			if (obj:IsA("Model") or obj:IsA("BasePart")) and utilMatchesFilter(obj) then
				addutilesp(obj)
			end
		end
	end

	local v68 = Port.Section(EspTab, "Utility ESP")

	v68:AddToggle('utilenable', {
		Text = 'enable',
		Default = utilconfig.enable,
		Callback = function(value)
			utilconfig.enable = value
			refreshutilesp()
		end
	}):AddColorPicker('utilcolor', {
		Title = 'text color',
		Default = utilconfig.color,
		Default2 = utilconfig.color2 or utilconfig.color,
		Transparency = false,
		Callback = function(value, value2)
			utilconfig.color = value
			utilconfig.color2 = value2 or value
			for _, data in pairs(utilespobjects) do
				for _, d in ipairs(data.drawings) do
					d.Color = value
				end
			end
		end
	})

	v68:AddDropdown('utilitems', {
		Text = 'utilities',
		Values = {
			"grenade",
			"subspace tripmine",
			"flashbang",
			"satchel",
			"warpstone",
			"molotov",
			"smoke grenade"
		},
		Multi = true,
		Default = {},
		Callback = function(value)
			-- The dropdown hands back a list ({ "grenade", ... }); the filter wants a set keyed by
			-- label. As a list it never matched, so every utility showed whatever was picked.
			local set = {}
			if type(value) == "table" then
				for key, entry in pairs(value) do
					if type(key) == "number" and type(entry) == "string" then
						set[entry] = true
					elseif type(key) == "string" and entry then
						set[key] = true
					end
				end
			end
			utilconfig.selected = set
			refreshutilesp()
		end
	})

	v68:AddToggle('utildistance', {
		Text = 'distance',
		Default = utilconfig.distance,
		Callback = function(value)
			utilconfig.distance = value
		end
	})

	v68:AddToggle('utilimages', {
		Text = 'images',
		Default = utilconfig.images,
		Callback = function(value)
			utilconfig.images = value
		end
	})

	Port.OnUnload(clearutilesp)

	-- Entering / leaving a match: scan once when the environment appears, drop everything
	-- when it goes away.
	Port.Track(LocalPlayer:GetAttributeChangedSignal("EnvironmentID"):Connect(function()
		task.defer(refreshutilesp)
	end))

	Port.Track(workspace.DescendantAdded:Connect(function(desc)
		if not utilconfig.enable or not utilInMatch() then return end
		if not desc:IsA("Model") and not desc:IsA("BasePart") then return end
		task.delay(0.15, function()
			if not utilconfig.enable or not utilInMatch() then return end
			if utilMatchesFilter(desc) then
				addutilesp(desc)
			end
		end)
	end))

	end)()

	-- Visuals: ambient sounds (the atmosphere itself is Lin67's Fog & Atmosphere section)
	do
		local SoundService = game:GetService("SoundService")

		local ambienceTab = Port.Section(VisualsTab, "Ambient Sounds")

		local ambientSettings = {
			SoundEnabled = false,
			SelectedSound = "None",
			SoundVolume = 0.6,
		}

		local curambientsound = nil

		local ambientSounds = {
			["None"] = nil,
			["Rain"] = 132717551555191,
			["Night"] = 125710682931536,
			["Birds Chirping"] = 9112831327,
			["Jungle Birds"] = 9114892930,
			["Campfire Crackling"] = 109494611784143,
			["Night Crickets"] = 9112764040,
			["Snow Storm"] = 551546110,
		}

		local function playambientsound()
			if curambientsound then
				curambientsound:Stop()
				curambientsound:Destroy()
				curambientsound = nil
			end

			local soundId = ambientSounds[ambientSettings.SelectedSound]
			if not soundId or not ambientSettings.SoundEnabled then
				return
			end

			curambientsound = Instance.new("Sound")
			curambientsound.Name = "CustomAmbientSound"
			curambientsound.SoundId = "rbxassetid://" .. soundId
			curambientsound.Looped = true
			curambientsound.Volume = ambientSettings.SoundVolume
			curambientsound.Parent = SoundService
			curambientsound:Play()
		end
		Port.OnUnload(function()
			if curambientsound then
				curambientsound:Destroy()
				curambientsound = nil
			end
		end)

		ambienceTab:AddToggle('atmosphere_sound_toggle', {
			Text = 'enable',
			Default = ambientSettings.SoundEnabled,
			Callback = function(v)
				ambientSettings.SoundEnabled = v
				playambientsound()
			end
		})

		ambienceTab:AddDropdown('atmosphere_ambient_sound', {
			Text = 'ambient sound',
			Values = {"None", "Rain", "Night", "Birds Chirping", "Jungle Birds", "Campfire Crackling", "Night Crickets", "Snow Storm"},
			Default = ambientSettings.SelectedSound,
			Multi = false,
			Callback = function(v)
				ambientSettings.SelectedSound = v
				playambientsound()
			end
		})

		ambienceTab:AddSlider('atmosphere_sound_volume', {
			Text = 'volume',
			Min = 0,
			Max = 10,
			Default = ambientSettings.SoundVolume,
			Rounding = 2,
			Compact = true,
			Callback = function(v)
				ambientSettings.SoundVolume = v
				if curambientsound then
					curambientsound.Volume = v
				end
			end
		})
	end

	-- Character: emotes
	do
		local animPlayerTab = Port.Section(CharacterTab, "Emotes & Animations")
		local p = game:GetService("Players").LocalPlayer
		local workspace = game:GetService("Workspace")
		local runService = game:GetService("RunService")

		getgenv()._animCmd = getgenv()._animCmd or nil

		local animPresets = {
			["Meditate"] = "96579993895076", ["Orbit"] = "133811691098518", ["Orbit V2"] = "73208745607037",
			["Orbit V3"] = "137869087140582", ["Floss"] = "72174079036035", ["OJ"] = "110064349530772",
			["Kicking Feet"] = "131879764029003", ["Tweaking"] = "114353590132838", ["Crazy"] = "120819498172771",
			["Crazy V2"] = "105670906411750", ["Take the L"] = "112884830175040", ["Hype"] = "80055417516516",
			["Small / Hide"] = "91194251426204", ["Sea Lion"] = "117932365044349", ["Gangnam"] = "104142334418357",
			["NLE"] = "125783279336153", ["The Man"] = "88737074755910", ["Spider Shit"] = "74716792202343",
			["Low Cortisol"] = "125822752810863", ["Rampage"] = "120605439830304",
		}
		local animPresetNames = {
			"Meditate", "Orbit", "Orbit V2", "Orbit V3", "Floss", "OJ", "Kicking Feet", "Tweaking", "Crazy",
			"Crazy V2", "Take the L", "Hype", "Small / Hide", "Sea Lion", "Gangnam", "NLE", "The Man",
			"Spider Shit", "Low Cortisol", "Rampage",
		}

		animPlayerTab:AddToggle("AnimEnabled", {
			Text = "enabled",
			Default = false,
		}):AddKeyPicker("AnimKey", { Default = "None", SyncToggleState = true, Mode = "Toggle", Text = "anim" })

		animPlayerTab:AddToggle("AnimServerVisible", {
			Tooltip = "Also play on your server rig so other players see it",
			Text = "server side",
			Default = true,
		})

		animPlayerTab:AddToggle("AnimJitter", { Text = "jitter mode", Default = false })
		animPlayerTab:AddSlider("JitterSpeed", { Text = "jitter interval", Default = 0.1, Min = 0.01, Max = 2, Rounding = 2, Suffix = "s" })
		animPlayerTab:AddToggle("AnimLoop", { Text = "loop", Default = true })
		animPlayerTab:AddToggle("AnimAutoRespawn", { Text = "spawn proof", Tooltip = "Start again after you respawn", Default = true })
		animPlayerTab:AddInput("AnimForceID", { Default = "96579993895076", Text = "primary anim id", Placeholder = "numbers", Numeric = false, Finished = true })
		animPlayerTab:AddInput("AnimJitterID", { Default = "120819498172771", Text = "jitter anim id", Placeholder = "numbers", Numeric = false, Finished = true })
		animPlayerTab:AddSlider("AnimSpeed", { Text = "play speed", Default = 2, Min = 0.1, Max = 200, Rounding = 1 })
		animPlayerTab:AddDropdown("AnimPresetSelector", {
			Text = "primary presets",
			Values = animPresetNames,
			Default = "Meditate",
		})
		animPlayerTab:AddDropdown("AnimJitterSelector", {
			Text = "jitter presets",
			Values = animPresetNames,
			Default = "Crazy",
		})

		Options.AnimPresetSelector:OnChanged(function()
			local id = animPresets[Options.AnimPresetSelector.Value]
			if id then
				Options.AnimForceID:SetValue(id)
				if Toggles.AnimEnabled.Value then getgenv()._animCmd = "Play" end
			end
		end)

		Options.AnimJitterSelector:OnChanged(function()
			local id = animPresets[Options.AnimJitterSelector.Value]
			if id then
				Options.AnimJitterID:SetValue(id)
				if Toggles.AnimEnabled.Value and Toggles.AnimJitter.Value then getgenv()._animCmd = "Play" end
			end
		end)

		animPlayerTab:AddButton("play", function()
			getgenv()._animCmd = "Play"
		end)
		animPlayerTab:AddButton("stop", function()
			getgenv()._animCmd = "Stop"
		end);

		(function()
			local animLanes = {}
			local currentAnimIds = { primary = "", jitter = "", jitterOn = false, serverVisible = false }
			local lastJitterSwitch = 0
			local currentJitterIndex = 1
			local serverRigCache = {}
			local serverRigCacheAt = 0

			-- A failed start (bad id / asset not loading) used to be retried on every Heartbeat: each try
			-- is a game:GetObjects call plus a popup, which stacked up into a few FPS. One attempt at a
			-- time, then wait before the same ids are tried again, and tell the user once.
			local animBusy, animFailedKey, animRetryAt, animNotifiedKey = false, nil, 0, nil

			local function normalizeAnimId(raw)
				local txt = tostring(raw or ""):gsub("rbxassetid://", "")
				local numeric = txt:match("%d+")
				return numeric or ""
			end

			local function stripAnimateOnRig(rig)
				if not rig then return end
				pcall(function()
					local animate = rig:FindFirstChild("Animate")
					if animate then
						animate.Disabled = true
						animate:Destroy()
					end
				end)
			end

			local function getFighterEntity()
				local ok, fc = pcall(function()
					return require(p.PlayerScripts.Controllers.FighterController)
				end)
				if ok and fc and fc.LocalFighter and fc.LocalFighter.Entity then
					return fc.LocalFighter.Entity
				end
				return nil
			end

			local function isRigInstance(obj)
				return typeof(obj) == "Instance" and obj:IsA("Model")
			end

			local function getServerRigs()
				local now = tick()
				if now - serverRigCacheAt < 0.35 and #serverRigCache > 0 then
					return serverRigCache
				end
				serverRigCacheAt = now
				serverRigCache = {}

				local live = workspace:FindFirstChild("Live")
				local liveFolder = live and live:FindFirstChild(p.Name)
				if liveFolder and typeof(liveFolder) == "Instance" then
					local added = {}
					local function tryAdd(rig)
						if isRigInstance(rig) and rig.Parent and not added[rig] then
							added[rig] = true
							table.insert(serverRigCache, rig)
						end
					end
					if isRigInstance(liveFolder) then
						tryAdd(liveFolder)
					end
					pcall(function()
						for _, child in liveFolder:GetChildren() do
							if isRigInstance(child) and (child:FindFirstChild("HumanoidRootPart") or child:FindFirstChild("RootPart")) then
								tryAdd(child)
							end
						end
					end)
					if #serverRigCache == 0 and isRigInstance(liveFolder) then
						tryAdd(liveFolder)
					end
				end

				local entity = getFighterEntity()
				if isRigInstance(entity) then
					local dup = false
					for _, r in serverRigCache do
						if r == entity then dup = true break end
					end
					if not dup then
						table.insert(serverRigCache, entity)
					end
				end

				return serverRigCache
			end

			local function deepDiveGetAnimObject(bundleId)
				bundleId = normalizeAnimId(bundleId)
				if bundleId == "" then return nil end

				local success, objects = pcall(function()
					return game:GetObjects("rbxassetid://" .. bundleId)
				end)

				if not success or not objects or #objects == 0 then
					return nil
				end

				local animObj = nil
				for _, topObject in pairs(objects) do
					if typeof(topObject) == "Instance" and topObject:IsA("Animation") then
						animObj = topObject
					elseif typeof(topObject) == "Instance" then
						for _, descendant in pairs(topObject:GetDescendants()) do
							if descendant:IsA("Animation") and descendant.AnimationId ~= "" then
								animObj = descendant
								break
							end
						end
					end
					if animObj then break end
				end

				if animObj then
					return animObj
				end

				local fallback = Instance.new("Animation")
				fallback.AnimationId = "rbxassetid://" .. bundleId
				return fallback
			end

			local function getAnimatorForRig(rig, waitTime)
				if not rig or not rig.Parent then return nil, nil end
				local hum = rig:FindFirstChildOfClass("Humanoid")
				if not hum then
					hum = rig:FindFirstChildWhichIsA("Humanoid", true)
				end
				if not hum then
					local ok, found = pcall(function()
						return rig:WaitForChild("Humanoid", waitTime or 8)
					end)
					hum = ok and found or nil
				end
				if not hum then return nil, nil end

				local animator = hum:FindFirstChildOfClass("Animator")
				if not animator then
					local ok, found = pcall(function()
						return hum:WaitForChild("Animator", waitTime or 8)
					end)
					animator = ok and found or nil
				end
				if not animator then
					animator = Instance.new("Animator")
					animator.Parent = hum
				end
				return animator, hum
			end

			local function deepDivePlayTrack(animator, animObj, priority, speed, looped)
				if not animator or not animObj then return nil end
				local ok, track = pcall(function()
					return animator:LoadAnimation(animObj)
				end)
				if not ok or not track then return nil end
				track.Priority = priority or Enum.AnimationPriority.Action4
				track.Looped = looped
				track:Play(0.1, 1, speed)
				return track
			end

			local function clearAnims()
				for _, lane in ipairs(animLanes) do
					for _, track in pairs(lane.tracks) do
						pcall(function()
							track:Stop(0)
							track:Destroy()
						end)
					end
					if lane.hum then
						pcall(function()
							for _, track in ipairs(lane.hum:GetPlayingAnimationTracks()) do
								track:Stop(0)
							end
						end)
					end
				end
				animLanes = {}
			end
			Port.OnUnload(clearAnims)

			local function buildLane(rig, animPrimary, animJitter, doJitter, speed, looped)
				if not rig or not rig.Parent or not animPrimary then return nil end
				stripAnimateOnRig(rig)
				local animator, hum = getAnimatorForRig(rig, 8)
				if not animator or not hum then return nil end

				local tracks = {}
				tracks[1] = deepDivePlayTrack(animator, animPrimary, Enum.AnimationPriority.Action4, speed, looped)
				if not tracks[1] then return nil end

				if doJitter and animJitter then
					tracks[2] = deepDivePlayTrack(animator, animJitter, Enum.AnimationPriority.Action3, speed, looped)
					if tracks[2] then
						pcall(function() tracks[2]:AdjustWeight(0) end)
					end
				end

				return { rig = rig, hum = hum, animator = animator, tracks = tracks }
			end

			local function startDeepDive(primaryId, jitterId, doJitter, serverVisible, speed, looped)
				if not Toggles.AnimEnabled or not Toggles.AnimEnabled.Value then
				    return false
				end
			clearAnims()

				local animPrimary = deepDiveGetAnimObject(primaryId)
				if not animPrimary then
					if animNotifiedKey ~= primaryId then
						animNotifiedKey = primaryId
						Library:Notify("animation bypass failed (bad bundle id?)", 3)
					end
					return false
				end

				local animJitter = nil
				if doJitter and jitterId ~= "" and jitterId ~= primaryId then
					animJitter = deepDiveGetAnimObject(jitterId)
				end

				local char = p.Character or p.CharacterAdded:Wait()
				stripAnimateOnRig(char)

				local clientLane = buildLane(char, animPrimary, animJitter, doJitter, speed, looped)
				if clientLane then
					table.insert(animLanes, clientLane)
				end

				if serverVisible then
					for _, rig in getServerRigs() do
						local lane = buildLane(rig, animPrimary, animJitter, doJitter, speed, looped)
						if lane then
							table.insert(animLanes, lane)
						end
					end
				end

				return #animLanes > 0
			end

			local function ironLockLane(lane, speed, activePrimary, activeJitter)
				if not lane or not lane.animator then return end
				local tracks = lane.tracks
				local ours = {}
				if tracks[1] then ours[tracks[1]] = true end
				if tracks[2] then ours[tracks[2]] = true end

				pcall(function()
					for _, t in pairs(lane.animator:GetPlayingAnimationTracks()) do
						if not ours[t] then
							t:Stop(0)
						end
					end
				end)

				if tracks[1] then
					pcall(function()
						if activePrimary then
							if not tracks[1].IsPlaying then
								tracks[1]:Play(0, 1, speed)
							end
							tracks[1]:AdjustSpeed(speed)
							tracks[1]:AdjustWeight(1)
						else
							tracks[1]:AdjustWeight(0)
						end
					end)
				end

				if tracks[2] then
					pcall(function()
						if activeJitter then
							if not tracks[2].IsPlaying then
								tracks[2]:Play(0, 1, speed)
							end
							tracks[2]:AdjustSpeed(speed)
							tracks[2]:AdjustWeight(1)
						else
							tracks[2]:AdjustWeight(0)
						end
					end)
				end
			end

			Port.Track(runService.Heartbeat:Connect(function()
				if Library.Unloaded then return end

				local mainEnabled = Toggles.AnimEnabled and Toggles.AnimEnabled.Value
				if not mainEnabled then
					if #animLanes > 0 then clearAnims() end
					return
				end

				local primaryId = normalizeAnimId(Options.AnimForceID and Options.AnimForceID.Value)
				local jitterId = normalizeAnimId(Options.AnimJitterID and Options.AnimJitterID.Value)
				local doJitter = Toggles.AnimJitter and Toggles.AnimJitter.Value
				local serverVisible = Toggles.AnimServerVisible and Toggles.AnimServerVisible.Value
				local playSpeed = Options.AnimSpeed and Options.AnimSpeed.Value or 2
				local looped = Toggles.AnimLoop and Toggles.AnimLoop.Value

				if getgenv()._animCmd == "Stop" then
					getgenv()._animCmd = nil
					clearAnims()
					currentAnimIds.primary = ""
					currentAnimIds.jitter = ""
					currentAnimIds.jitterOn = false
					currentAnimIds.serverVisible = false
					return
				end

				if primaryId == "" then return end
				if animBusy then return end
				local animKey = primaryId .. ":" .. jitterId .. ":" .. tostring(doJitter) .. ":" .. tostring(serverVisible)
				if animKey == animFailedKey and tick() < animRetryAt and getgenv()._animCmd ~= "Play" then return end

				local needsInit = getgenv()._animCmd == "Play"
					or #animLanes == 0
					or (animLanes[1] and animLanes[1].tracks[1] and not animLanes[1].tracks[1].IsPlaying)
				local idsChanged = primaryId ~= currentAnimIds.primary
					or jitterId ~= currentAnimIds.jitter
					or doJitter ~= currentAnimIds.jitterOn
					or serverVisible ~= currentAnimIds.serverVisible

				if needsInit or idsChanged then
					getgenv()._animCmd = nil
					currentAnimIds.primary = primaryId
					currentAnimIds.jitter = jitterId
					currentAnimIds.jitterOn = doJitter
					currentAnimIds.serverVisible = serverVisible
					currentJitterIndex = 1
					lastJitterSwitch = tick()

					animBusy = true
					local okStart, started = pcall(startDeepDive, primaryId, jitterId, doJitter, serverVisible, playSpeed, looped)
					animBusy = false
					if not (okStart and started) then
						animFailedKey, animRetryAt = animKey, tick() + 15
						return
					end
					animFailedKey, animNotifiedKey = nil, nil
				end

				local activePrimary = true
				local activeJitter = false

				if doJitter and animLanes[1] and animLanes[1].tracks[1] then
					local jitterInterval = Options.JitterSpeed and Options.JitterSpeed.Value or 0.1
					if tick() - lastJitterSwitch >= jitterInterval then
						lastJitterSwitch = tick()
						if animLanes[1].tracks[2] then
							currentJitterIndex = currentJitterIndex == 1 and 2 or 1
						else
							for _, lane in ipairs(animLanes) do
								local t = lane.tracks[1]
								if t then
									pcall(function()
										t:Stop(0)
										t:Play(0, 1, playSpeed)
									end)
								end
							end
						end
					end
					if animLanes[1].tracks[2] then
						activePrimary = currentJitterIndex == 1
						activeJitter = currentJitterIndex == 2
					end
				end

				for _, lane in ipairs(animLanes) do
					if lane.rig and lane.rig.Parent then
						ironLockLane(lane, playSpeed, activePrimary, activeJitter)
					end
				end
			end))

			Port.Track(p.CharacterAdded:Connect(function()
			    serverRigCache = {}
			    serverRigCacheAt = 0
			    task.wait(1.5)
			    local autoRespawn = Toggles.AnimAutoRespawn and Toggles.AnimAutoRespawn.Value
			    local mainEnabled = Toggles.AnimEnabled and Toggles.AnimEnabled.Value
			    if autoRespawn and mainEnabled then
			        getgenv()._animCmd = "Play"
			    end
			end))
		end)();
	end

	-- Visuals: world textures
	do
		(function()
		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local workspace = game:GetService("Workspace")
		local Lighting = game:GetService("Lighting")

		_G.Features.WorldTextures = _G.Features.WorldTextures or {
			Enabled = false,
			Selected = { all = true },
			Color = Color3.fromRGB(160, 160, 165),
			Dark = false,
		}
		_G.Features.SmoothTextures = _G.Features.SmoothTextures or {
			Enabled = false,
		}
		_G.Features.TransparentTextures = _G.Features.TransparentTextures or {
			Enabled = false,
			Transparency = 0.6,
		}

		do
			local oldBlur = Lighting:FindFirstChild("InstanceTextureBlur")
			if oldBlur then
				oldBlur:Destroy()
			end
		end

		local WORLD_TEXTURE_TYPES = {
			"all", "grass", "sand", "rock", "metal", "wood", "concrete", "brick",
			"glass", "plastic", "fabric", "ice", "ground", "other",
		}

		local WORLD_TEXTURE_MATS = {
			grass = { Enum.Material.Grass },
			sand = { Enum.Material.Sand },
			ground = { Enum.Material.Ground, Enum.Material.Mud, Enum.Material.LeafyGrass },
			rock = {
				Enum.Material.Rock, Enum.Material.Slate, Enum.Material.Basalt,
				Enum.Material.Pebble, Enum.Material.Limestone, Enum.Material.Salt,
				Enum.Material.CrackedLava, Enum.Material.Glacier, Enum.Material.Snow,
				Enum.Material.Marble, Enum.Material.Granite,
			},
			metal = { Enum.Material.Metal, Enum.Material.DiamondPlate, Enum.Material.CorrodedMetal, Enum.Material.Foil },
			wood = { Enum.Material.Wood, Enum.Material.WoodPlanks },
			concrete = { Enum.Material.Concrete, Enum.Material.Cobblestone },
			brick = { Enum.Material.Brick },
			glass = { Enum.Material.Glass },
			plastic = { Enum.Material.Plastic, Enum.Material.SmoothPlastic },
			fabric = { Enum.Material.Fabric },
			ice = { Enum.Material.Ice },
		}

		local MATERIAL_TO_WORLD_CAT = {}
		for cat, mats in pairs(WORLD_TEXTURE_MATS) do
			for _, mat in ipairs(mats) do
				MATERIAL_TO_WORLD_CAT[mat] = cat
			end
		end

		local smoothTexOrig = {}
		local smoothTexActive = {}
		local smoothTexPending = {}
		local smoothTexLoopConn = nil
		local smoothTexAddConn = nil
		local smoothTexScanRunning = false
		local SMOOTH_TEX_BATCH = 128
		local smoothTexSaStore = Instance.new("Folder")
		smoothTexSaStore.Name = "\0SmoothTexSA"
		smoothTexSaStore.Parent = Port.Holder

		local TARGET_TEXTURE_ASSET_ID = "7658055825"

		local function textureAssetMatches(value)
			if not value then return false end
			local ok, str = pcall(function() return tostring(value) end)
			if not ok or not str then return false end
			return str:find(TARGET_TEXTURE_ASSET_ID, 1, true) ~= nil
		end

		local function instanceHasTargetTexture(inst)
			if not inst then return false end
			local ok, result = pcall(function()
				if inst:IsA("Texture") then
					return textureAssetMatches(inst.Texture) or textureAssetMatches(inst.ColorMap) or textureAssetMatches(inst.ColorMapContent)
				elseif inst:IsA("Decal") then
					return textureAssetMatches(inst.Texture) or textureAssetMatches(inst.ColorMap) or textureAssetMatches(inst.ColorMapContent)
				elseif inst:IsA("SurfaceAppearance") then
					return textureAssetMatches(inst.ColorMap) or textureAssetMatches(inst.Albedo) or textureAssetMatches(inst.ColorMapContent)
				end
				return false
			end)
			return ok and result
		end

		local targetTextureOrig = {}
		local targetTextureConn = nil

		local function getInstProperty(inst, prop)
			local ok, value = pcall(function() return inst[prop] end)
			return ok and value or nil
		end

		local function setInstProperty(inst, prop, value)
			pcall(function() inst[prop] = value end)
		end

		local function matchAssetValue(value)
			if not value then return false end
			return tostring(value):find(TARGET_TEXTURE_ASSET_ID, 1, true) ~= nil
		end

		local function instanceHasTargetTexture(inst)
			if not inst then return false end
			if inst:IsA("Texture") then
				for _, prop in ipairs({"Texture", "ColorMap", "ColorMapContent"}) do
					if matchAssetValue(getInstProperty(inst, prop)) then return true end
				end
			elseif inst:IsA("Decal") then
				for _, prop in ipairs({"Texture", "TextureId", "TextureContent", "ColorMap", "ColorMapContent"}) do
					if matchAssetValue(getInstProperty(inst, prop)) then return true end
				end
			elseif inst:IsA("SurfaceAppearance") then
				for _, prop in ipairs({"ColorMap", "Albedo", "ColorMapContent", "NormalMap", "MetalnessMap", "RoughnessMap"}) do
					if matchAssetValue(getInstProperty(inst, prop)) then return true end
				end
			end
			return false
		end

		local function recordTargetTexture(inst)
			if not inst or targetTextureOrig[inst] or not instanceHasTargetTexture(inst) then return end
			targetTextureOrig[inst] = {
				Texture = getInstProperty(inst, "Texture"),
				TextureId = getInstProperty(inst, "TextureId"),
				TextureContent = getInstProperty(inst, "TextureContent"),
				ColorMap = getInstProperty(inst, "ColorMap"),
				ColorMapContent = getInstProperty(inst, "ColorMapContent"),
				Albedo = getInstProperty(inst, "Albedo"),
				NormalMap = getInstProperty(inst, "NormalMap"),
				MetalnessMap = getInstProperty(inst, "MetalnessMap"),
				RoughnessMap = getInstProperty(inst, "RoughnessMap"),
				Transparency = getInstProperty(inst, "Transparency"),
			}
		end

		local function restoreTargetTexture(inst)
			local orig = targetTextureOrig[inst]
			if not orig then return end
			if inst:IsA("Texture") or inst:IsA("Decal") or inst:IsA("SurfaceAppearance") then
				if orig.Texture ~= nil then setInstProperty(inst, "Texture", orig.Texture) end
				if orig.TextureId ~= nil then setInstProperty(inst, "TextureId", orig.TextureId) end
				if orig.TextureContent ~= nil then setInstProperty(inst, "TextureContent", orig.TextureContent) end
				if orig.ColorMap ~= nil then setInstProperty(inst, "ColorMap", orig.ColorMap) end
				if orig.ColorMapContent ~= nil then setInstProperty(inst, "ColorMapContent", orig.ColorMapContent) end
				if orig.Albedo ~= nil then setInstProperty(inst, "Albedo", orig.Albedo) end
				if orig.NormalMap ~= nil then setInstProperty(inst, "NormalMap", orig.NormalMap) end
				if orig.MetalnessMap ~= nil then setInstProperty(inst, "MetalnessMap", orig.MetalnessMap) end
				if orig.RoughnessMap ~= nil then setInstProperty(inst, "RoughnessMap", orig.RoughnessMap) end
				if orig.Transparency ~= nil then setInstProperty(inst, "Transparency", orig.Transparency) end
			end
			targetTextureOrig[inst] = nil
		end

		local function restoreAllTargetTextures()
			for inst in pairs(targetTextureOrig) do
				restoreTargetTexture(inst)
			end
			table.clear(targetTextureOrig)
		end

		local function degradeTextureInstance(inst)
			if not inst or not instanceHasTargetTexture(inst) then return end
			recordTargetTexture(inst)
			if inst:IsA("Texture") then
				setInstProperty(inst, "Transparency", 1)
				if matchAssetValue(getInstProperty(inst, "Texture")) then setInstProperty(inst, "Texture", "") end
				if matchAssetValue(getInstProperty(inst, "ColorMap")) then setInstProperty(inst, "ColorMap", "") end
				if matchAssetValue(getInstProperty(inst, "ColorMapContent")) then setInstProperty(inst, "ColorMapContent", "") end
			elseif inst:IsA("Decal") then
				setInstProperty(inst, "Transparency", 1)
				if matchAssetValue(getInstProperty(inst, "Texture")) then setInstProperty(inst, "Texture", "") end
				if matchAssetValue(getInstProperty(inst, "TextureId")) then setInstProperty(inst, "TextureId", "") end
				if matchAssetValue(getInstProperty(inst, "TextureContent")) then setInstProperty(inst, "TextureContent", "") end
			elseif inst:IsA("SurfaceAppearance") then
				if matchAssetValue(getInstProperty(inst, "ColorMap")) then setInstProperty(inst, "ColorMap", "") end
				if matchAssetValue(getInstProperty(inst, "Albedo")) then setInstProperty(inst, "Albedo", "") end
				if matchAssetValue(getInstProperty(inst, "ColorMapContent")) then setInstProperty(inst, "ColorMapContent", "") end
				if matchAssetValue(getInstProperty(inst, "NormalMap")) then setInstProperty(inst, "NormalMap", "") end
				if matchAssetValue(getInstProperty(inst, "MetalnessMap")) then setInstProperty(inst, "MetalnessMap", "") end
				if matchAssetValue(getInstProperty(inst, "RoughnessMap")) then setInstProperty(inst, "RoughnessMap", "") end
			end
		end

		local function processTargetTextureInstance(inst)
			if not inst then return end
			if instanceHasTargetTexture(inst) then degradeTextureInstance(inst) end
			for _, child in ipairs(inst:GetDescendants()) do
				if instanceHasTargetTexture(child) then degradeTextureInstance(child) end
			end
		end

		local function scanTargetTextures()
			for i, inst in ipairs(game:GetDescendants()) do
				if instanceHasTargetTexture(inst) then degradeTextureInstance(inst) end
				if i % 4000 == 0 then task.wait() end -- yield so a big map doesn't freeze a frame
			end
		end

		local function startTargetTextureFilter()
			scanTargetTextures()
			if targetTextureConn then targetTextureConn:Disconnect() end
			targetTextureConn = Port.Track(game.DescendantAdded:Connect(function(inst)
				task.wait(0.1)
				processTargetTextureInstance(inst)
			end))
		end

		local function stopTargetTextureFilter()
			if targetTextureConn then
				targetTextureConn:Disconnect()
				targetTextureConn = nil
			end
			restoreAllTargetTextures()
		end

		local function updSmoothTextures()
			if _G.Features.SmoothTextures.Enabled then
				startTargetTextureFilter()
			else
				stopTargetTextureFilter()
			end
		end

		local function darkenColor(color)
			if not color then return Color3.new(0.2, 0.2, 0.2) end
			return Color3.new(color.R * 0.45, color.G * 0.45, color.B * 0.45)
		end

		local darkTexOrig = {}
		local darkTexConn = nil

		local function applyDarkTexturesToInst(inst)
			if not inst or not inst:IsA("BasePart") then return end
			if darkTexOrig[inst] ~= nil then return end
			darkTexOrig[inst] = inst.Color
			pcall(function() inst.Color = darkenColor(inst.Color) end)
		end

		local function applyDarkTextures()
			for i, inst in ipairs(workspace:GetDescendants()) do
				applyDarkTexturesToInst(inst)
				if i % 4000 == 0 then
					task.wait() -- yield so a big map doesn't freeze a frame
					if not _G.Features.WorldTextures.Dark then break end
				end
			end
			if darkTexConn then darkTexConn:Disconnect() end
			darkTexConn = Port.Track(workspace.DescendantAdded:Connect(function(inst)
				task.defer(function()
					if _G.Features.WorldTextures.Dark then
						applyDarkTexturesToInst(inst)
					end
				end)
			end))
		end

		local function restoreDarkTextures()
			if darkTexConn then
				darkTexConn:Disconnect()
				darkTexConn = nil
			end
			for inst, oldColor in pairs(darkTexOrig) do
				if inst and inst.Parent then
					pcall(function() inst.Color = oldColor end)
				end
			end
			table.clear(darkTexOrig)
		end

		local function updDarkTextures()
			if _G.Features.WorldTextures.Dark then
				applyDarkTextures()
			else
				restoreDarkTextures()
			end
		end

		local transparentTexOrig = {}
		local transparentConn = nil

		local function isWorldPart(inst)
			if not inst or not inst:IsA("BasePart") then return false end
			if inst.Transparency >= 0.95 then return false end

			local model = inst:FindFirstAncestorWhichIsA("Model")
			if model then
				if Players:GetPlayerFromCharacter(model) then return false end
				if model:FindFirstChildOfClass("Humanoid") then return false end
				if model.Name:find("Weapon") or model.Name:find("Projectile") or model.Name:find("Effect") then return false end
			end

			if inst.Parent and (inst.Parent.Name == "ViewModels" or inst.Parent.Name == "Effects") then return false end
			if inst:FindFirstAncestor("Camera") then return false end

			return true
		end

		local function applyTransparentToInst(inst)
			if not isWorldPart(inst) then return end
			if transparentTexOrig[inst] then return end
			transparentTexOrig[inst] = inst.Transparency
			local targetTrans = math.clamp(_G.Features.TransparentTextures.Transparency, 0.05, 0.95)
			pcall(function()
				inst.Transparency = targetTrans
			end)
		end

		local function refreshAllTransparent()
			for inst, _ in pairs(transparentTexOrig) do
				if inst and inst.Parent then
					local targetTrans = math.clamp(_G.Features.TransparentTextures.Transparency, 0.05, 0.95)
					pcall(function() inst.Transparency = targetTrans end)
				end
			end
		end

		local function applyTransparentTextures()
			for i, inst in ipairs(workspace:GetDescendants()) do
				applyTransparentToInst(inst)
				if i % 4000 == 0 then
					task.wait() -- yield so a big map doesn't freeze a frame
					if not _G.Features.TransparentTextures.Enabled then break end
				end
			end
			if transparentConn then transparentConn:Disconnect() end
			transparentConn = Port.Track(workspace.DescendantAdded:Connect(function(inst)
				task.defer(function()
					if _G.Features.TransparentTextures.Enabled then
						applyTransparentToInst(inst)
					end
				end)
			end))
		end

		local function restoreTransparentTextures()
			if transparentConn then
				transparentConn:Disconnect()
				transparentConn = nil
			end
			for inst, oldTrans in pairs(transparentTexOrig) do
				if inst and inst.Parent then
					pcall(function() inst.Transparency = oldTrans end)
				end
			end
			table.clear(transparentTexOrig)
		end

		local function updTransparentTextures()
			if _G.Features.TransparentTextures.Enabled then
				applyTransparentTextures()
			else
				restoreTransparentTextures()
			end
		end

		getgenv().InstanceUpdSmoothTextures = updSmoothTextures
		getgenv().InstanceUpdDarkTextures = updDarkTextures
		getgenv().InstanceUpdTransparentTextures = updTransparentTextures

		local texturesBox = Port.Section(VisualsTab, "World Textures")

		texturesBox:AddToggle('smooth_textures', {
			Text = 'smooth textures',
			Default = _G.Features.SmoothTextures.Enabled,
			Tooltip = 'makes map textures smooth (smooth plastic, hides surface detail)',
			Callback = function(val)
				_G.Features.SmoothTextures.Enabled = val
				local fn = getgenv().InstanceUpdSmoothTextures
				if fn then fn() end
			end
		})

		texturesBox:AddToggle('dark_textures', {
			Text = 'dark textures',
			Default = _G.Features.WorldTextures.Dark,
			Tooltip = 'darkens world parts for a deeper, darker texture look',
			Callback = function(val)
				_G.Features.WorldTextures.Dark = val
				local fn = getgenv().InstanceUpdDarkTextures
				if fn then fn() end
			end
		})

		local transparentToggle = texturesBox:AddToggle('transparent_textures', {
			Text = 'transparent textures',
			Default = _G.Features.TransparentTextures.Enabled,
			Tooltip = 'makes world textures semi-transparent',
			Callback = function(val)
				_G.Features.TransparentTextures.Enabled = val
				local fn = getgenv().InstanceUpdTransparentTextures
				if fn then fn() end
			end
		})

		texturesBox:AddSlider("TransparentStrength", {
			Text = "transparency",
			Default = _G.Features.TransparentTextures.Transparency,
			Min = 0.5,
			Max = 1,
			Rounding = 2,
			Compact = true,
			Callback = function(val)
				_G.Features.TransparentTextures.Transparency = val
				if _G.Features.TransparentTextures.Enabled then
					refreshAllTransparent()
				end
			end
		})

		if _G.Features.SmoothTextures.Enabled then
			updSmoothTextures()
		end
		if _G.Features.WorldTextures.Dark then
			updDarkTextures()
		end
		if _G.Features.TransparentTextures.Enabled then
			updTransparentTextures()
		end

		end)()
	end
end

-- If the game changed under it, keep the rest of the hub (settings, HUD,
-- saved config) working.
local portedOk, portedError = pcall(loadPortedFeatures)
if not portedOk then
	warn("Lin67 Hub: combat / ESP / character features failed to load:", portedError)
	Window:Notify({ Title = "Some features failed to load", Content = tostring(portedError), Icon = "error", Duration = 8 })
end

-- Features merged in from main. A failure here mustn't stop the HUD /
-- config autoload below, so they run protected like the ported block.
local extrasOk, extrasError = pcall(function()
	--==========================================================================--
	--== Combat & movement extras (from main)                                ==--
	--==========================================================================--
	-- Added after the ported Combat sections so they come last in the tab.

	do
		local COMBAT_STEP = PREFIX .. "CombatExtras"

		-- Targeting -------------------------------------------------------------------

		local function isEnemy(player)
			if player == LocalPlayer then
				return false
			end
			-- The game tracks teams with the TeamID player attribute (Player.Team stays
			-- nil), so use that first; no TeamID means no team = enemy.
			local myId, theirId = LocalPlayer:GetAttribute("TeamID"), player:GetAttribute("TeamID")
			if myId ~= nil and theirId ~= nil then
				return myId ~= theirId
			end
			local localTeam, playerTeam = LocalPlayer.Team, player.Team
			return not (localTeam and playerTeam and localTeam == playerTeam)
		end

		local function isAlive(character)
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			return humanoid ~= nil and humanoid.Health > 0
		end

		local function screenPosition(part)
			local cam = camera()
			if not cam then
				return nil
			end
			local pos = cam:WorldToViewportPoint(part.Position)
			if pos.Z <= 0 then
				return nil
			end
			return Vector2.new(pos.X, pos.Y)
		end

		local function isVisible(origin, targetPart)
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Exclude
			params.FilterDescendantsInstances = { LocalPlayer.Character }
			local result = workspace:Raycast(origin, targetPart.Position - origin, params)
			return result == nil or result.Instance:IsDescendantOf(targetPart.Parent)
		end

		-- Enemies on screen, closest to the crosshair first.
		local function getTargets(fovRadius, checkVisible)
			local cam = camera()
			if not cam then
				return {}
			end
			local center = cam.ViewportSize / 2
			local results = {}
			for _, player in Players:GetPlayers() do
				local character = player.Character
				if isEnemy(player) and character and isAlive(character) then
					local part = character:FindFirstChild("HitboxHead") or character:FindFirstChild("Head")
					local sPos = part and screenPosition(part)
					if sPos then
						local distance = (sPos - center).Magnitude
						if (fovRadius <= 0 or distance <= fovRadius)
							and (not checkVisible or isVisible(cam.CFrame.Position, part))
						then
							table.insert(results, { player = player, character = character, part = part, distance = distance })
						end
					end
				end
			end
			table.sort(results, function(a, b)
				return a.distance < b.distance
			end)
			return results
		end

		local function simulateClick()
			if type(mouse1click) == "function" then
				mouse1click()
				return
			end
			pcall(function()
				local vim = cloneref(game:GetService("VirtualInputManager"))
				vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)
				task.defer(function()
					vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)
				end)
			end)
		end

		-- Triggerbot --------------------------------------------------------------------

		local triggerbot = { Enabled = false, KeyActive = false, ReactionTime = 0.1, ReleaseTime = 0.05, Reaction = nil, Release = 0 }
		local HITBOX_PARTS = { HitboxHead = true, HitboxBody = true, Head = true, HumanoidRootPart = true }

		local function crosshairOnEnemy()
			local cam = camera()
			if not cam then
				return false
			end
			local ray = cam:ViewportPointToRay(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Exclude
			params.FilterDescendantsInstances = { LocalPlayer.Character }
			local hit = workspace:Raycast(ray.Origin, ray.Direction * 2000, params)
			local model = hit and hit.Instance:FindFirstAncestorOfClass("Model")
			local player = model and Players:GetPlayerFromCharacter(model)
			return player ~= nil and isEnemy(player) and isAlive(model) and HITBOX_PARTS[hit.Instance.Name] == true
		end

		local function updateTriggerbot(dt)
			local character = LocalPlayer.Character
			if not (triggerbot.Enabled and triggerbot.KeyActive and character and isAlive(character)) then
				triggerbot.Reaction, triggerbot.Release = nil, 0
				return
			end
			if crosshairOnEnemy() then
				triggerbot.Reaction = (triggerbot.Reaction or 0) + dt
				if triggerbot.Reaction >= triggerbot.ReactionTime then
					triggerbot.Release = triggerbot.ReleaseTime
					simulateClick()
					return
				end
			else
				triggerbot.Reaction = nil
			end
			triggerbot.Release = math.max(0, triggerbot.Release - dt)
			if triggerbot.Release > 0 then
				simulateClick()
			end
		end

		local TriggerbotSection = CombatTab:AddSection("Triggerbot")
		local triggerbotToggle = TriggerbotSection:AddToggle({
			Title = "Enabled",
			Description = "Auto-fire while your crosshair is on an enemy hitbox",
			Default = false,
			Flag = "TriggerbotEnabled",
			Callback = function(on)
				triggerbot.Enabled = on
			end,
		})
		MD3.GearUI.gated(TriggerbotSection, triggerbotToggle, {
			KeyTitle = "Hold key",
			KeyFlag = "TriggerbotKey",
			ModeFlag = "TriggerbotMode",
			Modes = { "Always", "Hold", "Toggle" },
			DefaultMode = "Hold",
			OnActive = function(active) triggerbot.KeyActive = active end,
		})
		TriggerbotSection:AddSlider({ Title = "Reaction time", Min = 0, Max = 2, Step = 0.01, Default = triggerbot.ReactionTime, Suffix = "s", Flag = "TriggerbotReaction", Callback = function(v) triggerbot.ReactionTime = v end })
		TriggerbotSection:AddSlider({ Title = "Release time", Min = 0, Max = 2, Step = 0.01, Default = triggerbot.ReleaseTime, Suffix = "s", Flag = "TriggerbotRelease", Callback = function(v) triggerbot.ReleaseTime = v end })

		-- Flickbot --------------------------------------------------------------------
		-- On key press the camera follows an eased, slightly curved path to the
		-- closest enemy's head, optionally clicks, then waits out a cooldown.

		local flickbot = {
			Duration = 120, Curvature = 0.2, Humanness = 0.3, Cooldown = 200, Shoot = true, ShotDelay = 30,
			State = "Idle", Timer = 0, Path = nil, Index = 1, Elapsed = 0, Part = nil,
		}

		-- Guns that have no spread once aimed (the Sniper: AimSpreadMultiplier 0) fire wildly from
		-- the hip. For those the flick waits until the scope is fully in (IsAiming and the aim
		-- spring at its end) before it starts, and again before it clicks.
		local flickFighterController = nil
		local function flickAimState()
			if not flickFighterController then
				local ok, controller = pcall(function()
					return require(LocalPlayer.PlayerScripts.Controllers.FighterController)
				end)
				flickFighterController = ok and controller or nil
			end
			local fighter = flickFighterController and flickFighterController.LocalFighter
			local item = fighter and fighter.EquippedItem
			if not item then
				return false, true
			end
			local okInfo, multiplier = pcall(function()
				return item.Info.AimSpreadMultiplier
			end)
			if not (okInfo and multiplier == 0) then
				return false, true -- not a scope-only gun: nothing to wait for
			end
			local okAim, aiming = pcall(function()
				return item:Get("IsAiming")
			end)
			local okView, amount = pcall(function()
				return (rawget(item, "ViewModel") or item.ViewModel).CurrentAimValue
			end)
			return true, okAim and aiming == true and okView and type(amount) == "number" and amount >= 0.95
		end

		local function flickTo(target)
			local cam = camera()
			local sPos = cam and screenPosition(target.part)
			if not sPos then
				return
			end
			local cx, cy = cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2
			local dx, dy = sPos.X - cx, sPos.Y - cy
			local distance = math.sqrt(dx * dx + dy * dy)
			if distance < 1 then
				return
			end
			local steps = math.max(4, math.floor(flickbot.Duration / 8))
			local path = {}
			for step = 0, steps do
				local t = step / steps
				local ease = t * t * (3 - 2 * t)
				local noise = (1 - t) * flickbot.Humanness * (math.random() - 0.5) * distance * 0.1
				local curve = math.sin(t * math.pi) * flickbot.Curvature * distance * 0.15
				local px, py = cx + dx * ease + curve + noise, cy + dy * ease + noise * 0.5
				path[step + 1] = { t = t * flickbot.Duration, direction = cam:ViewportPointToRay(px, py).Direction }
			end
			flickbot.Path, flickbot.Index, flickbot.Elapsed = path, 1, 0
			flickbot.Part = target.part
			flickbot.State = "Flicking"
		end

		local function finishFlick()
			flickbot.Part, flickbot.Path = nil, nil
			flickbot.State = flickbot.Cooldown > 0 and "Cooldown" or "Idle"
			flickbot.Timer = flickbot.Cooldown / 1000
		end

		local function updateFlickbot(dt)
			local state = flickbot.State
			if state == "Flicking" then
				local path, cam = flickbot.Path, camera()
				if not (path and cam and flickbot.Part and flickbot.Part.Parent) then
					finishFlick()
					return
				end
				flickbot.Elapsed += dt * 1000
				local index = flickbot.Index
				while index < #path and path[index + 1].t <= flickbot.Elapsed do
					index += 1
				end
				flickbot.Index = index
				local current, following = path[index], path[index + 1]
				local direction = current.direction
				if following then
					local span = following.t - current.t
					direction = direction:Lerp(following.direction, span > 0 and math.clamp((flickbot.Elapsed - current.t) / span, 0, 1) or 1)
				end
				-- Pull toward where the target is now, not where it was at the press.
				local toTarget = (flickbot.Part.Position - cam.CFrame.Position).Unit
				local progress = math.clamp(flickbot.Elapsed / flickbot.Duration, 0, 1)
				direction = (direction + (toTarget - path[#path].direction) * progress).Unit
				cam.CFrame = CFrame.lookAt(cam.CFrame.Position, cam.CFrame.Position + direction)
				if not following then
					if flickbot.Shoot then
						flickbot.State, flickbot.Timer = "PostShot", flickbot.ShotDelay / 1000
					else
						finishFlick()
					end
				end
			elseif state == "WaitAim" then
				local needsAim, ready = flickAimState()
				flickbot.Timer -= dt
				if ready or not needsAim then
					flickbot.State = "Idle"
					local targets = getTargets(0, true)
					if targets[1] then
						flickTo(targets[1])
					end
				elseif flickbot.Timer <= 0 then
					flickbot.State = "Idle" -- never scoped in: give up
				end
			elseif state == "PostShot" or state == "Cooldown" then
				flickbot.Timer -= dt
				if flickbot.Timer <= 0 then
					if state == "PostShot" then
						local needsAim, ready = flickAimState()
						if needsAim and not ready and (flickbot.AimWait or 0) < 2 then
							flickbot.AimWait = (flickbot.AimWait or 0) + dt -- not scoped yet: hold the shot
							return
						end
						flickbot.AimWait = 0
						simulateClick()
						finishFlick()
					else
						flickbot.State = "Idle"
					end
				end
			end
		end

		local FlickbotSection = CombatTab:AddSection("Flickbot")
		FlickbotSection:AddKeybind({
			Title = "Flick key",
			Description = "Snap to the closest visible enemy on press",
			Mode = "Press",
			Flag = "FlickbotKey",
			Callback = function()
				if flickbot.State == "Idle" then
					local needsAim, ready = flickAimState()
					if needsAim and not ready then
						-- a scope-only gun that isn't scoped in yet: start once it is (3 s at most)
						flickbot.State, flickbot.Timer, flickbot.AimWait = "WaitAim", 3, 0
						return
					end
					local targets = getTargets(0, true)
					if targets[1] then
						flickTo(targets[1])
					end
				end
			end,
		})
		FlickbotSection:AddSlider({ Title = "Flick duration", Min = 20, Max = 500, Step = 5, Default = flickbot.Duration, Suffix = "ms", Flag = "FlickbotDuration", Callback = function(v) flickbot.Duration = v end })
		FlickbotSection:AddSlider({ Title = "Curvature", Min = 0, Max = 1, Step = 0.05, Default = flickbot.Curvature, Flag = "FlickbotCurvature", Callback = function(v) flickbot.Curvature = v end })
		FlickbotSection:AddSlider({ Title = "Humanness", Min = 0, Max = 1, Step = 0.05, Default = flickbot.Humanness, Flag = "FlickbotHumanness", Callback = function(v) flickbot.Humanness = v end })
		FlickbotSection:AddSlider({ Title = "Cooldown", Min = 0, Max = 2000, Step = 10, Default = flickbot.Cooldown, Suffix = "ms", Flag = "FlickbotCooldown", Callback = function(v) flickbot.Cooldown = v end })
		FlickbotSection:AddToggle({ Title = "Auto shoot", Default = flickbot.Shoot, Flag = "FlickbotShoot", Callback = function(on) flickbot.Shoot = on end })
		FlickbotSection:AddSlider({ Title = "Shot delay", Min = 0, Max = 200, Step = 5, Default = flickbot.ShotDelay, Suffix = "ms", Flag = "FlickbotShotDelay", Callback = function(v) flickbot.ShotDelay = v end })

		-- Target lock -------------------------------------------------------------------
		-- Marks the closest enemy; the lock drops when they die or leave.

		local lockedPlayer = nil
		local TargetLockSection = CombatTab:AddSection("Target Lock")
		TargetLockSection:AddKeybind({
			Title = "Lock key",
			Description = "Press to lock onto the closest enemy, again to release",
			Mode = "Press",
			Flag = "TargetLockKey",
			Callback = function()
				if lockedPlayer then
					lockedPlayer = nil
					Window:Notify({ Title = "Target Lock", Content = "Released", Icon = "lock_open" })
					return
				end
				local targets = getTargets(0, false)
				if targets[1] then
					lockedPlayer = targets[1].player
					Window:Notify({ Title = "Target Lock", Content = "Locked: " .. lockedPlayer.Name, Icon = "lock" })
				end
			end,
		})

		local function checkLockedTarget()
			if not lockedPlayer then
				return
			end
			local character = lockedPlayer.Parent and lockedPlayer.Character
			if not character or not isAlive(character) then
				lockedPlayer = nil
				Window:Notify({ Title = "Target Lock", Content = "Target eliminated", Icon = "lock_open" })
			end
		end

		-- Ragebot -----------------------------------------------------------------------
		-- Picks the best enemy every frame and fires the game's own UseItem
		-- (StartShooting) remote at their hitbox, the same call the game runs when
		-- you shoot -- guns and melee both use it. The aim CFrame is built from our
		-- root toward the target's hitbox, so nothing on the client camera moves
		-- (silent). An optional teleport snaps our root onto the target for the frame
		-- of the shot (needed for melee reach) and restores it before the frame is
		-- drawn, so our own view never jumps.

		local function rageWeaponDefaults(overrides)
			local d = {
				HitPart = "HitboxHead",
				HitChance = 100,
				Rate = 20,
				Teleport = false,
				TeleportReach = 0,
				Glue = false,
			}
			if overrides then
				for k, v in pairs(overrides) do d[k] = v end
			end
			return d
		end

		local rage = {
			Enabled = false,
			TargetDummies = false,
			ManualFire = false,
			EvadeBetweenShots = true,
			Activation = "Always",
			KeyActive = false,
			Priority = "Crosshair",
			WallCheck = false,
			AntiDeflect = true,
			AntiTranslocate = true,   -- always on with the ragebot (no toggle): tracks enemies hiding below OutOfBoundsParts
			PrioritizeHackers = false,
			SpoofViewAngles = false,
			Evasion = "Auto",
			EvadeRadius = 100,
			CycleMode = false,
			HideTime = 2,
			AttackTime = 1,
			AttackPrep = 0.2,
			AttackHeight = -0.7,      -- gun stand height relative to the target's head hitbox
			AutoUnderground = true,   -- detect an underground target and shoot it from below its head
			UndergroundHeight = -2,   -- stand height relative to the head of an underground target
			EvadeAnchorCharacter = false, -- Random evasion ring around the character instead of the world origin
			PBDepthUp = 5.5,          -- ProjectileBreaker: how far under the surface (oscillates 0..this)
			PBDepthForward = 4,       -- ProjectileBreaker: how far along the surface (oscillates 0..this)
			PBInterval = 0.3,         -- ProjectileBreaker: seconds before picking another surface
			ImmuneReload = true,      -- park in the immune ring while reloading / out of ammo
			AttackFrames = 0,         -- 0 = stay on the target between shots; 1-5 = only this many frames per shot, evade otherwise
			KnifeCooldown = 0.8,
			WaitKnifeHeavy = true, -- against a knife heavy attack: only strike in the cooldown after it
			DropMode = false, -- beta: teleport to a spot that is not out of bounds, then fall by gravity (no evasion)
			DropHeight = 60, -- studs above (+) or below (-) the floor you were standing on
			DropDistance = 30000, -- studs away from where you stood (far past every OutOfBoundsPart)
			DropSpeed = 800, -- studs/s: the fall is kept at least this fast while you are in the air
			DropAttackRange = 1000, -- drop mode only attacks a target closer than this (studs)
			RenderRestore = true, -- the RenderStepped hook that puts the real position back for the camera
			HeavyNotify = true, -- popup each time the wait kicks in (beta, to see that it works)
			_heavyNotifiedAt = 0,
			HeavySwingTime = 0.2, -- seconds from the heavy attack's start that count as the swing
			_cyclePhase = "Attack",
			_cycleTimer = 0,
			lastShotAt = 0,
			lastViewAt = 0,
			lastEvadeAt = 0,
			backupCFrame = nil,
			glueRoot = nil,
			-- 60/s = as fast as the server accepts (handgun took a shot every ~0.07 s);
			-- lower it only to save ammo.
			Primary   = rageWeaponDefaults({ Teleport = true, Rate = 60 }),
			Secondary = rageWeaponDefaults({ Teleport = true, Rate = 60 }),
			Knife     = rageWeaponDefaults({ HitPart = "HitboxHead", Rate = 20, Teleport = true, TeleportReach = 0 }),
			Melee     = rageWeaponDefaults({ HitPart = "HitboxHead", Rate = 20, Teleport = true, TeleportReach = 0 }),
			ShootFrames = 1,
			Stability = 0.15,
			_lockedUntil = nil,
			_spatial = {},
			_glue = nil,
			_dt = 1/60,
			_knifeWindowUntil    = 0,
			_knifeAttackCoolUntil = 0,
			_reloadUntil         = 0,
			_attackStart         = nil,
			_lastObjId           = nil,
			_spoofHiding         = false,
			TranslocateOffset    = -5,
			WeaponOnEmpty        = "Reload",   -- "Reload" | "Swap" | "SwapOrReload"
			WeaponPriority       = { "Primary", "Secondary", "Knife", "Melee" },
			_swapCoolUntil       = 0,
			_swapTarget          = nil,  -- item we most recently asked to equip
			_swapTargetUntil     = 0,    -- trust that item as equipped until this tick()
			_purgeEvade          = false,
			_evasionTrack        = {},  -- [player] = { lastNormalAt, normalPos }
			_evasionServerCF     = nil, -- cached evasion destination (set at intervals)
			_evasionClientCF     = nil, -- real root CFrame to restore in RenderPriority.First
		}

		-- Utility/melee items that can't ragebot; everything else (guns + knives) can.
		local RAGE_RESTRICTED = {
			Grenade = true, Flashbang = true, ["Smoke Grenade"] = true, Molotov = true,
			Satchel = true, ["Jump Pad"] = true, Medkit = true, ["War Horn"] = true,
			["Subspace Tripmine"] = true, Warpstone = true, ["Riot Shield"] = true,
		}

		-- Real damage hitboxes the game uses; falls back to Head/Torso rigs.
		-- Snipers register on the small hitboxes, so prefer those when `sniper`.
		local function rageHitbox(character, sniper)
			local hitPart = rage._hitPartOverride or "HitboxHead"
			-- The server only validates the Hitbox parts, never the visual Head/Body.
			if hitPart == "Head" then hitPart = "HitboxHead" end
			if hitPart == "HitboxHead" then
				if sniper then
					local small = character:FindFirstChild("HitboxHeadSmall")
					if small then return small end
				end
				return character:FindFirstChild("HitboxHead")
					or character:FindFirstChild("Head")
					or character:FindFirstChild("HumanoidRootPart")
			elseif hitPart == "HitboxBody" or hitPart == "Body" then
				if sniper then
					local small = character:FindFirstChild("HitboxBodySmall")
					if small then return small end
				end
				return character:FindFirstChild("HitboxBody")
					or character:FindFirstChild("HitboxBodySmall")
					or character:FindFirstChild("UpperTorso")
					or character:FindFirstChild("Torso")
					or character:FindFirstChild("HumanoidRootPart")
			elseif hitPart == "Closest" then
				local camPos = camera() and camera().CFrame.Position
				local best, bestD
				for _, part in character:GetChildren() do
					if part:IsA("BasePart") and camPos then
						local d = (part.Position - camPos).Magnitude
						if not bestD or d < bestD then bestD, best = d, part end
					end
				end
				return best or character:FindFirstChild("HitboxHead") or character:FindFirstChild("Head")
			elseif hitPart == "Random" then
				local list = {}
				for _, part in character:GetChildren() do
					if part:IsA("BasePart") then list[#list + 1] = part end
				end
				if #list > 0 then return list[math.random(1, #list)] end
			end
			-- Fallback for any other hitPart string: treat as HitboxHead
			if sniper then
				local small = character:FindFirstChild("HitboxHeadSmall")
				if small then return small end
			end
			return character:FindFirstChild("HitboxHead")
				or character:FindFirstChild("Head")
				or character:FindFirstChild("HumanoidRootPart")
		end

		-- Executor-elevated property write when available (needed on some builds to
		-- set the root CFrame under an anti-cheat identity); plain assignment works
		-- for our own network-owned character on most executors.
		-- Runs every frame while evading / attacking, so no closures are created here.
		local function rageWriteCFrame(part, cframe)
			part.CFrame = cframe
		end
		local function rageSetCFrame(part, cframe)
			if type(setthreadidentity) == "function" and type(getthreadidentity) == "function" then
				local id = getthreadidentity()
				setthreadidentity(8)
				local ok = pcall(rageWriteCFrame, part, cframe)
				setthreadidentity(id)
				if ok then return end
			end
			pcall(rageWriteCFrame, part, cframe)
		end

		-- Elevated write for a protected property (PhysicsRepRootPart). No-op if the
		-- executor lacks setthreadidentity; plain assignment is tried as a fallback.
		local function rageSetProp(inst, prop, value)
			if type(setthreadidentity) == "function" and type(getthreadidentity) == "function" then
				local ok = pcall(function()
					local id = getthreadidentity()
					setthreadidentity(8)
					inst[prop] = value
					setthreadidentity(id)
				end)
				if ok then return end
			end
			pcall(function() inst[prop] = value end)
		end

		-- Classify the equipped item straight from its Info table (never the screen):
		-- name, raycast/melee/sniper/revolver flags and the server attack cooldown.
		local function rageWeaponInfo(item)
			local info
			pcall(function() info = item.Info end)
			local name = (info and info.Name) or (item.Get and item:Get("Name"))
			local itype = info and info.Type
			local iclass = info and info.Class
			local isRaycast = info and info.IsRaycast == true
			local isMelee = itype == "Melee"
				or (info ~= nil and info.AttackReach ~= nil and info.MaxAmmo == nil and not isRaycast)
			local isKnife = isMelee and (name == "Knife")
			local isSniper = type(name) == "string" and string.find(name, "Sniper") ~= nil
			local isRevolver = name == "Revolver" or (info ~= nil and info.QuickShotCooldown ~= nil)
			local attackCd = (info and (info.HeavyAttackCooldown or info.AttackCooldown or info.ShootCooldown)) or 0
			if isRevolver and info and type(info.QuickShotCooldown) == "number" then
				attackCd = info.QuickShotCooldown
			end
			local slot = (isMelee and isKnife) and "Knife"
				or isMelee and "Melee"
				or (iclass == "Secondary" and "Secondary")
				or "Primary"
			return name, isRaycast, isMelee, isSniper, isRevolver, attackCd, slot, isKnife
		end

		local function rageIsDeflecting(player)
			-- Primary: read server-replicated _deflect_cooldown attribute.
			local char = player.Character
			if char then
				local ok, cd = pcall(function() return char:GetAttribute("_deflect_cooldown") end)
				if ok and type(cd) == "number" and tick() < cd then return true end
			end
			-- Fallback: katana-deflect bookkeeping from silent-aim block.
			local shared = getgenv().InstanceKatanaUsers
			if type(shared) == "table" and shared[player] then return true end
			return false
		end

		local RAGE_SPATIAL_LIMIT = 4194304

		-- Detect if a player is hiding below an OutOfBoundsPart (Translocate evasion).
		local function rageIsTranslocated(player)
			local char = player.Character
			if not char then return false end
			local root = char:FindFirstChild("HumanoidRootPart")
			if not root then return false end
			local pos = root.Position
			-- Fast path: extremely low Y strongly suggests below-map hiding.
			if pos.Y < -200 then return true end
			-- Random-evasion extreme axis (1,073,741,824).
			if math.abs(pos.X) >= RAGE_SPATIAL_LIMIT
			   or math.abs(pos.Y) >= RAGE_SPATIAL_LIMIT
			   or math.abs(pos.Z) >= RAGE_SPATIAL_LIMIT then return true end
			-- Precise check: inside/below a tagged OutOfBoundsPart.
			local ok, tagged = pcall(function()
				return cloneref(game:GetService("CollectionService")):GetTagged("OutOfBoundsPart")
			end)
			if not (ok and tagged) then return false end
			for _, p in tagged do
				if p:IsA("BasePart") then
					local lp = p.CFrame:PointToObjectSpace(pos)
					local hs = p.Size / 2
					-- Within horizontal footprint (+5 stud margin) and below the bottom face.
					if math.abs(lp.X) <= hs.X + 5
					   and math.abs(lp.Z) <= hs.Z + 5
					   and lp.Y < 0 and lp.Y > -(hs.Y + 40) then
						return true
					end
				end
			end
			return false
		end

		-- Is this player flagged by the hacker detector (movement anomaly)?
		local function rageIsHacker(player)
			local flagged = getgenv().InstanceHackerFlagged
			return type(flagged) == "table" and flagged[player] == true
		end

		local function rageSlotConfig(slot)
			return rage[slot] or rage.Primary
		end

		-- Best enemy under the current priority mode, honouring FOV / wall / deflect.
		-- Rounds are separated by EnvironmentID: in the lobby you have none, so nobody
		-- there is a target (and there is nothing to evade); otherwise only players in
		-- your own arena count.
		local function rageSameArena(player)
			local mine = LocalPlayer:GetAttribute("EnvironmentID")
			return mine ~= nil and player:GetAttribute("EnvironmentID") == mine
		end

		-- Spawn protection is not a ForceField: the game marks the fighter's entity
		-- with IsInvincible (checked live: players showed inv=true, forceField=false).
		local rageFighterController = nil
		local function rageInvincibleImpl(player)
			rageFighterController = rageFighterController
				or require(LocalPlayer.PlayerScripts.Controllers.FighterController)
			local fighter = rageFighterController:GetFighter(player)
			local entity = fighter and fighter.Entity
			return entity ~= nil and entity:Get("IsInvincible") == true
		end
		local function rageIsInvincible(player)
			local ok, result = pcall(rageInvincibleImpl, player)
			return ok and result == true
		end

		local function ragePickTarget()
			local cam = camera()
			if not cam then return nil end
			local center = cam.ViewportSize / 2
			local best, bestScore
			for _, player in Players:GetPlayers() do
				local character = player.Character
				if rageSameArena(player) and isEnemy(player) and character and isAlive(character)
					and not rageIsInvincible(player)
					and not character:FindFirstChildOfClass("ForceField")
				then
					if not (rage.AntiDeflect and rageIsDeflecting(player)) then
						local part = character:FindFirstChild("HitboxHead") or character:FindFirstChild("Head")
						if part then
							local sPos = screenPosition(part)
							local screenDist = sPos and (sPos - center).Magnitude or math.huge
							local visible = not rage.WallCheck or isVisible(cam.CFrame.Position, part)
							if visible then
								local hacker = rage.PrioritizeHackers and rageIsHacker(player)
								local score
								if rage.Priority == "Lowest health" then
									local hum = character:FindFirstChildOfClass("Humanoid")
									score = hum and hum.Health or math.huge
								elseif rage.Priority == "Distance" then
									local root = character:FindFirstChild("HumanoidRootPart") or part
									local myChar = LocalPlayer.Character
									local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
									score = myRoot and (root.Position - myRoot.Position).Magnitude or screenDist
								else -- Crosshair
									score = screenDist
								end
								if hacker then score = score - 1e9 end
								if not bestScore or score < bestScore then
									bestScore, best = score, { player = player, character = character }
								end
							end
						end
					end
				end
			end
			-- Anti-Translocate pass: find enemies hiding below OutOfBoundsParts or
			-- using Random extreme-axis evasion (no screen check).
			if rage.AntiTranslocate then
				local myChar = LocalPlayer.Character
				local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
				local now2 = tick()
				for _, player in Players:GetPlayers() do
					local character = player.Character
					if rageSameArena(player) and isEnemy(player) and character and isAlive(character)
					and not rageIsInvincible(player)
						and not character:FindFirstChildOfClass("ForceField")
						and not (rage.AntiDeflect and rageIsDeflecting(player))
					then
						local root2 = character:FindFirstChild("HumanoidRootPart")
						if root2 then
							local pos2 = root2.Position
							local isExtreme = math.abs(pos2.X) >= RAGE_SPATIAL_LIMIT
							             or math.abs(pos2.Y) >= RAGE_SPATIAL_LIMIT
							             or math.abs(pos2.Z) >= RAGE_SPATIAL_LIMIT
							if isExtreme then
								-- Keep existing track entry; don't update normalPos.
								if not rage._evasionTrack[player] then
									rage._evasionTrack[player] = { lastNormalAt = 0 }
								end
							else
								-- Normal position: update last known good state.
								rage._evasionTrack[player] = { lastNormalAt = now2, normalPos = pos2 }
							end
						end
						if rageIsTranslocated(player) then
							local part = character:FindFirstChild("HitboxHead") or character:FindFirstChild("Head")
							if part then
								local hacker = rage.PrioritizeHackers and rageIsHacker(player)
								local score = myRoot and (part.Position - myRoot.Position).Magnitude or 1e6
								if hacker then score = score - 1e9 end
								if not bestScore or score < bestScore then
									bestScore, best = score, { player = player, character = character }
								end
							end
						end
					end
				end
			end
			-- Test option: shooting-range dummies as targets when no player qualifies.
			if not best and rage.TargetDummies then
				local range = workspace:FindFirstChild("ShootingRangeEntities")
				local myChar = LocalPlayer.Character
				local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
				if range and myRoot then
					local bestD
					for _, m in range:GetChildren() do
						local hum = m:FindFirstChildOfClass("Humanoid")
						local hb = m:FindFirstChild("HitboxHead")
						if hum and hb and hum.Health > 0 and hum.Health < math.huge then
							local d = (hb.Position - myRoot.Position).Magnitude
							if not bestD or d < bestD then bestD, best = d, { character = m } end
						end
					end
				end
			end
			return best
		end

		-- The best target is re-picked at 20 Hz instead of every frame (with many players
		-- the pick is the most expensive part of an idle frame); a cached target that
		-- died or left is dropped at once.
		local function rageTarget()
			local now = tick()
			if now - (rage._targetAt or 0) < 0.05 then
				local cached = rage._targetCache
				if cached == nil then
					return nil
				end
				local character = cached.character
				if character and character.Parent and isAlive(character) then
					return cached
				end
			end
			local picked = ragePickTarget()
			-- Stick with the current target for a moment: the pick flips between
			-- similar candidates (lowest health, nearest dummy) several times a second,
			-- and every switch means a new position the server has to settle on before
			-- shots register (measured: handgun switched target every ~0.3 s, 13 hits
			-- from 61 accepted shots).
			local held = rage._targetCache
			if picked and held and picked.character ~= held.character
				and now - (rage._targetSince or 0) < 0.75 then
				local hc = held.character
				local hum = hc and hc.Parent and hc:FindFirstChildOfClass("Humanoid")
				if hum and hum.Health > 0 then
					rage._targetAt = now
					return held
				end
			end
			if not picked or not held or picked.character ~= held.character then
				rage._targetSince = now
			end
			rage._targetCache = picked
			rage._targetAt = now
			return picked
		end

		-- Is any alive enemy around? Cached, because the idle ragebot frame would
		-- otherwise pay for a full player scan on top of everything else.
		local function rageEnemyPresent()
			local now = tick()
			if now - (rage._enemyCheckAt or 0) < 0.25 then
				return rage._enemyPresent == true
			end
			rage._enemyCheckAt = now
			local present = false
			for _, player in Players:GetPlayers() do
				local character = player.Character
				if rageSameArena(player) and isEnemy(player) and character and isAlive(character) then
					present = true
					break
				end
			end
			rage._enemyPresent = present
			return present
		end

		local function rageEquippedItem()
			local ok, fc = pcall(function()
				return require(LocalPlayer.PlayerScripts.Controllers.FighterController)
			end)
			if ok and fc and fc.LocalFighter then
				return fc.LocalFighter.EquippedItem
			end
			return nil
		end

		-- Returns { {item, slot, ammo, isMelee} } for every non-restricted weapon the
		-- LocalFighter currently holds.  Ordered by rage.WeaponPriority.
		local function rageAllItems()
			local result = {}
			pcall(function()
				local fc = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
				local lf = fc and fc.LocalFighter
				if not lf then return end

				-- Prefer game-native itemBehaviors API.
				local gotItems = false
				pcall(function()
					local ib = lf.itemBehaviors
					if ib and type(ib.GetItems) == "function" then
						for _, ie in ib:GetItems() do
							if ie and ie.item then
								local it = ie.item
								local n, _, isM, _, _, _, s = rageWeaponInfo(it)
								if not (n and RAGE_RESTRICTED[n]) then
									local ammo = 0
									if isM then ammo = 1
									else pcall(function() ammo = it:Get("Ammo") or 0 end) end
									table.insert(result, { item=it, slot=s, ammo=ammo, isMelee=isM })
									gotItems = true
								end
							end
						end
					end
				end)

				if not gotItems then
					local rawItems
					pcall(function()
						rawItems = rawget(lf, "Items")
							or rawget(lf, "_items")
							or (type(rawget(lf, "GetItems")) == "function" and lf:GetItems())
					end)
					if not rawItems or not next(rawItems) then
						pcall(function()
							local t = lf.Items
							if type(t) == "table" and next(t) then rawItems = t end
						end)
					end
					for _, it in pairs(rawItems or {}) do
						local n, _, isM, _, _, _, s = rageWeaponInfo(it)
						if not (n and RAGE_RESTRICTED[n]) then
							local ammo = 0
							if isM then ammo = 1
							else pcall(function() ammo = it:Get("Ammo") or 0 end) end
							table.insert(result, { item=it, slot=s, ammo=ammo, isMelee=isM })
						end
					end
				end
			end)
			-- Sort by WeaponPriority order
			local order = {}
			for i, s in ipairs(rage.WeaponPriority) do order[s] = i end
			table.sort(result, function(a, b)
				return (order[a.slot] or 99) < (order[b.slot] or 99)
			end)
			return result
		end

		-- Try to equip a specific item via the LocalFighter.
		-- Returns true if a known equip method was found and called.
		-- item:Equip() internally does clientFighter:EquipItem(self.index) ??no arg needed.
		local function rageEquipItem(item)
			local ok = false
			pcall(function()
				-- 0. LocalFighter:EquipItem(index) ??what the game's own hotkeys call
				-- (item:Equip() alone does not change the equipped item).
				do
					local fc0 = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
					local lf0 = fc0 and fc0.LocalFighter
					local items0 = lf0 and (rawget(lf0, "Items") or lf0.Items)
					local idx0 = items0 and table.find(items0, item)
					if idx0 and type(lf0.EquipItem) == "function" then
						lf0:EquipItem(idx0)
						ok = true
						return
					end
				end

				-- 1. item:Equip() ??game-native; uses item.ClientFighter internally.
				if type(item.Equip) == "function" then
					item:Equip()
					ok = true
					return
				end

				-- 2. lf:EquipItem(index) ??equivalent to what Equip() does internally.
				local fc = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
				local lf = fc and fc.LocalFighter
				if not lf then return end
				local idx = item.index or item.Index or item.Slot or item.SlotIndex
				if idx ~= nil and type(lf.EquipItem) == "function" then
					lf:EquipItem(idx)
					ok = true
					return
				end

				-- 3. Last resort: pass item object.
				if     type(lf.EquipItem)  == "function" then lf:EquipItem(item);  ok = true
				elseif type(lf.Equip)      == "function" then lf:Equip(item);      ok = true
				elseif type(lf.SwitchItem) == "function" then lf:SwitchItem(item); ok = true
				end
			end)
			return ok
		end

		-- Map item.index (1/2/3) to slot name, with name-based Knife distinction.
		local function indexToSlot(item)
			local idx
			pcall(function() idx = item.index end)
			if idx == 1 then return "Primary"
			elseif idx == 2 then return "Secondary"
			elseif idx == 3 then
				local n
				pcall(function() n = item:Get("Name") end)
				return (n == "Knife") and "Knife" or "Melee"
			end
			-- Fallback: derive from Info table
			local _, _, isM, _, _, _, slot = rageWeaponInfo(item)
			return slot
		end

		-- Weapon-manager: scan every slot, pick the highest-priority valid action.
		-- Immune ring, built like the other hub's: the area between 2^27 and 2^30 studs is cut
		-- into 2048-stud cells; every cell owns one sphere (radius 400) whose centre comes from
		-- a keyed hash of the cell (random keys and salt every session, +-560 jitter in X / Z, a
		-- hashed Y). A position is a uniform random point inside a random cell's inner sphere
		-- (radius 200) with a fully random orientation. Hit queries lose all precision this far
		-- out, so the evasion holds for the whole reload. State lives in rage._ring (the main
		-- chunk is close to Luau's 200-register limit, so no new locals here).
		local function rageImmuneCFrame()
			local ring = rage._ring
			if not ring then
				local rng = Random.new()
				local function key() return rng:NextInteger(0, 65535) * 65536 + rng:NextInteger(0, 65535) end
				local min, max = 134217728, 1073741824
				ring = {
					rng = rng, k1 = key(), k2 = key(), k3 = key(), k4 = key(), salt = key(),
					min = min, cells = (max - min) // 2048,
					yMin = min + 400, ySpan = max - 400 - 64 - (min + 400) + 1,
				}
				function ring.hash(a, b)
					local n1 = (bit32.bxor(a, b, ring.k1) + ring.k2) % 4294967296
					local n2 = (bit32.bxor(n1, bit32.lrotate(n1, 7)) + ring.k3) % 4294967296
					local n3 = (bit32.bxor(n2, bit32.rrotate(n2, 11)) + ring.k4) % 4294967296
					return bit32.bxor(n3, bit32.lrotate(n3, 17))
				end
				function ring.cell(cx, cz, tag)
					return ring.hash(bit32.bxor(cx, bit32.lshift(cz, 16)), bit32.bxor(tag, ring.salt))
				end
				rage._ring = ring
			end
			local rng = ring.rng
			local cx, cz = rng:NextInteger(0, ring.cells - 1), rng:NextInteger(0, ring.cells - 1)
			local base = ring.min + 1024
			local centre = Vector3.new(
				base + cx * 2048 + (ring.cell(cx, cz, 324508639) % 1121 - 560),
				ring.yMin + ring.cell(cx, cz, 826366246) % ring.ySpan,
				base + cz * 2048 + (ring.cell(cx, cz, 610839776) % 1121 - 560)
			)
			local radius = 200 * rng:NextNumber() ^ (1 / 3)
			local cosT = rng:NextNumber(-1, 1)
			local sinT = math.sqrt(1 - cosT * cosT)
			local phi = rng:NextNumber(0, math.pi * 2)
			local offset = Vector3.new(radius * sinT * math.cos(phi), radius * cosT, radius * sinT * math.sin(phi))
			return CFrame.new(centre + offset)
				* CFrame.fromOrientation(rng:NextNumber(-math.pi, math.pi), rng:NextNumber(-math.pi, math.pi), rng:NextNumber(-math.pi, math.pi))
		end

		-- Ammo after the shots we already sent but the server hasn't replicated yet, so
		-- an emptied magazine is noticed right away (reload / immune parking) instead of
		-- a few frames later. Same bookkeeping as the other hub's Gun class:
		-- { expected, spend, deadline, nextAt } per item (weak keys).
		--   expected: ammo the server last showed us      spend: bullets sent, not yet replicated
		--   deadline: when an unconfirmed spend is dropped nextAt: earliest time another shot
		--             can really be accepted (a repeated call inside it is not counted)
		-- (helpers live in one table: the main chunk is close to Luau's 200-register limit)
		local rageAmmo = { state = setmetatable({}, { __mode = "k" }) }
		function rageAmmo.oneWay()
			local ok, ping = pcall(function() return LocalPlayer:GetNetworkPing() end)
			return 0.5 * (ok and tonumber(ping) or 0.05)
		end
		function rageAmmo.replication() return rageAmmo.oneWay() + 0.05 end
		function rageAmmo.remote() return rageAmmo.oneWay() + 1 / 60 end
		function rageAmmo.entry(item, rawAmmo)
			local st = rageAmmo.state[item]
			if not st then
				st = { expected = rawAmmo, spend = 0, nextAt = 0 }
				rageAmmo.state[item] = st
			end
			return st
		end
		function rageAmmo.clear(item)
			local st = rageAmmo.state[item]
			if st then
				st.spend, st.deadline, st.nextAt = 0, nil, 0
			end
		end
		function rageAmmo.reconcile(st, rawAmmo, now)
			if rawAmmo > st.expected then
				st.expected, st.spend, st.deadline, st.nextAt = rawAmmo, 0, nil, 0 -- reloaded
				return
			end
			if rawAmmo < st.expected then
				st.spend = math.max(st.spend - (st.expected - rawAmmo), 0)
				st.expected = rawAmmo
				if st.spend <= 0 then st.deadline = nil end
			end
			if st.deadline and now >= st.deadline then
				st.spend, st.nextAt, st.deadline = 0, 0, nil -- the server never spent it
			end
		end
		local function rageExpectedAmmo(item, rawAmmo)
			local st = rageAmmo.entry(item, rawAmmo)
			rageAmmo.reconcile(st, rawAmmo, tick())
			return math.max(st.expected - st.spend, 0)
		end
		-- Call after sending a shot. Returns the ammo expected once everything in flight lands.
		local function rageRecordShot(item, rawAmmo)
			local now = tick()
			local st = rageAmmo.entry(item, rawAmmo)
			rageAmmo.reconcile(st, rawAmmo, now)
			if now >= st.nextAt then
				local left = math.max(st.expected - st.spend, 0)
				if left > 0 then
					local info
					pcall(function() info = item.Info end)
					local burst = math.max(info and tonumber(info.ShootBurst) or 1, 1)
					st.spend += math.min(burst, left)
					st.deadline = now + rageAmmo.remote() + rageAmmo.replication()
					local quick = info and info.Name == "Revolver" and tonumber(info.QuickShotCooldown) or nil
					if quick then
						st.nextAt = now + quick
					else
						local burstCd = info and tonumber(info.ShootBurstCooldown) or 0
						st.nextAt = now + (burst - 1) * burstCd
							+ math.max(info and tonumber(info.ShootCooldown) or 0, burstCd)
					end
				end
			end
			return math.max(st.expected - st.spend, 0)
		end

		-- Reload transport (the other hub's _PlanReloadTransport). While a reload is under way
		-- we park in the immune ring and only send the reload request once the server has seen
		-- the gun run dry. States: gun (the gun being reloaded), pending (ammo when its last
		-- bullet went out, waiting for the server to show 0), readyAt (earliest reload request),
		-- ack (deadline for the server to react to what we sent). All in rage.RT because the
		-- main chunk is close to Luau's 200-register limit.
		rage.RT = {}
		function rage.RT.clear()
			local rt = rage.RT
			rt.gun, rt.readyAt, rt.ack, rt.pending = nil, nil, nil, nil
		end
		function rage.RT.same(a, b)
			if a == nil or b == nil then return false end
			if a == b then return true end
			local idA, idB
			pcall(function() idA = a:Get("ObjectID") end)
			pcall(function() idB = b:Get("ObjectID") end)
			return idA ~= nil and idA == idB
		end
		function rage.RT.reloading(item, now)
			local busy = false
			pcall(function()
				local rc = item:GetAttribute("_reload_cooldown")
				if type(rc) == "number" and now < rc then busy = true end
				local sc = item:GetAttribute("_shoot_cooldown_no_ammo")
				if type(sc) == "number" and now < sc then busy = true end
			end)
			return busy
		end
		-- Returns nil (no transport: carry on with attack / swap / evade) or a table: park in
		-- the immune ring, and when .reload is set also send the reload request this frame.
		function rage.RT.plan(action, now)
			local rt = rage.RT
			local gun = rt.gun
			if gun ~= nil then
				if not rage.RT.same(rageEquippedItem(), gun)
					or (action ~= nil and (action.type == "Swap" or action.type == "Attack") and not rage.RT.same(action.item, gun))
				then
					rage.RT.clear()
					return nil
				end
				if rage.RT.reloading(gun, now) then
					rt.readyAt, rt.pending, rt.ack = nil, nil, nil
					return {}
				end
				local ammo, reserve = 0, math.huge
				pcall(function() ammo = gun:Get("Ammo") or gun:GetAmmo() or 0 end)
				pcall(function()
					local r = gun:Get("AmmoReserve")
					if r == nil and gun.GetAmmoReserve then r = gun:GetAmmoReserve() end
					if r ~= nil then reserve = r end
				end)
				if rt.pending ~= nil then
					if not (ammo <= 0 and reserve > 0) then
						-- The server has not shown the empty magazine yet: wait for it, but give up
						-- at the deadline or when the shots in flight leave ammo after all.
						local giveUp = rt.ack == nil or now >= rt.ack
						if not giveUp then giveUp = rageExpectedAmmo(gun, ammo) > 0 end
						if giveUp then
							rage.RT.clear()
							return nil
						end
						return {}
					end
					rt.pending, rt.ack = nil, nil
				end
				if ammo > 0 or reserve <= 0 then
					rage.RT.clear()
					return nil
				end
				if rt.readyAt == nil then rt.readyAt = now + rageAmmo.replication() end
				local out = {}
				if now >= rt.readyAt and (rt.ack == nil or now >= rt.ack) then out.reload = true end
				return out
			end
			if action == nil or action.type ~= "Reload" then return nil end
			rt.gun, rt.readyAt, rt.ack, rt.pending = action.item, nil, nil, nil
			return {}
		end

		-- Returns { type="Attack"|"Reload"|"Swap"|"Evade", item, slot, isMelee }
		local function rageGetAction()
			local ok, fc = pcall(function()
				return require(LocalPlayer.PlayerScripts.Controllers.FighterController)
			end)
			if not (ok and fc and fc.LocalFighter) then return nil end
			local lf = fc.LocalFighter

			local order = {}
			for i, s in ipairs(rage.WeaponPriority) do order[s] = i end

			-- Collect item enumerations via the game-native itemBehaviors API first,
			-- then fall back to rawget / metatable access on the Items collection.
			local itemList = {}  -- list of { item=<obj>, slot=<str>, isMelee=<bool> }
			local gotItems = false

			pcall(function()
				local ib = lf.itemBehaviors
				if ib and type(ib.GetItems) == "function" then
					for _, ie in ib:GetItems() do
						if ie and ie.item then
							local it = ie.item
							local name
							pcall(function() name = it:Get("Name") end)
							if not (name and RAGE_RESTRICTED[name]) then
								local slot = indexToSlot(it)
								local isM = (ie.type ~= "Gun") or (slot == "Melee" or slot == "Knife")
								table.insert(itemList, { item=it, slot=slot, isMelee=isM })
								gotItems = true
							end
						end
					end
				end
			end)

			-- Fallback: iterate Items collection directly (may be rawget or via metatable).
			if not gotItems then
				local rawItems
				pcall(function()
					rawItems = rawget(lf, "Items")
						or rawget(lf, "_items")
						or (type(rawget(lf, "GetItems")) == "function" and lf:GetItems())
				end)
				if not rawItems or not next(rawItems) then
					pcall(function()
						local t = lf.Items
						if type(t) == "table" and next(t) then rawItems = t end
					end)
				end
				for _, it in pairs(rawItems or {}) do
					local name, _, isM, _, _, _, slot = rageWeaponInfo(it)
					if not (name and RAGE_RESTRICTED[name]) then
						table.insert(itemList, { item=it, slot=slot, isMelee=isM })
					end
				end
			end

			local bestItem,   bestPriority   = nil, math.huge  -- has ammo (or melee)
			local backupItem, backupPriority = nil, math.huge  -- empty clip, has reserve
			local anyEnabled = false

			for _, entry in ipairs(itemList) do
				local it, slot, isM = entry.item, entry.slot, entry.isMelee
				local priority = order[slot] or math.huge
				if priority >= math.huge then continue end  -- slot not in priority list
				anyEnabled = true

				local ammo, reserve = 0, 0
				if isM then
					ammo = 1  -- melee never runs out
				else
					-- The game's items have no GetAmmo / GetAmmoReserve methods (calling them
					-- errors), so read via Get() first; a failing call left ammo at 0 and the
					-- ragebot then never picked a gun, only the knife.
					pcall(function() ammo    = it:Get("Ammo")        or it:GetAmmo()        or 0 end)
					pcall(function() reserve = it:Get("AmmoReserve") or it:GetAmmoReserve() or 0 end)
					ammo = rageExpectedAmmo(it, ammo) -- minus shots still in flight
				end

				entry.ammo, entry.reserve = ammo, reserve
				if not isM and ammo == 0 then
					if reserve > 0 and priority < backupPriority then
						backupItem, backupPriority = entry, priority
					end
				else
					if priority < bestPriority then
						bestItem, bestPriority = entry, priority
					end
				end
			end

			if not anyEnabled then return { type="Evade" } end

			-- Check whether an item is currently equipped (game-native API).
			-- The game may hand back different Lua instances for the same item, so
			-- also compare the equipped item by ObjectID (a plain == would fail).
			local function objectIdOf(it)
				local id
				pcall(function() id = it:Get("ObjectID") end)
				return id
			end
			local function isSameItem(a, b)
				if a == nil or b == nil then return false end
				if a == b then return true end
				local idA = objectIdOf(a)
				return idA ~= nil and idA == objectIdOf(b)
			end
			local function isEquipped(it)
				local v = false
				pcall(function() v = it:IsEquipped() end)
				if v then return true end
				pcall(function() v = isSameItem(lf.EquippedItem, it) end)
				return v == true
			end

			-- On empty clip. A melee weapon always counts as "has ammo", so without this the
			-- ragebot swapped to the knife whenever a gun ran dry, whatever was picked.
			--   Reload:       reload the gun in your hands when it has reserve ammo.
			--   SwapOrReload: same, and also swap to a higher-priority gun that has reserve.
			--   Swap:         never reload, fall through to the swap below.
			if rage.WeaponOnEmpty ~= "Swap" then
				for _, entry in ipairs(itemList) do
					if not entry.isMelee and entry.ammo == 0 and (order[entry.slot] or math.huge) < math.huge
						and isEquipped(entry.item)
					then
						if (entry.reserve or 0) > 0 then
							return { type="Reload", item=entry.item, slot=entry.slot, isMelee=false }
						end
						break
					end
				end
				if rage.WeaponOnEmpty == "SwapOrReload" and backupItem
					and backupPriority < (bestItem and bestPriority or math.huge)
				then
					if isEquipped(backupItem.item) then
						return { type="Reload", item=backupItem.item, slot=backupItem.slot, isMelee=false }
					end
					return { type="Swap", item=backupItem.item, slot=backupItem.slot, isMelee=false }
				end
			end

			if not bestItem then
				if rage.WeaponOnEmpty == "Swap" or not backupItem then
					return { type="Evade" }
				end
				if isEquipped(backupItem.item) then
					return { type="Reload", item=backupItem.item, slot=backupItem.slot, isMelee=false }
				end
				return { type="Swap", item=backupItem.item, slot=backupItem.slot, isMelee=false }
			end

			-- Best item not equipped ??return Swap.
			-- Also honour a recent swap attempt (equip is async): for up to 2 s after
			-- we asked to equip bestItem, trust it as equipped to avoid a Swap loop.
			local equipped = isEquipped(bestItem.item)
			if not equipped and rage._swapTarget ~= nil and tick() < (rage._swapTargetUntil or 0) then
				equipped = isSameItem(rage._swapTarget, bestItem.item)
			end
			if not equipped then
				return { type="Swap", item=bestItem.item, slot=bestItem.slot, isMelee=bestItem.isMelee }
			end

			return { type="Attack", item=bestItem.item, slot=bestItem.slot, isMelee=bestItem.isMelee }
		end

		local RageEncode, RageToEnum
		local function rageEncoders()
			if RageEncode and RageToEnum then return true end
			local ok = pcall(function()
				local modules = ReplicatedStorage:WaitForChild("Modules", 5)
				RageEncode = require(modules:WaitForChild("Utility", 5))
				RageToEnum = require(modules:WaitForChild("EnumLibrary", 5))
			end)
			return ok and RageEncode ~= nil and RageToEnum ~= nil
		end

		-- Random far-away position for knife/melee when ShootLock/cooldown blocks the attack.
		-- Server sees us far away; RenderStep restores client view to backupCFrame.
		local function rageKnifeFarPos(root)
			local s = math.random(0, 1) == 0 and -1 or 1
			local t = math.random(0, 1) == 0 and -1 or 1
			rageSetCFrame(root, CFrame.new(
				s * math.random(500000, 1000000),
				math.random(5000, 10000),
				t * math.random(500000, 1000000)
			))
		end

		-- Far-away escape for any weapon; keeps the real CFrame for the render restore.
		local function rageFarPos(root)
			if not rage.backupCFrame then rage.backupCFrame = root.CFrame end
			rage._evasionServerCF = nil
			rage._evasionClientCF = nil
			rageKnifeFarPos(root)
		end

		-- ShootLock: true = cannot fire this frame.
		local function rageShootLockBlocked(spatialLimited, lockDuration)
			local now = os.clock()
			local locked = rage._lockedUntil ~= nil and now < rage._lockedUntil
			if spatialLimited then rage._lockedUntil = now + lockDuration end
			if not locked then locked = spatialLimited end
			return locked
		end

		-- SpatialLimitGate: true while the target sits at extreme coordinates and has
		-- not yet been there for (expected duration - Stability).
		-- Target's equipped gun has ammo? (false only for a gun at 0 ammo; unknown -> true.)
		local function rageTargetHasAmmo(player)
			local has = true
			pcall(function()
				local fc = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
				local fighter = fc:GetFighter(player)
				local item = fighter and fighter.EquippedItem
				if not item then return end
				local _, _, isM = rageWeaponInfo(item)
				if isM then return end
				local ammo = item:Get("Ammo")
				if type(ammo) == "number" and ammo <= 0 then has = false end
			end)
			return has
		end

		local function rageSpatialTick(target)
			local hasAmmo = true
			if target.player then hasAmmo = rageTargetHasAmmo(target.player) end
			local troot = target.character:FindFirstChild("HumanoidRootPart")
			if not troot then return false end
			local now = os.clock()
			local skey = target.player or target.character
			local m = rage._spatial[skey]
			if not m then m = { expected = 0 }; rage._spatial[skey] = m end
			local p = troot.Position
			local out = math.abs(p.X) >= RAGE_SPATIAL_LIMIT or math.abs(p.Y) >= RAGE_SPATIAL_LIMIT
				or math.abs(p.Z) >= RAGE_SPATIAL_LIMIT
			if not out then
				if m.entry then
					if hasAmmo then m.expected = now - m.entry end
					m.entry = nil
				end
				return false
			end
			if not m.entry then m.entry = now end
			if hasAmmo and m.expected - rage.Stability <= now - m.entry then return false end
			return true
		end

		-- PartGlue: detach a target hitbox from its weld and anchor it while attacking.
		-- Reference counted like the reference bot: rage._glues[hitbox] = { refs = n, ... },
		-- the weld / Anchored state is only restored when the last reference is gone. With
		-- several targets in a row (free-for-all, someone dying next to you) the previous
		-- hitbox stays glued and keeps following its owner for a short grace period, so
		-- switching back and forth does not un-anchor and re-anchor hitboxes every frame.
		rage._glues = {}
		rage._glueBound = nil -- hitbox our root is currently bound to
		local GLUE_GRACE = 0.4

		local function rageGlueRestore(g)
			if g.weld and g.part1 then rageSetProp(g.weld, "Part1", g.part1) end
			if g.part then rageSetProp(g.part, "Anchored", g.wasAnchored) end
			rage._glues[g.part] = nil
		end

		-- Drops our reference on the currently bound hitbox (restored after the grace).
		local function rageGlueRelease()
			local part = rage._glueBound
			if not part then return end
			rage._glueBound = nil
			local g = rage._glues[part]
			if g then
				g.refs = g.refs - 1
				if g.refs <= 0 then
					g.expireAt = tick() + GLUE_GRACE
				end
			end
		end

		-- Restores every glued hitbox immediately (disable / unload).
		local function rageGlueReleaseAll()
			rage._glueBound = nil
			for _, g in pairs(table.clone(rage._glues)) do
				rageGlueRestore(g)
			end
		end

		-- Keeps every glued hitbox on its owner and expires unreferenced ones.
		local function rageGlueTick()
			if next(rage._glues) == nil then return end
			local now = tick()
			for _, g in pairs(table.clone(rage._glues)) do
				local alive = g.part and g.part.Parent and g.root and g.root.Parent
				if not alive then
					rageGlueRestore(g)
				elseif g.refs <= 0 and g.expireAt and now >= g.expireAt then
					rageGlueRestore(g)
				elseif g.rel then
					-- Anchored hitboxes no longer follow their weld: keep them on the target.
					rageSetCFrame(g.part, g.root.CFrame * g.rel)
				end
			end
		end

		local function rageGlueAcquire(part)
			if rage._glueBound == part then
				local g = rage._glues[part]
				if g and g.root and g.root.Parent and g.rel then
					rageSetCFrame(part, g.root.CFrame * g.rel)
				end
				return
			end
			rageGlueRelease()
			local g = rage._glues[part]
			if g then
				g.refs = g.refs + 1
				g.expireAt = nil
			else
				local weld = part:FindFirstChildWhichIsA("WeldConstraint")
				local groot = part.Parent and part.Parent:FindFirstChild("HumanoidRootPart")
				g = {
					part = part, weld = weld, part1 = weld and weld.Part1, wasAnchored = part.Anchored,
					root = groot, rel = groot and groot.CFrame:ToObjectSpace(part.CFrame), refs = 1,
				}
				if weld then rageSetProp(weld, "Part1", nil) end
				rageSetProp(part, "Anchored", true)
				rage._glues[part] = g
			end
			rage._glueBound = part
		end

		-- Returns true when a shot went out (so the caller skips evasion this frame).
		local function rageFire()
			local now = tick()

			-- Nobody to shoot (lobby, shooting range, empty server): only keep weapons
			-- in order (reload / swap) a couple of times a second instead of every frame.
			if not rage.TargetDummies and not rageEnemyPresent() then
				if now - (rage._idleActionAt or 0) < 0.5 then
					return false
				end
				rage._idleActionAt = now
			end

			-- Weapon manager: determine the best action this frame.
			-- The weapon manager is the other big per-frame cost: run it at 20 Hz.
			local action = rage._action
			if not action or now - (rage._actionAt or 0) >= 0.05 then
				action = rageGetAction()
				rage._action, rage._actionAt = action, now
			end
			if not action then
				rage._purgeEvade = false
				rage._attackStart = nil
				return false
			end

			if action.type == "Evade" then
				rage._purgeEvade = true
				rage._attackStart = nil
				return false
			end
			rage._purgeEvade = false

			-- Reload transport: while it is active we park in the immune ring (kept alive here
			-- every frame) and only a ready plan sends the reload request.
			do
				local plan = rage.RT.plan(action, now)
				if plan then
					rage._attackStart = nil
					rage._immuneUntil = now + 0.2
					if not plan.reload then return false end
					action = { type = "Reload", item = rage.RT.gun, slot = action.slot, isMelee = false }
				end
			end

			-- Swapping or reloading means we are not attacking: clear the attack cycle
			-- so evasion (which skips while _attackStart is set) runs meanwhile. The next
			-- attack starts a fresh prep hold, which it needs anyway after a weapon change.
			if action.type == "Swap" or action.type == "Reload" then
				rage._attackStart = nil
			end

			if action.type == "Swap" then
				if now >= rage._swapCoolUntil then
					if rageEquipItem(action.item) then
						rageAmmo.clear(action.item)
						rage._swapCoolUntil   = now + 0.5
						-- Remember what we swapped to so rageGetAction() can trust it
						-- as equipped for up to 2 s (equip is async on the server side).
						rage._swapTarget      = action.item
						rage._swapTargetUntil = now + 2.0
					else
						rage._purgeEvade = true  -- equip failed ??evade
					end
				end
				return false
			end
			-- Successful attack clears the swap-trust window.
			rage._swapTarget      = nil
			rage._swapTargetUntil = 0

			local item = action.item
			local objId = item.Get and item:Get("ObjectID")
			if objId then
				rage._lastObjId = objId
			else
				objId = rage._lastObjId
			end
			if not objId then return false end
			local name, isRaycast, isMelee, isSniper, isRevolver, attackCd, slot, isKnife = rageWeaponInfo(item)
			if name and RAGE_RESTRICTED[name] then return false end
			local cfg = rageSlotConfig(slot)

			-- Reload action: send the StartReloading remote (throttled; gated by server
			-- attributes so we don't spam while an in-progress reload is already running).
			if action.type == "Reload" then
				local serverReloading = false
				pcall(function()
					local rc = item:GetAttribute("_reload_cooldown")
					if type(rc) == "number" and now < rc then serverReloading = true end
				end)
				if not serverReloading then
					pcall(function()
						local sc = item:GetAttribute("_shoot_cooldown_no_ammo")
						if type(sc) == "number" and now < sc then serverReloading = true end
					end)
				end
				if not serverReloading then
					local ammo, maxAmmo = 0, 0
					pcall(function() ammo    = item:Get("Ammo") or 0 end)
					pcall(function() maxAmmo = (item.Info and item.Info.MaxAmmo) or item:Get("MaxAmmo") or 0 end)
					if maxAmmo > 0 and ammo >= maxAmmo then
						rage._reloadUntil = 0  -- already full; clear timer
					elseif now >= rage._reloadUntil and rageEncoders() then
						rage.RT.ack = now + rageAmmo.remote() + rageAmmo.replication()
						rage._reloadUntil = rage.RT.ack
						pcall(function()
							local reloadEncoded = RageToEnum:ToEnum("Reload")
							ReplicatedStorage.Remotes.Replication.Fighter.UseItem:FireServer(
								objId, RageToEnum:ToEnum("StartReloading"),
								{ [utf8.char(1)] = reloadEncoded, [utf8.char(2)] = reloadEncoded },
								nil
							)
						end)
					end
				end
				return false  -- hold fire while reloading
			end

			-- action.type == "Attack" ??also gate on server reload attributes and
			-- the segmented-reload window (shotgun refills one shell at a time).
			if not isMelee then
				local serverReloading = false
				pcall(function()
					local rc = item:GetAttribute("_reload_cooldown")
					if type(rc) == "number" and now < rc then serverReloading = true end
				end)
				if not serverReloading then
					pcall(function()
						local sc = item:GetAttribute("_shoot_cooldown_no_ammo")
						if type(sc) == "number" and now < sc then serverReloading = true end
					end)
				end
				if serverReloading then
					rage._attackStart = nil -- waiting on the reload: let evasion run instead of standing still
					return false
				end
				local ammo, maxAmmo = 0, 0
				pcall(function() ammo    = item:Get("Ammo") or 0 end)
				pcall(function() maxAmmo = (item.Info and item.Info.MaxAmmo) or item:Get("MaxAmmo") or 0 end)
				if maxAmmo > 0 and ammo >= maxAmmo then rage._reloadUntil = 0 end
				if now < rage._reloadUntil then
					rage._attackStart = nil
					return false
				end
				-- The server keeps ignoring shots for ~0.7 s after a gun reload
				-- finishes (ammo already shows full): those shots were spent as blanks.
				-- Measured: accepted once the client's reload cooldown had <= 0.36 s left.
				local rcd = item._reload_cooldown
				if type(rcd) == "number" and rcd - now > 0.3 then
					rage._attackStart = nil
					return false
				end
			end

			-- Rate limit: knife uses cfg.Rate, melee uses attackCd.
			-- The knife attack-cooldown check is deferred until AFTER teleport (below)
			-- so we can also issue the far-pos escape when blocked.
			local deferredGap
			if isMelee then
				-- Melee (knife and fists alike): the attack cooldown is checked after the
				-- teleport below, so we keep standing on the target between swings. Gating
				-- it here teleported us only on the swing frame, and the server needs the
				-- position held ~0.2 s to count the hit (fists: 0 hits in 29 swings).
				local minGap = cfg.Rate > 0 and (1 / cfg.Rate) or 0.05
				if now - rage.lastShotAt < minGap then return false end
			else
				local minGap = math.max(cfg.Rate > 0 and (1 / cfg.Rate) or 0, isRevolver and attackCd or 0)
				-- Same as melee: the fire-rate gate for a slow weapon (revolver, handgun,
				-- shotgun ...) must not gate the teleport, or the server only
				-- sees us at the target on shot frames and most shots land as blanks
				-- (shotgun: 2 hits from 12 accepted shots). The gap is checked after the
				-- teleport below. Burst weapons keep the old rate-only gate.
				local info = item.Info
				local burst = info and type(info.BurstCount) == "number" and info.BurstCount > 1
				if not burst and attackCd > 0.05 then
					-- Only the "Fire rate" slider gates the shot here. The weapon's listed
					-- cooldown is not a hard limit for the server (handgun cd 0.13 s was
					-- accepted every 0.10 s), so capping at it (or 0.75 of it) made the
					-- slider useless above ~10/s and cost fire rate.
					deferredGap = minGap
					minGap = 0.02
				end
				if now - rage.lastShotAt < minGap then return false end
			end

			if cfg.HitChance < 100 and math.random(1, 100) > cfg.HitChance then
				rage.lastShotAt = now
				return false
			end

			local target = rageTarget()
			if not target then
				rage._attackStart = nil
				rageGlueRelease()
				return false
			end
			local savedHitPart = rage._hitPartOverride
			rage._hitPartOverride = cfg.HitPart
			local part = rageHitbox(target.character, isSniper)
			rage._hitPartOverride = savedHitPart
			if not part then return false end

			-- Drop mode: a target at an extreme distance can't be attacked from here.
			if rage.DropMode then
				local ownRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
				if not ownRoot or (part.Position - ownRoot.Position).Magnitude > rage.DropAttackRange then
					rage._attackStart = nil
					return false
				end
			end

			-- The enemy is in the middle of a knife heavy attack: stay out of it (evasion runs instead)
			-- and strike once the swing is over, while the heavy attack is still on cooldown.
			if rage.WaitKnifeHeavy and rage.heavyPhase(target, now) == "swing" then
				if rage.HeavyNotify and now - rage._heavyNotifiedAt > 1 then
					rage._heavyNotifiedAt = now
					Window:Notify({
						Title = "Ragebot (Beta)",
						Content = "Enemy knife heavy attack: waiting for it to finish",
						Icon = "shield",
					})
				end
				rage._attackStart = nil
				rageGlueRelease()
				return false
			end

			-- Evade between shots: a slow weapon (shotgun 0.7 s, sniper 1.5 s, knife 0.8 s) leaves
			-- long gaps in which we would sit on the target for nothing. Measured in a fight:
			-- 26 of 28 hits we took landed while the attack cycle held us at the enemy.
			-- Skip the teleport until the next shot is close enough for the prep hold.
			if rage.EvadeBetweenShots and not (isMelee and not isKnife) then
				local nextAt
				if isKnife then
					nextAt = rage._knifeAttackCoolUntil
				elseif attackCd >= 0.4 then
					nextAt = rage.lastShotAt + attackCd * 0.95
				end
				if nextAt and nextAt - now > rage.AttackPrep + 0.15 then
					rage._attackStart = nil
					rageGlueRelease()
					return false
				end
			end

			-- Pre-compute crouching state for melee (used by both teleport CFrame and
			-- attack-angle construction).  Head < 1.2 units above root Y = crouching.
			local isCrouching = false
			do
				local troot = target.character:FindFirstChild("HumanoidRootPart")
				if troot then
					isCrouching = (part.Position.Y - troot.Position.Y) < 1.2
				end
			end

			local myChar = LocalPlayer.Character
			local root = myChar and myChar:FindFirstChild("HumanoidRootPart")
			if not root then return false end
			if not rageEncoders() then return false end

			-- Our own root must be at a valid coordinate before we fire.
			do
				local mp = root.Position
				if math.abs(mp.X) >= RAGE_SPATIAL_LIMIT or math.abs(mp.Y) >= RAGE_SPATIAL_LIMIT
					or math.abs(mp.Z) >= RAGE_SPATIAL_LIMIT then
					rage._attackStart = nil
					return false
				end
			end

			-- SpatialLimitGate + ShootLock: when blocked, sit at a random far position.
			local spatialLimited = rageSpatialTick(target)
			if rageShootLockBlocked(spatialLimited, rage._dt * rage.ShootFrames) then
				rage._attackStart = nil
				if spatialLimited and rage.AntiTranslocate then
					local track = target.player and rage._evasionTrack[target.player]
					if track and track.lastNormalAt > 0 and (now - track.lastNormalAt) < 0.4 then
						return false
					end
				end
				rageFarPos(root)
				return false
			end

			-- 66.7ms (1/15s) prep window for guns (not snipers): we still move onto the
			-- target below, but hold the shot until the window has elapsed.
			-- Measured in game: the server only sees the teleported position reliably
			-- after it has been held for ~0.2 s (70 ms landed 1/3, 200 ms 3/3), so every
			-- new attack cycle holds the position for AttackPrep before the first packet.
			local prepWaiting = false
			if not isSniper then
				if rage._attackStart == nil then rage._attackStart = now end
				prepWaiting = now - rage._attackStart < rage.AttackPrep
			else
				rage._attackStart = nil
			end

			local shootPos = root.Position
			-- Drop mode shoots from where it stands: no teleport onto the target.
			local doTeleport = cfg.Teleport and not rage.DropMode
			if doTeleport and cfg.Glue then
				rageGlueAcquire(part)
			else
				rageGlueRelease()
			end
			-- "Stay on target" in frames: with 1-5, only the frame of a shot plus (frames - 1)
			-- more are spent on the target; every other frame evades (the other hub's ShootLock
			-- rhythm). The attack-prep hold does not apply then. 0 keeps the old behaviour.
			if rage.AttackFrames > 0 and doTeleport then
				prepWaiting = false
				local due = not (isKnife and now < rage._knifeAttackCoolUntil)
					and not (isMelee and not isKnife and now < (rage._meleeCoolUntil or 0))
					and not (deferredGap and now - rage.lastShotAt < deferredGap)
				if not due and (rage._onTarget or 0) >= rage.AttackFrames then
					rage._attackStart = nil
					rageGlueRelease()
					return false
				end
			end
			if doTeleport then
				local targetPos = part.Position
				local standPos
				-- Underground target (below an OutOfBoundsPart / far below the map): stand
				-- below its head instead. The check is cached 0.25 s per target.
				local underground = false
				if rage.AutoUnderground and target.player then
					local ug = rage._ug
					if not ug or ug.player ~= target.player or now - ug.at > 0.25 then
						ug = { player = target.player, at = now, val = rageIsTranslocated(target.player) }
						rage._ug = ug
					end
					underground = ug.val
				end
				if isMelee then
					local troot = target.character:FindFirstChild("HumanoidRootPart")
					local back = troot and -troot.CFrame.LookVector or (root.Position - targetPos)
					back = back.Magnitude > 0.01 and back.Unit or Vector3.new(0, 0, 1)
					-- Always end up slightly behind the target (relative to its facing) so the
					-- knife hit counts as a backstab even with Teleport reach = 0.
					standPos = targetPos + back * (cfg.TeleportReach + 0.5)
					standPos = standPos + Vector3.new(0, isCrouching and -3.85 or (underground and rage.UndergroundHeight or -0.70), 0.05)
				elseif isSniper then
					-- Sniper: teleport straight onto the target's root part.
					local troot = target.character:FindFirstChild("HumanoidRootPart")
					standPos = troot and troot.Position or targetPos
				else
					-- HitscanStrategy: teleport onto hitbox head with vertical offset.
					local yOffset = isCrouching and -3 or (underground and rage.UndergroundHeight or rage.AttackHeight)
					local dir = root.Position - targetPos
					dir = dir.Magnitude > 0.01 and dir.Unit or Vector3.new(0, 0, 1)
					standPos = targetPos + dir * cfg.TeleportReach + Vector3.new(0, yOffset, 0)
				end
				-- Stop evasion double-buffer while attack teleport is in effect.
				rage._evasionServerCF = nil
				rage._evasionClientCF = nil
				rage.backupCFrame = root.CFrame
				-- Standing melee / sniper: position only; everything else looks at the target.
				local teleportCF = (isSniper or (isMelee and not isCrouching))
					and CFrame.new(standPos)
					or  CFrame.new(standPos, targetPos)
				rageSetCFrame(root, teleportCF)
				shootPos = standPos
				rage._onTarget = (rage._onTarget or 0) + 1
				if cfg.Glue then
					rage.glueRoot = root
					rageSetProp(root, "PhysicsRepRootPart", part)
				end
			end

			-- Knife attack-cooldown check (deferred from above so we can issue far-pos).
			-- The server will see us at the far position while the cooldown is active,
			-- matching MeleeStrategy:Plan() "?�送到?��??��?，�??��?" behaviour.
			-- Backstab: the server counts a knife hit as a crit (150) when the view
			-- yaw it last received matches the victim's facing (measured in game), so
			-- keep sending that view while we hold/attack.
			if isMelee then
				local troot3 = target.character:FindFirstChild("HumanoidRootPart")
				if troot3 and now - (rage._lastBackstabView or 0) >= 0.03 then
					rage._lastBackstabView = now
					rage._viewLockUntil = now + 0.2
					local _, ty = troot3.CFrame:ToOrientation()
					pcall(function()
						ReplicatedStorage.Remotes.Replication.Fighter.UpdateCameraRotation:FireServer(
							RageEncode:EncodeCameraRotation(Vector2.new(0, ty)),
							nil
						)
					end)
				end
			end
			-- Measured in game: consecutive backstabs land every ~0.8 s (0.9 s 4/4, 0.8 s 5/5,
			-- 0.75 s 3/5, 0.7 s 2/4), well under the 1.25 s heavy cooldown. We stay on the
			-- target between attacks, so the position is already held when the next one is due.
			if isKnife and now < rage._knifeAttackCoolUntil then return false end
			if isMelee and not isKnife and now < (rage._meleeCoolUntil or 0) then return false end
			if prepWaiting then return false end
			if deferredGap and now - rage.lastShotAt < deferredGap then return false end

			-- Sniper fires the ray from two slightly offset heights at once (the game's
			-- own double-angle sniper shot); Knife uses the real heavy-attack layout
			-- (camera position looking at the target); everything else uses one look CFrame.
			local targetPos = part.Position
			local startCF, endCF
			local hitCF = CFrame.new(0.43, 0.25, 0.42) -- ["\3"]; knives use the real hit offset
			if isSniper then
				startCF = CFrame.new(targetPos + Vector3.new(0, 0.6, 0), targetPos)
				endCF   = CFrame.new(targetPos - Vector3.new(0, 0.6, 0), targetPos)
			elseif isMelee then
				-- Real game melee packet (captured from the game's own UseItem):
				-- c0 = camera position looking at the target (root + 1.75 up), c1 = c0
				-- moved 0.1 stud along the look direction, c3 = hit point in the hit
				-- part's object space. No -9e37 coordinates.
				local eye = shootPos + Vector3.new(0, 1.75, 0)
				local look = (targetPos - eye).Magnitude > 1e-3 and CFrame.lookAt(eye, targetPos) or CFrame.new(eye)
				startCF = look
				endCF = look + look.LookVector * 0.1
				hitCF = CFrame.Angles(0, math.pi / 2, 0)
			else
				-- Guns: same as the reference ragebot. The origin is our own position as
				-- the server knows it (standPos when TP is on, root.Position otherwise)
				-- aimed at the hitbox. Extreme coordinates (void-spam) aim a fixed short
				-- distance instead, to keep CFrame encoding sane.
				local aimTarget = targetPos
				if targetPos.Magnitude >= 100000 then
					local dir = targetPos - shootPos
					dir = dir.Magnitude > 0.1 and dir.Unit or Vector3.new(0, 0, 1)
					aimTarget = shootPos + dir * 10
				end
				local aim = CFrame.new(shootPos, aimTarget)
				startCF, endCF = aim, aim
			end

			-- ["\2"] = target hit part (matches GetCameraData()["\2"] = actual BasePart).
			-- ["\3"] = viewmodel/barrel offset CFrame, not target position.
			-- Both from silent aim reference implementation (line ~6837) and Gun.luau.
			local shot = {
				[utf8.char(0)] = RageEncode:EncodeCFrame(startCF),
				[utf8.char(1)] = RageEncode:EncodeCFrame(endCF),
				[utf8.char(2)] = part,
				[utf8.char(3)] = RageEncode:EncodeCFrame(hitCF),
			}
			rage.lastShotAt = now
			rage._lockedUntil = nil
			rage._onTarget = 0
			if not isMelee then
				local rawAmmo = 0
				pcall(function() rawAmmo = item:Get("Ammo") or 0 end)
				if rageRecordShot(item, rawAmmo) <= 0 then
					-- that was the last bullet: start the reload transport (park, wait for the server
					-- to show the empty magazine, then reload)
					rage.RT.gun, rage.RT.pending = item, rawAmmo
					rage.RT.readyAt = now + rageAmmo.replication()
					rage.RT.ack = now + rageAmmo.remote() + rageAmmo.replication()
					rage._immuneUntil = now + 0.2
				end
			end
			-- Record Knife backstab window on the first hit outside the window.
			-- attackCd for Knife comes from HeavyAttackCooldown (1.25 s by default).
			if isKnife then
				rage._knifeAttackCoolUntil = now + rage.KnifeCooldown
			end
			if isMelee and not isKnife then
				rage._meleeCoolUntil = now + math.max(attackCd, 0.05)
			end
			-- Knife QuickAttackInputs = "StartAiming" (byte 28, heavy/backstab);
			-- everything else uses "StartShooting" (byte 26).
			local actionEnum = isKnife and "StartAiming" or "StartShooting"
			pcall(function()
				ReplicatedStorage.Remotes.Replication.Fighter.UseItem:FireServer(
					objId,
					RageToEnum:ToEnum(actionEnum),
					-- Revolver quick shot (the game's StartAiming -> StartShooting(true)) returns
					-- (camera data, false, true): the flag rides in the outer packet ([\3]),
					-- not in the camera data. Measured: 2 shots 0.17 s apart both counted.
					isRevolver and { [utf8.char(1)] = shot, [utf8.char(2)] = false, [utf8.char(3)] = true }
						or (isMelee and { [utf8.char(1)] = shot }
						-- "aiming" flag: the server then uses the weapon's aim spread (see NoSpread)
						or { [utf8.char(1)] = shot, [utf8.char(2)] = true }),
					nil
				)
			end)
			if type(getgenv().InstanceMarkCombatShot) == "function" then
				getgenv().InstanceMarkCombatShot()
			end
			return true
		end

		-- Send a defensive/random look angle so the server-side view direction never
		-- lines up with where we are actually shooting from (throttled ~15/s).
		local function rageSpoofView()
			if not rage.SpoofViewAngles then return end
			local now = tick()
			if now < (rage._viewLockUntil or 0) then return end
			if now - rage.lastViewAt < 1 / 15 then return end
			rage.lastViewAt = now
			if not rageEncoders() then return end
			-- AimMatrix / DefensiveCFrame: send extreme vertical pitch so the server
			-- records a camera direction unrelated to the actual attack trajectory.
			-- Equipped/attacking ??+?/2 (looking up); evading/hiding ??-?/2 (looking down).
			local pitch = rage._spoofHiding and -(math.pi / 2) or (math.pi / 2)
			local yaw = math.random() * math.pi * 2
			pcall(function()
				ReplicatedStorage.Remotes.Replication.Fighter.UpdateCameraRotation:FireServer(
					RageEncode:EncodeCameraRotation(Vector2.new(pitch, yaw)),
					nil
				)
			end)
		end

		-- Random point on a sphere shell around an anchor (Evasion Random).
		-- ProjectileBreaker evasion (the other hub's mode for Slingshot users): while an enemy
		-- holds a projectile weapon, stand just under a random upward-facing map surface so the
		-- terrain stops the projectile; without that threat the normal random evasion runs.
		-- A pool of surface frames is built from the arena's RaycastWhitelist parts, a few per
		-- call. Everything lives in rage.PB (the main chunk is near Luau's 200-register limit).
		rage.PB = { pool = {}, done = setmetatable({}, { __mode = "k" }), env = nil, nextAt = 0, threatAt = 0, threat = false }
		function rage.PB.hazard(part)
			return part.Name == "Barriers" or part:HasTag("OutOfBoundsPart") or part:HasTag("KillBrick")
		end
		function rage.PB.frame(hitPos, normal, part)
			local up = normal.Unit
			local flat = (part.Position - hitPos) - up * (part.Position - hitPos):Dot(up)
			if flat.Magnitude < 0.0001 then
				flat = part.CFrame.LookVector - up * part.CFrame.LookVector:Dot(up)
				if flat.Magnitude < 0.0001 then flat = Vector3.xAxis - up * up:Dot(Vector3.xAxis) end
			end
			local right = flat.Unit:Cross(up).Unit
			return { pos = hitPos, right = right, up = up, forward = up:Cross(right).Unit }
		end
		function rage.PB.surface(part)
			if part.Transparency == 1 then return nil end
			local size = part.Size
			if size.X * size.Y * size.Z < 64 then return nil end
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Include
			params.FilterDescendantsInstances = { part }
			params.RespectCanCollide = false
			local reach = size.Magnitude + 1000
			for _ = 1, 8 do
				local origin = part.Position + Random.new():NextUnitVector() * reach
				local hit = workspace:Raycast(origin, (part.Position - origin).Unit * (reach + 100), params)
				if hit and hit.Normal.Y >= 0.98 then return rage.PB.frame(hit.Position, hit.Normal, part) end
			end
			local top = part.Position + Vector3.yAxis * reach
			local hit = workspace:Raycast(top, Vector3.yAxis * -(reach + 100), params)
			if hit and hit.Normal.Y >= 0.98 then return rage.PB.frame(hit.Position, hit.Normal, part) end
			return nil
		end
		function rage.PB.stand(f)
			local t = os.clock() * math.pi * 2
			local up = rage.PBDepthUp * (math.sin(t * 5) + 1) * 0.5
			local fwd = rage.PBDepthForward * (math.sin(t * 5) + 1) * 0.5
			return CFrame.fromMatrix(f.pos - f.up * 0.01 - f.up * up + f.forward * fwd, f.right, f.up, -f.forward)
		end
		-- Phase of the target's knife heavy attack: "swing" (the first HeavySwingTime seconds),
		-- "recover" (until the heavy cooldown is over) or nil. Other players' items run the same
		-- Melee code when the server replicates their attack, but only the animation key
		-- (HeavyAttack1) and _attack_cooldown (a tick() time) are kept up to date; _last_attack stays
		-- 0 (measured on another player's knife). The start is taken when _attack_cooldown is seen
		-- to change, or cooldown - HeavyAttackCooldown for a heavy attack already under way.
		rage.HeavySeen = setmetatable({}, { __mode = "k" })
		function rage.heavyPhase(target, now)
			if not target.player then return nil end
			local phase
			pcall(function()
				local fc = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
				local fighter = fc:GetFighter(target.player)
				local item = fighter and fighter.EquippedItem
				local info = item and item.Info
				local heavyCooldown = info and info.HeavyAttackCooldown
				if type(heavyCooldown) ~= "number" then return end
				local key, ends = item._last_attack_animation_name, item._attack_cooldown
				if type(key) ~= "string" or type(ends) ~= "number" or not key:match("^HeavyAttack%d") then return end
				local clock = tick()
				if ends <= clock then return end
				local seen = rage.HeavySeen[item]
				if not seen then
					seen = { ends = ends, started = ends - heavyCooldown }
					rage.HeavySeen[item] = seen
				elseif seen.ends ~= ends then
					seen.ends, seen.started = ends, clock
				end
				if clock - seen.started < rage.HeavySwingTime then
					phase = "swing"
				else
					phase = "recover"
				end
			end)
			return phase
		end
		function rage.PB.hasThreat(now)
			if now - rage.PB.threatAt < 0.3 then return rage.PB.threat end
			rage.PB.threatAt = now
			local found = false
			pcall(function()
				local fc = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
				for _, player in Players:GetPlayers() do
					if player ~= LocalPlayer and rageSameArena(player) and isEnemy(player) then
						local fighter = fc:GetFighter(player)
						local item = fighter and fighter.EquippedItem
						local info = item and item.Info
						if info and info.IsRaycast == false and info.Name == "Slingshot" then
							found = true
							break
						end
					end
				end
			end)
			rage.PB.threat = found
			return found
		end
		function rage.PB.scan(env)
			if rage.PB.env ~= env then
				rage.PB.env, rage.PB.pool, rage.PB.done = env, {}, setmetatable({}, { __mode = "k" })
			end
			local CS = cloneref(game:GetService("CollectionService"))
			local budget = 0
			local function take(part)
				if not part:IsA("BasePart") or rage.PB.done[part] or rage.PB.hazard(part) then return end
				rage.PB.done[part] = true
				budget += 1
				local f = rage.PB.surface(part)
				if f then table.insert(rage.PB.pool, f) end
			end
			for _, tagged in CS:GetTagged("RaycastWhitelist" .. tostring(env)) do
				take(tagged)
				if budget >= 24 or #rage.PB.pool >= 30 then return end
				for _, d in tagged:GetDescendants() do
					take(d)
					if budget >= 24 or #rage.PB.pool >= 30 then return end
				end
			end
		end
		-- Returns a CFrame to stand at, or nil when there is no threat / no surface yet.
		function rage.PB.compute(now)
			if now < rage.PB.nextAt and rage.PB.last then return rage.PB.stand(rage.PB.last) end
			if not rage.PB.hasThreat(now) then rage.PB.last = nil return nil end
			local env = LocalPlayer:GetAttribute("EnvironmentID")
			if env == nil then return nil end
			if #rage.PB.pool < 10 then rage.PB.scan(env) end
			if #rage.PB.pool < 10 then return nil end
			rage.PB.nextAt = now + rage.PBInterval
			rage.PB.last = rage.PB.pool[math.random(1, #rage.PB.pool)]
			return rage.PB.stand(rage.PB.last)
		end

		local function rageRandomPoint(anchor, radius)
			local u, v = math.random(), math.random()
			local theta = u * math.pi * 2
			local phi = math.acos(2 * v - 1)
			local r = radius * (0.75 + math.random() * 0.25)
			return anchor + Vector3.new(
				r * math.sin(phi) * math.cos(theta),
				r * math.sin(phi) * math.sin(theta),
				r * math.cos(phi)
			)
		end

		-- When enabled with no valid target, reposition the server-side root to dodge.
		-- The same render restore hides it locally. Bounded on purpose (the doc uses
		-- extreme coordinates, which read as out-of-bounds and get you killed/kicked).
		-- Evasion uses the same double-buffer pattern as attack teleport:
		--   Heartbeat  ??root = evasionDest (server replication sees this)
		--   First(100) ??root = real pos    (camera update at 300 sees real pos)
		-- So the camera never observes the evasion position at all.
		-- DefensiveCFrame: gun -> face the enemy, unarmed -> face away, knife -> random spin.
		local function rageDefensiveCFrame(cf)
			local myPos = cf.Position
			local item = rageEquippedItem()
			local name, isM
			if item then
				local n, _, m = rageWeaponInfo(item)
				name, isM = n, m
			end
			if item and isM then
				if name == "Knife" then
					return cf * CFrame.Angles(math.random() * math.pi * 2, math.random() * math.pi * 2, math.random() * math.pi * 2)
				end
				return cf
			end
			local target = rageTarget()
			local troot = target and target.character:FindFirstChild("HumanoidRootPart")
			if not troot then return cf end
			local toTarget = troot.Position - myPos
			if toTarget.Magnitude < 0.01 then return cf end
			if item then
				return CFrame.lookAt(myPos, troot.Position)
			end
			return CFrame.lookAt(myPos, myPos - toTarget)
		end

		-- Drop mode (beta): instead of the evasion above, teleport once DropDistance studs away from
		-- where you stand (tens of thousands: far outside the map, so no OutOfBoundsPart is there),
		-- DropHeight studs above (+) or below (-) the floor you were on, and leave the character to
		-- gravity. Switching it off takes you back. Attacks shoot from where it stands (no teleport
		-- onto the target). Nothing is written every frame and the evasion / RenderStepped restore
		-- are not involved.
		rage.Drop = { at = 0, floorY = nil, home = nil, root = nil, angle = 0, oob = {}, oobAt = 0 }
		function rage.dropInOutOfBounds(point)
			local drop = rage.Drop
			local now = tick()
			if now - drop.oobAt > 1 then
				drop.oobAt = now
				local ok, tagged = pcall(function()
					return cloneref(game:GetService("CollectionService")):GetTagged("OutOfBoundsPart")
				end)
				drop.oob = ok and tagged or {}
			end
			for _, part in drop.oob do
				if part:IsA("BasePart") and part.Parent then
					local relative = part.CFrame:PointToObjectSpace(point)
					local half = part.Size / 2
					if math.abs(relative.X) <= half.X and math.abs(relative.Y) <= half.Y and math.abs(relative.Z) <= half.Z then
						return true
					end
				end
			end
			return false
		end
		function rage.dropStep()
			local now = tick()
			if rage._attackStart ~= nil and rage.backupCFrame ~= nil then return end
			local character = LocalPlayer.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			if not root then return end
			local drop = rage.Drop
			if drop.root ~= root then
				-- a new character: forget the old spot
				drop.root, drop.home, drop.floorY, drop.at = root, nil, nil, 0
			end
			local grounded = humanoid ~= nil and humanoid.FloorMaterial ~= Enum.Material.Air
			if not drop.home then
				drop.home = root.Position
				drop.angle = math.random() * math.pi * 2
				drop.floorY = root.Position.Y - 3
			elseif grounded then
				drop.floorY = root.Position.Y - 3
			end
			-- gravity alone is slow: while in the air the fall is kept at least DropSpeed studs/s
			if drop.at ~= 0 and not grounded then
				pcall(function()
					local velocity = root.AssemblyLinearVelocity
					if velocity.Y > -rage.DropSpeed then
						root.AssemblyLinearVelocity = Vector3.new(velocity.X, -rage.DropSpeed, velocity.Z)
					end
				end)
			end
			-- one drop, then gravity: the next one only after landing
			if drop.at ~= 0 and (now - drop.at < 0.4 or not grounded) then return end
			local home = drop.home
			local point = Vector3.new(
				home.X + math.cos(drop.angle) * rage.DropDistance,
				(drop.floorY or (home.Y - 3)) + rage.DropHeight,
				home.Z + math.sin(drop.angle) * rage.DropDistance
			)
			-- a spot above the floor that is out of bounds is nudged down, one below it up
			local step = rage.DropHeight >= 0 and -5 or 5
			for _ = 1, 40 do
				if not rage.dropInOutOfBounds(point) then break end
				point += Vector3.new(0, step, 0)
			end
			rageSetCFrame(root, CFrame.new(point) * (root.CFrame - root.CFrame.Position))
			pcall(function()
				root.AssemblyLinearVelocity = Vector3.new(0, -rage.DropSpeed, 0)
			end)
			drop.at = now
		end
		-- Back to where you stood when the drop mode was switched on.
		function rage.dropReturn()
			local drop = rage.Drop
			local character = LocalPlayer.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root and drop.home and drop.root == root and drop.at ~= 0 then
				rageSetCFrame(root, CFrame.new(drop.home + Vector3.new(0, 3, 0)) * (root.CFrame - root.CFrame.Position))
				pcall(function()
					root.AssemblyLinearVelocity = Vector3.zero
				end)
			end
			drop.home, drop.at, drop.floorY = nil, 0, nil
		end

		local function rageEvade()
			if rage.DropMode then
				rage.dropStep()
				return
			end
			if rage.Evasion == "Off" then return end
			-- Always evade (lobby, no enemy, anything): nobody may ever see us standing
			-- at our real position.
			local now = tick()
			-- A cycle older than the prep hold plus a shot window is stale (nothing fired
			-- and nothing cleared it): never let it freeze evasion.
			if rage._attackStart ~= nil and now - rage._attackStart > 1.5 then
				rage._attackStart = nil
			end
			-- Only the frames where the attack teleport is actually in effect (root sits
			-- on the target) must not be overwritten by evasion, or the shot would be
			-- validated from our evasion position. Every other frame evades.
			if rage._attackStart ~= nil and rage.backupCFrame ~= nil then return end
			local myChar = LocalPlayer.Character
			local root = myChar and myChar:FindFirstChild("HumanoidRootPart")
			if not root then return end

			-- Reloading / out of ammo: park in the immune ring, a fresh point every frame.
			local reloading = rage._action ~= nil and rage._action.type == "Reload" and now - (rage._actionAt or 0) < 0.3
			if rage.ImmuneReload and (reloading or now < (rage._immuneUntil or 0)) then
				rage.lastEvadeAt = now
				rage._evasionServerCF = rageImmuneCFrame()
				rage._evasionClientCF = rage._evasionClientCF or root.CFrame
				rageSetCFrame(root, rage._evasionServerCF)
				return
			end

			-- Weapon kind and target are looked up every 0.3 s (the lookups are heavy; doing
			-- them per frame froze the game on melee). Everything else is per frame.
			if now - (rage._evadeInfoAt or 0) >= 0.3 then
				rage._evadeInfoAt = now
				local item = rageEquippedItem()
				local name, isM
				if item then
					local n, _, m = rageWeaponInfo(item)
					name, isM = n, m
				end
				local kind = "none"
				if item and isM then
					kind = name == "Knife" and "knife" or "melee"
				elseif item then
					kind = "gun"
				end
				rage._evadeKind = kind
				local target = kind ~= "melee" and kind ~= "knife" and rageTarget() or nil
				rage._evadeTroot = target and target.character:FindFirstChild("HumanoidRootPart") or nil
			end

			local dest
			-- Auto: the other hub's _Plan order for the evasion. While reloading / about to
			-- reload the immune ring has already taken over above; otherwise an enemy with a
			-- projectile weapon means ProjectileBreaker, anything else Translocate (which falls
			-- back to a random far point when the map has no OutOfBoundsPart).
			local mode = rage.Evasion
			if mode == "Auto" then
				mode = rage.PB.hasThreat(now) and "ProjectileBreaker" or "Translocate"
			end
			if mode == "Translocate" then
				-- Scans tagged parts: keep the 0.3 s interval.
				if rage._evasionServerCF == nil or now - rage.lastEvadeAt >= 0.3 then
					local ok, tagged = pcall(function()
						return cloneref(game:GetService("CollectionService")):GetTagged("OutOfBoundsPart")
					end)
					if ok and tagged then
						for _, p in tagged do
							if p:IsA("BasePart") and p:GetAttribute("KillDelay") == 0 then
								dest = p.CFrame * CFrame.new(0, -p.Size.Y / 2 + rage.TranslocateOffset, 0)
								break
							end
						end
					end
					if dest then
						rage.lastEvadeAt = now
						rage._evasionServerCF = dest
					end
				end
			end
			if mode == "ProjectileBreaker" then
				local ok, cf = pcall(rage.PB.compute, now)
				if ok and cf then
					dest = cf
					rage.lastEvadeAt = now
					rage._evasionServerCF = cf
				end
			end
			if not dest and not (mode == "Translocate" and rage._evasionServerCF ~= nil and now - rage.lastEvadeAt < 0.3) then
				-- Random (and Translocate fallback): new position and facing every frame.
				-- Like the other hub's Random evasion (AnchorFromCharacter = false): a point on a
				-- horizontal ring of radius R .. 1.5 R around the world origin at our own height,
				-- then one axis pushed to 2^30. The two ordinary coordinates therefore sit near
				-- the origin instead of inside the arena's footprint.
				local ringAngle = math.random() * math.pi * 2
				local ringRadius = rage.EvadeRadius * (1 + math.random() * 0.5)
				local anchor = rage.EvadeAnchorCharacter and root.Position or Vector3.new(0, root.Position.Y, 0)
				local pt = anchor + Vector3.new(math.cos(ringAngle) * ringRadius, 0, math.sin(ringAngle) * ringRadius)
				local axis = math.random(1, 3)
				if axis == 1 then pt = Vector3.new(1073741824, pt.Y, pt.Z)
				elseif axis == 2 then pt = Vector3.new(pt.X, 1073741824, pt.Z)
				else pt = Vector3.new(pt.X, pt.Y, 1073741824) end
				-- Facing: fully random on all three axes, like the other hub.
				local cf = CFrame.new(pt)
					* CFrame.fromOrientation(math.random() * math.pi * 2, math.random() * math.pi * 2, math.random() * math.pi * 2)
				if mode == "Translocate" then
					-- No out-of-bounds part: a random far point (1e4 .. 1e9 studs), random facing.
					local direction = Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5)
					direction = direction.Magnitude > 0.001 and direction.Unit or Vector3.yAxis
					local distance = 10 ^ (4 + math.random() * 5)
					cf = CFrame.new(root.Position + direction * distance)
						* CFrame.fromOrientation(math.random() * math.pi * 2, math.random() * math.pi * 2, math.random() * math.pi * 2)
				end
				local kind = rage._evadeKind
				if mode == "Random" then
					-- the other hub's Random keeps the random facing as is
				elseif kind == "knife" then
					cf = cf * CFrame.Angles(math.random() * math.pi * 2, math.random() * math.pi * 2, math.random() * math.pi * 2)
				elseif kind ~= "melee" then
					local troot = rage._evadeTroot
					if troot and troot.Parent then
						local toTarget = troot.Position - pt
						if toTarget.Magnitude >= 0.01 then
							cf = kind == "gun" and CFrame.lookAt(pt, troot.Position) or CFrame.lookAt(pt, pt - toTarget)
						end
					end
				end
				rage.lastEvadeAt = now
				rage._evasionServerCF = cf
			end

			-- Every Heartbeat: move root to cached evasion dest.
			-- RenderPriority.First (priority 100, before camera at 300) will restore it,
			-- so the camera never sees the evasion position.
			if rage._evasionServerCF then
				rage._evasionClientCF = rage._evasionClientCF or root.CFrame  -- real pos; First will restore this
				rageSetCFrame(root, rage._evasionServerCF)
			end
		end

		-- Restore the teleported root before the frame is drawn so our view never
		-- shows the jump (the shot already reached the server on Heartbeat).
		local RAGE_RESTORE = PREFIX .. "RageRestore"
		local function rageRestoreRoot()
			-- Release the physics-root glue first so restoring the CFrame sticks.
			if rage.glueRoot then
				rageSetProp(rage.glueRoot, "PhysicsRepRootPart", nil)
				rage.glueRoot = nil
			end
			local myChar = LocalPlayer.Character
			local root = myChar and myChar:FindFirstChild("HumanoidRootPart")
			if rage.backupCFrame then
				if root then rageSetCFrame(root, rage.backupCFrame) end
				rage.backupCFrame = nil
				rage._evasionClientCF = nil
			elseif rage._evasionClientCF then
				-- Evasion double-buffer: restore real pos so camera (priority 300)
				-- always sees the non-evaded position.
				if root then rageSetCFrame(root, rage._evasionClientCF) end
				rage._evasionClientCF = nil
			end
			-- Failsafe for the camera: whatever happened above, a root left at an extreme
			-- coordinate here would drag the view into the void. Put it back on the last
			-- position seen near the map.
			if root then
				local p = root.Position
				if math.abs(p.X) > 1e5 or math.abs(p.Y) > 1e5 or math.abs(p.Z) > 1e5 then
					if rage._lastRealCF then
						rageSetCFrame(root, rage._lastRealCF)
					end
				else
					rage._lastRealCF = root.CFrame
				end
			end
		end
		-- The RenderStepped hook has a switch (Ragebot > "RenderStepped restore").
		function rage.setRenderRestore(on)
			pcall(function()
				RunService:UnbindFromRenderStep(RAGE_RESTORE)
			end)
			if on then
				pcall(function()
					RunService:BindToRenderStep(RAGE_RESTORE, Enum.RenderPriority.First.Value, rageRestoreRoot)
				end)
			end
		end
		rage.setRenderRestore(rage.RenderRestore)
		table.insert(cleanup, function()
			pcall(function() RunService:UnbindFromRenderStep(RAGE_RESTORE) end)
			if rage.glueRoot then
				rageSetProp(rage.glueRoot, "PhysicsRepRootPart", nil)
				rage.glueRoot = nil
			end
			if rage.backupCFrame then
				local myChar = LocalPlayer.Character
				local root = myChar and myChar:FindFirstChild("HumanoidRootPart")
				if root then pcall(function() root.CFrame = rage.backupCFrame end) end
				rage.backupCFrame = nil
			end
			rage._evasionServerCF = nil
			rage._evasionClientCF = nil
		end)

		-- Manual fire: is the player holding the fire input right now? Uses the game's own
		-- input state (touch fire button on mobile, mouse / keybind / gamepad elsewhere).
		local rageMechanics
		local function rageUserFiring()
			if rageMechanics == nil then
				local ok, mech = pcall(function()
					return require(LocalPlayer.PlayerScripts.Controllers.MechanicsController)
				end)
				rageMechanics = ok and mech or false
			end
			if rageMechanics then
				local ok, down = pcall(rageMechanics.IsInputDown, rageMechanics, "Shoot")
				if ok and down then
					return true
				end
			end
			local ok, down = pcall(UserInputService.IsMouseButtonPressed, UserInputService, Enum.UserInputType.MouseButton1)
			return ok and down == true
		end

		local rageHeartbeat = RunService.Heartbeat:Connect(function(dt)
			-- Heartbeat can run more than once per render frame; without this the
			-- next one still sees the root at the teleport/evasion position (shot
			-- origin ~1e9 studs = blank shot) and backs that position up as "real".
			rageRestoreRoot()
			rage._dt = dt
			if not rage.Enabled then rageGlueReleaseAll() return end
			-- No match environment (lobby): do nothing at all and drop all state, the way the
			-- other hub resets: no attack, no evasion, nothing carried over into the match.
			if LocalPlayer:GetAttribute("EnvironmentID") == nil then
				rage._attackStart, rage._action, rage._actionAt = nil, nil, nil
				rage._evasionServerCF, rage._evasionClientCF = nil, nil
				rage._purgeEvade, rage._immuneUntil, rage._onTarget = false, 0, 0
				rage._lockedUntil, rage._reloadUntil = nil, 0
				rage.RT.clear()
				rage._manualLatch, rage._spoofHiding = false, false
				rageGlueReleaseAll()
				return
			end
			rageGlueTick()
			if rage.Activation ~= "Always" and not rage.KeyActive then return end
			local character = LocalPlayer.Character
			if not character or not isAlive(character) then return end


			-- Manual fire: the ragebot only attacks (teleport + shoot) while the player is
			-- holding the fire input; the rest of the time it evades instead.
			local manualAttack = true
			if rage.ManualFire then
				local now = tick()
				-- Your own tap would also make the game fire its own shot first, using up the
				-- weapon cooldown (shotgun 0.7 s, sniper 1.5 s) so the ragebot's teleported
				-- shot 0.2 s later is rejected (measured: 1 ammo per tap, no damage). While a
				-- target exists keep the game's client-side cooldown set so it never sends
				-- that shot; the ragebot's own packets do not go through the client cooldown.
				local heldItem = rageEquippedItem()
				if heldItem and rageTarget() then
					local block = now + 0.3
					if type(heldItem._shoot_cooldown) == "number" and heldItem._shoot_cooldown < block then
						heldItem._shoot_cooldown = block
					end
					if type(heldItem._attack_cooldown) == "number" and heldItem._attack_cooldown < block then
						heldItem._attack_cooldown = block
					end
				end
				local down = rageUserFiring()
				if down then
					if not rage._manualDown then
						rage._manualPressAt = now
					end
					rage._manualLatch = true
				end
				rage._manualDown = down
				-- A tap is shorter than the prep hold and the weapon cooldown, so a released
				-- button keeps the attack going until one shot has actually gone out after
				-- the press (or 1.5 s pass, e.g. no target).
				if not down and rage._manualLatch then
					local pressAt = rage._manualPressAt or 0
					if rage.lastShotAt >= pressAt or now - pressAt > 1.5 then
						rage._manualLatch = false
					end
				end
				manualAttack = rage._manualLatch == true
			end
			if not manualAttack then
				rage._attackStart = nil
				rage._purgeEvade = false
				rageGlueRelease()
				rage._spoofHiding = true
				rageSpoofView()
				rageEvade()
				return
			end

			if rage.CycleMode then
				rage._cycleTimer = rage._cycleTimer - dt
				if rage._cycleTimer <= 0 then
					if rage._cyclePhase == "Hide" then
						rage._cyclePhase = "Attack"
						rage._cycleTimer = rage.AttackTime
					else
						rage._cyclePhase = "Hide"
						rage._cycleTimer = rage.HideTime
					end
				end
				if rage._cyclePhase == "Hide" then
					-- Hiding is not attacking: drop the attack cycle left over from the last
					-- shot, otherwise rageEvade() skips and we stand still the whole phase.
					rage._attackStart = nil
					rageGlueRelease()
					rageEvade()
					rage._spoofHiding = true
					rageSpoofView()
					return
				end
			end

			local fired = rageFire()
			-- Pure-evade mode: no usable weapon found by weapon manager. rageFire()
			-- re-evaluates the flag every frame; checking it *before* calling rageFire
			-- latched it forever (only rageFire could clear it).
			if rage._purgeEvade then
				rageEvade()
				rage._spoofHiding = true
				rageSpoofView()
				return
			end
			rage._spoofHiding = not fired  -- hiding = not actively shooting
			rageSpoofView()
			-- Also in CycleMode's Attack phase: any frame without a shot evades, so the
			-- real position is never exposed between shots.
			if not fired then
				rageEvade()
			end
		end)
		table.insert(cleanup, rageHeartbeat)

		table.insert(cleanup, function() rageGlueReleaseAll() end)

		-- While the ragebot is on: send our physics to the server at 120 Hz instead of 15
		-- (so the evasion / attack positions set each Heartbeat reach it every frame, not
		-- one frame in four) and stop the engine from killing the character at extreme
		-- coordinates. Both are put back when it is switched off. Needs an executor with
		-- setfflag; skipped silently otherwise.
		local rageFallenHeight = workspace.FallenPartsDestroyHeight
		local function rageSetPhysics(on)
			local setFlag = setfflag or set_fflag
			if type(setFlag) == "function" then
				pcall(setFlag, "DFIntS2PhysicsSenderRate", on and "120" or "15")
			end
			pcall(function()
				workspace.FallenPartsDestroyHeight = on and (0 / 0) or rageFallenHeight
			end)
			-- The game's own kill check (OutOfBoundsMachine.IsOutOfBounds) reads our root part
			-- and kills us when it sits inside an OutOfBoundsPart, which the attack position
			-- under an enemy that hides below one does. Like the other hub, rename the "RootPart"
			-- constant it looks up to "RootPart " (no such child) while the ragebot is on, so
			-- the check finds nothing; the original name comes back when it is switched off.
			pcall(function()
				local oob = rage._oob
				if not oob then
					local mod = require(ReplicatedStorage.Modules.OutOfBoundsMachine)
					local fn = type(mod) == "table" and rawget(mod, "IsOutOfBounds")
					if type(fn) == "function" then
						for index, constant in ipairs(debug.getconstants(fn)) do
							if constant == "RootPart" or constant == "RootPart " then
								oob = { fn = fn, index = index }
								break
							end
						end
					end
					rage._oob = oob
				end
				if oob then
					debug.setconstant(oob.fn, oob.index, on and "RootPart " or "RootPart")
				end
			end)
		end
		table.insert(cleanup, function() rageSetPhysics(false) end)

