	local dictionaries = { ["English"] = false, ["繁�?中�?"] = ZH }
	local current = "English"
	local originals = setmetatable({}, { __mode = "k" }) -- object -> { text, shown, placeholder, shownPlaceholder }
	local hooked = setmetatable({}, { __mode = "k" })    -- object -> connection
	local sweepToken = 0

	local function lookup(dict, text)
		if type(text) ~= "string" or text == "" then
			return nil
		end
		local key = string.lower((string.gsub(string.gsub(text, "^%s+", ""), "%s+$", "")))
		return dict[key]
	end

	local function isTextObject(inst)
		return inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox")
	end

	-- Bring one object in line with the current language.
	local function sync(inst)
		local dict = dictionaries[current]
		local rec = originals[inst]
		if not rec then
			rec = {}
			originals[inst] = rec
		end
		if not inst:IsA("TextBox") then
			local now = inst.Text
			if rec.shown == nil or now ~= rec.shown then
				rec.text = now -- new original (first sight, or the script changed it)
			end
			local shown = dict and lookup(dict, rec.text) or rec.text
			-- Remember what we show BEFORE writing it: with immediate signals the change
			-- handler runs inside the assignment and must see it is our own text, or it
			-- would take the translation for the new original.
			rec.shown = shown
			if inst.Text ~= shown then
				inst.Text = shown
			end
		else
			local now = inst.PlaceholderText
			if rec.shownPlaceholder == nil or now ~= rec.shownPlaceholder then
				rec.placeholder = now
			end
			local shown = dict and lookup(dict, rec.placeholder) or rec.placeholder
			rec.shownPlaceholder = shown
			if inst.PlaceholderText ~= shown then
				inst.PlaceholderText = shown
			end
		end
	end

	local function hook(inst)
		if hooked[inst] or not isTextObject(inst) then
			return
		end
		local property = inst:IsA("TextBox") and "PlaceholderText" or "Text"
		hooked[inst] = inst:GetPropertyChangedSignal(property):Connect(function()
			if current ~= "English" then
				pcall(sync, inst)
			end
		end)
		pcall(sync, inst)
	end

	local function sweep()
		sweepToken += 1
		local token = sweepToken
		local root = Window.Gui
		if not root then
			return
		end
		task.spawn(function()
			local count = 0
			for _, inst in ipairs(root:GetDescendants()) do
				if token ~= sweepToken then
					return
				end
				if isTextObject(inst) then
					if current == "English" then
						local rec = originals[inst]
						if rec then
							pcall(function()
								if inst:IsA("TextBox") then
									if rec.placeholder ~= nil then inst.PlaceholderText = rec.placeholder end
								elseif rec.text ~= nil then
									inst.Text = rec.text
								end
							end)
						end
						local conn = hooked[inst]
						if conn then
							conn:Disconnect()
							hooked[inst] = nil
						end
						originals[inst] = nil
					else
						hook(inst)
					end
				end
				count += 1
				if count % 250 == 0 then
					task.wait() -- spread the work over frames, no hitch
				end
			end
		end)
	end

	local function setLanguage(name)
		if not dictionaries[name] and name ~= "English" then
			name = "English"
		end
		if name == current then
			return
		end
		current = name
		sweep()
	end

	if Window.Gui then
		track(Window.Gui.DescendantAdded:Connect(function(inst)
			if current ~= "English" and isTextObject(inst) then
				task.defer(hook, inst)
			end
		end))
	end

	local LanguageSection = SettingsTab:AddSection("Language")
	LanguageSection:AddDropdown({
		Title = "Language",
		Options = { "English", "繁�?中�?" },
		Default = "English",
		Flag = "Language",
		Callback = function(value)
			setLanguage(value or "English")
		end,
	})
end
