-- Components/Button.lua
loaders[newNode("Button", N_Components)] = function(script, require)
--[[
	Material 3 Button. Variants: "Filled" (default), "Tonal", "Outlined", "Text", "Elevated".

	MD3.Button.new({
		Text = "Continue",
		Variant = "Filled",
		Theme = myTheme,      -- optional, defaults to the shared Theme.Default()
		Parent = someFrame,
		Disabled = false,
	})
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Ripple = require(Root.Core.Ripple)
local Elevation = require(Root.Core.Elevation)
local Assets = require(Root.Executor.Assets)

local Button = {}
Button.__index = Button

local HEIGHT = 40

local function colorsFor(theme, variant: string)
	local c = theme.Colors
	if variant == "Filled" then
		return { container = c.Primary, label = c.OnPrimary, border = nil, elevation = 0 }
	elseif variant == "Tonal" then
		return { container = c.SecondaryContainer, label = c.OnSecondaryContainer, border = nil, elevation = 0 }
	elseif variant == "Elevated" then
		return { container = c.SurfaceContainerLow, label = c.Primary, border = nil, elevation = 1 }
	elseif variant == "Outlined" then
		return { container = c.Surface, containerTransparency = 1, label = c.Primary, border = c.Outline, elevation = 0 }
	elseif variant == "Text" then
		return { container = c.Surface, containerTransparency = 1, label = c.Primary, border = nil, elevation = 0 }
	end
	error(`Unknown Button variant "{variant}"`)
end

function Button.new(props)
	props = props or {}
	local self = setmetatable({}, Button)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._variant = props.Variant or "Filled"
	self._disabled = props.Disabled or false
	self.Activated = Signal.new()

	local button = Create("TextButton") {
		Name = props.Name or "MD3Button",
		AutoButtonColor = false,
		Text = "",
		Size = props.Size or UDim2.new(0, 0, 0, HEIGHT),
		AutomaticSize = props.Size and Enum.AutomaticSize.None or Enum.AutomaticSize.X,
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		LayoutOrder = props.LayoutOrder or 0,
		ClipsDescendants = false,
	}
	Shape.Corner(Shape.Full, button)

	-- Padding + layout live on an inner frame: the state layer and ripples
	-- are parented to the button itself and must not be laid out.
	local content = Create("Frame") {
		Name = "Content",
		BackgroundTransparency = 1,
		Size = props.Size and UDim2.fromScale(1, 1) or UDim2.new(0, 0, 1, 0),
		AutomaticSize = props.Size and Enum.AutomaticSize.None or Enum.AutomaticSize.X,
		Parent = button,
	}

	local padding = Create("UIPadding") {
		PaddingLeft = UDim.new(0, 24),
		PaddingRight = UDim.new(0, 24),
		Parent = content,
	}
	self._padding = padding

	Create("UIListLayout") {
		SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 8),
		Parent = content,
	}

	local icon = nil
	if props.Icon then
		icon = Create("ImageLabel") {
			Name = "Icon",
			BackgroundTransparency = 1,
			Image = Assets.Resolve(props.Icon),
			Size = UDim2.fromOffset(18, 18),
			LayoutOrder = 1,
			Parent = content,
		}
	end
	self._icon = icon

	local label = Create("TextLabel") {
		Name = "Label",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.new(0, 0, 1, 0),
		Text = props.Text or "",
		LayoutOrder = 2,
		Parent = content,
	}
	Typography.Apply(label, "LabelLarge")
	self._label = label

	local stroke = Create("UIStroke") {
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = button,
	}
	self._stroke = stroke

	self.Instance = button
	self._stateLayer = StateLayer.new(button, Color3.new(1, 1, 1), Shape.Full)

	self:_applyTheme()
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if props.Parent then
		button.Parent = props.Parent
	end

	return self
end

function Button:_applyTheme()
	local colors = colorsFor(self._theme, self._variant)
	local button = self.Instance

	TweenService:Create(button, Motion.Standard(Motion.Duration.Short2), {
		BackgroundColor3 = colors.container,
		BackgroundTransparency = self._disabled and 0.88 or (colors.containerTransparency or 0),
	}):Play()

	self._label.TextColor3 = colors.label
	self._label.TextTransparency = self._disabled and 0.62 or 0
	if self._icon then
		self._icon.ImageColor3 = colors.label
		self._icon.ImageTransparency = self._disabled and 0.62 or 0
	end

	self._stroke.Color = colors.border or colors.label
	self._stroke.Transparency = colors.border and (self._disabled and 0.88 or 0) or 1

	self._stateLayer:SetColor(colors.label)

	if colors.elevation and colors.elevation > 0 and not self._disabled then
		Elevation.Apply(button, colors.elevation, self._theme.Colors.Shadow, Shape.Full)
	else
		Elevation.Remove(button)
	end
end

function Button:_bindInput()
	local button = self.Instance

	self._maid:GiveTask(button.MouseEnter:Connect(function()
		if not self._disabled then
			self._stateLayer:SetState("Hover", true)
		end
	end))
	self._maid:GiveTask(button.MouseLeave:Connect(function()
		self._stateLayer:SetState("Hover", false)
		self._stateLayer:SetState("Pressed", false)
	end))
	self._maid:GiveTask(button.InputBegan:Connect(function(input)
		if self._disabled then
			return
		end
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", true)
			Ripple.Emit(button, input.Position, colorsFor(self._theme, self._variant).label)
		end
	end))
	self._maid:GiveTask(button.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", false)
		end
	end))
	self._maid:GiveTask(button.Activated:Connect(function(...)
		if not self._disabled then
			self.Activated:Fire(...)
		end
	end))
end

function Button:SetText(text: string)
	self._label.Text = text
end

function Button:SetVariant(variant: string)
	self._variant = variant
	self:_applyTheme()
end

function Button:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self.Instance.Active = not disabled
	self:_applyTheme()
end

function Button:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function Button:Destroy()
	Elevation.Remove(self.Instance)
	self._stateLayer:Destroy()
	self._maid:Destroy()
	self.Activated:DisconnectAll()
	self.Instance:Destroy()
end

return Button
end

-- Components/Card.lua
loaders[newNode("Card", N_Components)] = function(script, require)
--[[
	Material 3 Card. Variants: "Elevated", "Filled", "Outlined".
	Cards are plain containers (Size/AutomaticSize up to the caller) with an
	optional content UIListLayout + UIPadding for convenience.

	local card = MD3.Card.new({ Variant = "Elevated", Parent = screen, Size = UDim2.fromOffset(300, 160) })
	someChild.Parent = card.Instance
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Ripple = require(Root.Core.Ripple)
local Elevation = require(Root.Core.Elevation)

local Card = {}
Card.__index = Card

local function colorsFor(theme, variant)
	local c = theme.Colors
	if variant == "Filled" then
		return { container = c.SurfaceContainerHighest, border = nil, elevation = 0 }
	elseif variant == "Outlined" then
		return { container = c.Surface, border = c.OutlineVariant, elevation = 0 }
	end
	return { container = c.SurfaceContainerLow, border = nil, elevation = 1 } -- Elevated
end

function Card.new(props)
	props = props or {}
	local self = setmetatable({}, Card)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._variant = props.Variant or "Elevated"
	self._interactive = props.Interactive or false
	self.Activated = Signal.new()

	local className = self._interactive and "TextButton" or "Frame"
	local card = Create(className) {
		Name = props.Name or "MD3Card",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Size = props.Size or UDim2.fromOffset(280, 160),
		LayoutOrder = props.LayoutOrder or 0,
		ClipsDescendants = props.ClipsDescendants ~= false,
	}
	if self._interactive then
		card.AutoButtonColor = false
		card.Text = ""
	end
	Shape.Corner(Shape.Medium, card)

	local stroke = Create("UIStroke") {
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = card,
	}
	self._stroke = stroke

	Create("UIPadding") {
		PaddingTop = UDim.new(0, 16),
		PaddingBottom = UDim.new(0, 16),
		PaddingLeft = UDim.new(0, 16),
		PaddingRight = UDim.new(0, 16),
		Parent = card,
	}

	if props.Layout ~= false then
		Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			Padding = UDim.new(0, 8),
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = card,
		}
	end

	self.Instance = card

	if self._interactive then
		self._stateLayer = StateLayer.new(card, Color3.new(1, 1, 1), Shape.Medium)
		self:_bindInput()
	end

	self:_applyTheme()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if props.Parent then
		card.Parent = props.Parent
	end

	return self
end

function Card:_applyTheme()
	local colors = colorsFor(self._theme, self._variant)
	TweenService:Create(self.Instance, Motion.Standard(Motion.Duration.Short2), {
		BackgroundColor3 = colors.container,
	}):Play()

	self._stroke.Color = colors.border or colors.container
	self._stroke.Transparency = colors.border and 0 or 1

	if colors.elevation > 0 then
		Elevation.Apply(self.Instance, colors.elevation, self._theme.Colors.Shadow, Shape.Medium)
	else
		Elevation.Remove(self.Instance)
	end

	if self._stateLayer then
		self._stateLayer:SetColor(self._theme.Colors.OnSurface)
	end
end

function Card:_bindInput()
	local card = self.Instance
	self._maid:GiveTask(card.MouseEnter:Connect(function()
		self._stateLayer:SetState("Hover", true)
	end))
	self._maid:GiveTask(card.MouseLeave:Connect(function()
		self._stateLayer:SetState("Hover", false)
		self._stateLayer:SetState("Pressed", false)
	end))
	self._maid:GiveTask(card.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", true)
			Ripple.Emit(card, input.Position, self._theme.Colors.OnSurface)
		end
	end))
	self._maid:GiveTask(card.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", false)
		end
	end))
	self._maid:GiveTask(card.Activated:Connect(function(...)
		self.Activated:Fire(...)
	end))
end

function Card:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function Card:Destroy()
	Elevation.Remove(self.Instance)
	if self._stateLayer then
		self._stateLayer:Destroy()
	end
	self._maid:Destroy()
	self.Activated:DisconnectAll()
	self.Instance:Destroy()
end

return Card
end

-- Components/Checkbox.lua
loaders[newNode("Checkbox", N_Components)] = function(script, require)
--[[
	Material 3 Checkbox (supports true/false/"Indeterminate").

	local cb = MD3.Checkbox.new({ Value = false, Parent = row })
	cb.Changed:Connect(function(value) ... end)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Icons = require(Root.Core.Icons)

local Checkbox = {}
Checkbox.__index = Checkbox

local BOX_SIZE = 18
local HITBOX_SIZE = 40

function Checkbox.new(props)
	props = props or {}
	local self = setmetatable({}, Checkbox)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._value = props.Value or false -- true | false | "Indeterminate"
	self._disabled = props.Disabled or false
	self.Changed = Signal.new()

	local hitbox = Create("TextButton") {
		Name = props.Name or "MD3Checkbox",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(HITBOX_SIZE, HITBOX_SIZE),
		LayoutOrder = props.LayoutOrder or 0,
	}
	Shape.Corner(Shape.Full, hitbox)

	local box = Create("Frame") {
		Name = "Box",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(BOX_SIZE, BOX_SIZE),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Parent = hitbox,
	}
	Shape.Corner(Shape.ExtraSmall, box)

	local stroke = Create("UIStroke") {
		Thickness = 2,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = box,
	}
	self._stroke = stroke

	-- Drawn as a Material icon glyph (check / remove) rather than an image
	-- asset. Renders the real Material Design flat icon once you've called
	-- MD3.Icons.SetFont(...); falls back to a plain glyph until then ??see
	-- Core/Icons.lua for setup.
	local mark = Create("TextLabel") {
		Name = "Mark",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(0.85, 0.85),
		Font = Enum.Font.GothamBold,
		TextScaled = true,
		Parent = box,
	}
	self._mark = mark

	self.Instance = hitbox
	self._box = box
	self._stateLayer = StateLayer.new(hitbox, Color3.new(1, 1, 1), Shape.Full)

	self:_render(false)
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_render(true)
	end))

	if props.Parent then
		hitbox.Parent = props.Parent
	end

	return self
end

function Checkbox:_render(animate: boolean)
	local c = self._theme.Colors
	local checked = self._value == true or self._value == "Indeterminate"

	local boxColor = checked and (self._disabled and c.OnSurface or c.Primary) or c.Surface
	local boxTransparency = checked and (self._disabled and 0.62 or 0) or 1
	local borderColor = self._disabled and c.OnSurface or c.OnSurfaceVariant
	local borderTransparency = self._disabled and 0.62 or 0
	local markColor = self._disabled and c.Surface or c.OnPrimary

	local ti = Motion.Standard(Motion.Duration.Short2)
	local apply = animate and function(inst, props_) TweenService:Create(inst, ti, props_):Play() end
		or function(inst, props_) for k, v in pairs(props_) do inst[k] = v end end

	apply(self._box, { BackgroundColor3 = boxColor, BackgroundTransparency = boxTransparency })
	apply(self._mark, { TextColor3 = markColor, TextTransparency = checked and 0 or 1 })

	Icons.Apply(self._mark, self._value == "Indeterminate" and "remove" or "check")

	self._stroke.Color = borderColor
	self._stroke.Transparency = checked and 1 or borderTransparency
	self._stateLayer:SetColor(checked and c.Primary or c.OnSurface)
end

function Checkbox:_bindInput()
	local hitbox = self.Instance
	self._maid:GiveTask(hitbox.MouseEnter:Connect(function()
		if not self._disabled then
			self._stateLayer:SetState("Hover", true)
		end
	end))
	self._maid:GiveTask(hitbox.MouseLeave:Connect(function()
		self._stateLayer:SetState("Hover", false)
		self._stateLayer:SetState("Pressed", false)
	end))
	self._maid:GiveTask(hitbox.InputBegan:Connect(function(input)
		if not self._disabled and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
			self._stateLayer:SetState("Pressed", true)
		end
	end))
	self._maid:GiveTask(hitbox.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", false)
		end
	end))
	self._maid:GiveTask(hitbox.Activated:Connect(function()
		if not self._disabled then
			self:SetValue(not (self._value == true))
		end
	end))
end

function Checkbox:SetValue(value, silent: boolean?)
	self._value = value
	self:_render(true)
	if not silent then
		self.Changed:Fire(value)
	end
end

function Checkbox:GetValue()
	return self._value
end

function Checkbox:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self.Instance.Active = not disabled
	self:_render(true)
end

function Checkbox:SetTheme(theme)
	self._theme = theme
	self:_render(true)
end

function Checkbox:Destroy()
	self._stateLayer:Destroy()
	self._maid:Destroy()
	self.Changed:DisconnectAll()
	self.Instance:Destroy()
end

return Checkbox
end

-- Components/Chip.lua
loaders[newNode("Chip", N_Components)] = function(script, require)
--[[
	Material 3 Chip. Variants: "Assist", "Filter", "Input", "Suggestion".
	Filter chips toggle Selected on click. Input chips can show a remove (x)
	affordance by passing Removable = true.

	local chip = MD3.Chip.new({ Text = "Extra cheese", Variant = "Filter", Parent = row })
	chip.Toggled:Connect(function(selected) ... end)
	chip.Removed:Connect(function() ... end)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Ripple = require(Root.Core.Ripple)
local Icons = require(Root.Core.Icons)
local Assets = require(Root.Executor.Assets)

local Chip = {}
Chip.__index = Chip

local HEIGHT = 32

function Chip.new(props)
	props = props or {}
	local self = setmetatable({}, Chip)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._variant = props.Variant or "Assist"
	self._selected = props.Selected or false
	self._disabled = props.Disabled or false
	self.Activated = Signal.new()
	self.Toggled = Signal.new()
	self.Removed = Signal.new()

	local chip = Create("TextButton") {
		Name = props.Name or "MD3Chip",
		AutoButtonColor = false,
		Text = "",
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.new(0, 0, 0, HEIGHT),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		LayoutOrder = props.LayoutOrder or 0,
	}
	Shape.Corner(Shape.Small, chip)

	local stroke = Create("UIStroke") {
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = chip,
	}
	self._stroke = stroke

	-- Padding + layout live on an inner frame: the state layer and ripples
	-- are parented to the chip itself and must not be laid out.
	local content = Create("Frame") {
		Name = "Content",
		BackgroundTransparency = 1,
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		Parent = chip,
	}
	Create("UIPadding") {
		PaddingLeft = UDim.new(0, 12),
		PaddingRight = UDim.new(0, 12),
		Parent = content,
	}
	Create("UIListLayout") {
		SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 8),
		Parent = content,
	}

	local leadingIcon = nil
	if props.Icon then
		leadingIcon = Create("ImageLabel") {
			Name = "LeadingIcon",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(18, 18),
			Image = Assets.Resolve(props.Icon),
			LayoutOrder = 1,
			Parent = content,
		}
	end
	self._leadingIcon = leadingIcon

	local label = Create("TextLabel") {
		Name = "Label",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.new(0, 0, 1, 0),
		Text = props.Text or "",
		LayoutOrder = 2,
		Parent = content,
	}
	Typography.Apply(label, "LabelLarge")
	self._label = label

	local removeButton = nil
	if props.Removable then
		removeButton = Create("TextButton") {
			Name = "Remove",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(18, 18),
			TextScaled = true,
			LayoutOrder = 3,
			Parent = content,
		}
		Icons.Apply(removeButton, "close")
	end
	self._removeButton = removeButton

	self.Instance = chip
	self._stateLayer = StateLayer.new(chip, Color3.new(1, 1, 1), Shape.Small)

	self:_applyTheme()
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if props.Parent then
		chip.Parent = props.Parent
	end

	return self
end

function Chip:_applyTheme()
	local c = self._theme.Colors
	local selected = self._selected and self._variant == "Filter"

	local container = selected and c.SecondaryContainer or c.Surface
	local containerTransparency = selected and 0 or 1
	local onColor = selected and c.OnSecondaryContainer or c.OnSurfaceVariant
	local borderColor = selected and container or c.Outline

	if self._disabled then
		container, onColor, borderColor = c.OnSurface, c.OnSurface, c.OnSurface
		containerTransparency = selected and 0.88 or 1
	end

	TweenService:Create(self.Instance, Motion.Standard(Motion.Duration.Short2), {
		BackgroundColor3 = container,
		BackgroundTransparency = containerTransparency,
	}):Play()

	self._label.TextColor3 = onColor
	self._label.TextTransparency = self._disabled and 0.62 or 0
	self._stroke.Color = borderColor
	self._stroke.Transparency = self._disabled and 0.88 or (selected and 1 or 0)

	if self._leadingIcon then
		self._leadingIcon.ImageColor3 = onColor
		self._leadingIcon.ImageTransparency = self._disabled and 0.62 or 0
	end
	if self._removeButton then
		Icons.Apply(self._removeButton, "close")
		self._removeButton.TextColor3 = onColor
		self._removeButton.TextTransparency = self._disabled and 0.62 or 0
	end

	self._stateLayer:SetColor(onColor)
end

function Chip:_bindInput()
	local chip = self.Instance
	self._maid:GiveTask(chip.MouseEnter:Connect(function()
		if not self._disabled then
			self._stateLayer:SetState("Hover", true)
		end
	end))
	self._maid:GiveTask(chip.MouseLeave:Connect(function()
		self._stateLayer:SetState("Hover", false)
		self._stateLayer:SetState("Pressed", false)
	end))
	self._maid:GiveTask(chip.InputBegan:Connect(function(input)
		if not self._disabled and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
			self._stateLayer:SetState("Pressed", true)
			Ripple.Emit(chip, input.Position, self._theme.Colors.OnSurfaceVariant)
		end
	end))
	self._maid:GiveTask(chip.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", false)
		end
	end))
	self._maid:GiveTask(chip.Activated:Connect(function()
		if self._disabled then
			return
		end
		if self._variant == "Filter" then
			self._selected = not self._selected
			self:_applyTheme()
			self.Toggled:Fire(self._selected)
		end
		self.Activated:Fire()
	end))

	if self._removeButton then
		self._maid:GiveTask(self._removeButton.Activated:Connect(function()
			if not self._disabled then
				self.Removed:Fire()
			end
		end))
	end
end

function Chip:SetSelected(selected: boolean)
	self._selected = selected
	self:_applyTheme()
end

function Chip:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self.Instance.Active = not disabled
	self:_applyTheme()
end

function Chip:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function Chip:Destroy()
	self._stateLayer:Destroy()
	self._maid:Destroy()
	self.Activated:DisconnectAll()
	self.Toggled:DisconnectAll()
	self.Removed:DisconnectAll()
	self.Instance:Destroy()
end

return Chip
end

