-- Components/FAB.lua
loaders[newNode("FAB", N_Components)] = function(script, require)
--[[
	Material 3 Floating Action Button. Sizes: "Small" (40), "Standard" (56), "Large" (96).
	Set Extended = true + Text to get the pill-shaped extended FAB with a label.

	MD3.FAB.new({ Icon = "rbxassetid://...", Size = "Standard", Parent = screen })
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Ripple = require(Root.Core.Ripple)
local Elevation = require(Root.Core.Elevation)
local Assets = require(Root.Executor.Assets)

local FAB = {}
FAB.__index = FAB

local SIZES = { Small = 40, Standard = 56, Large = 96 }
local ICON_SIZES = { Small = 24, Standard = 24, Large = 36 }
local RADII = { Small = UDim.new(0, 12), Standard = UDim.new(0, 16), Large = UDim.new(0, 28) }

function FAB.new(props)
	props = props or {}
	local self = setmetatable({}, FAB)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._size = props.Size or "Standard"
	self._color = props.Color or "PrimaryContainer" -- or "Surface" / "Secondary" / "Tertiary"
	self._extended = props.Extended or false
	self.Activated = Signal.new()

	local dim = SIZES[self._size]
	local radius = RADII[self._size]

	local button = Create("TextButton") {
		Name = props.Name or "MD3FAB",
		AutoButtonColor = false,
		Text = "",
		AutomaticSize = self._extended and Enum.AutomaticSize.X or Enum.AutomaticSize.None,
		Size = self._extended and UDim2.new(0, 0, 0, dim) or UDim2.fromOffset(dim, dim),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		LayoutOrder = props.LayoutOrder or 0,
	}
	Shape.Corner(radius, button)

	-- Padding + layout live on an inner frame: the state layer and ripples
	-- are parented to the button itself and must not be laid out.
	local content = Create("Frame") {
		Name = "Content",
		BackgroundTransparency = 1,
		Size = self._extended and UDim2.new(0, 0, 1, 0) or UDim2.fromScale(1, 1),
		AutomaticSize = self._extended and Enum.AutomaticSize.X or Enum.AutomaticSize.None,
		Parent = button,
	}

	Create("UIListLayout") {
		SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 12),
		Parent = content,
	}

	if self._extended then
		Create("UIPadding") {
			PaddingLeft = UDim.new(0, 16),
			PaddingRight = UDim.new(0, 20),
			Parent = content,
		}
	end

	local icon = Create("ImageLabel") {
		Name = "Icon",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(ICON_SIZES[self._size], ICON_SIZES[self._size]),
		Image = Assets.Resolve(props.Icon),
		LayoutOrder = 1,
		Parent = content,
	}
	self._icon = icon

	local label = nil
	if self._extended then
		label = Create("TextLabel") {
			Name = "Label",
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.new(0, 0, 1, 0),
			Text = props.Text or "",
			LayoutOrder = 2,
			Parent = content,
		}
		Typography.Apply(label, "LabelLarge")
	end
	self._label = label

	self.Instance = button
	self._stateLayer = StateLayer.new(button, Color3.new(1, 1, 1), radius)

	self:_applyTheme()
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if props.Parent then
		button.Parent = props.Parent
	end

	return self
end

function FAB:_applyTheme()
	local c = self._theme.Colors
	local container = c[self._color] or c.PrimaryContainer
	local onContainerKey = "On" .. self._color
	local onContainer = c[onContainerKey] or c.OnPrimaryContainer

	TweenService:Create(self.Instance, Motion.Standard(Motion.Duration.Short2), {
		BackgroundColor3 = container,
	}):Play()
	self._icon.ImageColor3 = onContainer
	if self._label then
		self._label.TextColor3 = onContainer
	end
	self._stateLayer:SetColor(onContainer)
	Elevation.Apply(self.Instance, 3, c.Shadow, RADII[self._size])
end

function FAB:_bindInput()
	local button = self.Instance
	self._maid:GiveTask(button.MouseEnter:Connect(function()
		self._stateLayer:SetState("Hover", true)
		Elevation.Apply(button, 4, self._theme.Colors.Shadow, RADII[self._size])
	end))
	self._maid:GiveTask(button.MouseLeave:Connect(function()
		self._stateLayer:SetState("Hover", false)
		self._stateLayer:SetState("Pressed", false)
		Elevation.Apply(button, 3, self._theme.Colors.Shadow, RADII[self._size])
	end))
	self._maid:GiveTask(button.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", true)
			local onContainer = self._theme.Colors["On" .. self._color] or self._theme.Colors.OnPrimaryContainer
			Ripple.Emit(button, input.Position, onContainer)
		end
	end))
	self._maid:GiveTask(button.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", false)
		end
	end))
	self._maid:GiveTask(button.Activated:Connect(function(...)
		self.Activated:Fire(...)
	end))
end

function FAB:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function FAB:Destroy()
	Elevation.Remove(self.Instance)
	self._stateLayer:Destroy()
	self._maid:Destroy()
	self.Activated:DisconnectAll()
	self.Instance:Destroy()
end

return FAB
end

-- Components/IconButton.lua
loaders[newNode("IconButton", N_Components)] = function(script, require)
--[[
	Material 3 Icon Button. Variants: "Standard", "Filled", "Tonal", "Outlined".
	Optionally toggleable: pass Toggleable = true, then use :SetSelected()/:GetSelected()
	and listen to .Toggled(selected).

	MD3.IconButton.new({ Icon = "rbxassetid://...", Variant = "Standard", Parent = bar })
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Ripple = require(Root.Core.Ripple)
local Assets = require(Root.Executor.Assets)

local IconButton = {}
IconButton.__index = IconButton

local SIZE = 40

local function colorsFor(theme, variant, selected, disabled)
	local c = theme.Colors
	if disabled then
		return { container = c.OnSurface, containerTransparency = variant == "Standard" and 1 or 0.88, icon = c.OnSurface, iconTransparency = 0.62, border = variant == "Outlined" and c.OnSurface or nil, borderTransparency = 0.88 }
	end

	if selected then
		return { container = c.Primary, containerTransparency = 0, icon = c.OnPrimary, iconTransparency = 0 }
	end

	if variant == "Filled" then
		return { container = c.SurfaceContainerHighest, containerTransparency = 0, icon = c.Primary, iconTransparency = 0 }
	elseif variant == "Tonal" then
		return { container = c.SecondaryContainer, containerTransparency = 0, icon = c.OnSecondaryContainer, iconTransparency = 0 }
	elseif variant == "Outlined" then
		return { container = c.Surface, containerTransparency = 1, icon = c.OnSurfaceVariant, iconTransparency = 0, border = c.Outline, borderTransparency = 0 }
	end
	return { container = c.Surface, containerTransparency = 1, icon = c.OnSurfaceVariant, iconTransparency = 0 }
end

function IconButton.new(props)
	props = props or {}
	local self = setmetatable({}, IconButton)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._variant = props.Variant or "Standard"
	self._disabled = props.Disabled or false
	self._selected = props.Selected or false
	self._toggleable = props.Toggleable or false
	self.Activated = Signal.new()
	self.Toggled = Signal.new()

	local button = Create("TextButton") {
		Name = props.Name or "MD3IconButton",
		AutoButtonColor = false,
		Text = "",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Size = props.Size or UDim2.fromOffset(SIZE, SIZE),
		LayoutOrder = props.LayoutOrder or 0,
	}
	Shape.Corner(Shape.Full, button)

	local stroke = Create("UIStroke") {
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = button,
	}
	self._stroke = stroke

	local icon = Create("ImageLabel") {
		Name = "Icon",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(24, 24),
		Image = Assets.Resolve(props.Icon),
		Parent = button,
	}
	self._icon = icon

	self.Instance = button
	self._stateLayer = StateLayer.new(button, Color3.new(1, 1, 1), Shape.Full)

	self:_applyTheme()
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if props.Parent then
		button.Parent = props.Parent
	end

	return self
end

function IconButton:_applyTheme()
	local colors = colorsFor(self._theme, self._variant, self._selected, self._disabled)
	local tweenInfo = Motion.Standard(Motion.Duration.Short2)

	TweenService:Create(self.Instance, tweenInfo, {
		BackgroundColor3 = colors.container,
		BackgroundTransparency = colors.containerTransparency,
	}):Play()
	TweenService:Create(self._icon, tweenInfo, {
		ImageColor3 = colors.icon,
		ImageTransparency = colors.iconTransparency,
	}):Play()

	self._stroke.Color = colors.border or colors.icon
	self._stroke.Transparency = colors.border and (colors.borderTransparency or 0) or 1
	self._stateLayer:SetColor(colors.icon)
end

function IconButton:_bindInput()
	local button = self.Instance

	self._maid:GiveTask(button.MouseEnter:Connect(function()
		if not self._disabled then
			self._stateLayer:SetState("Hover", true)
		end
	end))
	self._maid:GiveTask(button.MouseLeave:Connect(function()
		self._stateLayer:SetState("Hover", false)
		self._stateLayer:SetState("Pressed", false)
	end))
	self._maid:GiveTask(button.InputBegan:Connect(function(input)
		if self._disabled then
			return
		end
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", true)
			Ripple.Emit(button, input.Position, colorsFor(self._theme, self._variant, self._selected, false).icon)
		end
	end))
	self._maid:GiveTask(button.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", false)
		end
	end))
	self._maid:GiveTask(button.Activated:Connect(function(...)
		if self._disabled then
			return
		end
		if self._toggleable then
			self:SetSelected(not self._selected)
		end
		self.Activated:Fire(...)
	end))
end

function IconButton:SetSelected(selected: boolean)
	self._selected = selected
	self:_applyTheme()
	self.Toggled:Fire(selected)
end

function IconButton:GetSelected(): boolean
	return self._selected
end

function IconButton:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self.Instance.Active = not disabled
	self:_applyTheme()
end

function IconButton:SetIcon(image: string)
	self._icon.Image = Assets.Resolve(image)
end

function IconButton:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function IconButton:Destroy()
	self._stateLayer:Destroy()
	self._maid:Destroy()
	self.Activated:DisconnectAll()
	self.Toggled:DisconnectAll()
	self.Instance:Destroy()
end

return IconButton
end

-- Components/NavigationBar.lua
loaders[newNode("NavigationBar", N_Components)] = function(script, require)
--[[
	Material 3 Navigation Bar (bottom bar with 3-5 destinations).

	local nav = MD3.NavigationBar.new({
		Destinations = {
			{ Icon = "rbxassetid://...", Label = "Home" },
			{ Icon = "rbxassetid://...", Label = "Search" },
			{ Icon = "rbxassetid://...", Label = "Profile" },
		},
		Selected = 1,
		Parent = screen,
	})
	nav.Changed:Connect(function(index) ... end)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Assets = require(Root.Executor.Assets)

local NavigationBar = {}
NavigationBar.__index = NavigationBar

local HEIGHT = 80
local INDICATOR_SIZE = UDim2.fromOffset(64, 32)

function NavigationBar.new(props)
	props = props or {}
	local self = setmetatable({}, NavigationBar)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._items = {}
	self._selected = props.Selected or 1
	self.Changed = Signal.new()

	local root = Create("Frame") {
		Name = props.Name or "MD3NavigationBar",
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, HEIGHT),
		LayoutOrder = props.LayoutOrder or 0,
	}
	Create("UIListLayout") {
		SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Parent = root,
	}

	for i, dest in ipairs(props.Destinations or {}) do
		local item = Create("TextButton") {
			Name = "Item" .. i,
			AutoButtonColor = false,
			Text = "",
			BackgroundTransparency = 1,
			Size = UDim2.new(1 / math.max(#props.Destinations, 1), 0, 1, 0),
			LayoutOrder = i,
			Parent = root,
		}

		local content = Create("Frame") {
			Name = "Content",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(0, 64, 0, 0),
			Parent = item,
		}
		Create("UIListLayout") {
			SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
			FillDirection = Enum.FillDirection.Vertical,
			HorizontalAlignment = Enum.HorizontalAlignment.Center,
			Padding = UDim.new(0, 4),
			Parent = content,
		}

		local indicator = Create("Frame") {
			Name = "Indicator",
			Size = INDICATOR_SIZE,
			BorderSizePixel = 0,
			LayoutOrder = 0,
			Parent = content,
		}
		Shape.Corner(Shape.Full, indicator)
		local stateLayer = StateLayer.new(indicator, Color3.new(1, 1, 1), Shape.Full)

		local icon = Create("ImageLabel") {
			Name = "Icon",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(24, 24),
			Image = Assets.Resolve(dest.Icon),
			Parent = indicator,
		}

		local label = Create("TextLabel") {
			Name = "Label",
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.new(0, 0, 0, 16),
			Text = dest.Label or "",
			LayoutOrder = 1,
			Parent = content,
		}
		Typography.Apply(label, "LabelMedium")

		local entry = { button = item, indicator = indicator, icon = icon, label = label, stateLayer = stateLayer }
		table.insert(self._items, entry)

		self._maid:GiveTask(item.MouseEnter:Connect(function()
			stateLayer:SetState("Hover", true)
		end))
		self._maid:GiveTask(item.MouseLeave:Connect(function()
			stateLayer:SetState("Hover", false)
			stateLayer:SetState("Pressed", false)
		end))
		self._maid:GiveTask(item.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				stateLayer:SetState("Pressed", true)
			end
		end))
		self._maid:GiveTask(item.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				stateLayer:SetState("Pressed", false)
			end
		end))
		self._maid:GiveTask(item.Activated:Connect(function()
			self:SetSelected(i)
		end))
	end

	self.Instance = root

	self:_render(false)
	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_render(true)
	end))

	if props.Parent then
		root.Parent = props.Parent
	end

	return self
end

function NavigationBar:_render(animate: boolean)
	local c = self._theme.Colors
	self.Instance.BackgroundColor3 = c.SurfaceContainer

	for i, entry in ipairs(self._items) do
		local selected = i == self._selected
		local indicatorColor = selected and c.SecondaryContainer or c.SurfaceContainer
		local indicatorTransparency = selected and 0 or 1
		local iconColor = selected and c.OnSecondaryContainer or c.OnSurfaceVariant
		local labelColor = selected and c.OnSurface or c.OnSurfaceVariant

		local apply = animate and function(inst, p) TweenService:Create(inst, Motion.Standard(Motion.Duration.Short2), p):Play() end
			or function(inst, p) for k, v in pairs(p) do inst[k] = v end end

		apply(entry.indicator, { BackgroundColor3 = indicatorColor, BackgroundTransparency = indicatorTransparency })
		apply(entry.icon, { ImageColor3 = iconColor })
		apply(entry.label, { TextColor3 = labelColor })
		entry.stateLayer:SetColor(c.OnSurface)
	end
end

function NavigationBar:SetSelected(index: number)
	if self._selected == index then
		return
	end
	self._selected = index
	self:_render(true)
	self.Changed:Fire(index)
end

function NavigationBar:GetSelected(): number
	return self._selected
end

function NavigationBar:SetTheme(theme)
	self._theme = theme
	self:_render(true)
end

function NavigationBar:Destroy()
	for _, entry in self._items do
		entry.stateLayer:Destroy()
	end
	self._maid:Destroy()
	self.Changed:DisconnectAll()
	self.Instance:Destroy()
end

return NavigationBar
end

-- Components/ProgressIndicator.lua
loaders[newNode("ProgressIndicator", N_Components)] = function(script, require)
--[[
	Material 3 Progress Indicators.

	MD3.ProgressIndicator.Linear({ Value = 0.4, Parent = frame })            -- determinate
	MD3.ProgressIndicator.Linear({ Indeterminate = true, Parent = frame })
	MD3.ProgressIndicator.Circular({ Value = 0.4, Parent = frame })          -- determinate
	MD3.ProgressIndicator.Circular({ Indeterminate = true, Parent = frame })
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Theme = require(Root.Core.Theme)
local Shape = require(Root.Core.Shape)

local ProgressIndicator = {}

--============================== Linear ==============================--

local Linear = {}
Linear.__index = Linear

function ProgressIndicator.Linear(props)
	props = props or {}
	local self = setmetatable({}, Linear)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._value = math.clamp(props.Value or 0, 0, 1)
	self._indeterminate = props.Indeterminate or false

	local track = Create("Frame") {
		Name = props.Name or "MD3LinearProgress",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Size = props.Size or UDim2.new(1, 0, 0, 4),
		LayoutOrder = props.LayoutOrder or 0,
	}
	Shape.Corner(Shape.Full, track)

	local bar = Create("Frame") {
		Name = "Bar",
		BorderSizePixel = 0,
		Size = UDim2.new(self._indeterminate and 0.3 or self._value, 0, 1, 0),
		Parent = track,
	}
	Shape.Corner(Shape.Full, bar)

	self.Instance = track
	self._bar = bar

	self:_applyTheme()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if self._indeterminate then
		self:_startIndeterminate()
	end

	if props.Parent then
		track.Parent = props.Parent
	end

	return self
end

function Linear:_applyTheme()
	self.Instance.BackgroundColor3 = self._theme.Colors.SecondaryContainer
	self._bar.BackgroundColor3 = self._theme.Colors.Primary
end

function Linear:_startIndeterminate()
	task.spawn(function()
		while self._indeterminate and self.Instance.Parent do
			local tween = TweenService:Create(self._bar, TweenInfo.new(1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
				Position = UDim2.new(0.85, 0, 0, 0),
			})
			self._bar.Position = UDim2.new(-0.3, 0, 0, 0)
			tween:Play()
			tween.Completed:Wait()
		end
	end)
end

function Linear:SetValue(value: number)
	self._indeterminate = false
	self._value = math.clamp(value, 0, 1)
	TweenService:Create(self._bar, TweenInfo.new(0.2, Enum.EasingStyle.Quad), {
		Size = UDim2.new(self._value, 0, 1, 0),
	}):Play()
end

function Linear:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function Linear:Destroy()
	self._indeterminate = false
	self._maid:Destroy()
	self.Instance:Destroy()
end

--============================== Circular ==============================--

local Circular = {}
Circular.__index = Circular

local EPS = 0.004

local function arcSequence(value: number)
	if value <= 0 then
		return NumberSequence.new(1)
	elseif value >= 1 then
		return NumberSequence.new(0)
	end
	-- Keypoint times must be strictly increasing, so keep value-EPS above 0.
	value = math.clamp(value, 2 * EPS, 1 - EPS)
	return NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(value - EPS, 0),
		NumberSequenceKeypoint.new(value, 1),
		NumberSequenceKeypoint.new(1, 1),
	})
end

function ProgressIndicator.Circular(props)
	props = props or {}
	local self = setmetatable({}, Circular)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._value = math.clamp(props.Value or 0.25, 0, 1)
	self._indeterminate = props.Indeterminate or false
	local diameter = props.Diameter or 40

	local root = Create("Frame") {
		Name = props.Name or "MD3CircularProgress",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(diameter, diameter),
		LayoutOrder = props.LayoutOrder or 0,
	}

	local track = Create("Frame") {
		Name = "Track",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Parent = root,
	}
	Shape.Corner(Shape.Full, track)
	local trackStroke = Create("UIStroke") {
		Thickness = props.Thickness or 4,
		Parent = track,
	}
	self._trackStroke = trackStroke

	local active = Create("Frame") {
		Name = "Active",
		BackgroundTransparency = 1,
		Rotation = -90,
		Size = UDim2.fromScale(1, 1),
		Parent = root,
	}
	Shape.Corner(Shape.Full, active)
	local activeStroke = Create("UIStroke") {
		Thickness = props.Thickness or 4,
		Parent = active,
	}
	local gradient = Create("UIGradient") {
		Transparency = arcSequence(self._value),
		Parent = activeStroke,
	}
	self._activeFrame = active
	self._activeStroke = activeStroke
	self._gradient = gradient

	self.Instance = root

	self:_applyTheme()
	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if self._indeterminate then
		self:_startIndeterminate()
	end

	if props.Parent then
		root.Parent = props.Parent
	end

	return self
end

function Circular:_applyTheme()
	self._trackStroke.Color = self._theme.Colors.SecondaryContainer
	self._activeStroke.Color = self._theme.Colors.Primary
end

function Circular:_startIndeterminate()
	if not self._indeterminate then
		self._gradient.Transparency = arcSequence(0.28)
	end
	task.spawn(function()
		while self._indeterminate and self.Instance.Parent do
			local tween = TweenService:Create(self._activeFrame, TweenInfo.new(1.1, Enum.EasingStyle.Linear), {
				Rotation = self._activeFrame.Rotation + 360,
			})
			tween:Play()
			tween.Completed:Wait()
		end
	end)
end

function Circular:SetValue(value: number)
	self._indeterminate = false
	self._value = math.clamp(value, 0, 1)
	self._gradient.Transparency = arcSequence(self._value)
end

function Circular:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function Circular:Destroy()
	self._indeterminate = false
	self._maid:Destroy()
	self.Instance:Destroy()
end

return ProgressIndicator
end

-- Components/RadioButton.lua
loaders[newNode("RadioButton", N_Components)] = function(script, require)
--[[
	Material 3 Radio Button. Typically used in a RadioGroup so only one is
	selected at a time ??see RadioButton.Group() below.

	local group = MD3.RadioButton.Group({ "a", "b", "c" }, "a", parentFrame)
	group.Changed:Connect(function(value) ... end)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)

local RadioButton = {}
RadioButton.__index = RadioButton

local RING_SIZE = 20
local DOT_SIZE = 10
local HITBOX_SIZE = 40

function RadioButton.new(props)
	props = props or {}
	local self = setmetatable({}, RadioButton)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._selected = props.Selected or false
	self._disabled = props.Disabled or false
	self.Activated = Signal.new()

	local hitbox = Create("TextButton") {
		Name = props.Name or "MD3Radio",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(HITBOX_SIZE, HITBOX_SIZE),
		LayoutOrder = props.LayoutOrder or 0,
	}
	Shape.Corner(Shape.Full, hitbox)

	local ring = Create("Frame") {
		Name = "Ring",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(RING_SIZE, RING_SIZE),
		BackgroundTransparency = 1,
		Parent = hitbox,
	}
	Shape.Corner(Shape.Full, ring)

	local stroke = Create("UIStroke") {
		Thickness = 2,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = ring,
	}
	self._stroke = stroke

	local dot = Create("Frame") {
		Name = "Dot",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(0, 0),
		BorderSizePixel = 0,
		Parent = ring,
	}
	Shape.Corner(Shape.Full, dot)
	self._dot = dot

	self.Instance = hitbox
	self._stateLayer = StateLayer.new(hitbox, Color3.new(1, 1, 1), Shape.Full)

	self:_render(false)
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_render(true)
	end))

	if props.Parent then
		hitbox.Parent = props.Parent
	end

	return self
end

function RadioButton:_render(animate: boolean)
	local c = self._theme.Colors
	local ringColor = self._selected and (self._disabled and c.OnSurface or c.Primary) or (self._disabled and c.OnSurface or c.OnSurfaceVariant)
	local dotColor = ringColor
	local dotSize = self._selected and DOT_SIZE or 0

	self._stroke.Color = ringColor
	self._stroke.Transparency = self._disabled and 0.62 or 0

	if animate then
		TweenService:Create(self._dot, Motion.Standard(Motion.Duration.Short2), {
			Size = UDim2.fromOffset(dotSize, dotSize),
			BackgroundColor3 = dotColor,
			BackgroundTransparency = self._disabled and 0.62 or 0,
		}):Play()
	else
		self._dot.Size = UDim2.fromOffset(dotSize, dotSize)
		self._dot.BackgroundColor3 = dotColor
		self._dot.BackgroundTransparency = self._disabled and 0.62 or 0
	end

	self._stateLayer:SetColor(self._selected and c.Primary or c.OnSurface)
end

function RadioButton:_bindInput()
	local hitbox = self.Instance
	self._maid:GiveTask(hitbox.MouseEnter:Connect(function()
		if not self._disabled then
			self._stateLayer:SetState("Hover", true)
		end
	end))
	self._maid:GiveTask(hitbox.MouseLeave:Connect(function()
		self._stateLayer:SetState("Hover", false)
		self._stateLayer:SetState("Pressed", false)
	end))
	self._maid:GiveTask(hitbox.InputBegan:Connect(function(input)
		if not self._disabled and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
			self._stateLayer:SetState("Pressed", true)
		end
	end))
	self._maid:GiveTask(hitbox.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self._stateLayer:SetState("Pressed", false)
		end
	end))
	self._maid:GiveTask(hitbox.Activated:Connect(function()
		if not self._disabled then
			self.Activated:Fire()
		end
	end))
end

function RadioButton:SetSelected(selected: boolean)
	self._selected = selected
	self:_render(true)
end

function RadioButton:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self.Instance.Active = not disabled
	self:_render(true)
end

function RadioButton:SetTheme(theme)
	self._theme = theme
	self:_render(true)
end

function RadioButton:Destroy()
	self._stateLayer:Destroy()
	self._maid:Destroy()
	self.Activated:DisconnectAll()
	self.Instance:Destroy()
end

-- Convenience: builds a set of radio buttons that behave as a mutually-
-- exclusive group. `options` is an array of { Value = any, Text = string? }.
function RadioButton.Group(options, initialValue, parent, theme)
	local group = {}
	group.Changed = Signal.new()
	group._buttons = {}
	group.Value = initialValue

	for index, option in ipairs(options) do
		local row = Create("Frame") {
			Name = "Option",
			LayoutOrder = index,
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(1, 0, 0, 0),
			Parent = parent,
			[1] = Create("UIListLayout") {
				SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
				FillDirection = Enum.FillDirection.Horizontal,
				VerticalAlignment = Enum.VerticalAlignment.Center,
				Padding = UDim.new(0, 4),
			},
		}

		local radio = RadioButton.new({
			Theme = theme,
			Selected = option.Value == initialValue,
			LayoutOrder = 1,
			Parent = row,
		})

		if option.Text then
			local Typography = require(Root.Core.Typography)
			local label = Create("TextLabel") {
				Name = "Label",
				BackgroundTransparency = 1,
				AutomaticSize = Enum.AutomaticSize.X,
				Size = UDim2.new(0, 0, 1, 0),
				Text = option.Text,
				TextColor3 = (theme or Theme.Default()).Colors.OnSurface,
				LayoutOrder = 2,
				Parent = row,
			}
			Typography.Apply(label, "BodyLarge")
		end

		radio.Activated:Connect(function()
			group:SetValue(option.Value)
		end)

		table.insert(group._buttons, { radio = radio, value = option.Value, row = row })
	end

	function group:SetValue(value)
		if self.Value == value then
			return
		end
		self.Value = value
		for _, entry in self._buttons do
			entry.radio:SetSelected(entry.value == value)
		end
		self.Changed:Fire(value)
	end

	function group:Destroy()
		for _, entry in self._buttons do
			entry.radio:Destroy()
			entry.row:Destroy()
		end
		self.Changed:DisconnectAll()
	end

	return group
end

return RadioButton
end

-- Components/Slider.lua
loaders[newNode("Slider", N_Components)] = function(script, require)
--[[
	Material 3 Slider (continuous or stepped).

	local slider = MD3.Slider.new({ Min = 0, Max = 100, Value = 50, Step = 1, Parent = row })
	slider.Changed:Connect(function(value) ... end)
]]
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)

local Slider = {}
Slider.__index = Slider

local TRACK_HEIGHT = 16
local HANDLE_SIZE = 4
local HANDLE_HEIGHT = 44

function Slider.new(props)
	props = props or {}
	local self = setmetatable({}, Slider)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._min = props.Min or 0
	self._max = props.Max or 100
	self._step = props.Step
	self._value = math.clamp(props.Value or self._min, self._min, self._max)
	self._disabled = props.Disabled or false
	self._dragging = false
	self.Changed = Signal.new()

	local root = Create("Frame") {
		Name = props.Name or "MD3Slider",
		BackgroundTransparency = 1,
		Size = props.Size or UDim2.new(1, 0, 0, HANDLE_HEIGHT),
		LayoutOrder = props.LayoutOrder or 0,
	}

	-- Invisible full-width button so clicking/tapping anywhere on the track
	-- jumps there and starts a drag, not just on the handle.
	local trackHitArea = Create("TextButton") {
		Name = "TrackHitArea",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Parent = root,
	}
	self._trackHitArea = trackHitArea

	local inactiveTrack = Create("Frame") {
		Name = "InactiveTrack",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.new(1, 0, 0, TRACK_HEIGHT),
		BorderSizePixel = 0,
		Parent = root,
	}
	Shape.Corner(Shape.Full, inactiveTrack)
	self._inactiveTrack = inactiveTrack

	local activeTrack = Create("Frame") {
		Name = "ActiveTrack",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.new(0, 0, 0, TRACK_HEIGHT),
		BorderSizePixel = 0,
		ZIndex = 2,
		Parent = root,
	}
	Shape.Corner(Shape.Full, activeTrack)
	self._activeTrack = activeTrack

	local handleArea = Create("TextButton") {
		Name = "HandleArea",
		AutoButtonColor = false,
		Text = "",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.fromOffset(HANDLE_HEIGHT, HANDLE_HEIGHT),
		BackgroundTransparency = 1,
		ZIndex = 3,
		Parent = root,
	}
	self._handleArea = handleArea

	local handle = Create("Frame") {
		Name = "Handle",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(0, HANDLE_SIZE, 0, TRACK_HEIGHT + 8),
		BorderSizePixel = 0,
		ZIndex = 4,
		Parent = handleArea,
	}
	Shape.Corner(Shape.Full, handle)
	self._handle = handle

	self.Instance = root

	self:_render(false)
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_render(true)
	end))
	self._maid:GiveTask(root:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		self:_render(false)
	end))

	if props.Parent then
		root.Parent = props.Parent
	end

	return self
end

function Slider:_alphaFor(value: number): number
	if self._max == self._min then
		return 0
	end
	return (value - self._min) / (self._max - self._min)
end

function Slider:_render(animate: boolean)
	local c = self._theme.Colors
	local alpha = self:_alphaFor(self._value)

	local trackColor = self._disabled and c.OnSurface or c.Primary
	local inactiveColor = self._disabled and c.OnSurface or c.SecondaryContainer

	self._inactiveTrack.BackgroundColor3 = inactiveColor
	self._inactiveTrack.BackgroundTransparency = self._disabled and 0.88 or 0
	self._handle.BackgroundColor3 = trackColor
	self._handle.BackgroundTransparency = self._disabled and 0.62 or 0
	self._activeTrack.BackgroundColor3 = trackColor
	self._activeTrack.BackgroundTransparency = self._disabled and 0.88 or 0

	local targetSize = UDim2.new(alpha, 0, 0, TRACK_HEIGHT)
	local targetHandlePos = UDim2.new(alpha, 0, 0.5, 0)

	if animate then
		local ti = Motion.Standard(Motion.Duration.Short2)
		TweenService:Create(self._activeTrack, ti, { Size = targetSize }):Play()
		TweenService:Create(self._handleArea, ti, { Position = targetHandlePos }):Play()
	else
		self._activeTrack.Size = targetSize
		self._handleArea.Position = targetHandlePos
	end
end

function Slider:_valueFromInputX(inputX: number): number
	local abs = self.Instance.AbsolutePosition.X
	local width = self.Instance.AbsoluteSize.X
	if width <= 0 then
		return self._value
	end
	local alpha = math.clamp((inputX - abs) / width, 0, 1)
	local value = self._min + alpha * (self._max - self._min)
	if self._step then
		value = math.round(value / self._step) * self._step
	end
	return math.clamp(value, self._min, self._max)
end

function Slider:_bindInput()
	local handleArea = self._handleArea

	local function beginDrag(input)
		if self._disabled then
			return
		end
		self._dragging = true
		self:SetValue(self:_valueFromInputX(input.Position.X))

		local moveConn, endConn
		moveConn = UserInputService.InputChanged:Connect(function(moveInput)
			if moveInput.UserInputType == Enum.UserInputType.MouseMovement or moveInput.UserInputType == Enum.UserInputType.Touch then
				if self._dragging then
					self:SetValue(self:_valueFromInputX(moveInput.Position.X))
				end
			end
		end)
		endConn = UserInputService.InputEnded:Connect(function(endInput)
			if endInput.UserInputType == Enum.UserInputType.MouseButton1 or endInput.UserInputType == Enum.UserInputType.Touch then
				self._dragging = false
				moveConn:Disconnect()
				endConn:Disconnect()
			end
		end)
	end

	for _, target in { handleArea, self._trackHitArea } do
		self._maid:GiveTask(target.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				beginDrag(input)
			end
		end))
	end
end

function Slider:SetValue(value: number, silent: boolean?)
	value = math.clamp(value, self._min, self._max)
	if value == self._value then
		return
	end
	self._value = value
	self:_render(true)
	if not silent then
		self.Changed:Fire(value)
	end
end

function Slider:GetValue(): number
	return self._value
end

function Slider:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self._handleArea.Active = not disabled
	self._trackHitArea.Active = not disabled
	self:_render(true)
end

function Slider:SetTheme(theme)
	self._theme = theme
	self:_render(true)
end

function Slider:Destroy()
	self._maid:Destroy()
	self.Changed:DisconnectAll()
	self.Instance:Destroy()
end

return Slider
end

-- Components/Snackbar.lua
loaders[newNode("Snackbar", N_Components)] = function(script, require)
--[[
	Material 3 Snackbar: transient bottom message with an optional action.

	local snackbar = MD3.Snackbar.new({ Parent = screenGui })
	snackbar:Show("Message sent", { Text = "Undo", OnActivated = function() end }, 4)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Theme = require(Root.Core.Theme)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local Elevation = require(Root.Core.Elevation)
local Button = require(Root.Components.Button)

local Snackbar = {}
Snackbar.__index = Snackbar

function Snackbar.new(props)
	props = props or {}
	local self = setmetatable({}, Snackbar)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._hideToken = 0

	local root = Create("Frame") {
		Name = props.Name or "MD3Snackbar",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, 24),
		AutomaticSize = Enum.AutomaticSize.XY,
		BorderSizePixel = 0,
		Visible = false,
		ZIndex = props.ZIndex or 100,
	}
	Shape.Corner(Shape.ExtraSmall, root)
	Create("UIPadding") {
		PaddingTop = UDim.new(0, 14),
		PaddingBottom = UDim.new(0, 14),
		PaddingLeft = UDim.new(0, 16),
		PaddingRight = UDim.new(0, 8),
		Parent = root,
	}
	Create("UIListLayout") {
		SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
		FillDirection = Enum.FillDirection.Horizontal,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 8),
		Parent = root,
	}

	local label = Create("TextLabel") {
		Name = "Label",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.new(0, 0, 0, 20),
		Text = "",
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = root.ZIndex,
		LayoutOrder = 1,
		Parent = root,
	}
	Typography.Apply(label, "BodyMedium")
	self._label = label
	self._actionButton = nil

	self.Instance = root

	self:_applyTheme()
	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if props.Parent then
		root.Parent = props.Parent
	end

	return self
end

function Snackbar:_applyTheme()
	local c = self._theme.Colors
	self.Instance.BackgroundColor3 = c.InverseSurface
	self._label.TextColor3 = c.InverseOnSurface
	Elevation.Apply(self.Instance, 3, c.Shadow, Shape.ExtraSmall)
	if self._actionButton then
		self._actionButton:SetVariant("Text")
	end
end

function Snackbar:Show(message: string, action, duration: number?)
	self._hideToken += 1
	local token = self._hideToken

	self._label.Text = message

	if self._actionButton then
		self._actionButton:Destroy()
		self._actionButton = nil
	end
	if action then
		self._actionButton = Button.new({
			Text = action.Text,
			Variant = "Text",
			Theme = self._theme,
			LayoutOrder = 2,
			Parent = self.Instance,
		})
		self._actionButton.Instance.ZIndex = self.Instance.ZIndex
		-- Snackbar action buttons use the inverse-primary color on the inverse surface.
		self._actionButton._label.TextColor3 = self._theme.Colors.InversePrimary
		if action.OnActivated then
			self._actionButton.Activated:Connect(action.OnActivated)
		end
	end

	local root = self.Instance
	root.Visible = true
	root.Position = UDim2.new(0.5, 0, 1, 24)
	TweenService:Create(root, Motion.Emphasized(Motion.Duration.Medium2), {
		Position = UDim2.new(0.5, 0, 1, -24),
	}):Play()

	task.delay(duration or 4, function()
		if token == self._hideToken then
			self:Hide()
		end
	end)
end

function Snackbar:Hide()
	self._hideToken += 1
	local root = self.Instance
	local tween = TweenService:Create(root, Motion.Standard(Motion.Duration.Short3), {
		Position = UDim2.new(0.5, 0, 1, 24),
	})
	tween:Play()
	tween.Completed:Once(function()
		root.Visible = false
	end)
end

function Snackbar:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
	if self._actionButton then
		self._actionButton:SetTheme(theme)
	end
end

function Snackbar:Destroy()
	Elevation.Remove(self.Instance)
	self._maid:Destroy()
	if self._actionButton then
		self._actionButton:Destroy()
	end
	self.Instance:Destroy()
end

return Snackbar
end

-- Components/Switch.lua
loaders[newNode("Switch", N_Components)] = function(script, require)
--[[
	Material 3 Switch.

	local sw = MD3.Switch.new({ Value = false, Parent = row })
	sw.Changed:Connect(function(value) ... end)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local Assets = require(Root.Executor.Assets)

local Switch = {}
Switch.__index = Switch

local TRACK_SIZE = UDim2.fromOffset(52, 32)
local THUMB_OFF = 16
local THUMB_ON = 24
local THUMB_PRESSED = 28

function Switch.new(props)
	props = props or {}
	local self = setmetatable({}, Switch)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._value = props.Value or false
	self._disabled = props.Disabled or false
	self.Changed = Signal.new()

	local track = Create("TextButton") {
		Name = props.Name or "MD3Switch",
		AutoButtonColor = false,
		Text = "",
		Size = TRACK_SIZE,
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		LayoutOrder = props.LayoutOrder or 0,
	}
	Shape.Corner(Shape.Full, track)

	local stroke = Create("UIStroke") {
		Thickness = 2,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = track,
	}
	self._stroke = stroke

	local thumb = Create("Frame") {
		Name = "Thumb",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 6, 0.5, 0),
		Size = UDim2.fromOffset(THUMB_OFF, THUMB_OFF),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Parent = track,
	}
	Shape.Corner(Shape.Full, thumb)

	-- Optional checkmark glyph shown on the thumb when toggled on; pass your
	-- own icon asset via props.CheckedIcon, otherwise the switch stays iconless
	-- (a valid M3 switch style).
	local checkIcon = Create("ImageLabel") {
		Name = "Check",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(0.7, 0.7),
		Image = Assets.Resolve(props.CheckedIcon),
		ImageTransparency = 1,
		Parent = thumb,
	}
	self._checkIcon = checkIcon

	self.Instance = track
	self._thumb = thumb

	self:_render(false)
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_render(true)
	end))

	if props.Parent then
		track.Parent = props.Parent
	end

	return self
end

function Switch:_render(animate: boolean)
	local c = self._theme.Colors
	local trackColor, thumbColor, borderColor, thumbSize, thumbPos

	if self._value then
		trackColor = self._disabled and c.OnSurface or c.Primary
		thumbColor = self._disabled and c.Surface or c.OnPrimary
		borderColor = trackColor
		thumbSize = THUMB_ON
		thumbPos = UDim2.new(1, -6 - thumbSize, 0.5, 0)
	else
		trackColor = self._disabled and c.SurfaceContainerHighest or c.SurfaceContainerHighest
		thumbColor = self._disabled and c.OnSurface or c.Outline
		borderColor = self._disabled and c.OnSurface or c.Outline
		thumbSize = THUMB_OFF
		thumbPos = UDim2.new(0, 6, 0.5, 0)
	end

	local containerTransparency = self._disabled and 0.88 or 0
	local thumbTransparency = self._disabled and (self._value and 0.62 or 0.38) or 0

	if animate then
		local ti = Motion.Standard(Motion.Duration.Short3)
		TweenService:Create(self.Instance, ti, { BackgroundColor3 = trackColor, BackgroundTransparency = containerTransparency }):Play()
		TweenService:Create(self._thumb, ti, {
			BackgroundColor3 = thumbColor,
			BackgroundTransparency = thumbTransparency,
			Size = UDim2.fromOffset(thumbSize, thumbSize),
			Position = thumbPos,
		}):Play()
	else
		self.Instance.BackgroundColor3 = trackColor
		self.Instance.BackgroundTransparency = containerTransparency
		self._thumb.BackgroundColor3 = thumbColor
		self._thumb.BackgroundTransparency = thumbTransparency
		self._thumb.Size = UDim2.fromOffset(thumbSize, thumbSize)
		self._thumb.Position = thumbPos
	end

	self._stroke.Color = borderColor
	self._stroke.Transparency = self._value and 1 or (self._disabled and 0.88 or 0)
	self._checkIcon.ImageColor3 = c.OnPrimaryContainer
	self._checkIcon.ImageTransparency = self._value and 0 or 1
end

function Switch:_bindInput()
	local track = self.Instance
	self._maid:GiveTask(track.MouseEnter:Connect(function()
		if not self._disabled then
			TweenService:Create(self._thumb, Motion.Standard(Motion.Duration.Short2), {
				Size = UDim2.fromOffset(THUMB_PRESSED, THUMB_PRESSED),
			}):Play()
		end
	end))
	self._maid:GiveTask(track.MouseLeave:Connect(function()
		if not self._disabled then
			local size = self._value and THUMB_ON or THUMB_OFF
			TweenService:Create(self._thumb, Motion.Standard(Motion.Duration.Short2), {
				Size = UDim2.fromOffset(size, size),
			}):Play()
		end
	end))
	self._maid:GiveTask(track.Activated:Connect(function()
		if not self._disabled then
			self:SetValue(not self._value)
		end
	end))
end

function Switch:SetValue(value: boolean, silent: boolean?)
	if self._value == value then
		return
	end
	self._value = value
	self:_render(true)
	if not silent then
		self.Changed:Fire(value)
	end
end

function Switch:GetValue(): boolean
	return self._value
end

function Switch:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self.Instance.Active = not disabled
	self:_render(true)
end

function Switch:SetTheme(theme)
	self._theme = theme
	self:_render(true)
end

function Switch:Destroy()
	self._maid:Destroy()
	self.Changed:DisconnectAll()
	self.Instance:Destroy()
end

return Switch
end

-- Components/TextField.lua
loaders[newNode("TextField", N_Components)] = function(script, require)
--[[
	Material 3 Text Field. Variants: "Outlined" (default), "Filled".

	local field = MD3.TextField.new({ Label = "Email", Variant = "Outlined", Parent = form })
	field.Changed:Connect(function(text) ... end)
	field.Submitted:Connect(function(text) ... end)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)

local TextField = {}
TextField.__index = TextField

local HEIGHT = 56

function TextField.new(props)
	props = props or {}
	local self = setmetatable({}, TextField)
	self._maid = Maid.new()
	self._theme = props.Theme or Theme.Default()
	self._variant = props.Variant or "Outlined"
	self._disabled = props.Disabled or false
	self._error = props.Error or false
	self._focused = false
	self.Changed = Signal.new()
	self.Submitted = Signal.new()
	self.FocusChanged = Signal.new()

	local root = Create("Frame") {
		Name = props.Name or "MD3TextField",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = props.Size or UDim2.new(1, 0, 0, 0),
		LayoutOrder = props.LayoutOrder or 0,
	}
	Create("UIListLayout") {
		SortOrder = Enum.SortOrder.LayoutOrder, -- the default sorts by Name
		FillDirection = Enum.FillDirection.Vertical,
		Padding = UDim.new(0, 4),
		Parent = root,
	}

	local container = Create("Frame") {
		Name = "Container",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, HEIGHT),
		LayoutOrder = 1,
		Parent = root,
	}
	local isFilled = self._variant == "Filled"
	Shape.Corner(isFilled and Shape.ExtraSmall or Shape.ExtraSmall, container)
	self._container = container

	local stroke = Create("UIStroke") {
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = container,
	}
	self._stroke = stroke

	if isFilled then
		-- Filled variant gets a bottom "indicator" line instead of a full outline.
		stroke.Thickness = 0
		Create("Frame") {
			Name = "Indicator",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, 0, 1, 0),
			Size = UDim2.new(1, 0, 0, 1),
			BorderSizePixel = 0,
			Parent = container,
		}
		self._indicator = container.Indicator
	end

	Create("UIPadding") {
		PaddingLeft = UDim.new(0, 16),
		PaddingRight = UDim.new(0, 16),
		PaddingTop = UDim.new(0, isFilled and 8 or 0),
		Parent = container,
	}

	local label = Create("TextLabel") {
		Name = "Label",
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0, 0),
		Size = UDim2.new(1, 0, 0, 16),
		Text = props.Label or "",
		TextXAlignment = Enum.TextXAlignment.Left,
		Visible = isFilled,
		Parent = container,
	}
	Typography.Apply(label, "BodySmall")
	self._label = label

	local textBox = Create("TextBox") {
		Name = "Input",
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0, isFilled and 16 or 0),
		Size = UDim2.new(1, 0, 1, isFilled and -16 or 0),
		ClearTextOnFocus = false,
		Text = props.Text or "",
		PlaceholderText = isFilled and (props.Placeholder or "") or (props.Label or props.Placeholder or ""),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextWrapped = false,
		MultiLine = props.MultiLine or false,
		Parent = container,
	}
	Typography.Apply(textBox, "BodyLarge")
	self._textBox = textBox

	local supportingText = Create("TextLabel") {
		Name = "SupportingText",
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, -32, 0, 0),
		Position = UDim2.new(0, 16, 0, 0),
		Text = props.SupportingText or "",
		TextXAlignment = Enum.TextXAlignment.Left,
		TextWrapped = true,
		Visible = (props.SupportingText or "") ~= "" or self._error,
		LayoutOrder = 2,
		Parent = root,
	}
	Typography.Apply(supportingText, "BodySmall")
	self._supportingText = supportingText

	self.Instance = root

	self:_applyTheme()
	self:_bindInput()

	self._maid:GiveTask(self._theme.Changed:Connect(function()
		self:_applyTheme()
	end))

	if props.Parent then
		root.Parent = props.Parent
	end

	return self
end

function TextField:_applyTheme()
	local c = self._theme.Colors
	local isFilled = self._variant == "Filled"
	local accent = self._error and c.Error or c.Primary

	self._container.BackgroundColor3 = isFilled and c.SurfaceContainerHighest or c.Surface
	self._container.BackgroundTransparency = self._disabled and (isFilled and 0.88 or 1) or (isFilled and 0 or 1)

	self._textBox.TextColor3 = self._disabled and c.OnSurface or c.OnSurface
	self._textBox.TextTransparency = self._disabled and 0.62 or 0
	self._textBox.PlaceholderColor3 = self._disabled and c.OnSurface or c.OnSurfaceVariant

	self._label.TextColor3 = self._disabled and c.OnSurface or (self._focused and accent or c.OnSurfaceVariant)

	local ti = Motion.Standard(Motion.Duration.Short2)
	if isFilled then
		self._indicator.BackgroundColor3 = self._disabled and c.OnSurface or accent
		TweenService:Create(self._indicator, ti, {
			Size = UDim2.new(1, 0, 0, (self._focused or self._error) and 2 or 1),
		}):Play()
	else
		self._stroke.Color = self._disabled and c.OnSurface or accent
		self._stroke.Transparency = self._disabled and 0.62 or 0
		TweenService:Create(self._stroke, ti, {
			Thickness = self._focused and 2 or 1,
		}):Play()
	end

	self._supportingText.TextColor3 = self._error and c.Error or c.OnSurfaceVariant
	self._supportingText.Visible = self._supportingText.Text ~= ""
end

function TextField:_bindInput()
	local textBox = self._textBox

	self._maid:GiveTask(textBox:GetPropertyChangedSignal("Text"):Connect(function()
		self.Changed:Fire(textBox.Text)
	end))
	self._maid:GiveTask(textBox.Focused:Connect(function()
		self._focused = true
		self:_applyTheme()
		self.FocusChanged:Fire(true)
	end))
	self._maid:GiveTask(textBox.FocusLost:Connect(function(enterPressed)
		self._focused = false
		self:_applyTheme()
		self.FocusChanged:Fire(false)
		if enterPressed then
			self.Submitted:Fire(textBox.Text)
		end
	end))
end

function TextField:GetText(): string
	return self._textBox.Text
end

function TextField:SetText(text: string)
	self._textBox.Text = text
end

function TextField:SetError(isError: boolean, message: string?)
	self._error = isError
	if message ~= nil then
		self._supportingText.Text = message
	end
	self:_applyTheme()
end

function TextField:SetSupportingText(text: string)
	self._supportingText.Text = text
	self._supportingText.Visible = text ~= ""
end

function TextField:SetDisabled(disabled: boolean)
	self._disabled = disabled
	self._textBox.TextEditable = not disabled
	self:_applyTheme()
end

function TextField:SetTheme(theme)
	self._theme = theme
	self:_applyTheme()
end

function TextField:Destroy()
	self._maid:Destroy()
	self.Changed:DisconnectAll()
	self.Submitted:DisconnectAll()
	self.FocusChanged:DisconnectAll()
	self.Instance:Destroy()
end

return TextField
end

