-- Core/Icons.lua
loaders[newNode("Icons", N_Core)] = function(script, require)
--[[
	Material Design flat-icon glyph support.

	Roblox has no built-in Material Symbols font, so real MD icons need a font
	*asset* ??there is no way to ship the actual glyph shapes without one.
	This module gets you there without image assets per icon: one font
	covers every glyph below, rendered as ordinary colorable text (so it
	tints, resizes and themes exactly like a TextLabel).

	Setup (one-time per game):
		1. Download a Material Icons .ttf: assets/fonts/MaterialIconsOutlined-Regular.ttf
		   in this repo (Outlined, the M3 look), or font/MaterialIcons-Regular.ttf
		   from https://github.com/google/material-design-icons (Filled). Apache-2.0.
		2. Upload it to Roblox Studio as a Font asset (Toolbox > your fonts,
		   or Asset Manager) and copy its rbxassetid.
		3. MD3.Icons.SetFont(Font.new("rbxassetid://<your id>"))

	On executors none of this is needed: CreateWindow loads the icons as
	sprite-sheet *images* instead (MD3.IconImages, see Icons.SetSheet), which
	take priority over any font. The sheets hold Google's whole set, about
	4,300 names: every Material Icons name plus the Material Symbols (MD3)
	names the Material Icons fonts don't have. Browse them at
	https://fonts.google.com/icons, or Icons.Search("arrow") / Icons.Has(name).
	MD3.IconFont.Load() can still load the font (Outlined by default; Filled
	/ Round / Sharp also available); fonts only draw the Material Icons names.

	Until SetFont is called, Icons.Apply() falls back to Roblox's own
	BuilderIcons font, which ships inside every Roblox client (no download,
	no asset upload; icons are ligatures, i.e. the text "gear" renders as a
	gear). Material names are mapped onto the closest BuilderIcons glyph.
	Names with no BuilderIcons match fall back to a small set of plain glyph
	characters, so components never show a blank/tofu box.

	Any BuilderIcons glyph can also be used directly: Icons.Apply(label, "builder:sword").

	local Icons = MD3.Icons
	Icons.Apply(myTextLabel, "settings")   -- sets FontFace + Text
	Icons.Glyph("settings")                -- just the character, if you want
	                                        -- to lay it out yourself
]]
local IconSheet = require(script.Parent.IconSheet)

local Icons = {}

-- Material Icons font codepoints for every name the fonts have (generated
-- from Google's MaterialIcons-Regular.codepoints into IconSheet.lua; all four
-- Material Icons styles share them). Material Symbols-only icons have no
-- entry: they exist only on the sprite sheets.
local CODEPOINTS = table.clone(IconSheet.Codepoints)

-- Plain-character stand-ins used only until a real icon font is configured.
local FALLBACK_GLYPHS = {
	check = "\u{2713}",
	check_box = "\u{2713}",
	radio_button_checked = "\u{25CF}",
	radio_button_unchecked = "\u{25CB}",
	remove = "\u{2212}",
	close = "\u{2715}",
	cancel = "\u{2715}",
	add = "+",
	arrow_back = "\u{2190}",
	arrow_forward = "\u{2192}",
	chevron_left = "\u{2039}",
	chevron_right = "\u{203A}",
	expand_more = "\u{2304}",
	expand_less = "\u{2303}",
	minimize = "\u{2212}",
	menu = "\u{2261}",
	done = "\u{2713}",
}

-- Roblox's built-in ligature icon font (the same one the Roblox app UI
-- uses). Font.new doesn't throw for a missing file, so this is safe to
-- create even if Roblox moves it; SetBuilderIconsEnabled(false) opts out.
local BUILDER_FONT = Font.new(
	"rbxasset://LuaPackages/Packages/_Index/BuilderIcons/BuilderIcons/BuilderIcons.json",
	Enum.FontWeight.Regular,
	Enum.FontStyle.Normal
)

-- Material icon name -> closest BuilderIcons ligature.
local BUILDER_NAMES = {
	add = "plus-large",
	alarm = "bell-clock",
	arrow_back = "arrow-large-left",
	arrow_drop_down = "caret-small-down",
	arrow_drop_up = "caret-small-up",
	arrow_forward = "arrow-large-right",
	attach_file = "chain-link",
	autorenew = "arrow-rotate-right",
	backpack = "backpack",
	bar_chart = "chart-three-vertical-bars",
	block = "circle-slash",
	bolt = "lightning-bolt",
	bookmark = "bookmark",
	build = "hammer-code",
	calendar_today = "calendar",
	camera_alt = "photo-camera",
	cancel = "circle-x",
	chat = "speech-bubble-round",
	check = "check",
	check_box = "square-check",
	check_circle = "circle-check",
	chevron_left = "chevron-large-left",
	chevron_right = "chevron-large-right",
	close = "x",
	cloud = "cloud",
	code = "code",
	comment = "speech-bubble-round",
	content_copy = "two-stacked-squares",
	credit_card = "wallet",
	dark_mode = "moon",
	dashboard = "squares-grid-plus",
	delete = "trash-can",
	done = "check",
	download = "arrow-down-to-line",
	drag_handle = "three-bars-horizontal",
	drag_indicator = "six-dots-two-column-grid",
	edit = "pencil",
	error = "triangle-exclamation",
	event = "calendar",
	expand_less = "chevron-small-up",
	expand_more = "chevron-small-down",
	explore = "compass",
	favorite = "heart",
	flag = "flag",
	folder = "folder",
	fullscreen = "dual-arrows-to-corners",
	grid_view = "grid",
	group = "two-people",
	groups = "three-people",
	help_outline = "circle-question",
	history = "clock",
	home = "house",
	image = "image",
	info = "circle-i",
	keyboard_arrow_down = "chevron-small-down",
	keyboard_arrow_left = "chevron-small-left",
	keyboard_arrow_right = "chevron-small-right",
	keyboard_arrow_up = "chevron-small-up",
	language = "globe-simplified",
	light_mode = "sun",
	link = "chain-link",
	list = "list-bulleted",
	location_on = "location-pin",
	lock = "lock-closed",
	login = "door-open-arrow-to-bottom-right",
	mail = "envelope",
	menu = "three-bars-horizontal",
	mic = "microphone",
	mic_off = "microphone-slash",
	minimize = "minus",
	more_horiz = "three-dots-horizontal",
	more_vert = "three-dots-vertical",
	notifications = "bell",
	open_in_new = "arrow-up-right-from-square",
	palette = "paint-brush",
	pause = "pause-large",
	person = "person",
	play_arrow = "play-large",
	public = "globe-simplified",
	refresh = "arrow-rotate-right",
	remove = "minus",
	reorder = "four-bars-horizontal-justified-aligned",
	search = "magnifying-glass",
	send = "paper-airplane",
	settings = "gear",
	shield = "shield-check",
	shopping_cart = "shopping-cart",
	skip_next = "skip-next-large",
	skip_previous = "skip-previous-large",
	sports_esports = "controller-with-cog",
	star = "star",
	stop = "stop-large",
	swap_horiz = "two-arrows-left-right",
	swap_vert = "two-arrows-down-and-up",
	sync = "arrow-rotate-right",
	tag = "hashtag",
	thumb_down = "thumb-down",
	thumb_up = "thumb-up",
	timer = "clock",
	schedule = "clock",
	tune = "three-sliders-horizontal",
	verified = "verified-check",
	visibility = "eye",
	visibility_off = "eye-slash",
	volume_off = "speaker-slash",
	volume_up = "speaker",
	warning = "triangle-exclamation",
	widgets = "nine-dots-grid",
	zoom_in = "magnifying-glass-plus",
	zoom_out = "magnifying-glass-minus",
}

Icons.Codepoints = CODEPOINTS
Icons.BuilderNames = BUILDER_NAMES
Icons.BuilderFont = BUILDER_FONT

local iconFont: Font? = nil
-- The icon sprite sheet: one image per page of IconSheet. Page 0 is set up
-- front; the others come from `sheetLoader` the first time one of their
-- icons is drawn.
local sheetPages: { [number]: string } = {} -- page -> content id
local sheetLoader: ((number) -> string?)? = nil
local pageState: { [number]: string } = {} -- page -> "loading" | "failed"
local sheetGeneration = 0 -- bumped by SetSheet so stale page loads are dropped

-- Every label Icons.Apply has drawn on, so switching the icon font (or
-- style) at runtime redraws icons that already exist. Strong keys with a
-- Destroying cleanup rather than weak keys: Roblox may recreate an
-- Instance's Lua wrapper, which would silently drop weak entries.
local applied = {} -- label -> icon name
local managed = {} -- labels whose Visible follows whether the icon can be drawn
local sprites = {} -- label -> ImageLabel showing the icon from the sprite sheet
local labelFonts = {} -- label -> the label's own font, for plain fallbacks
local cleanups = {}

local reapplyAll, draw

-- Sets the Material icon font (any style) and redraws every icon already
-- on screen with it.
function Icons.SetFont(font: Font)
	iconFont = font
	reapplyAll()
end

function Icons.HasFont(): boolean
	return iconFont ~= nil
end

function Icons.GetFont(): Font?
	return iconFont
end

-- Sets the icon sprite sheet and redraws every icon on screen with it; the
-- sheet takes priority over the font. `image` is page 0 (a content id, e.g.
-- from getcustomasset; see Executor/IconImages.lua, which loads one set of
-- pages per style). `loader(page)` returns another page's content id (or
-- nil if it can't); it may yield, and runs once per page, on first use.
-- Without a loader only page 0's icons come from the sheet. nil removes it.
function Icons.SetSheet(image: string?, loader: ((number) -> string?)?)
	sheetGeneration += 1
	sheetPages = {}
	pageState = {}
	if image ~= nil and image ~= "" then
		sheetPages[0] = image
		sheetLoader = loader
	else
		sheetLoader = nil
	end
	reapplyAll()
end

-- Page 0 of the current sprite sheet (nil when there is none).
function Icons.GetSheet(): string?
	return sheetPages[0]
end

-- The page a sheet icon is on, or nil if the sheet doesn't have it.
local function pageOf(name: string): number?
	local index = IconSheet.Index[name]
	return index and index // IconSheet.PerPage
end

local function redrawPage(page: number)
	for textObject, name in applied do
		if textObject.Parent and pageOf(name) == page then
			draw(textObject, name)
		end
	end
end

-- The content id of a sheet page, starting its download the first time.
-- Returns nil while it loads (icons on it are redrawn once it's there).
local function pageImage(page: number): string?
	if sheetPages[page] or not sheetLoader or pageState[page] then
		return sheetPages[page]
	end
	pageState[page] = "loading"
	local loader, generation = sheetLoader, sheetGeneration
	task.spawn(function()
		local ok, image = pcall(loader, page)
		if generation ~= sheetGeneration then
			return -- the sheet (style) changed meanwhile
		end
		if ok and type(image) == "string" and image ~= "" then
			sheetPages[page] = image
			pageState[page] = nil
			redrawPage(page)
		else
			pageState[page] = "failed"
		end
	end)
	return sheetPages[page] -- set already if the loader didn't yield
end

-- True when `name` is on the sprite sheet and its page is (or can be) loaded.
local function onSheet(name: string): boolean
	local page = pageOf(name)
	if page == nil or sheetPages[0] == nil then
		return false
	end
	return sheetPages[page] ~= nil or (sheetLoader ~= nil and pageState[page] ~= "failed")
end

local builderEnabled = true

-- BuilderIcons is on by default; turn it off to use only the Material font
-- and the plain-character fallbacks.
function Icons.SetBuilderIconsEnabled(enabled: boolean)
	builderEnabled = enabled
	reapplyAll()
end

-- Resolves `name` to the text to display and the font to display it in
-- (nil font = keep the label's own font) when it's drawn as text.
-- Priority: sprite sheet image (handled by Apply) -> Material font ->
-- BuilderIcons -> plain character.
function Icons.Resolve(name: string): (string, Font?)
	local builderName = name:match("^builder:(.+)$")
	if builderName then
		return builderName, BUILDER_FONT
	end
	if iconFont and CODEPOINTS[name] then
		return utf8.char(CODEPOINTS[name]), iconFont
	end
	if builderEnabled and BUILDER_NAMES[name] then
		return BUILDER_NAMES[name], BUILDER_FONT
	end
	-- Never emit a bare Material codepoint without the Material font: those
	-- are Private Use Area characters, and system fallback fonts draw them
	-- as something unrelated (e.g. Chinese user-defined characters on
	-- Traditional Chinese Windows). Drawing nothing is better.
	return FALLBACK_GLYPHS[name] or "", nil
end

-- The text Icons.Apply would put on a label for `name`.
function Icons.Glyph(name: string): string
	return (Icons.Resolve(name))
end

-- True when `name` renders as something meaningful right now (a Material
-- glyph with the font set, a BuilderIcons glyph, or a plain fallback).
function Icons.CanRender(name: string): boolean
	if type(name) ~= "string" then
		return false
	end
	return name:match("^builder:.+") ~= nil
		or onSheet(name)
		or (iconFont ~= nil and CODEPOINTS[name] ~= nil)
		or (builderEnabled and BUILDER_NAMES[name] ~= nil)
		or FALLBACK_GLYPHS[name] ~= nil
end

-- Adds (or overrides) a font glyph by codepoint, e.g. one from a newer
-- MaterialIcons-Regular.codepoints file. Font only: the sprite sheets
-- can't gain icons at runtime.
function Icons.Register(name: string, codepoint: number)
	CODEPOINTS[name] = codepoint
end

-- True when `name` is a Material icon this library knows (on the sprite
-- sheets or registered for the font), whether or not it can be drawn now.
function Icons.Has(name: string): boolean
	return type(name) == "string" and (IconSheet.Index[name] ~= nil or CODEPOINTS[name] ~= nil)
end

-- Every known icon name containing `query` (plain text, case-insensitive;
-- nil / "" lists them all), sorted.
function Icons.Search(query: string?): { string }
	local needle = string.lower(query or "")
	local found, seen = {}, {}
	local function consider(name)
		if not seen[name] and (needle == "" or string.find(name, needle, 1, true)) then
			seen[name] = true
			table.insert(found, name)
		end
	end
	for name in IconSheet.Index do
		consider(name)
	end
	for name in CODEPOINTS do
		consider(name)
	end
	table.sort(found)
	return found
end

-- Keeps the sprite looking like the label's text would: same color,
-- transparency, size and layer.
local function syncSprite(textObject, sprite)
	sprite.ImageColor3 = textObject.TextColor3
	sprite.ImageTransparency = textObject.TextTransparency
	sprite.Size = if textObject.TextScaled
		then UDim2.fromScale(1, 1)
		else UDim2.fromOffset(textObject.TextSize, textObject.TextSize)
	sprite.ZIndex = textObject.ZIndex
end

local function spriteFor(textObject)
	local sprite = sprites[textObject]
	if sprite and sprite.Parent == textObject then
		return sprite
	end
	sprite = Instance.new("ImageLabel")
	sprite.Name = "MD3Icon"
	sprite.BackgroundTransparency = 1
	sprite.AnchorPoint = Vector2.new(0.5, 0.5)
	sprite.Position = UDim2.fromScale(0.5, 0.5)
	sprite.ScaleType = Enum.ScaleType.Fit
	sprite.ImageRectSize = Vector2.new(IconSheet.Cell, IconSheet.Cell)
	sprite.Parent = textObject
	sprites[textObject] = sprite
	for _, prop in { "TextColor3", "TextTransparency", "TextSize", "TextScaled", "ZIndex" } do
		textObject:GetPropertyChangedSignal(prop):Connect(function()
			if sprites[textObject] == sprite then
				syncSprite(textObject, sprite)
			end
		end)
	end
	return sprite
end

function draw(textObject, name: string)
	local index = IconSheet.Index[name]
	local image = index and sheetPages[0] and pageImage(index // IconSheet.PerPage)
	if image then
		local cell = index % IconSheet.PerPage
		local sprite = spriteFor(textObject)
		sprite.Image = image
		sprite.ImageRectOffset = Vector2.new(
			(cell % IconSheet.Columns) * IconSheet.Pitch + IconSheet.Gutter,
			(cell // IconSheet.Columns) * IconSheet.Pitch + IconSheet.Gutter
		)
		sprite.Visible = true
		syncSprite(textObject, sprite)
		textObject.Text = ""
		if managed[textObject] then
			textObject.Visible = true
		end
		return
	end

	if sprites[textObject] then
		sprites[textObject].Visible = false
	end
	local text, font = Icons.Resolve(name)
	textObject.Text = text
	textObject.FontFace = font or labelFonts[textObject] or textObject.FontFace
	if managed[textObject] then
		textObject.Visible = text ~= ""
	end
end

-- Applies the icon onto a Text object (TextLabel/TextButton) in one call:
-- as a sprite-sheet image when one is loaded, otherwise as a glyph. The
-- label keeps following later SetSheet / SetFont / style changes. With
-- `manageVisibility`, the label is hidden while the icon can't be drawn
-- and shown again once a source that has it arrives.
function Icons.Apply(textObject: TextLabel | TextButton, name: string, manageVisibility: boolean?)
	if applied[textObject] == nil then
		labelFonts[textObject] = textObject.FontFace
		local ok, connection = pcall(function()
			return textObject.Destroying:Connect(function()
				applied[textObject] = nil
				managed[textObject] = nil
				sprites[textObject] = nil
				labelFonts[textObject] = nil
				cleanups[textObject] = nil
			end)
		end)
		if ok then
			cleanups[textObject] = connection
		end
	end
	applied[textObject] = name
	if manageVisibility then
		managed[textObject] = true
	end
	draw(textObject, name)
end

function reapplyAll()
	for textObject, name in applied do
		if textObject.Parent then
			draw(textObject, name)
		end
	end
end

return Icons
end

-- Core/Motion.lua
loaders[newNode("Motion", N_Core)] = function(script, require)
-- Material 3 motion tokens (durations) and the closest built-in Roblox easing
-- equivalents to the M3 "standard" / "emphasized" curves (Roblox TweenInfo
-- doesn't accept arbitrary cubic-bezier control points, so these are the
-- nearest EasingStyle/EasingDirection matches).
local Motion = {}

Motion.Duration = {
	Short1 = 0.05,
	Short2 = 0.10,
	Short3 = 0.15,
	Short4 = 0.20,
	Medium1 = 0.25,
	Medium2 = 0.30,
	Medium3 = 0.35,
	Medium4 = 0.40,
	Long1 = 0.45,
	Long2 = 0.50,
	Long3 = 0.55,
	Long4 = 0.60,
}

function Motion.Standard(duration: number?): TweenInfo
	return TweenInfo.new(duration or Motion.Duration.Medium2, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
end

function Motion.Emphasized(duration: number?): TweenInfo
	return TweenInfo.new(duration or Motion.Duration.Medium4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
end

function Motion.Decelerate(duration: number?): TweenInfo
	return TweenInfo.new(duration or Motion.Duration.Short4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
end

function Motion.Accelerate(duration: number?): TweenInfo
	return TweenInfo.new(duration or Motion.Duration.Short2, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
end

return Motion
end

-- Core/Ripple.lua
loaders[newNode("Ripple", N_Core)] = function(script, require)
-- M3 ripple: an expanding, fading circle spawned at the input position on
-- press. Purely decorative feedback layered on top of the StateLayer.
local TweenService = game:GetService("TweenService")
local Create = require(script.Parent.Parent.Util.Create)

local Ripple = {}

-- `inputPosition` is usually InputObject.Position, which is a Vector3 in
-- Roblox; only its X / Y matter (Vector3 - Vector2 would throw).
function Ripple.Emit(parent: GuiObject, inputPosition: Vector2 | Vector3, color: Color3)
	local absPos, absSize = parent.AbsolutePosition, parent.AbsoluteSize
	if absSize.X <= 0 or absSize.Y <= 0 then
		return
	end

	local localPos = Vector2.new(inputPosition.X, inputPosition.Y) - absPos
	-- Diameter big enough to cover the furthest corner from the tap point.
	local maxDist = math.max(
		(localPos - Vector2.new(0, 0)).Magnitude,
		(localPos - Vector2.new(absSize.X, 0)).Magnitude,
		(localPos - Vector2.new(0, absSize.Y)).Magnitude,
		(localPos - Vector2.new(absSize.X, absSize.Y)).Magnitude
	)
	local diameter = maxDist * 2

	local circle = Create("Frame") {
		Name = "Ripple",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromOffset(localPos.X, localPos.Y),
		Size = UDim2.fromOffset(0, 0),
		BackgroundColor3 = color,
		BackgroundTransparency = 0.7,
		BorderSizePixel = 0,
		ZIndex = parent.ZIndex + 2,
		[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
		Parent = parent,
	}

	local grow = TweenService:Create(circle, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		Size = UDim2.fromOffset(diameter, diameter),
	})
	local fade = TweenService:Create(circle, TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		BackgroundTransparency = 1,
	})

	grow:Play()
	task.delay(0.15, function()
		fade:Play()
	end)
	fade.Completed:Once(function()
		circle:Destroy()
	end)
end

return Ripple
end

-- Core/Shape.lua
loaders[newNode("Shape", N_Core)] = function(script, require)
-- Material 3 shape scale (corner radius tokens).
local Shape = {
	None = UDim.new(0, 0),
	ExtraSmall = UDim.new(0, 4),
	Small = UDim.new(0, 8),
	Medium = UDim.new(0, 12),
	Large = UDim.new(0, 16),
	ExtraLarge = UDim.new(0, 28),
	Full = UDim.new(1, 0), -- pill / fully rounded, pair with UICorner on a fixed-height element
}

function Shape.Corner(radius: UDim, parent: Instance?): UICorner
	local corner = Instance.new("UICorner")
	corner.CornerRadius = radius
	if parent then
		corner.Parent = parent
	end
	return corner
end

return Shape
end

-- Core/StateLayer.lua
loaders[newNode("StateLayer", N_Core)] = function(script, require)
-- M3 "state layer": a full-bleed overlay tinted with the content color that
-- fades in/out to communicate hover / focus / press / drag states.
local Create = require(script.Parent.Parent.Util.Create)
local Motion = require(script.Parent.Motion)

local OPACITY = {
	Hover = 0.08,
	Focus = 0.10,
	Pressed = 0.10,
	Dragged = 0.16,
}

local StateLayer = {}
StateLayer.__index = StateLayer
StateLayer.Opacity = OPACITY

function StateLayer.new(parent: GuiObject, color: Color3, cornerRadius: UDim?)
	local self = setmetatable({}, StateLayer)

	self.Instance = Create("Frame") {
		Name = "StateLayer",
		BackgroundColor3 = color,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 1, 0),
		ZIndex = parent.ZIndex + 1,
		[1] = Create("UICorner") { CornerRadius = cornerRadius or UDim.new(0, 0) },
		Parent = parent,
	}

	self._active = {}
	return self
end

function StateLayer:SetColor(color: Color3)
	self.Instance.BackgroundColor3 = color
end

-- Turns a named state (Hover/Focus/Pressed/Dragged) on or off. Multiple
-- states can be active at once; the strongest opacity wins, matching M3.
function StateLayer:SetState(name: string, active: boolean)
	self._active[name] = active or nil

	local strongest = 0
	for state in pairs(self._active) do
		strongest = math.max(strongest, OPACITY[state] or 0)
	end

	local tween = game:GetService("TweenService"):Create(
		self.Instance,
		Motion.Standard(Motion.Duration.Short2),
		{ BackgroundTransparency = 1 - strongest }
	)
	tween:Play()
end

function StateLayer:Destroy()
	self.Instance:Destroy()
end

return StateLayer
end

-- Core/Theme.lua
loaders[newNode("Theme", N_Core)] = function(script, require)
-- Material 3 color system: builds a full light/dark color-role scheme from a
-- single seed color, and lets components subscribe to live theme changes
-- (mode switch, seed color / dynamic-color swap, contrast changes, etc).
local Color = require(script.Parent.Parent.Util.Color)
local Signal = require(script.Parent.Parent.Util.Signal)

local DEFAULT_SEED = Color3.fromHex("#6750A4") -- Material baseline seed

local Theme = {}
Theme.__index = Theme

local function buildPalettes(seed: Color3)
	return {
		Primary = Color.PaletteFromSeed(seed, 0.55, 0),
		Secondary = Color.PaletteFromSeed(seed, 0.18, 0),
		Tertiary = Color.PaletteFromSeed(seed, 0.30, 1 / 6), -- +60deg hue
		Neutral = Color.PaletteFromSeed(seed, 0.06, 0),
		NeutralVariant = Color.PaletteFromSeed(seed, 0.10, 0),
		Error = Color.Palette.new(0 / 360, 0.62), -- fixed red hue, like real M3
	}
end

local function buildScheme(p, isDark: boolean)
	local N, NV = p.Neutral, p.NeutralVariant

	if isDark then
		return {
			Primary = p.Primary:Tone(80),
			OnPrimary = p.Primary:Tone(20),
			PrimaryContainer = p.Primary:Tone(30),
			OnPrimaryContainer = p.Primary:Tone(90),

			Secondary = p.Secondary:Tone(80),
			OnSecondary = p.Secondary:Tone(20),
			SecondaryContainer = p.Secondary:Tone(30),
			OnSecondaryContainer = p.Secondary:Tone(90),

			Tertiary = p.Tertiary:Tone(80),
			OnTertiary = p.Tertiary:Tone(20),
			TertiaryContainer = p.Tertiary:Tone(30),
			OnTertiaryContainer = p.Tertiary:Tone(90),

			Error = p.Error:Tone(80),
			OnError = p.Error:Tone(20),
			ErrorContainer = p.Error:Tone(30),
			OnErrorContainer = p.Error:Tone(90),

			Background = N:Tone(6),
			OnBackground = N:Tone(90),
			Surface = N:Tone(6),
			OnSurface = N:Tone(90),
			SurfaceVariant = NV:Tone(30),
			OnSurfaceVariant = NV:Tone(80),

			Outline = NV:Tone(60),
			OutlineVariant = NV:Tone(30),
			Shadow = N:Tone(0),
			Scrim = N:Tone(0),

			InverseSurface = N:Tone(90),
			InverseOnSurface = N:Tone(20),
			InversePrimary = p.Primary:Tone(40),

			SurfaceDim = N:Tone(6),
			SurfaceBright = N:Tone(24),
			SurfaceContainerLowest = N:Tone(4),
			SurfaceContainerLow = N:Tone(10),
			SurfaceContainer = N:Tone(12),
			SurfaceContainerHigh = N:Tone(17),
			SurfaceContainerHighest = N:Tone(22),
		}
	end

	return {
		Primary = p.Primary:Tone(40),
		OnPrimary = p.Primary:Tone(100),
		PrimaryContainer = p.Primary:Tone(90),
		OnPrimaryContainer = p.Primary:Tone(10),

		Secondary = p.Secondary:Tone(40),
		OnSecondary = p.Secondary:Tone(100),
		SecondaryContainer = p.Secondary:Tone(90),
		OnSecondaryContainer = p.Secondary:Tone(10),

		Tertiary = p.Tertiary:Tone(40),
		OnTertiary = p.Tertiary:Tone(100),
		TertiaryContainer = p.Tertiary:Tone(90),
		OnTertiaryContainer = p.Tertiary:Tone(10),

		Error = p.Error:Tone(40),
		OnError = p.Error:Tone(100),
		ErrorContainer = p.Error:Tone(90),
		OnErrorContainer = p.Error:Tone(10),

		Background = N:Tone(98),
		OnBackground = N:Tone(10),
		Surface = N:Tone(98),
		OnSurface = N:Tone(10),
		SurfaceVariant = NV:Tone(90),
		OnSurfaceVariant = NV:Tone(30),

		Outline = NV:Tone(50),
		OutlineVariant = NV:Tone(80),
		Shadow = N:Tone(0),
		Scrim = N:Tone(0),

		InverseSurface = N:Tone(20),
		InverseOnSurface = N:Tone(95),
		InversePrimary = p.Primary:Tone(80),

		SurfaceDim = N:Tone(87),
		SurfaceBright = N:Tone(98),
		SurfaceContainerLowest = N:Tone(100),
		SurfaceContainerLow = N:Tone(96),
		SurfaceContainer = N:Tone(94),
		SurfaceContainerHigh = N:Tone(92),
		SurfaceContainerHighest = N:Tone(90),
	}
end

-- Roles whose "On" color (text/icons drawn on top) is recomputed for
-- contrast when the role is overridden but its On role isn't.
local ON_PAIRS = {
	Primary = "OnPrimary",
	PrimaryContainer = "OnPrimaryContainer",
	Secondary = "OnSecondary",
	SecondaryContainer = "OnSecondaryContainer",
	Tertiary = "OnTertiary",
	TertiaryContainer = "OnTertiaryContainer",
	Error = "OnError",
	ErrorContainer = "OnErrorContainer",
	Surface = "OnSurface",
	Background = "OnBackground",
}

-- Relative luminance (WCAG) of a color, 0..1.
local function luminance(c: Color3): number
	local function channel(v)
		return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4
	end
	return 0.2126 * channel(c.R) + 0.7152 * channel(c.G) + 0.0722 * channel(c.B)
end

-- Readable content color for a background: near-black or near-white.
function Theme:ContrastColor(background: Color3): Color3
	local N = self._palettes.Neutral
	return luminance(background) > 0.18 and N:Tone(10) or N:Tone(98)
end

-- The generated scheme, then the user's overrides on top. Also derives the
-- icon roles, which default to the M3 roles icons normally use:
--   Icon         = OnSurfaceVariant      (regular icons)
--   IconAccent   = Primary               (app icon, notification icons)
--   IconSelected = OnSecondaryContainer  (the selected navigation item)
-- Overrides cascade so one color can restyle a whole group:
--   * OnSurface (text) -> OnSurfaceVariant (secondary text, a softer mix of
--     the text and background colors) and OnBackground follow it
--   * Icon -> IconAccent and IconSelected follow it
-- unless those roles are overridden themselves.
function Theme:_build()
	local colors = buildScheme(self._palettes, self.Mode == "Dark")
	local overrides = self._overrides
	for role, color in overrides do
		colors[role] = color
	end
	for role, onRole in ON_PAIRS do
		if overrides[role] and not overrides[onRole] then
			colors[onRole] = self:ContrastColor(colors[role])
		end
	end
	if (overrides.OnSurface or overrides.Surface) and not overrides.OnSurfaceVariant then
		colors.OnSurfaceVariant = Color.Blend(colors.OnSurface, colors.Surface, 0.3)
	end
	if overrides.OnSurface and not overrides.OnBackground then
		colors.OnBackground = colors.OnSurface
	end
	colors.Icon = overrides.Icon or colors.OnSurfaceVariant
	colors.IconAccent = overrides.IconAccent or overrides.Icon or colors.Primary
	colors.IconSelected = overrides.IconSelected or overrides.Icon or colors.OnSecondaryContainer
	-- Roles a preset links to another role, or to "Seed" (the theme color
	-- itself), so they keep matching when it changes: NeverLose's accent is
	-- exactly the theme color and its selected tab icon is the accent. An
	-- override on the role still wins. A linked role's text color (ON_PAIRS)
	-- gets a readable contrast color unless it is overridden too.
	local function resolve(role, depth)
		local source = self._follow[role]
		if overrides[role] or not source or depth > 4 then
			return colors[role]
		elseif source == "Seed" then
			return self.Seed
		end
		return resolve(source, depth + 1)
	end
	local linked = {}
	for role in self._follow do
		linked[role] = resolve(role, 0)
	end
	for role, color in linked do
		colors[role] = color
		local onRole = ON_PAIRS[role]
		if onRole and not overrides[role] and not overrides[onRole] then
			colors[onRole] = self:ContrastColor(color)
		end
	end
	-- HUD (watermark, keybind list, indicators): colors follow the window's
	-- rows / outline / text unless set, but transparency is the HUD's own.
	colors.HUDBackground = overrides.HUDBackground or colors.SurfaceContainerHigh
	colors.HUDOutline = overrides.HUDOutline or colors.OutlineVariant
	colors.HUDText = overrides.HUDText or colors.OnSurface

	-- Transparency per role, cascading the same way as the colors.
	local t = self._transparency
	local transparency = table.clone(t)
	transparency.OnSurfaceVariant = t.OnSurfaceVariant or t.OnSurface
	transparency.OnBackground = t.OnBackground or t.OnSurface
	transparency.Icon = t.Icon or transparency.OnSurfaceVariant
	transparency.IconAccent = t.IconAccent or t.Icon
	transparency.IconSelected = t.IconSelected or t.Icon
	-- Deliberately not inherited from the window's roles, so a see-through
	-- window can have a solid HUD and the other way round.
	transparency.HUDOutline = t.HUDOutline or t.HUDBackground
	self.Transparency = transparency
	return colors
end

-- Transparency (0 = opaque, 1 = invisible) set for a color role, or nil
-- when the role is left opaque. Window chrome applies it through Themer to
-- the matching BackgroundTransparency / TextTransparency / ... property.
function Theme:GetTransparency(role: string): number?
	return self.Transparency[role]
end

-- One-call helpers for the three colors people most want to change.
-- nil returns that color to the generated default.
function Theme:SetThemeColor(color: Color3)
	self:SetSeedColor(color)
end

function Theme:SetTextColor(color: Color3?)
	self:SetOverride("OnSurface", color)
end

function Theme:SetIconColor(color: Color3?)
	self:SetOverride("Icon", color)
end

function Theme.new(seed: Color3?, mode: string?)
	local self = setmetatable({}, Theme)
	self.Seed = seed or DEFAULT_SEED
	self.Mode = mode or "Light"
	self._palettes = buildPalettes(self.Seed)
	self._overrides = {}
	self._transparency = {}
	self._follow = {}
	self.Colors = self:_build()
	self.Changed = Signal.new()
	return self
end

function Theme:SetMode(mode: string)
	assert(mode == "Light" or mode == "Dark", "mode must be \"Light\" or \"Dark\"")
	if self.Mode == mode then
		return
	end
	self.Mode = mode
	self.Colors = self:_build()
	self.Changed:Fire(self)
end

function Theme:Toggle()
	self:SetMode(self.Mode == "Light" and "Dark" or "Light")
end

function Theme:SetSeedColor(seed: Color3)
	self.Seed = seed
	self._palettes = buildPalettes(seed)
	self.Colors = self:_build()
	self.Changed:Fire(self)
end

--== Overrides (theme editor) ==--

local function cleanTransparency(value)
	if type(value) ~= "number" then
		return nil
	end
	value = math.clamp(value, 0, 1)
	return if value > 0 then value else nil
end

-- Pins one color role (e.g. "Primary", "Surface", "Icon") to a fixed
-- color, on top of the seed-generated scheme. Survives SetSeedColor /
-- SetMode. `transparency` (0-1, optional) sets how see-through the role is;
-- leaving it out keeps the current one. color = nil resets the role
-- entirely (generated color, opaque).
function Theme:SetOverride(role: string, color: Color3?, transparency: number?)
	self._overrides[role] = color
	if color == nil then
		self._transparency[role] = nil
	elseif transparency ~= nil then
		self._transparency[role] = cleanTransparency(transparency)
	end
	self.Colors = self:_build()
	self.Changed:Fire(self)
end

-- Sets only a role's transparency (0-1; 0 or nil = opaque), keeping its color.
function Theme:SetTransparency(role: string, transparency: number?)
	self._transparency[role] = cleanTransparency(transparency)
	self.Colors = self:_build()
	self.Changed:Fire(self)
end

-- Replaces all overrides at once: colors ({ [role] = Color3 }) and,
-- optionally, transparencies ({ [role] = number }) and role links
-- ({ [role] = sourceRole }, see Presets' Follow); nil keeps the current.
function Theme:SetOverrides(overrides: { [string]: Color3 }?, transparency: { [string]: number }?, follow: { [string]: string }?)
	self._overrides = table.clone(overrides or {})
	if follow then
		self._follow = table.clone(follow)
	end
	if transparency then
		self._transparency = {}
		for role, value in transparency do
			self._transparency[role] = cleanTransparency(value)
		end
	end
	self.Colors = self:_build()
	self.Changed:Fire(self)
end

function Theme:GetOverrides(): { [string]: Color3 }
	return table.clone(self._overrides)
end

function Theme:GetTransparencies(): { [string]: number }
	return table.clone(self._transparency)
end

-- Role links set by a preset ({ IconSelected = "Primary" }).
function Theme:GetFollow(): { [string]: string }
	return table.clone(self._follow)
end

function Theme:IsOverridden(role: string): boolean
	return self._overrides[role] ~= nil or self._transparency[role] ~= nil
end

function Theme:ClearOverrides()
	self._presetOverrides = nil
	self:SetOverrides({}, {}, {})
end

-- Plain table describing the theme (hex strings), e.g. to share as JSON:
-- { Seed = "6750a4", Mode = "Dark", Overrides = { Primary = "ff0000" },
--   Transparency = { Surface = 0.3 } }
function Theme:Export()
	local overrides = {}
	for role, color in self._overrides do
		overrides[role] = color:ToHex()
	end
	return {
		Seed = self.Seed:ToHex(),
		Mode = self.Mode,
		Overrides = overrides,
		Transparency = table.clone(self._transparency),
		Follow = if next(self._follow) then table.clone(self._follow) else nil,
	}
end

-- Applies a table made by Export (one Changed event).
function Theme:Import(data)
	assert(type(data) == "table", "Theme:Import expects a table from Theme:Export")
	if data.Seed then
		self.Seed = Color3.fromHex(data.Seed)
		self._palettes = buildPalettes(self.Seed)
	end
	if data.Mode == "Light" or data.Mode == "Dark" then
		self.Mode = data.Mode
	end
	local overrides = {}
	for role, hex in data.Overrides or {} do
		overrides[role] = Color3.fromHex(hex)
	end
	self._overrides = overrides
	self._presetOverrides = nil
	self._follow = table.clone(data.Follow or {})
	self._transparency = {}
	for role, value in data.Transparency or {} do
		self._transparency[role] = cleanTransparency(value)
	end
	self.Colors = self:_build()
	self.Changed:Fire(self)
end

-- Color roles worth exposing in an editor, with friendly names.
Theme.EditableRoles = {
	{ Role = "Primary", Name = "Primary" },
	{ Role = "Secondary", Name = "Secondary" },
	{ Role = "Tertiary", Name = "Tertiary" },
	{ Role = "SecondaryContainer", Name = "Selection" },
	{ Role = "Surface", Name = "Background" },
	{ Role = "SurfaceContainerLow", Name = "Content panel" },
	{ Role = "SurfaceContainerHigh", Name = "Rows" },
	{ Role = "OnSurface", Name = "Text" },
	{ Role = "OnSurfaceVariant", Name = "Secondary text" },
	{ Role = "Outline", Name = "Outline" },
	{ Role = "Icon", Name = "Icons" },
	{ Role = "IconAccent", Name = "Accent icons" },
	{ Role = "IconSelected", Name = "Selected tab icon" },
	{ Role = "Error", Name = "Error" },
}

-- Theme presets. Most are just a seed color (M3 baseline + common hues);
-- a "full" preset also sets the mode and pins colors (Overrides, hex) to
-- reproduce a specific look. Apply with Theme:ApplyPreset(name).
Theme.Presets = {
	{ Name = "Baseline", Seed = "6750A4" },
	{ Name = "Blue", Seed = "0061A4" },
	{ Name = "Teal", Seed = "006A6A" },
	{ Name = "Green", Seed = "006E1C" },
	{ Name = "Yellow", Seed = "6D5E0F" },
	{ Name = "Orange", Seed = "8B5000" },
	{ Name = "Red", Seed = "B3261E" },
	{ Name = "Pink", Seed = "984061" },
	-- The colors of the NeverLose UI (github.com/engnyg/NeverLose): near-black
	-- surfaces, slate outlines, white text, #4E7FFC accent.
	{
		Name = "NeverLose",
		Seed = "4E7FFC",
		Mode = "Dark",
		Overrides = {
			OnPrimary = "FFFFFF", -- white on the accent (switch thumb, buttons)
			Surface = "08080D", -- window
			SurfaceContainerLow = "0D1116", -- content panel
			SurfaceContainerHigh = "14161B", -- rows, dropdown / tooltip popups
			SurfaceContainerHighest = "1A1C24", -- input fields, keybind chips
			SecondaryContainer = "272831", -- selection (option buttons)
			OnSecondaryContainer = "FFFFFF",
			OutlineVariant = "2D303A", -- outlines
			OnSurface = "FFFFFF", -- text
			OnSurfaceVariant = "BABABA", -- secondary text
			Icon = "DFDFDF",
			Error = "FF6669", -- red indicator
			HUDBackground = "08080D", -- watermark
		},
		-- The accent (switches, slider, tab icon) is the theme color itself
		-- rather than M3's lighter dark-mode tone, and the selected tab icon
		-- and accent icons use it; all of them follow a new theme color.
		Follow = { Primary = "Seed", IconSelected = "Primary", IconAccent = "Primary" },
	},
}

-- LinoriaLib's built-in themes (github.com/engnyg/LinoriaLib,
-- addons/ThemeManager.lua), in its order. Each is its five colors:
-- { name, FontColor, MainColor, AccentColor, BackgroundColor, OutlineColor }.
-- Its "Default" is called "Linoria" here so it isn't mistaken for ours.
local LINORIA_THEMES = {
	{ "Linoria", "ffffff", "1c1c1c", "0055ff", "141414", "323232" },
	{ "BBot", "ffffff", "1e1e1e", "7e48a3", "232323", "141414" },
	{ "Fatality", "ffffff", "1e1842", "c50754", "191335", "3c355d" },
	{ "Jester", "ffffff", "242424", "db4467", "1c1c1c", "373737" },
	{ "Mint", "ffffff", "242424", "3db488", "1c1c1c", "373737" },
	{ "Tokyo Night", "ffffff", "191925", "6759b3", "16161f", "323232" },
	{ "Ubuntu", "ffffff", "3e3e3e", "e2581e", "323232", "191919" },
	{ "Quartz", "ffffff", "232330", "426e87", "1d1b26", "27232f" },
}

-- Maps a LinoriaLib theme onto the M3 roles: MainColor is the window and
-- the rows (its element boxes), BackgroundColor the content panel (its
-- groupboxes) and input fields, OutlineColor the outlines and selection.
-- Secondary text and the error color are the ones LinoriaLib uses for every
-- theme (DisabledTextColor, RiskColor). Like NeverLose, the accent is the
-- theme color itself, so changing the theme color re-colors it.
local function linoriaPreset(name, font, main, accent, background, outline)
	return {
		Name = name,
		Seed = accent,
		Mode = "Dark",
		Overrides = {
			OnPrimary = font,
			Surface = main,
			SurfaceContainerLow = background,
			SurfaceContainerHigh = main,
			SurfaceContainerHighest = background,
			SecondaryContainer = outline,
			OnSecondaryContainer = font,
			OutlineVariant = outline,
			OnSurface = font,
			OnSurfaceVariant = "8e8e8e",
			Error = "ff3232",
			HUDBackground = main,
		},
		Follow = { Primary = "Seed", IconSelected = "Primary", IconAccent = "Primary" },
	}
end

for _, spec in LINORIA_THEMES do
	table.insert(Theme.Presets, linoriaPreset(table.unpack(spec)))
end

-- Applies a preset from Theme.Presets by name. A seed-only preset changes
-- the theme color and keeps custom colors; a full preset also sets its mode
-- and colors. Colors a previously applied full preset set, and that haven't
-- been changed since, are removed first, so switching presets doesn't leave
-- the old look behind. Returns false for an unknown name.
function Theme:ApplyPreset(name: string): boolean
	local preset = nil
	for _, candidate in Theme.Presets do
		if candidate.Name == name then
			preset = candidate
		end
	end
	if not preset then
		return false
	end

	local overrides = table.clone(self._overrides)
	for role, hex in self._presetOverrides or {} do
		local color = overrides[role]
		if color and color:ToHex() == string.lower(hex) then
			overrides[role] = nil
		end
	end
	self._presetOverrides = nil
	if preset.Overrides then
		for role, hex in preset.Overrides do
			overrides[role] = Color3.fromHex(hex)
		end
		self._presetOverrides = preset.Overrides
	end
	self._follow = table.clone(preset.Follow or {})

	self.Seed = Color3.fromHex(preset.Seed)
	self._palettes = buildPalettes(self.Seed)
	if preset.Mode then
		self.Mode = preset.Mode
	end
	self._overrides = overrides
	self.Colors = self:_build()
	self.Changed:Fire(self)
	return true
end

-- Surface tint overlay used to fake elevation (M3 uses a primary-tinted
-- overlay on top of Surface instead of a pure drop shadow to convey elevation).
local ELEVATION_OPACITY = { [0] = 0, 0.05, 0.08, 0.11, 0.12, 0.14 }

function Theme:SurfaceAtElevation(level: number): Color3
	level = math.clamp(level, 0, 5)
	return Color.Blend(self.Colors.Surface, self.Colors.Primary, ELEVATION_OPACITY[level])
end

-- Global default instance so components work out of the box without every
-- call site having to thread a theme object through.
local defaultTheme: typeof(Theme.new()) = nil

function Theme.Default()
	if not defaultTheme then
		defaultTheme = Theme.new()
	end
	return defaultTheme
end

Theme.DefaultSeed = DEFAULT_SEED

return Theme
end

-- Core/Typography.lua
loaders[newNode("Typography", N_Core)] = function(script, require)
-- Material 3 type scale, mapped onto Roblox Font/TextSize/LineHeight properties.
local Typography = {}

local REGULAR = Font.fromEnum(Enum.Font.Gotham)
local MEDIUM = Font.fromEnum(Enum.Font.GothamMedium)

-- size = TextSize (px), lineHeight = TextSize multiplier Roblox understands (LineHeight prop, 0-2 scale-ish "relative")
local SCALE = {
	DisplayLarge = { size = 57, lineHeight = 1.12, font = REGULAR },
	DisplayMedium = { size = 45, lineHeight = 1.16, font = REGULAR },
	DisplaySmall = { size = 36, lineHeight = 1.22, font = REGULAR },

	HeadlineLarge = { size = 32, lineHeight = 1.25, font = REGULAR },
	HeadlineMedium = { size = 28, lineHeight = 1.29, font = REGULAR },
	HeadlineSmall = { size = 24, lineHeight = 1.33, font = REGULAR },

	TitleLarge = { size = 22, lineHeight = 1.27, font = REGULAR },
	TitleMedium = { size = 16, lineHeight = 1.5, font = MEDIUM },
	TitleSmall = { size = 14, lineHeight = 1.43, font = MEDIUM },

	BodyLarge = { size = 16, lineHeight = 1.5, font = REGULAR },
	BodyMedium = { size = 14, lineHeight = 1.43, font = REGULAR },
	BodySmall = { size = 12, lineHeight = 1.33, font = REGULAR },

	LabelLarge = { size = 14, lineHeight = 1.43, font = MEDIUM },
	LabelMedium = { size = 12, lineHeight = 1.33, font = MEDIUM },
	LabelSmall = { size = 11, lineHeight = 1.45, font = MEDIUM },
}

Typography.Scale = SCALE

-- Applies a type-scale role onto a TextLabel/TextButton/TextBox.
function Typography.Apply(textObject: TextLabel | TextButton | TextBox, role: string)
	local style = SCALE[role]
	assert(style, `Unknown typography role "{role}"`)
	textObject.FontFace = style.font
	textObject.TextSize = style.size
	textObject.LineHeight = style.lineHeight
	textObject.RichText = false
end

return Typography
end

-- Executor/Assets.lua
loaders[newNode("Assets", N_Executor)] = function(script, require)
--[[
	Loads images from outside Roblox (a web URL or a file in the executor
	workspace) so they can be used anywhere an Image is expected, without
	uploading them as Roblox assets first.

	How: HttpGet the file once, writefile it into MD3/assets/, then turn it
	into a content id with getcustomasset (cached on disk and in memory).

	local image = MD3.Assets.Resolve("https://example.com/logo.png")
	imageLabel.Image = image

	Every Icon / Logo prop in MD3 goes through Assets.Resolve, so these all
	work the same:
		Icon = "https://raw.githubusercontent.com/me/repo/main/icon.png"
		Icon = "rbxassetid://1234567"   or   Icon = 1234567
		Icon = "MyHub/icon.png"         -- a file already in the workspace
	Without executor file functions, web URLs resolve to "" (no image) and
	rbxassetid ids pass through unchanged.
]]
local Root = script.Parent.Parent
local Env = require(Root.Executor.Env)

local Assets = {}

Assets.Folder = "MD3/assets"

local cache: { [string]: string } = {}

-- Short stable hash so different URLs with the same file name don't clash.
local function hash(text: string): string
	local h = 5381
	for i = 1, #text do
		h = (h * 33 + string.byte(text, i)) % 4294967296
	end
	return string.format("%08x", h)
end

local function fileNameFor(url: string): string
	local path = url:gsub("[?#].*$", "")
	local name = path:match("([^/]+)$") or "image"
	name = name:gsub("[^%w%-_%.]", "_")
	if not name:find("%.%w+$") then
		name ..= ".png"
	end
	return `{hash(url)}\_{name}`
end

local function looksLikeHtml(data: string): boolean
	local head = data:sub(1, 256):lower()
	return head:find("<!doctype", 1, true) ~= nil or head:find("<html", 1, true) ~= nil
end

-- What a file is, from its first bytes: "png" | "jpg" | "webm" | "gif" |
-- "webp" | "html", or nil when unknown.
function Assets.Sniff(data: string): string?
	if data:sub(1, 4) == "\137PNG" then
		return "png"
	elseif data:sub(1, 3) == "\255\216\255" then
		return "jpg"
	elseif data:sub(1, 4) == "\26\69\223\163" then
		return "webm"
	elseif data:sub(1, 4) == "GIF8" then
		return "gif"
	elseif data:sub(1, 4) == "RIFF" and data:sub(9, 12) == "WEBP" then
		return "webp"
	elseif looksLikeHtml(data) then
		return "html"
	end
	return nil
end

-- Why `data` can't be used as `want` ("image" or "video"), or nil when it
-- can. Unknown formats are let through as images (Roblox also reads BMP /
-- TGA); a video must really be WebM. The second result is true when the
-- file is no use for anything (so a cached copy can be deleted), false when
-- it is just the wrong kind for this request.
local function unusable(data: string, want: string): (string?, boolean)
	local kind = Assets.Sniff(data)
	if kind == "html" then
		return "the link returned a web page, not the file (use a direct download link, e.g. raw.githubusercontent.com)", true
	elseif kind == "gif" then
		return "GIF isn't supported by Roblox (it can't play or even show it); use PNG / JPG for a still image, or convert it to WebM for a video background", true
	elseif kind == "webp" then
		return "WebP isn't supported by Roblox; use PNG or JPG", true
	elseif want == "image" and kind == "webm" then
		return "that's a WebM video, not an image"
	elseif want == "video" and kind ~= "webm" then
		return "a video background has to be a WebM file"
	end
	return nil
end

-- True for values that should be shown as an image rather than treated as
-- a Material icon name.
function Assets.IsImage(value): boolean
	if type(value) == "number" then
		return true
	end
	if type(value) ~= "string" or value == "" then
		return false
	end
	return value:match("^rbxasset") ~= nil
		or value:match("^rbxthumb") ~= nil
		or value:match("^rbxhttp") ~= nil
		or value:match("^https?://") ~= nil
		or value:match("%.png$") ~= nil
		or value:match("%.jpe?g$") ~= nil
		or value:match("^%d+$") ~= nil
end

-- Downloads `url` (once) into the workspace and returns a content id for it,
-- or nil and the reason. `want` is "image" (default) or "video"; the file is
-- checked for a format Roblox can actually use either way.
function Assets.FromUrl(url: string, fileName: string?, want: string?): (string?, string?)
	want = want or "image"
	local key = `{want}:{url}`
	if cache[key] then
		return cache[key]
	end
	if not Env.CanUseCustomAssets then
		return nil, "this executor has no writefile / getcustomasset"
	end

	Env.MakeFolder(Assets.Folder)
	local path = `{Assets.Folder}/{fileName or fileNameFor(url)}`
	local data = Env.ReadFile(path)
	if data then
		-- Downloaded before, possibly before these checks existed.
		local problem, useless = unusable(data, want)
		if problem then
			if useless then
				Env.DeleteFile(path) -- so a fixed file at the same URL is fetched again
			end
			return nil, problem
		end
	else
		data = Env.HttpGet(url)
		if not data or #data == 0 then
			return nil, `could not download {url}`
		end
		local problem = unusable(data, want)
		if problem then
			return nil, problem
		end
		if not Env.WriteFile(path, data) then
			return nil, `could not write {path}`
		end
	end

	local asset = Env.GetCustomAsset(path)
	if not asset then
		return nil, `getcustomasset failed for {path}`
	end
	cache[key] = asset
	return asset
end

-- Drops a cached URL/file so the next request loads it again.
function Assets.Forget(key: string)
	for _, want in { "image", "video" } do
		cache[`{want}:{key}`] = nil
	end
end

-- Returns a workspace file as a content id, or nil and the reason.
function Assets.FromFile(path: string, want: string?): (string?, string?)
	want = want or "image"
	local key = `{want}:{path}`
	if cache[key] then
		return cache[key]
	end
	local data = Env.ReadFile(path)
	if not data then
		return nil, `no file {path} in the workspace`
	end
	local problem = unusable(data, want)
	if problem then
		return nil, problem
	end
	local asset = Env.GetCustomAsset(path)
	if not asset then
		return nil, `getcustomasset failed for {path}`
	end
	cache[key] = asset
	return asset
end

-- Like Resolve, but returns "" plus the reason instead of warning.
-- `want` is "image" (default) or "video".
function Assets.ResolveWithReason(source, want: string?): (string, string?)
	if source == nil or source == "" then
		return "", "no image given"
	end
	if type(source) == "number" or (type(source) == "string" and source:match("^%d+$")) then
		return `rbxassetid://{source}`
	end
	if type(source) ~= "string" then
		return "", `not an image: {tostring(source)}`
	end
	if source:match("^rbx") or source:match("^http://www%.roblox%.com/asset") then
		return source
	end
	local ok, asset, problem
	if source:match("^https?://") then
		ok, asset, problem = pcall(Assets.FromUrl, source, nil, want)
	else
		ok, asset, problem = pcall(Assets.FromFile, source, want)
	end
	if not ok then
		return "", tostring(asset)
	end
	return asset or "", if asset then nil else (problem or `could not load {source}`)
end

-- Turns any supported image reference into something ImageLabel.Image
-- accepts. Never throws; returns "" (and warns) when the image can't be loaded.
function Assets.Resolve(image): string
	if image == nil or image == "" then
		return ""
	end
	local asset, problem = Assets.ResolveWithReason(image, "image")
	if asset == "" then
		warn(`\[MD3] could not load image {image}: {problem}`)
	end
	return asset
end

-- Downloads several images up front (e.g. at script start) so later
-- Resolve calls don't wait on the network.
function Assets.Preload(urls: { string })
	for _, url in urls do
		task.spawn(function()
			pcall(Assets.FromUrl, url, nil, if url:lower():gsub("[?#].*$", ""):match("%.webm$") then "video" else "image")
		end)
	end
end

return Assets
end

-- Executor/Env.lua
loaders[newNode("Env", N_Executor)] = function(script, require)
--[[
	Executor environment shims. Script executors expose non-standard globals
	(gethui, writefile, getcustomasset, ...) whose names and availability
	differ per executor; everything here degrades gracefully when a function
	is missing, so the library still runs in plain Roblox Studio/LocalScripts.

	local Env = MD3.Env
	Env.GetGuiParent()          -- gethui() > CoreGui > PlayerGui
	Env.WriteFile("MyHub/a.txt", "hi")
	Env.HttpGet(url)
]]
local Players = game:GetService("Players")

local Env = {}

-- Executor globals are read through the chunk's environment; in normal
-- Roblox these are simply nil.
local gethui_ = gethui or get_hidden_gui
local protectGui = (syn and syn.protect_gui) or protect_gui or protectgui
local writefile_ = writefile
local readfile_ = readfile
local isfile_ = isfile
local isfolder_ = isfolder
local makefolder_ = makefolder
local listfiles_ = listfiles
local delfile_ = delfile
local getcustomasset_ = getcustomasset or getsynasset
local setclipboard_ = setclipboard or toclipboard or set_clipboard
local request_ = (syn and syn.request) or (http and http.request) or http_request or request
local identifyexecutor_ = identifyexecutor or getexecutorname

local function try(fn, ...)
	if type(fn) ~= "function" then
		return false, "unsupported"
	end
	return pcall(fn, ...)
end

do
	local ok, name = try(identifyexecutor_)
	Env.Name = ok and tostring(name) or nil
end
Env.IsExecutor = Env.Name ~= nil or type(getgenv) == "function"
Env.CanUseFiles = type(writefile_) == "function" and type(readfile_) == "function" and type(isfile_) == "function"
Env.CanUseCustomAssets = Env.CanUseFiles and type(getcustomasset_) == "function"

-- Shared table that survives re-executing a script (getgenv), used to find
-- and replace windows created by a previous run of the same script.
function Env.Registry(): { [any]: any }
	local ok, genv = try(getgenv)
	local root = (ok and type(genv) == "table" and genv) or shared or _G
	root.__MD3 = root.__MD3 or {}
	return root.__MD3
end

-- Best container for executor UIs: a hidden UI root when the executor has
-- one, then CoreGui (needs elevated identity), then the player's PlayerGui.
function Env.GetGuiParent(): Instance
	local ok, hui = try(gethui_)
	if ok and typeof(hui) == "Instance" then
		return hui
	end
	local coreOk, coreGui = pcall(function()
		local core = game:GetService("CoreGui")
		-- Parenting into CoreGui is what fails without elevated identity,
		-- so that's the thing to test.
		local probe = Instance.new("Folder")
		probe.Parent = core
		probe:Destroy()
		return core
	end)
	if coreOk and coreGui then
		return coreGui
	end
	local player = Players.LocalPlayer
	return player:FindFirstChildOfClass("PlayerGui") or player:WaitForChild("PlayerGui")
end

function Env.ProtectGui(gui: Instance)
	try(protectGui, gui)
end

-- A random, unremarkable instance name so scripts in the game can't find
-- the UI by searching for a fixed name.
function Env.RandomName(): string
	local chars = table.create(12)
	for i = 1, 12 do
		chars[i] = string.char(math.random(97, 122))
	end
	return table.concat(chars)
end

--== Files ==--

function Env.IsFile(path: string): boolean
	local ok, result = try(isfile_, path)
	return ok and result == true
end

function Env.IsFolder(path: string): boolean
	local ok, result = try(isfolder_, path)
	return ok and result == true
end

function Env.ReadFile(path: string): string?
	if not Env.IsFile(path) then
		return nil
	end
	local ok, content = try(readfile_, path)
	return ok and content or nil
end

function Env.WriteFile(path: string, content: string): boolean
	local ok = try(writefile_, path, content)
	return ok
end

function Env.DeleteFile(path: string): boolean
	local ok = try(delfile_, path)
	return ok
end

-- Creates every folder along `path` ("A/B/C").
function Env.MakeFolder(path: string)
	local current = ""
	for part in string.gmatch(path, "[^/\\]+") do
		current = current == "" and part or `{current}/{part}`
		if not Env.IsFolder(current) then
			try(makefolder_, current)
		end
	end
end

function Env.ListFiles(path: string): { string }
	local ok, files = try(listfiles_, path)
	return ok and type(files) == "table" and files or {}
end

--== Web / misc ==--

function Env.HttpGet(url: string): string?
	local ok, body = pcall(function()
		return game:HttpGet(url)
	end)
	if ok and type(body) == "string" then
		return body
	end
	local reqOk, response = try(request_, { Url = url, Method = "GET" })
	if reqOk and type(response) == "table" and type(response.Body) == "string" then
		return response.Body
	end
	return nil
end

function Env.GetCustomAsset(path: string): string?
	local ok, asset = try(getcustomasset_, path)
	return ok and asset or nil
end

function Env.SetClipboard(text: string): boolean
	local ok = try(setclipboard_, text)
	return ok
end

return Env
end

-- Executor/IconFont.lua
loaders[newNode("IconFont", N_Executor)] = function(script, require)
--[[
	Loads Google's Material Icons font at runtime on executors, so real
	Material glyphs render without uploading a Font asset first.

	Styles (all Apache-2.0, google/material-design-icons):
		"Outlined" (default ??the M3 look), "Filled", "Round", "Sharp"

	Downloads the style's .ttf once into the executor workspace, wraps it in
	a Roblox font-family JSON, and loads that through getcustomasset. Google
	only ships Outlined/Round/Sharp as .otf, so those come from this repo's
	assets/fonts/ (converted to TrueType by tools/convert_icon_fonts.py);
	Filled comes straight from Google. If a non-Filled style can't be loaded
	it falls back to Filled. Needs writefile/readfile + getcustomasset;
	returns nil (leaving the BuilderIcons / plain-glyph fallbacks in place)
	when the executor lacks them.

	local font = MD3.IconFont.Load()             -- Outlined; also calls MD3.Icons.SetFont(font)
	local font = MD3.IconFont.Load("MD3", "Round") -- switch at any time; icons already
	                                               -- on screen are redrawn
	MD3.IconFont.CurrentStyle                    -- style actually loaded (after fallbacks)
]]
local HttpService = game:GetService("HttpService")

local Root = script.Parent.Parent
local Env = require(Root.Executor.Env)
local Icons = require(Root.Core.Icons)

local IconFont = {}

local REPO_FONTS = "https://raw.githubusercontent.com/engnyg/Material-Design-3-Roblox-lua-ui/main/assets/fonts/"

IconFont.DefaultStyle = "Outlined"
IconFont.StyleNames = { "Outlined", "Filled", "Round", "Sharp" }
IconFont.CurrentStyle = nil :: string?
IconFont.Styles = {
	Filled = {
		file = "MaterialIcons-Regular.ttf",
		url = "https://raw.githubusercontent.com/google/material-design-icons/master/font/MaterialIcons-Regular.ttf",
	},
	Outlined = { file = "MaterialIconsOutlined-Regular.ttf", url = REPO_FONTS .. "MaterialIconsOutlined-Regular.ttf" },
	Round = { file = "MaterialIconsRound-Regular.ttf", url = REPO_FONTS .. "MaterialIconsRound-Regular.ttf" },
	Sharp = { file = "MaterialIconsSharp-Regular.ttf", url = REPO_FONTS .. "MaterialIconsSharp-Regular.ttf" },
}
-- Kept for backwards compatibility: the Filled font URL.
IconFont.Url = IconFont.Styles.Filled.url

local loaded: { [string]: Font } = {}

local function loadStyle(folder: string, style: string): (Font?, string?)
	local spec = IconFont.Styles[style]
	Env.MakeFolder(folder)
	local ttfPath = `{folder}/{spec.file}`
	local familyPath = `{folder}/MaterialIcons{style}.json`

	if not Env.IsFile(ttfPath) then
		local data = Env.HttpGet(spec.url)
		-- The real fonts are 350-500 KB; anything tiny is an error page.
		if not data or #data < 10000 then
			return nil, `could not download the {style} icon font`
		end
		if not Env.WriteFile(ttfPath, data) then
			return nil, "could not write the icon font"
		end
	end

	local ttfAsset = Env.GetCustomAsset(ttfPath)
	if not ttfAsset then
		return nil, "getcustomasset failed for the icon font"
	end

	-- The asset id getcustomasset hands out can change between sessions, so
	-- the family file is rewritten every time.
	local family = HttpService:JSONEncode({
		name = `MaterialIcons{style}`,
		faces = { { name = "Regular", weight = 400, style = "normal", assetId = ttfAsset } },
	})
	if not Env.WriteFile(familyPath, family) then
		return nil, "could not write the font family file"
	end
	local familyAsset = Env.GetCustomAsset(familyPath)
	if not familyAsset then
		return nil, "getcustomasset failed for the font family"
	end

	local ok, font = pcall(Font.new, familyAsset, Enum.FontWeight.Regular, Enum.FontStyle.Normal)
	if not ok then
		return nil, tostring(font)
	end
	return font
end

function IconFont.Load(folder: string?, style: string?): (Font?, string?)
	folder = folder or "MD3"
	style = style or IconFont.DefaultStyle
	if loaded[style] then
		IconFont.CurrentStyle = style
		Icons.SetFont(loaded[style])
		return loaded[style]
	end
	if not IconFont.Styles[style] then
		return nil, `unknown icon style "{style}" (use Outlined, Filled, Round or Sharp)`
	end
	if not Env.CanUseCustomAssets then
		return nil, "executor has no writefile/getcustomasset"
	end

	local font, err = loadStyle(folder, style)
	if not font and style ~= "Filled" then
		local fallback = loadStyle(folder, "Filled")
		if fallback then
			warn(`\[MD3] {err}; using the Filled icon style instead`)
			font, err, style = fallback, nil, "Filled"
		end
	end
	if not font then
		return nil, err
	end

	loaded[style] = font
	IconFont.CurrentStyle = style
	Icons.SetFont(font)
	return font
end

return IconFont
end

-- Executor/IconImages.lua
loaders[newNode("IconImages", N_Executor)] = function(script, require)
--[[
	Loads the Material icons as images (sprite sheets) on executors, the
	same way NeverLose loads its images: HttpGet the PNG, writefile it into
	the workspace, then getcustomasset. Images load reliably on executors
	where fonts built from getcustomasset files don't.

	Each style is a set of pages (assets/icons/<Style>/<page>.png in this
	repo, rendered from Google's fonts by tools/build_icon_sheets.py):
		"Outlined" (default ??the M3 look), "Filled", "Round", "Sharp"
	Load() fetches page 0, which has every icon the library draws itself;
	the other pages download the first time one of their icons is shown.

	local ok, err = MD3.IconImages.Load("Round")  -- switch at any time;
	                                                -- icons on screen are redrawn
	MD3.IconImages.CurrentStyle                   -- style currently shown

	If loading fails, icons keep whatever they showed before (another
	style, Roblox's BuilderIcons or plain symbols).
]]
local ContentProvider = game:GetService("ContentProvider")

local Root = script.Parent.Parent
local Env = require(Root.Executor.Env)
local Assets = require(Root.Executor.Assets)
local Icons = require(Root.Core.Icons)
local IconSheet = require(Root.Core.IconSheet)

local IconImages = {}

IconImages.BaseUrl = "https://raw.githubusercontent.com/engnyg/Material-Design-3-Roblox-lua-ui/main/assets/icons/"
IconImages.DefaultStyle = "Outlined"
IconImages.StyleNames = { "Outlined", "Filled", "Round", "Sharp" }
IconImages.CurrentStyle = nil :: string?

local STYLES = {}
for _, style in IconImages.StyleNames do
	STYLES[style] = true
end

local PNG_SIGNATURE = "\137PNG"
local loaded: { [string]: { [number]: string } } = {} -- style -> page -> content id

local function pageUrl(style: string, page: number): string
	return `{IconImages.BaseUrl}{style}/{page}.png`
end

-- The workspace file a page is cached in; the layout version keeps pages
-- of an older layout (or the old single-sheet files) from being reused.
local function fileName(style: string, page: number): string
	return `MaterialIcons{IconSheet.Version}-{style}-{page}.png`
end

-- Downloads (once) and returns the content id for a page of a style.
local function fetch(style: string, page: number): (string?, string?)
	local name = fileName(style, page)
	local path = `{Assets.Folder}/{name}`
	-- A file left over from a failed download would otherwise be reused
	-- forever, so check it really is a PNG.
	local existing = Env.ReadFile(path)
	if existing and existing:sub(1, 4) ~= PNG_SIGNATURE then
		Env.DeleteFile(path)
	end

	local url = pageUrl(style, page)
	local asset, err = Assets.FromUrl(url, name)
	if not asset then
		return nil, err
	end
	local data = Env.ReadFile(path)
	if data and data:sub(1, 4) ~= PNG_SIGNATURE then
		Env.DeleteFile(path)
		Assets.Forget(url)
		return nil, `the downloaded {style} icon sheet is not a PNG`
	end
	return asset
end

-- Asks Roblox to load the image and reports whether it failed. Yields.
local function verify(asset: string): boolean
	local failed = false
	pcall(function()
		ContentProvider:PreloadAsync({ asset }, function(_, status)
			if status == Enum.AssetFetchStatus.Failure then
				failed = true
			end
		end)
	end)
	return not failed
end

-- A style's page, downloaded and checked once (nil + reason on failure).
-- Yields.
local function loadPage(style: string, page: number): (string?, string?)
	local pages = loaded[style]
	if pages and pages[page] then
		return pages[page]
	end
	local asset, err = fetch(style, page)
	if not asset then
		return nil, err
	end
	if not verify(asset) then
		return nil, `Roblox could not load the {style} icon sheet`
	end
	loaded[style] = loaded[style] or {}
	loaded[style][page] = asset
	return asset
end

-- Loads a style and shows it on every icon (existing ones included).
-- Returns true, or false + a reason. May yield (download + image load).
function IconImages.Load(style: string?): (boolean, string?)
	style = style or IconImages.DefaultStyle
	if not STYLES[style] then
		return false, `unknown icon style "{style}" (use Outlined, Filled, Round or Sharp)`
	end
	if not Env.CanUseCustomAssets then
		return false, "executor has no writefile/getcustomasset"
	end

	local asset, err = loadPage(style, 0)
	if not asset then
		return false, err
	end

	IconImages.CurrentStyle = style
	Icons.SetSheet(asset, function(page)
		local image, pageErr = loadPage(style, page)
		if not image then
			warn(`\[MD3] could not load {style} icon page {page}: {pageErr}`)
		end
		return image
	end)
	return true
end

-- Stops using the sprite sheet (back to font / BuilderIcons / symbols).
function IconImages.Unload()
	IconImages.CurrentStyle = nil
	Icons.SetSheet(nil)
end

return IconImages
end

-- Util/Color.lua
loaders[newNode("Color", N_Util)] = function(script, require)
-- Color math used to build Material 3 tonal palettes from a single seed color.
-- Note: this uses HSL as a practical stand-in for Google's HCT color space.
-- It reproduces the *shape* of M3 tonal palettes (13 tones per hue, consistent
-- contrast between roles) without needing the full CAM16 implementation.
local Color = {}

function Color.RGBToHSL(color: Color3)
	local r, g, b = color.R, color.G, color.B
	local max, min = math.max(r, g, b), math.min(r, g, b)
	local h, s, l = 0, 0, (max + min) / 2

	if max ~= min then
		local d = max - min
		s = l > 0.5 and d / (2 - max - min) or d / (max + min)
		if max == r then
			h = (g - b) / d + (g < b and 6 or 0)
		elseif max == g then
			h = (b - r) / d + 2
		else
			h = (r - g) / d + 4
		end
		h = h / 6
	end

	return h, s, l
end

local function hueToRGB(p, q, t)
	if t < 0 then
		t += 1
	end
	if t > 1 then
		t -= 1
	end
	if t < 1 / 6 then
		return p + (q - p) * 6 * t
	end
	if t < 1 / 2 then
		return q
	end
	if t < 2 / 3 then
		return p + (q - p) * (2 / 3 - t) * 6
	end
	return p
end

function Color.HSLToRGB(h: number, s: number, l: number): Color3
	if s <= 0 then
		return Color3.new(l, l, l)
	end

	local q = l < 0.5 and l * (1 + s) or l + s - l * s
	local p = 2 * l - q

	local r = hueToRGB(p, q, h + 1 / 3)
	local g = hueToRGB(p, q, h)
	local b = hueToRGB(p, q, h - 1 / 3)

	return Color3.new(r, g, b)
end

-- Blend two colors, `amount` is the weight of `to` (0-1).
function Color.Blend(from: Color3, to: Color3, amount: number): Color3
	amount = math.clamp(amount, 0, 1)
	return Color3.new(
		from.R + (to.R - from.R) * amount,
		from.G + (to.G - from.G) * amount,
		from.B + (to.B - from.B) * amount
	)
end

-- A "palette" is a hue + saturation pair; :Tone(t) produces the color at
-- lightness t/100, tapering saturation near the extremes like HCT chroma does.
local Palette = {}
Palette.__index = Palette

function Palette.new(hue: number, saturation: number)
	return setmetatable({ Hue = hue % 1, Saturation = math.clamp(saturation, 0, 1) }, Palette)
end

function Palette:Tone(tone: number): Color3
	local l = math.clamp(tone, 0, 100) / 100
	-- Taper saturation as we approach black/white so extreme tones don't clip oddly.
	local taper = 1 - math.abs(l - 0.5) * 2 * 0.35
	return Color.HSLToRGB(self.Hue, self.Saturation * taper, l)
end

function Color.PaletteFromSeed(seed: Color3, saturationOverride: number?, hueShift: number?): typeof(Palette.new(0, 0))
	local h, s, _ = Color.RGBToHSL(seed)
	h = (h + (hueShift or 0)) % 1
	return Palette.new(h, saturationOverride or math.max(s, 0.16))
end

Color.Palette = Palette

return Color
end

-- Util/Create.lua
loaders[newNode("Create", N_Util)] = function(script, require)
-- Declarative instance constructor: Create("Frame"){ Size = ..., [1] = child, ... }
local function Create(className)
	return function(props)
		local inst = Instance.new(className)
		local parent = nil

		for key, value in pairs(props) do
			if type(key) == "number" then
				value.Parent = inst
			elseif key == "Parent" then
				parent = value
			else
				inst[key] = value
			end
		end

		if parent then
			inst.Parent = parent
		end

		return inst
	end
end

return Create
end

-- Util/Maid.lua
loaders[newNode("Maid", N_Util)] = function(script, require)
-- Cleanup helper: tracks connections/instances/callbacks and disposes them together.
local Maid = {}
Maid.__index = Maid

function Maid.new()
	return setmetatable({ _tasks = {} }, Maid)
end

local function cleanupTask(task_)
	local t = typeof(task_)
	if t == "RBXScriptConnection" then
		task_:Disconnect()
	elseif t == "function" then
		task_()
	elseif t == "Instance" then
		task_:Destroy()
	elseif t == "table" and task_.Destroy then
		task_:Destroy()
	elseif t == "table" and task_.Disconnect then
		task_:Disconnect()
	end
end

-- Give the maid something to clean up later. Returns a key you can use with :Remove().
function Maid:GiveTask(job)
	local key = #self._tasks + 1
	self._tasks[key] = job
	return key
end

function Maid:Remove(key)
	local job = self._tasks[key]
	if job then
		cleanupTask(job)
		self._tasks[key] = nil
	end
end

function Maid:DoCleaning()
	local tasks = self._tasks
	self._tasks = {}
	for _, job in pairs(tasks) do
		cleanupTask(job)
	end
end

Maid.Destroy = Maid.DoCleaning

return Maid
end

-- Util/Signal.lua
loaders[newNode("Signal", N_Util)] = function(script, require)
-- Lightweight signal implementation (avoids BindableEvent overhead).
local Signal = {}
Signal.__index = Signal

function Signal.new()
	return setmetatable({ _handlers = {} }, Signal)
end

function Signal:Connect(fn)
	local handlers = self._handlers
	local connection = { _connected = true }
	handlers[connection] = fn

	function connection:Disconnect()
		if self._connected then
			self._connected = false
			handlers[self] = nil
		end
	end

	return connection
end

function Signal:Fire(...)
	-- Snapshot first: task.spawn runs handlers immediately, and a handler that
	-- connects, disconnects or calls DisconnectAll (e.g. Dialog.Dismissed ->
	-- Destroy) would otherwise break pairs() with "invalid key to 'next'".
	local snapshot = {}
	for connection, fn in pairs(self._handlers) do
		snapshot[#snapshot + 1] = connection
		snapshot[#snapshot + 1] = fn
	end
	for i = 1, #snapshot, 2 do
		if snapshot[i]._connected then
			task.spawn(snapshot[i + 1], ...)
		end
	end
end

function Signal:DisconnectAll()
	for connection in pairs(self._handlers) do
		connection._connected = false
	end
	table.clear(self._handlers)
end

return Signal
end

-- Window/Config.lua
loaders[newNode("Config", N_Window)] = function(script, require)
-- (De)serializes flag values to JSON for config files. JSON has no Color3
-- or EnumItem, so those are wrapped in small tagged tables.
local HttpService = game:GetService("HttpService")

local Config = {}

function Config.Serialize(value)
	local t = typeof(value)
	if t == "Color3" then
		return { __type = "Color3", hex = value:ToHex() }
	elseif t == "EnumItem" then
		return { __type = "EnumItem", enum = tostring(value.EnumType), name = value.Name }
	elseif t == "table" then
		local out = {}
		for k, v in value do
			out[k] = Config.Serialize(v)
		end
		return out
	end
	return value
end

function Config.Deserialize(value)
	if type(value) ~= "table" then
		return value
	end
	if value.__type == "Color3" then
		return Color3.fromHex(value.hex)
	elseif value.__type == "EnumItem" then
		local ok, item = pcall(function()
			return (Enum :: any)[value.enum][value.name]
		end)
		return ok and item or nil
	end
	local out = {}
	for k, v in value do
		out[k] = Config.Deserialize(v)
	end
	return out
end

-- flags: { [flagName] = element } -> JSON string of every element's value
function Config.Encode(flags): string
	local data = {}
	for flag, element in flags do
		if element.Save ~= false then
			-- Elements that store more than .Value (e.g. a color picker's
			-- transparency) provide GetSaveValue; Set accepts what it returns.
			local value = if element.GetSaveValue then element:GetSaveValue() else element.Value
			data[flag] = Config.Serialize(value)
		end
	end
	return HttpService:JSONEncode(data)
end

function Config.Decode(json: string): { [string]: any }?
	local ok, data = pcall(HttpService.JSONDecode, HttpService, json)
	if not ok or type(data) ~= "table" then
		return nil
	end
	local out = {}
	for flag, value in data do
		out[flag] = Config.Deserialize(value)
	end
	return out
end

return Config
end

-- Window/Container.lua
loaders[newNode("Container", N_Window)] = function(script, require)
-- Mixin giving Tabs and Sections the same element API:
--   AddButton / AddToggle / AddSlider / AddInput / AddDropdown / AddKeybind /
--   AddColorPicker / AddLabel / AddParagraph / AddDivider
-- Each also has a Create* alias (CreateToggle, ...) for scripts written
-- against other executor UI libraries.
local Elements = script.Parent.Elements
local Text = require(Elements.Text)

local BUILDERS = {
	Button = require(Elements.Button),
	Toggle = require(Elements.Toggle),
	Slider = require(Elements.Slider),
	Input = require(Elements.Input),
	Dropdown = require(Elements.Dropdown),
	Keybind = require(Elements.Keybind),
	ColorPicker = require(Elements.ColorPicker),
	Label = Text.Label,
	Paragraph = Text.Paragraph,
	Divider = Text.Divider,
}

local ALIASES = {
	Textbox = "Input",
	TextBox = "Input",
	Bind = "Keybind",
	Colorpicker = "ColorPicker",
}

local Container = {}

function Container.extend(class)
	for name, builder in BUILDERS do
		local function add(self, props)
			props = props or {}
			local element = builder(self, props)
			table.insert(self._elements, element)

			local window = self._window or (self._tab and self._tab._window)
			local elementName = props.Title or props.Text or props.Name
			if window and window._registerSearchable and elementName and elementName ~= "" and name ~= "Divider" then
				local tab = self._tab or self
				local subTab = self._subTab
				local pathParts = { tab.Title or "Tab" }
				if subTab then
					table.insert(pathParts, subTab)
				end
				if self.Title and self.Title ~= "" and self ~= tab and self.Title ~= subTab then
					table.insert(pathParts, self.Title)
				end
				table.insert(pathParts, elementName)

				window:_registerSearchable({
					name = elementName,
					path = table.concat(pathParts, " > "),
					tab = tab,
					subTab = subTab,
					target = element.Instance,
				})
			end

			return element
		end
		class["Add" .. name] = add
		class["Create" .. name] = add
	end
	for alias, target in ALIASES do
		class["Add" .. alias] = class["Add" .. target]
		class["Create" .. alias] = class["Add" .. target]
	end

	function class:_nextOrder()
		self._order += 1
		return self._order
	end
end

return Container
end

-- Window/Draggable.lua
loaders[newNode("Draggable", N_Window)] = function(script, require)
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local function isPress(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function isMove(input)
	return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
end

local function getEffectiveScale(obj: Instance?): number
	local scale = 1
	local current = obj
	while current and not current:IsA("DataModel") do
		if current:IsA("GuiObject") then
			local uiScale = current:FindFirstChildOfClass("UIScale")
			if uiScale and uiScale.Scale then
				scale = scale * uiScale.Scale
			end
		end
		current = current.Parent
	end
	return math.max(scale, 0.001)
end

-- Shared controller registry per target GuiObject so multiple handles
-- (e.g. watermark background + multiple blocks, indicator stack + chips)
-- share drag state and never fight each other.
local controllers = setmetatable({}, { __mode = "k" })

local function getOrCreateController(target: GuiObject)
	local existing = controllers[target]
	if existing then
		return existing
	end

	local controller = {
		target = target,
		handles = {},
		dragging = false,
		settling = false,
		moved = false,
		dragInput = nil,
		startInput = nil,
		startPos = target.Position,
		targetOffset = Vector2.new(target.Position.X.Offset, target.Position.Y.Offset),
		activeHandle = nil,
		activeConfig = nil,
	}

	local function getScreenClamp(ox: number, oy: number)
		local parent = target.Parent
		local pSize = parent and parent.AbsoluteSize or (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080))
		local effScale = getEffectiveScale(parent)
		local parentW = pSize.X / effScale
		local parentH = pSize.Y / effScale
		local w = target.AbsoluteSize.X / effScale
		local h = target.AbsoluteSize.Y / effScale

		if target.AnchorPoint.X == 0.5 and target.AnchorPoint.Y == 0.5 then
			local halfW = w / 2
			local halfH = h / 2
			local minX = -parentW * 0.5 + halfW + 8
			local maxX = parentW * 0.5 - halfW - 8
			local minY = -parentH * 0.5 + halfH + 8
			local maxY = parentH * 0.5 - halfH - 8
			return math.clamp(ox, minX, maxX), math.clamp(oy, minY, maxY)
		else
			local minX = 8
			local maxX = math.max(8, parentW - w - 8)
			local minY = 8
			local maxY = math.max(8, parentH - h - 8)
			return math.clamp(ox, minX, maxX), math.clamp(oy, minY, maxY)
		end
	end

	local connChanged = UserInputService.InputChanged:Connect(function(input)
		if not controller.dragging or not isMove(input) then
			return
		end
		if input.UserInputType == Enum.UserInputType.Touch and controller.dragInput and input ~= controller.dragInput then
			return
		end
		if input.UserInputType == Enum.UserInputType.MouseMovement and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
			controller.dragging = false
			return
		end

		local effScale = getEffectiveScale(target.Parent)
		local delta = (input.Position - controller.startInput) / effScale
		if delta.Magnitude > 2 then
			controller.moved = true
		end

		local rawX = controller.startPos.X.Offset + delta.X
		local rawY = controller.startPos.Y.Offset + delta.Y

		local config = controller.activeConfig
		local clampScreen = not config or (config.options and config.options.ClampScreen ~= false)
		if clampScreen then
			local cx, cy = getScreenClamp(rawX, rawY)
			controller.targetOffset = Vector2.new(cx, cy)
		else
			controller.targetOffset = Vector2.new(rawX, rawY)
		end

		local smooth = config and config.options and config.options.Smooth == true
		if not smooth then
			target.Position = UDim2.new(controller.startPos.X.Scale, math.round(controller.targetOffset.X), controller.startPos.Y.Scale, math.round(controller.targetOffset.Y))
		end
	end)

	local connEnded = UserInputService.InputEnded:Connect(function(input)
		if controller.dragging and isPress(input) then
			if input.UserInputType == Enum.UserInputType.Touch and controller.dragInput and input ~= controller.dragInput then
				return
			end
			controller.dragging = false
			local config = controller.activeConfig
			local wasMoved = controller.moved
			local smooth = config and config.options and config.options.Smooth == true
			if not smooth then
				controller.settling = false
				target.Position = UDim2.new(controller.startPos.X.Scale, math.round(controller.targetOffset.X), controller.startPos.Y.Scale, math.round(controller.targetOffset.Y))
			end

			if not wasMoved and config and config.onClick then
				config.onClick()
			elseif wasMoved and config and config.onDragEnd then
				config.onDragEnd()
			end
		end
	end)

	local connRender = RunService.RenderStepped:Connect(function(dt)
		local config = controller.activeConfig
		local smooth = config and config.options and config.options.Smooth == true
		if not smooth or (not controller.dragging and not controller.settling) then
			return
		end
		local curX = target.Position.X.Offset
		local curY = target.Position.Y.Offset
		local dist = math.sqrt((curX - controller.targetOffset.X) ^ 2 + (curY - controller.targetOffset.Y) ^ 2)
		if dist > 0.4 then
			local factor = 1 - math.exp(-24 * dt)
			local newX = curX + (controller.targetOffset.X - curX) * factor
			local newY = curY + (controller.targetOffset.Y - curY) * factor
			target.Position = UDim2.new(controller.startPos.X.Scale, math.round(newX), controller.startPos.Y.Scale, math.round(newY))
		else
			if not controller.dragging then
				controller.settling = false
				target.Position = UDim2.new(controller.startPos.X.Scale, math.round(controller.targetOffset.X), controller.startPos.Y.Scale, math.round(controller.targetOffset.Y))
			end
		end
	end)

	local connDestroying = target.Destroying:Connect(function()
		if controller.cleanup then
			controller.cleanup()
		end
	end)

	controller.cleanup = function()
		connChanged:Disconnect()
		connEnded:Disconnect()
		connRender:Disconnect()
		connDestroying:Disconnect()
		controllers[target] = nil
	end

	controllers[target] = controller
	return controller
end

return function(maid, handle: GuiObject, target: GuiObject, onClick, onDragEnd, options)
	options = options or {}
	local controller = getOrCreateController(target)
	local config = {
		onClick = onClick,
		onDragEnd = onDragEnd,
		options = options,
	}
	controller.handles[handle] = config

	local connBegan = handle.InputBegan:Connect(function(input)
		if not isPress(input) then
			return
		end
		-- In FPS games, don't drag UI when mouse is locked for aiming/shooting.
		if input.UserInputType == Enum.UserInputType.MouseButton1 and UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
			return
		end
		-- If already dragging (e.g. from another handle on the same target), ignore.
		if controller.dragging then
			return
		end

		controller.dragging = true
		controller.settling = true
		controller.moved = false
		controller.dragInput = input
		controller.startInput = input.Position
		controller.activeHandle = handle
		controller.activeConfig = config

		-- Normalize AnchorPoint to (0, 0) and Position to pure offset for HUD widgets
		-- so presets with Scale (1, 0.5) don't distort or jump during dragging.
		-- Preserve (0.5, 0.5) for the center-anchored main Window.
		if not (target.AnchorPoint.X == 0.5 and target.AnchorPoint.Y == 0.5 and target.Position.X.Scale == 0.5 and target.Position.Y.Scale == 0.5) then
			if target.AnchorPoint ~= Vector2.new(0, 0) or target.Position.X.Scale ~= 0 or target.Position.Y.Scale ~= 0 then
				local parent = target.Parent
				local pAbs = parent and parent.AbsolutePosition or Vector2.new(0, 0)
				local effScale = getEffectiveScale(parent)
				local localX = (target.AbsolutePosition.X - pAbs.X) / effScale
				local localY = (target.AbsolutePosition.Y - pAbs.Y) / effScale
				target.AnchorPoint = Vector2.new(0, 0)
				target.Position = UDim2.fromOffset(math.round(localX), math.round(localY))
			end
		end

		controller.startPos = target.Position
		controller.targetOffset = Vector2.new(target.Position.X.Offset, target.Position.Y.Offset)
	end)

	maid:GiveTask(connBegan)
	maid:GiveTask(function()
		controller.handles[handle] = nil
		if next(controller.handles) == nil then
			controller.cleanup()
		end
	end)
end
end

-- Window/Elements/Base.lua
loaders[newNode("Base", N_Window_Elements)] = function(script, require)
-- Shared plumbing for executor-window elements: the common element object
-- (Value / Set / Get / Flag / Callback), the M3 list-item row every element
-- is laid out in, and small glyph/state-layer helpers.
local UserInputService = game:GetService("UserInputService")

local Root = script.Parent.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local StateLayer = require(Root.Core.StateLayer)
local Ripple = require(Root.Core.Ripple)
local Icons = require(Root.Core.Icons)
local Assets = require(Root.Executor.Assets)

local Base = {}

local Element = {}
Element.__index = Element
Base.ElementClass = Element

function Base.Element(container, props, kind: string)
	local window = container._window
	local self = setmetatable({
		Type = kind,
		Flag = props.Flag,
		Value = nil,
		Changed = Signal.new(),
		_window = window,
		_container = container,
		_maid = Maid.new(),
		_callback = props.Callback,
	}, Element)
	return self
end

function Element:Get()
	return self.Value
end

-- Sets the value, updates the visuals and (unless `silent`) fires Changed
-- and the element's Callback ??same path as a user interaction.
function Element:Set(value, silent: boolean?)
	if self._normalize then
		value = self._normalize(value)
	end
	self.Value = value
	if self._render then
		self._render(value)
	end
	if not silent then
		self:_emit(value)
	end
end

function Element:_emit(...)
	self.Changed:Fire(...)
	if self._callback then
		self._window:_call(self._callback, ...)
	end
end

function Element:OnChanged(fn)
	return self.Changed:Connect(fn)
end

function Element:SetCallback(fn)
	self._callback = fn
end

function Element:SetVisible(visible: boolean)
	self.Instance.Visible = visible
end

function Element:SetTitle(text: string)
	if self._title then
		self._title.Text = text
	end
end

function Element:SetDescription(text: string?)
	if self._desc then
		self._desc.Text = text or ""
		self._desc.Visible = (text or "") ~= ""
	end
end

function Element:Destroy()
	if self.Flag and self._window.Flags[self.Flag] == self then
		self._window.Flags[self.Flag] = nil
	end
	self._maid:Destroy()
	self.Changed:DisconnectAll()
	if self.Instance then
		self.Instance:Destroy()
	end
end

-- Registers the element under its Flag (if any) and returns it.
function Base.Finish(element)
	if element.Flag then
		element._window.Flags[element.Flag] = element
	end
	return element
end

-- An icon: either an image (URL / rbxassetid / workspace file, loaded via
-- Assets) as an ImageLabel, or a Material icon name as a glyph TextLabel.
-- Hidden when it can't be drawn. `role` tints it: a theme color role name
-- ("Icon", "Primary", ...) or a fixed Color3. Pass tint = false to keep a
-- colored image (e.g. a logo) as-is.
function Base.Glyph(themer, name, size: number, role, parent: Instance?, tint: boolean?)
	if Assets.IsImage(name) then
		local image = Create("ImageLabel") {
			Name = "Icon",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(size, size),
			Image = Assets.Resolve(name),
			ScaleType = Enum.ScaleType.Fit,
			Parent = parent,
		}
		image.Visible = image.Image ~= ""
		if role and tint ~= false then
			themer:Bind(image, { ImageColor3 = role })
		end
		return image
	end

	local label = Create("TextLabel") {
		Name = "Icon",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(size, size),
		TextSize = size,
		Font = Enum.Font.GothamMedium,
		Visible = Icons.CanRender(name),
		Parent = parent,
	}
	-- Icons manages Visible: hidden while no source can draw the icon, shown
	-- once the icon images (or a font) arrive.
	Icons.Apply(label, name, true)
	if role then
		themer:Bind(label, { TextColor3 = role })
	end
	return label
end
Base.Icon = Base.Glyph

-- True for images and for any icon that can be drawn now or once the icon
-- images finish loading.
function Base.CanShowIcon(icon): boolean
	return Assets.IsImage(icon) or Icons.CanRender(icon) or (type(icon) == "string" and Icons.Codepoints[icon] ~= nil)
end

-- Colors an icon made by Base.Glyph, whichever kind it is (optionally
-- with a transparency, 0 = solid).
function Base.SetIconColor(icon: GuiObject, color: Color3, transparency: number?)
	if icon:IsA("ImageLabel") then
		icon.ImageColor3 = color
		icon.ImageTransparency = transparency or 0
	else
		icon.TextColor3 = color
		icon.TextTransparency = transparency or 0
	end
end

--[[
	Lays out an M3 list item:

	?��??�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�??
	??Title                              [control] ?? <- Header
	??Description                                  ??
	??[extra content, e.g. slider / dropdown list] ?? <- :Extra()
	?��??�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�?�??

	opts.ClassName: "Frame" | "TextButton" (whole row clickable)
	opts.ControlWidth / opts.ControlHeight: size of the right-hand slot
]]
function Base.Row(element, props, opts)
	opts = opts or {}
	local container = element._container
	local themer = element._window._themer
	local controlWidth = opts.ControlWidth or 0
	local controlHeight = opts.ControlHeight or 0

	local frame = Create(opts.ClassName or "Frame") {
		Name = props.Title or element.Type,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = container:_nextOrder(),
	}
	if frame:IsA("TextButton") then
		frame.AutoButtonColor = false
		frame.Text = ""
		frame.ClipsDescendants = true -- keeps ripples inside the rounded row
	end
	Shape.Corner(Shape.Medium, frame)
	themer:Bind(frame, { BackgroundColor3 = "SurfaceContainerHigh" })

	-- Padding + list layout live on an inner frame so overlays parented to
	-- the row itself (state layer, ripples) aren't pulled into the layout.
	local body = Create("Frame") {
		Name = "Body",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		[1] = Create("UIPadding") {
			PaddingTop = UDim.new(0, 10),
			PaddingBottom = UDim.new(0, 10),
			PaddingLeft = UDim.new(0, 16),
			PaddingRight = UDim.new(0, 12),
		},
		[2] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
		},
		Parent = frame,
	}

	local header = Create("Frame") {
		Name = "Header",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, math.max(controlHeight, 24)),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = body,
	}
	Create("UIListLayout") {
		FillDirection = Enum.FillDirection.Horizontal,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 12),
		Parent = header,
	}

	local text = Create("Frame") {
		Name = "Text",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, controlWidth > 0 and -(controlWidth + 12) or 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = header,
	}
	Create("UIListLayout") {
		FillDirection = Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 2),
		Parent = text,
	}

	local title = Create("TextLabel") {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = props.Title or props.Name or "",
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 1,
		Parent = text,
	}
	Typography.Apply(title, "BodyLarge")
	themer:Bind(title, { TextColor3 = "OnSurface" })

	local descText = props.Description or props.Desc or props.Content or ""
	local desc = Create("TextLabel") {
		Name = "Description",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = descText,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		Visible = descText ~= "",
		LayoutOrder = 2,
		Parent = text,
	}
	Typography.Apply(desc, "BodyMedium")
	themer:Bind(desc, { TextColor3 = "OnSurfaceVariant" })

	local control = nil
	if controlWidth > 0 then
		control = Create("Frame") {
			Name = "Control",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(controlWidth, controlHeight),
			LayoutOrder = 2,
			Parent = header,
		}
	end

	element.Instance = frame
	element._title = title
	element._desc = desc
	frame.Parent = container._holder

	local row = { Frame = frame, Body = body, Header = header, Control = control, Title = title, Description = desc }

	-- Lazily creates the full-width area under the header.
	function row.Extra(visible: boolean?)
		if not row._extra then
			row._extra = Create("Frame") {
				Name = "Extra",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				Visible = visible ~= false,
				LayoutOrder = 2,
				Parent = body,
			}
		end
		return row._extra
	end

	return row
end

-- Hover/press state layer + ripple for a clickable surface.
-- opts.Header = the row (from Base.Row) of an element that opens content
-- below its header (a color picker): the layer and ripples then cover only
-- the header, and presses on the opened content don't light the row up.
-- Returns the state layer and a function telling whether an input is on
-- the pressable part.
function Base.Interactive(element, button: GuiButton, role: string?, opts)
	opts = opts or {}
	local theme = element._window.Theme
	local surface = button
	local header = opts.Header
	if header then
		-- A clipping frame over the header: holds the layer and the ripples.
		surface = Create("Frame") {
			Name = "Touch",
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Size = UDim2.new(1, 0, 1, 0),
			ZIndex = button.ZIndex,
			Parent = button,
		}
		Shape.Corner(Shape.Medium, surface)
		local function fit()
			-- From the top of the row to just under the header (its padding).
			local height = header.Header.AbsolutePosition.Y + header.Header.AbsoluteSize.Y + 10 - button.AbsolutePosition.Y
			surface.Size = UDim2.new(1, 0, 0, math.max(height, 0))
		end
		fit()
		element._maid:GiveTask(button:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
		element._maid:GiveTask(header.Header:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
	end

	local function isPress(input)
		return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
	end
	local function onSurface(input): boolean
		if surface == button then
			return true
		end
		local top = surface.AbsolutePosition.Y
		return input.Position.Y >= top and input.Position.Y <= top + surface.AbsoluteSize.Y
	end

	local layer = StateLayer.new(surface, theme.Colors[role or "OnSurface"], Shape.Medium)
	element._maid:GiveTask(layer)
	element._maid:GiveTask(theme.Changed:Connect(function()
		layer:SetColor(theme.Colors[role or "OnSurface"])
	end))
	-- On touch-only devices MouseEnter fires on a tap but MouseLeave often
	-- never does, which left the hover tint stuck; hover is for mice.
	local hoverable = not (UserInputService.TouchEnabled and not UserInputService.MouseEnabled)
	element._maid:GiveTask(button.MouseEnter:Connect(function()
		if hoverable then
			layer:SetState("Hover", true)
		end
	end))
	element._maid:GiveTask(button.MouseLeave:Connect(function()
		layer:SetState("Hover", false)
		layer:SetState("Pressed", false)
	end))
	element._maid:GiveTask(button.InputBegan:Connect(function(input)
		if isPress(input) and onSurface(input) then
			layer:SetState("Pressed", true)
			Ripple.Emit(surface, input.Position, theme.Colors[role or "OnSurface"])
		end
	end))
	element._maid:GiveTask(button.InputEnded:Connect(function(input)
		if isPress(input) then
			layer:SetState("Pressed", false)
		end
	end))
	return layer, onSurface
end

-- A small rounded input "field" used by Input / Dropdown / Slider value box.
function Base.Field(themer, className: string, parent: Instance, size: UDim2)
	local field = Create(className) {
		Name = "Field",
		BorderSizePixel = 0,
		Size = size,
		Text = "",
		Parent = parent,
	}
	if field:IsA("TextButton") then
		field.AutoButtonColor = false
	end
	Shape.Corner(Shape.Small, field)
	themer:Bind(field, { BackgroundColor3 = "SurfaceContainerHighest" })
	local stroke = Create("UIStroke") {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
		Parent = field,
	}
	themer:Bind(stroke, { Color = "OutlineVariant" })
	return field, stroke
end

return Base
end

-- Window/Elements/Button.lua
loaders[newNode("Button", N_Window_Elements)] = function(script, require)
-- Tab:AddButton({ Title = "Rejoin", Description = "...", Icon = "refresh", Callback = function() end })
-- IconColor: a theme role ("Error", "Primary", ...) or a Color3; default "Icon".
local Base = require(script.Parent.Base)

return function(container, props)
	local element = Base.Element(container, props, "Button")
	local themer = element._window._themer
	element.Flag = nil -- buttons hold no value to save

	local row = Base.Row(element, props, { ClassName = "TextButton", ControlWidth = 24, ControlHeight = 24 })
	Base.Glyph(themer, props.Icon or "chevron_right", 24, props.IconColor or "Icon", row.Control)
	Base.Interactive(element, row.Frame)

	element._maid:GiveTask(row.Frame.Activated:Connect(function()
		element:_emit()
	end))

	-- Runs the callback as if the button was clicked.
	function element:Fire()
		self:_emit()
	end

	return Base.Finish(element)
end
end

-- Window/Elements/ColorPicker.lua
loaders[newNode("ColorPicker", N_Window_Elements)] = function(script, require)
--[[
	Tab:AddColorPicker({
		Title = "ESP color",
		Default = Color3.fromRGB(255, 80, 80),
		Flag = "EspColor",
		Callback = function(color) end,
	})

	Click the row's header to open (animated) a saturation/value square, a
	hue bar and a hex field; :SetExpanded(open) does it from code.

	Transparency: pass Transparency = 0..1 (or Alpha = true) to add an
	opacity bar. The callback then gets (color, transparency), .Transparency
	holds the current value, :Set accepts { Color = c, Transparency = t },
	and both are saved in configs.
]]
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")

local Root = script.Parent.Parent.Parent
local Base = require(script.Parent.Base)
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)

local PICKER_HEIGHT = 128
local HUE_WIDTH = 16
local ALPHA_HEIGHT = 16

local function isPress(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function isMove(input)
	return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
end

return function(container, props)
	local element = Base.Element(container, props, "ColorPicker")
	local window = element._window
	local themer = window._themer

	local alphaEnabled = props.Transparency ~= nil or props.Alpha == true
	element.Transparency = if alphaEnabled then math.clamp(props.Transparency or 0, 0, 1) else 0

	-- Lin67: gradient / animation state ------------------------------------------
	local ext = { mode = "Solid", stops = nil, sel = nil, anim = "None", speed = 1, restoring = false }
	local function toColor(v)
		if typeof(v) == "Color3" then
			return v
		elseif type(v) == "string" then
			local ok, color = pcall(Color3.fromHex, v)
			if ok then
				return color
			end
		end
		return nil
	end
	function ext.parse(value)
		if type(value.Mode) ~= "string" then
			return
		end
		ext.restoring = true
		ext.mode = if value.Mode == "Gradient" then "Gradient" else "Solid"
		ext.anim = if value.Anim == "Breathing" or value.Anim == "Rainbow" or value.Anim == "Cycle" then value.Anim else "None"
		if type(value.Speed) == "number" then
			ext.speed = math.clamp(value.Speed, 0.1, 5)
		end
		local solid = toColor(value.Color)
		if solid then
			ext.solid = solid
		end
		if type(value.Stops) == "table" then
			local list = {}
			for _, stop in value.Stops do
				local col = type(stop) == "table" and toColor(stop.Color) or nil
				if col and type(stop.Pos) == "number" then
					table.insert(list, { pos = math.clamp(stop.Pos, 0, 1), color = col })
				end
			end
			if #list >= 2 then
				table.sort(list, function(a, b)
					return a.pos < b.pos
				end)
				ext.stops = list
				ext.sel = list[1]
			end
		end
	end

	local function normalize(value)
		if type(value) == "table" then
			-- { Color = Color3, Transparency = number } (also what configs store)
			if alphaEnabled and type(value.Transparency) == "number" then
				element.Transparency = math.clamp(value.Transparency, 0, 1)
			end
			ext.parse(value)
			value = value.Color
		end
		if typeof(value) == "Color3" then
			return value
		elseif type(value) == "string" then
			local ok, color = pcall(Color3.fromHex, value)
			if ok then
				return color
			end
		end
		return element.Value or Color3.new(1, 1, 1)
	end

	element.Value = normalize(props.Default or props.Value or props.Color)
	ext.solid = ext.solid or element.Value
	if not ext.stops then
		local h0, s0, v0 = ext.solid:ToHSV()
		ext.stops = {
			{ pos = 0, color = ext.solid },
			{ pos = 1, color = Color3.fromHSV((h0 + 0.12) % 1, s0, v0) },
		}
		ext.sel = ext.stops[1]
	end
	local hue, sat, val = element.Value:ToHSV()

	local row = Base.Row(element, props, { ClassName = "TextButton", ControlWidth = 44, ControlHeight = 28 })
	-- Press feedback only on the header, not over the picker once it's open.
	local _, onHeader = Base.Interactive(element, row.Frame, nil, { Header = row })

	local swatch = Create("Frame") {
		Name = "Swatch",
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = element.Value,
		Parent = row.Control,
	}
	Shape.Corner(Shape.Small, swatch)
	themer:Bind(Create("UIStroke") {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
		Parent = swatch,
	}, { Color = "Outline" })

	-- Rows below the square: [opacity bar] then hex / RGB.
	local infoY = PICKER_HEIGHT + 10 + (if alphaEnabled then ALPHA_HEIGHT + 10 else 0)
	local panelHeight = infoY + 176
	local panel = row.Extra(false)
	panel.Size = UDim2.new(1, 0, 0, panelHeight)
	panel.AutomaticSize = Enum.AutomaticSize.None

	-- Saturation (x) / value (y) square: hue background, a white->clear
	-- gradient left to right, then a clear->black gradient top to bottom.
	local svBox = Create("TextButton") {
		Name = "SaturationValue",
		AutoButtonColor = false,
		Text = "",
		BorderSizePixel = 0,
		Size = UDim2.new(1, -(HUE_WIDTH + 12), 0, PICKER_HEIGHT),
		Parent = panel,
	}
	Shape.Corner(Shape.Small, svBox)
	local whiteLayer = Create("Frame") {
		Name = "Saturation",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		Parent = svBox,
		[1] = Create("UIGradient") {
			Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }),
		},
	}
	Shape.Corner(Shape.Small, whiteLayer)
	local blackLayer = Create("Frame") {
		Name = "Value",
		BackgroundColor3 = Color3.new(0, 0, 0),
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		Parent = svBox,
		[1] = Create("UIGradient") {
			Rotation = 90,
			Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }),
		},
	}
	Shape.Corner(Shape.Small, blackLayer)
	local svCursor = Create("Frame") {
		Name = "Cursor",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = UDim2.fromOffset(14, 14),
		BorderSizePixel = 0,
		ZIndex = 3,
		Parent = svBox,
		[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
		[2] = Create("UIStroke") { Color = Color3.new(1, 1, 1), Thickness = 2 },
	}

	local hueKeypoints = {}
	for i = 0, 6 do
		table.insert(hueKeypoints, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV((i / 6) % 1, 1, 1)))
	end
	local hueBar = Create("TextButton") {
		Name = "Hue",
		AutoButtonColor = false,
		Text = "",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.fromScale(1, 0),
		Size = UDim2.fromOffset(HUE_WIDTH, PICKER_HEIGHT),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Parent = panel,
		[1] = Create("UIGradient") { Rotation = 90, Color = ColorSequence.new(hueKeypoints) },
	}
	Shape.Corner(Shape.Full, hueBar)
	local hueCursor = Create("Frame") {
		Name = "Cursor",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = UDim2.new(1, 6, 0, 6),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		ZIndex = 3,
		Parent = hueBar,
		[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
	}
	themer:Bind(Create("UIStroke") { Thickness = 1, Parent = hueCursor }, { Color = "Outline" })

	-- Opacity bar: the current color fading from see-through (left) to
	-- solid (right) over an outline-colored track, so the fade is visible.
	local alphaBar, alphaFill, alphaCursor = nil, nil, nil
	if alphaEnabled then
		alphaBar = Create("TextButton") {
			Name = "Opacity",
			AutoButtonColor = false,
			Text = "",
			Position = UDim2.fromOffset(0, PICKER_HEIGHT + 10),
			Size = UDim2.new(1, 0, 0, ALPHA_HEIGHT),
			BorderSizePixel = 0,
			Parent = panel,
		}
		Shape.Corner(Shape.Full, alphaBar)
		themer:Bind(alphaBar, { BackgroundColor3 = "OutlineVariant" })
		alphaFill = Create("Frame") {
			Name = "Fill",
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			Parent = alphaBar,
			[1] = Create("UIGradient") {
				Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }),
			},
		}
		Shape.Corner(Shape.Full, alphaFill)
		alphaCursor = Create("Frame") {
			Name = "Cursor",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(1, 0.5),
			Size = UDim2.fromOffset(6, ALPHA_HEIGHT + 6),
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			ZIndex = 3,
			Parent = alphaBar,
			[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
		}
		themer:Bind(Create("UIStroke") { Thickness = 1, Parent = alphaCursor }, { Color = "Outline" })
	end

	local hexBox = Base.Field(themer, "TextBox", panel, UDim2.fromOffset(120, 28))
	hexBox.Position = UDim2.fromOffset(0, infoY)
	hexBox.ClearTextOnFocus = false
	hexBox.TextXAlignment = Enum.TextXAlignment.Left
	Typography.Apply(hexBox, "BodyMedium")
	themer:Bind(hexBox, { TextColor3 = "OnSurface" })
	Create("UIPadding") { PaddingLeft = UDim.new(0, 10), Parent = hexBox }

	local rgbLabel = Create("TextLabel") {
		Name = "RGB",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(132, infoY),
		Size = UDim2.new(1, -132, 0, 28),
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = panel,
	}
	Typography.Apply(rgbLabel, "BodySmall")
	themer:Bind(rgbLabel, { TextColor3 = "OnSurfaceVariant" })

	-- Lin67: solid / gradient stops / animation controls --------------------------
	local paint, paintBase
	local getEdit, setEdit, refresh, paintExtras, syncAnim
	local EXTRA_Y = infoY + 40
	local MAX_STOPS = 8

	local function sortStops()
		table.sort(ext.stops, function(a, b)
			return a.pos < b.pos
		end)
	end

	function getEdit()
		if ext.mode == "Gradient" and ext.sel then
			return ext.sel.color
		end
		return ext.solid
	end

	function setEdit(color)
		if ext.mode == "Gradient" and ext.sel then
			ext.sel.color = color
		else
			ext.solid = color
		end
	end

	local function loadEditIntoHSV()
		local h, s, v = getEdit():ToHSV()
		if s > 0 then
			hue = h
		end
		sat, val = s, v
	end

	local function sampleList(list, p)
		if p <= list[1].pos then
			return list[1].color
		end
		for i = 2, #list do
			if p <= list[i].pos then
				local a, b = list[i - 1], list[i]
				return a.color:Lerp(b.color, (p - a.pos) / math.max(b.pos - a.pos, 1e-4))
			end
		end
		return list[#list].color
	end

	local function sampleLoop(p)
		local list = table.clone(ext.stops)
		table.insert(list, { pos = ext.stops[1].pos + 1, color = ext.stops[1].color })
		return sampleList(list, ext.stops[1].pos + p)
	end

	local function evaluate(t)
		local anim, speed = ext.anim, ext.speed
		if anim == "Rainbow" then
			return Color3.fromHSV((t * speed * 0.15) % 1, 1, 1)
		end
		if ext.mode == "Gradient" then
			if anim == "Breathing" then
				return sampleList(ext.stops, 0.5 - 0.5 * math.cos(t * speed * 1.2))
			elseif anim == "Cycle" then
				return sampleLoop((t * speed * 0.2) % 1)
			end
			return ext.stops[1].color
		end
		if anim == "Breathing" then
			local f = 0.5 + 0.5 * math.sin(t * speed * 2)
			return ext.solid:Lerp(Color3.new(0, 0, 0), (1 - f) * 0.8)
		elseif anim == "Cycle" then
			local h, s, v = ext.solid:ToHSV()
			return Color3.fromHSV((h + t * speed * 0.15) % 1, s, v)
		end
		return ext.solid
	end

	-- One shared ~30 Hz driver per window ticks every picker that is animated.
	local function tick()
		local color = evaluate(os.clock())
		element.Value = color
		swatch.BackgroundColor3 = color
		element:_emit(color)
	end
	function syncAnim()
		local registry = window._lin67PickerAnims
		if not registry then
			registry = {}
			window._lin67PickerAnims = registry
			local acc = 0
			window._maid:GiveTask(game:GetService("RunService").Heartbeat:Connect(function(dt)
				acc += dt
				if acc < 1 / 30 then
					return
				end
				acc = 0
				for _, fn in registry do
					fn()
				end
			end))
		end
		if ext.anim ~= "None" then
			if not registry[element] then
				element._maid:GiveTask(function()
					registry[element] = nil
				end)
			end
			registry[element] = tick
		else
			registry[element] = nil
		end
	end

	function refresh(emit)
		element.Value = evaluate(os.clock())
		paint()
		syncAnim()
		if emit then
			element:_emit(element.Value)
		end
	end

	local function makeButton(text, position, size)
		local button = Create("TextButton") {
			AutoButtonColor = false,
			Text = text,
			Position = position,
			Size = size,
			BorderSizePixel = 0,
			Parent = panel,
		}
		Shape.Corner(Shape.Full, button)
		Typography.Apply(button, "LabelMedium")
		return button
	end

	local modeButtons = {
		Solid = makeButton("Solid", UDim2.fromOffset(0, EXTRA_Y), UDim2.fromOffset(84, 26)),
		Gradient = makeButton("Gradient", UDim2.fromOffset(90, EXTRA_Y), UDim2.fromOffset(84, 26)),
	}

	local gradY = EXTRA_Y + 34
	local minusButton = makeButton("-", UDim2.fromOffset(0, gradY), UDim2.fromOffset(26, 26))
	local plusButton = makeButton("+", UDim2.new(1, -26, 0, gradY), UDim2.fromOffset(26, 26))
	local gradBar = Create("Frame") {
		Name = "GradientBar",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(34, gradY + 2),
		Size = UDim2.new(1, -68, 0, 22),
		Parent = panel,
	}
	Shape.Corner(Shape.Small, gradBar)
	local gradFill = Create("UIGradient") { Parent = gradBar }
	local markerLayer = Create("Frame") {
		Name = "Markers",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 3,
		Parent = gradBar,
	}

	local animNames = { "None", "Breathing", "Rainbow", "Cycle" }
	local animButtons = {}
	local animY = EXTRA_Y + 68
	for i, name in animNames do
		animButtons[name] = makeButton(name, UDim2.new((i - 1) * 0.25, if i == 1 then 0 else 2, 0, animY), UDim2.new(0.25, -2, 0, 26))
	end

	local speedY = EXTRA_Y + 104
	local speedLabel = Create("TextLabel") {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, speedY),
		Size = UDim2.fromOffset(84, 26),
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = panel,
	}
	Typography.Apply(speedLabel, "BodySmall")
	local speedTrack = Create("TextButton") {
		AutoButtonColor = false,
		Text = "",
		Position = UDim2.new(0, 90, 0, speedY + 8),
		Size = UDim2.new(1, -90, 0, 10),
		BorderSizePixel = 0,
		Parent = panel,
	}
	Shape.Corner(Shape.Full, speedTrack)
	local speedFill = Create("Frame") {
		BorderSizePixel = 0,
		Size = UDim2.fromScale(0.5, 1),
		Parent = speedTrack,
	}
	Shape.Corner(Shape.Full, speedFill)

	local dragStop, dragSpeed = nil, false
	local rebuildMarkers

	function paintExtras()
		local c = window.Theme.Colors
		local off = c.SurfaceContainerHighest or c.SurfaceContainer
		local function style(button, active)
			button.BackgroundColor3 = if active then c.SecondaryContainer else off
			button.TextColor3 = if active then c.OnSecondaryContainer else c.OnSurfaceVariant
		end
		for name, button in modeButtons do
			style(button, ext.mode == name)
		end
		for name, button in animButtons do
			style(button, ext.anim == name)
		end
		local gradient = ext.mode == "Gradient"
		style(minusButton, false)
		style(plusButton, false)
		minusButton.TextTransparency = if gradient and #ext.stops > 2 then 0 else 0.6
		plusButton.TextTransparency = if gradient and #ext.stops < MAX_STOPS then 0 else 0.6
		speedTrack.BackgroundColor3 = off
		speedFill.BackgroundColor3 = c.Primary
		speedFill.Size = UDim2.fromScale(math.clamp((ext.speed - 0.1) / 4.9, 0, 1), 1)
		speedLabel.TextColor3 = c.OnSurfaceVariant
		speedLabel.Text = string.format("Speed %.1fx", ext.speed)

		if gradient then
			local keys = {}
			local first, last = ext.stops[1], ext.stops[#ext.stops]
			if first.pos > 0 then
				table.insert(keys, ColorSequenceKeypoint.new(0, first.color))
			end
			for _, stop in ext.stops do
				table.insert(keys, ColorSequenceKeypoint.new(stop.pos, stop.color))
			end
			if last.pos < 1 then
				table.insert(keys, ColorSequenceKeypoint.new(1, last.color))
			end
			gradFill.Color = ColorSequence.new(keys)
		else
			gradFill.Color = ColorSequence.new(ext.solid)
		end
		rebuildMarkers(c)
	end

	function rebuildMarkers(c)
		markerLayer:ClearAllChildren()
		if ext.mode ~= "Gradient" then
			return
		end
		for _, stop in ext.stops do
			local selected = stop == ext.sel
			local marker = Create("TextButton") {
				AutoButtonColor = false,
				Text = "",
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(stop.pos, 0.5),
				Size = UDim2.fromOffset(if selected then 12 else 9, 32),
				BackgroundColor3 = stop.color,
				BorderSizePixel = 0,
				ZIndex = if selected then 5 else 4,
				Parent = markerLayer,
				[1] = Create("UICorner") { CornerRadius = UDim.new(0, 4) },
				[2] = Create("UIStroke") {
					Color = if selected then c.Primary else Color3.new(1, 1, 1),
					Thickness = if selected then 2.5 else 1.5,
				},
			}
			marker.InputBegan:Connect(function(input)
				if isPress(input) then
					ext.sel = stop
					dragStop = stop
					loadEditIntoHSV()
					refresh(true)
				end
			end)
		end
	end

	for name, button in modeButtons do
		element._maid:GiveTask(button.Activated:Connect(function()
			if ext.mode == name then
				return
			end
			ext.mode = name
			if name == "Gradient" and not ext.sel then
				ext.sel = ext.stops[1]
			end
			loadEditIntoHSV()
			refresh(true)
		end))
	end
	for name, button in animButtons do
		element._maid:GiveTask(button.Activated:Connect(function()
			ext.anim = name
			refresh(true)
		end))
	end
	element._maid:GiveTask(plusButton.Activated:Connect(function()
		if ext.mode ~= "Gradient" or #ext.stops >= MAX_STOPS then
			return
		end
		local bestGap, bestAt = -1, 0.5
		local previous = 0
		for i = 1, #ext.stops + 1 do
			local nextPos = if ext.stops[i] then ext.stops[i].pos else 1
			if nextPos - previous > bestGap then
				bestGap, bestAt = nextPos - previous, (previous + nextPos) / 2
			end
			previous = nextPos
		end
		local stop = { pos = bestAt, color = sampleList(ext.stops, bestAt) }
		table.insert(ext.stops, stop)
		sortStops()
		ext.sel = stop
		loadEditIntoHSV()
		refresh(true)
	end))
	element._maid:GiveTask(minusButton.Activated:Connect(function()
		if ext.mode ~= "Gradient" or #ext.stops <= 2 then
			return
		end
		table.remove(ext.stops, table.find(ext.stops, ext.sel))
		ext.sel = ext.stops[1]
		loadEditIntoHSV()
		refresh(true)
	end))
	element._maid:GiveTask(speedTrack.InputBegan:Connect(function(input)
		if isPress(input) then
			dragSpeed = true
			ext.speed = 0.1 + 4.9 * math.clamp((input.Position.X - speedTrack.AbsolutePosition.X) / math.max(speedTrack.AbsoluteSize.X, 1), 0, 1)
			refresh(true)
		end
	end))
	element._maid:GiveTask(UserInputService.InputChanged:Connect(function(input)
		if not isMove(input) then
			return
		end
		if dragStop then
			dragStop.pos = math.clamp((input.Position.X - gradBar.AbsolutePosition.X) / math.max(gradBar.AbsoluteSize.X, 1), 0, 1)
			sortStops()
			refresh(true)
		elseif dragSpeed then
			ext.speed = 0.1 + 4.9 * math.clamp((input.Position.X - speedTrack.AbsolutePosition.X) / math.max(speedTrack.AbsoluteSize.X, 1), 0, 1)
			refresh(true)
		end
	end))
	element._maid:GiveTask(UserInputService.InputEnded:Connect(function(input)
		if isPress(input) then
			dragStop = nil
			dragSpeed = false
		end
	end))
	element._maid:GiveTask(window.Theme.Changed:Connect(function()
		paintExtras()
	end))

	function paintBase()
		local color = getEdit()
		swatch.BackgroundColor3 = element.Value
		swatch.BackgroundTransparency = element.Transparency
		svBox.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
		svCursor.BackgroundColor3 = color
		svCursor.Position = UDim2.fromScale(sat, 1 - val)
		hueCursor.Position = UDim2.fromScale(0.5, hue)
		hexBox.Text = "#" .. color:ToHex():upper()
		rgbLabel.Text = string.format(
			"RGB %d, %d, %d",
			math.round(color.R * 255),
			math.round(color.G * 255),
			math.round(color.B * 255)
		)
		if alphaEnabled then
			alphaFill.BackgroundColor3 = color
			alphaCursor.Position = UDim2.fromScale(1 - element.Transparency, 0.5)
			rgbLabel.Text ..= string.format(" · Opacity %d%%", math.round((1 - element.Transparency) * 100))
		end
	end

	function paint()
		paintBase()
		paintExtras()
	end

	if alphaEnabled then
		-- Callback / Changed get (color, transparency).
		function element:_emit(color)
			self.Changed:Fire(color, self.Transparency)
			if self._callback then
				window:_call(self._callback, color, self.Transparency)
			end
		end

		-- What configs store for this picker.
		function element:GetSaveValue()
			return { Color = self.Value, Transparency = self.Transparency }
		end
	end

	-- Lin67: what configs store (Color3 still loads through the old path).
	function element:GetSaveValue()
		local stops = {}
		for i, stop in ext.stops do
			stops[i] = { Pos = stop.pos, Color = stop.color }
		end
		local out = { Color = ext.solid, Mode = ext.mode, Stops = stops, Anim = ext.anim, Speed = ext.speed }
		if alphaEnabled then
			out.Transparency = element.Transparency
		end
		return out
	end

	-- Lin67: far end of the gradient, for features that draw a two-color gradient.
	function element:GetColor2()
		if ext.anim ~= "None" then
			return evaluate(os.clock() + 0.6)
		end
		if ext.mode == "Gradient" then
			return ext.stops[#ext.stops].color
		end
		return ext.solid
	end

	-- Sets only the transparency (0 = solid, 1 = invisible).
	function element:SetTransparency(transparency: number, silent: boolean?)
		self:Set({ Color = self.Value, Transparency = transparency }, silent)
	end

	local function commit()
		setEdit(Color3.fromHSV(hue, sat, val))
		refresh(true)
	end

	element._normalize = normalize
	element._render = function(color)
		if ext.restoring then
			ext.restoring = false
		else
			setEdit(color)
		end
		color = getEdit()
		-- Keep the current hue for greys, where ToHSV can't recover one.
		local h, s, v = color:ToHSV()
		if s > 0 then
			hue = h
		end
		sat, val = s, v
		refresh(false)
	end

	-- Opens / closes by tweening the row's own height; the row clips the
	-- picker while it slides in / out. Its height is set explicitly instead
	-- of through AutomaticSize: on devices that lags frames behind a tween
	-- (the row stayed tall and empty after the picker had folded away).
	local frame, body = row.Frame, row.Body
	local bodyPadding = body:FindFirstChildOfClass("UIPadding")
	local bodyLayout = body:FindFirstChildOfClass("UIListLayout")
	frame.AutomaticSize = Enum.AutomaticSize.None
	local function rowHeight(open: boolean): number
		local height = row.Header.AbsoluteSize.Y + bodyPadding.PaddingTop.Offset + bodyPadding.PaddingBottom.Offset
		if open then
			height += bodyLayout.Padding.Offset + panelHeight
		end
		return height
	end

	element.Expanded = false
	local motion = nil
	local function fit()
		if not motion then
			frame.Size = UDim2.new(1, 0, 0, rowHeight(element.Expanded))
		end
	end
	fit()
	-- Title / description edits (or wrapping) change the header's height.
	element._maid:GiveTask(row.Header:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))

	function element:SetExpanded(open: boolean)
		if open == element.Expanded then
			return
		end
		element.Expanded = open
		-- Completed also fires for a cancelled tween; clearing `motion` first
		-- lets its handler (below) see it was replaced and do nothing.
		local previous = motion
		motion = nil
		if previous then
			previous:Cancel()
		end
		panel.Visible = true
		local goal = { Size = UDim2.new(1, 0, 0, rowHeight(open)) }
		if open then
			motion = TweenService:Create(frame, Motion.Emphasized(Motion.Duration.Medium2), goal)
		else
			motion = TweenService:Create(frame, Motion.Emphasized(Motion.Duration.Short4), goal)
		end
		local thisMotion = motion
		motion.Completed:Once(function()
			if motion ~= thisMotion then
				return
			end
			motion = nil
			panel.Visible = element.Expanded
			fit()
		end)
		motion:Play()
	end

	-- Only a press that started on the header toggles it: taps on the open
	-- picker's gaps shouldn't fold it away under your finger.
	local pressedHeader = false
	element._maid:GiveTask(row.Frame.InputBegan:Connect(function(input)
		if isPress(input) then
			pressedHeader = onHeader(input)
		end
	end))
	element._maid:GiveTask(row.Frame.Activated:Connect(function()
		if pressedHeader then
			element:SetExpanded(not element.Expanded)
		end
		pressedHeader = false
	end))

	local dragging = nil
	local function updateFrom(input)
		if dragging == "sv" then
			local pos, size = svBox.AbsolutePosition, svBox.AbsoluteSize
			sat = math.clamp((input.Position.X - pos.X) / math.max(size.X, 1), 0, 1)
			val = 1 - math.clamp((input.Position.Y - pos.Y) / math.max(size.Y, 1), 0, 1)
		elseif dragging == "hue" then
			local pos, size = hueBar.AbsolutePosition, hueBar.AbsoluteSize
			hue = math.clamp((input.Position.Y - pos.Y) / math.max(size.Y, 1), 0, 0.999)
		elseif dragging == "alpha" then
			local pos, size = alphaBar.AbsolutePosition, alphaBar.AbsoluteSize
			element.Transparency = 1 - math.clamp((input.Position.X - pos.X) / math.max(size.X, 1), 0, 1)
		end
		commit()
	end

	element._maid:GiveTask(svBox.InputBegan:Connect(function(input)
		if isPress(input) then
			dragging = "sv"
			updateFrom(input)
		end
	end))
	element._maid:GiveTask(hueBar.InputBegan:Connect(function(input)
		if isPress(input) then
			dragging = "hue"
			updateFrom(input)
		end
	end))
	if alphaBar then
		element._maid:GiveTask(alphaBar.InputBegan:Connect(function(input)
			if isPress(input) then
				dragging = "alpha"
				updateFrom(input)
			end
		end))
	end
	element._maid:GiveTask(UserInputService.InputChanged:Connect(function(input)
		if dragging and isMove(input) then
			updateFrom(input)
		end
	end))
	element._maid:GiveTask(UserInputService.InputEnded:Connect(function(input)
		if isPress(input) then
			dragging = nil
		end
	end))
	element._maid:GiveTask(hexBox.FocusLost:Connect(function()
		local ok, color = pcall(Color3.fromHex, (hexBox.Text:gsub("[^%x]", "")))
		if ok then
			element:Set(color)
		else
			paint()
		end
	end))

	paint()
	syncAnim()
	return Base.Finish(element)
end
end

-- Window/Elements/Dropdown.lua
loaders[newNode("Dropdown", N_Window_Elements)] = function(script, require)
--[[
	Tab:AddDropdown({
		Title = "Weapon",
		Options = { "Sword", "Bow", "Staff" },
		Default = "Sword",          -- Multi: a list, e.g. { "Sword", "Bow" }
		Multi = false,
		Searchable = nil,           -- defaults to true when there are > 8 options
		Flag = "Weapon",
		Callback = function(value) end, -- Multi: receives a list
	})

	dropdown:SetOptions({ ... })   -- replace the option list (e.g. player names)
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent.Parent
local Base = require(script.Parent.Base)
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)

local ITEM_HEIGHT = 32
local MAX_LIST_HEIGHT = 6 * (ITEM_HEIGHT + 2)

return function(container, props)
	local element = Base.Element(container, props, "Dropdown")
	local window = element._window
	local themer = window._themer
	local theme = window.Theme
	local multi = props.Multi == true or props.MultipleOptions == true

	local options = {}
	local items = {} -- option -> { Button, Label, Check }
	local open = false

	local function normalize(value)
		if multi then
			local list = {}
			if type(value) == "table" then
				for key, v in value do
					-- accept both { "A", "B" } and { A = true, B = true }
					if type(key) == "number" then
						table.insert(list, v)
					elseif v == true then
						table.insert(list, key)
					end
				end
			elseif value ~= nil then
				list = { value }
			end
			return list
		end
		if type(value) == "table" then
			return value[1]
		end
		return value
	end

	local function isSelected(option)
		if multi then
			return table.find(element.Value, option) ~= nil
		end
		return element.Value == option
	end

	local function copyValue()
		return multi and table.clone(element.Value) or element.Value
	end

	element.Value = normalize(props.Default or props.Value or props.CurrentOption)

	local row = Base.Row(element, props, { ControlWidth = 170, ControlHeight = 32 })

	local field = Base.Field(themer, "TextButton", row.Control, UDim2.fromScale(1, 1))
	local fieldLabel = Create("TextLabel") {
		Name = "Value",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(10, 0),
		Size = UDim2.new(1, -40, 1, 0),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = field,
	}
	Typography.Apply(fieldLabel, "BodyMedium")

	local arrow = Base.Glyph(themer, "expand_more", 20, "Icon", field)
	arrow.AnchorPoint = Vector2.new(1, 0.5)
	arrow.Position = UDim2.new(1, -8, 0.5, 0)

	-- Inline menu under the header (inline instead of a floating popup so it
	-- scrolls with the page and never gets clipped by the window).
	local panel = row.Extra(false)
	Create("UIListLayout") {
		FillDirection = Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 6),
		Parent = panel,
	}

	local search = nil
	local searchable = props.Searchable
	if searchable == nil then
		searchable = #(props.Options or props.Values or {}) > 8
	end
	if searchable then
		search = Base.Field(themer, "TextBox", panel, UDim2.new(1, 0, 0, 32))
		search.LayoutOrder = 1
		search.ClearTextOnFocus = false
		search.PlaceholderText = "Search..."
		search.TextXAlignment = Enum.TextXAlignment.Left
		Typography.Apply(search, "BodyMedium")
		themer:Bind(search, { TextColor3 = "OnSurface", PlaceholderColor3 = "OnSurfaceVariant" })
		Create("UIPadding") { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = search }
	end

	local list = Create("ScrollingFrame") {
		Name = "Options",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 3,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar,
		LayoutOrder = 2,
		Parent = panel,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 2),
		},
	}
	themer:Bind(list, { ScrollBarImageColor3 = "Outline" })

	local function displayText()
		if multi then
			return #element.Value > 0 and table.concat(element.Value, ", ") or (props.Placeholder or "None")
		end
		return element.Value ~= nil and tostring(element.Value) or (props.Placeholder or "Select...")
	end

	local function paint()
		local c = theme.Colors
		local function alpha(role)
			return theme:GetTransparency(role) or 0
		end
		fieldLabel.Text = displayText()
		local hasValue = if multi then #element.Value > 0 else element.Value ~= nil
		local fieldRole = if hasValue then "OnSurface" else "OnSurfaceVariant"
		fieldLabel.TextColor3 = c[fieldRole]
		fieldLabel.TextTransparency = alpha(fieldRole)
		for option, item in items do
			local selected = isSelected(option)
			local labelRole = if selected then "OnSecondaryContainer" else "OnSurface"
			item.Button.BackgroundColor3 = c.SecondaryContainer
			item.Button.BackgroundTransparency = if selected then alpha("SecondaryContainer") else 1
			item.Label.TextColor3 = c[labelRole]
			item.Label.TextTransparency = alpha(labelRole)
			-- Hidden through transparency, not Visible: Icons manages Visible
			-- and would show the check again once the icon images load.
			item.Check.TextColor3 = c.OnSecondaryContainer
			item.Check.TextTransparency = if selected then alpha("OnSecondaryContainer") else 1
		end
	end

	local function layoutList()
		local query = search and search.Text:lower() or ""
		local shown = 0
		for option, item in items do
			local visible = query == "" or tostring(option):lower():find(query, 1, true) ~= nil
			item.Button.Visible = visible
			if visible then
				shown += 1
			end
		end
		list.Size = UDim2.new(1, 0, 0, math.min(shown * (ITEM_HEIGHT + 2), MAX_LIST_HEIGHT))
	end

	local function select(option)
		if multi then
			local index = table.find(element.Value, option)
			if index then
				table.remove(element.Value, index)
			else
				table.insert(element.Value, option)
			end
		else
			element.Value = option
		end
		paint()
		element:_emit(copyValue())
	end

	local function setOpen(value: boolean)
		open = value
		panel.Visible = value
		TweenService:Create(arrow, Motion.Standard(Motion.Duration.Short3), { Rotation = value and 180 or 0 }):Play()
		if value then
			layoutList()
		end
	end

	local function buildItems()
		for _, item in items do
			item.Button:Destroy()
		end
		table.clear(items)
		for index, option in options do
			local item = Create("TextButton") {
				Name = tostring(option),
				AutoButtonColor = false,
				Text = "",
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, ITEM_HEIGHT),
				LayoutOrder = index,
				Parent = list,
			}
			Shape.Corner(Shape.Small, item)
			local label = Create("TextLabel") {
				Name = "Label",
				BackgroundTransparency = 1,
				Position = UDim2.fromOffset(12, 0),
				Size = UDim2.new(1, -44, 1, 0),
				Text = tostring(option),
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = item,
			}
			Typography.Apply(label, "BodyMedium")
			local check = Base.Glyph(themer, "check", 18, nil, item)
			check.AnchorPoint = Vector2.new(1, 0.5)
			check.Position = UDim2.new(1, -10, 0.5, 0)

			item.Activated:Connect(function()
				select(option)
				if not multi then
					setOpen(false)
				end
			end)
			items[option] = { Button = item, Label = label, Check = check }
		end
		paint()
		if open then
			layoutList()
		end
	end

	element._normalize = normalize
	element._render = paint

	-- Replaces the option list. Selections that no longer exist are dropped.
	function element:SetOptions(newOptions)
		options = table.clone(newOptions or {})
		if multi then
			for i = #self.Value, 1, -1 do
				if not table.find(options, self.Value[i]) then
					table.remove(self.Value, i)
				end
			end
		elseif self.Value ~= nil and not table.find(options, self.Value) then
			self.Value = nil
		end
		buildItems()
	end
	element.Refresh = element.SetOptions

	function element:GetOptions()
		return table.clone(options)
	end

	function element:Open()
		setOpen(true)
	end

	function element:Close()
		setOpen(false)
	end

	element._maid:GiveTask(field.Activated:Connect(function()
		setOpen(not open)
	end))
	if search then
		element._maid:GiveTask(search:GetPropertyChangedSignal("Text"):Connect(layoutList))
	end
	element._maid:GiveTask(theme.Changed:Connect(paint))

	options = table.clone(props.Options or props.Values or {})
	buildItems()

	return Base.Finish(element)
end
end

-- Window/Elements/Input.lua
loaders[newNode("Input", N_Window_Elements)] = function(script, require)
--[[
	Tab:AddInput({
		Title = "Target player",
		Placeholder = "Username",
		Default = "",
		Numeric = false,        -- only allow number characters
		Finished = true,        -- fire on focus lost (false = on every keystroke)
		ClearOnSubmit = false,  -- empty the box after firing
		Flag = "Target",
		Callback = function(text) end,
	})
]]
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent.Parent
local Base = require(script.Parent.Base)
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Motion = require(Root.Core.Motion)

return function(container, props)
	local element = Base.Element(container, props, "Input")
	local window = element._window
	local themer = window._themer
	local numeric = props.Numeric == true
	local finished = props.Finished ~= false

	local function clean(text)
		text = tostring(text or "")
		if numeric then
			text = text:gsub("[^%d%.%-]", "")
		end
		return text
	end

	element.Value = clean(props.Default or props.Value)

	local row = Base.Row(element, props, { ControlWidth = 170, ControlHeight = 32 })
	local field, stroke = Base.Field(themer, "TextBox", row.Control, UDim2.fromScale(1, 1))
	field.ClearTextOnFocus = false
	field.Text = element.Value
	field.PlaceholderText = props.Placeholder or props.PlaceholderText or ""
	field.TextXAlignment = Enum.TextXAlignment.Left
	field.TextTruncate = Enum.TextTruncate.AtEnd
	Typography.Apply(field, "BodyMedium")
	themer:Bind(field, { TextColor3 = "OnSurface", PlaceholderColor3 = "OnSurfaceVariant" })
	Create("UIPadding") {
		PaddingLeft = UDim.new(0, 10),
		PaddingRight = UDim.new(0, 10),
		Parent = field,
	}

	element._normalize = clean
	element._render = function(value)
		field.Text = value
	end

	local function submit()
		element.Value = field.Text
		element:_emit(field.Text)
		if props.ClearOnSubmit or props.RemoveTextAfterFocusLost then
			field.Text = ""
			element.Value = ""
		end
	end

	element._maid:GiveTask(field:GetPropertyChangedSignal("Text"):Connect(function()
		local cleaned = clean(field.Text)
		if cleaned ~= field.Text then
			field.Text = cleaned
			return
		end
		-- Comparing against Value (instead of a "rendering" flag) also
		-- holds under deferred signal behavior.
		if not finished and cleaned ~= element.Value then
			element.Value = cleaned
			element:_emit(cleaned)
		end
	end))
	element._maid:GiveTask(field.Focused:Connect(function()
		themer:Bind(stroke, { Color = "Primary" })
		TweenService:Create(stroke, Motion.Standard(Motion.Duration.Short2), { Thickness = 2 }):Play()
	end))
	element._maid:GiveTask(field.FocusLost:Connect(function()
		themer:Bind(stroke, { Color = "OutlineVariant" })
		TweenService:Create(stroke, Motion.Standard(Motion.Duration.Short2), { Thickness = 1 }):Play()
		if finished then
			submit()
		end
	end))

	return Base.Finish(element)
end
end

-- Window/Elements/Keybind.lua
loaders[newNode("Keybind", N_Window_Elements)] = function(script, require)
--[[
	Tab:AddKeybind({
		Title = "Dash",
		Default = Enum.KeyCode.Q,   -- or "Q"
		Mode = "Press",             -- "Press": Callback()  | "Toggle": Callback(on) | "Hold": Callback(isDown)
		Flag = "DashKey",
		Callback = function(...) end,
		ChangedCallback = function(newKey) end, -- when the user rebinds
		Notify = nil,               -- toast when used; default: on for Press / Toggle, off for Hold
	})

	Click the chip, then press a key. Esc cancels, Backspace unbinds.
	Keybinds don't fire while typing in a TextBox.
]]
local UserInputService = game:GetService("UserInputService")

local Root = script.Parent.Parent.Parent
local Base = require(script.Parent.Base)
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)

local function toKeyCode(value)
	if typeof(value) == "EnumItem" then
		if value == Enum.UserInputType.MouseButton2 or value == Enum.UserInputType.MouseButton3 then
			return value
		end
		return value.EnumType == Enum.KeyCode and value ~= Enum.KeyCode.Unknown and value or nil
	elseif type(value) == "string" and value ~= "" and value ~= "None" then
		if value == "MouseButton2" or value == "MouseButton3" then
			return Enum.UserInputType[value]
		end
		local ok, key = pcall(function()
			return (Enum.KeyCode :: any)[value]
		end)
		return ok and key or nil
	end
	return nil
end

return function(container, props)
	local element = Base.Element(container, props, "Keybind")
	local window = element._window
	local themer = window._themer
	local mode = props.Mode or "Press"
	local changedCallback = props.ChangedCallback
	local listening = false

	element.Value = toKeyCode(props.Default or props.Value or props.CurrentKeybind)
	element.State = false -- Toggle mode: current on/off, Hold mode: held down
	element.Mode = mode

	table.insert(window._keybinds, element)
	element._maid:GiveTask(function()
		local index = table.find(window._keybinds, element)
		if index then
			table.remove(window._keybinds, index)
		end
		window.KeybindsChanged:Fire()
	end)

	local function setState(state: boolean)
		element.State = state
		window.KeybindsChanged:Fire()
	end

	-- Toggle mode: set the on/off state from code (e.g. to match a Toggle
	-- element), without firing Callback.
	function element:SetState(state: boolean)
		setState(state == true)
	end

	local row = Base.Row(element, props, { ControlWidth = 96, ControlHeight = 32 })

	local chip = Create("TextButton") {
		Name = "Key",
		AutoButtonColor = false,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.new(0, 0, 0, 32),
		AutomaticSize = Enum.AutomaticSize.X,
		BorderSizePixel = 0,
		Parent = row.Control,
		[1] = Create("UIPadding") { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) },
		[2] = Create("UISizeConstraint") { MinSize = Vector2.new(56, 32) },
	}
	Shape.Corner(Shape.Small, chip)
	Typography.Apply(chip, "LabelLarge")

	local function paint()
		local shown = element.Value and (element.Value == Enum.KeyCode.World90 and "Mouse4" or element.Value == Enum.KeyCode.World91 and "Mouse5" or element.Value.Name)
		chip.Text = listening and "..." or (shown or "None")
		themer:Bind(chip, {
			BackgroundColor3 = listening and "PrimaryContainer" or "SecondaryContainer",
			TextColor3 = listening and "OnPrimaryContainer" or "OnSecondaryContainer",
		})
	end

	element._normalize = toKeyCode
	element._render = paint
	-- A keybind's "value changed" is a rebind, so Set() reports through
	-- ChangedCallback; Callback is reserved for the key actually being used.
	function element:_emit(key)
		window.KeybindsChanged:Fire()
		self.Changed:Fire(key)
		if changedCallback then
			window:_call(changedCallback, key)
		end
	end

	function element:SetChangedCallback(fn)
		changedCallback = fn
	end

	local function fire(...)
		if element._callback then
			window:_call(element._callback, ...)
		end
	end

	-- Toast telling the player what the key just did. Hold keys stay quiet
	-- by default (you see the effect while holding). A new toast replaces
	-- this keybind's previous one, so repeated presses don't pile up.
	local notify = props.Notify
	if notify == nil then
		notify = mode ~= "Hold"
	end
	local toast = nil
	local function announce(content: string, icon: string)
		if not notify or not window:GetKeybindNotify() then
			return
		end
		if toast then
			toast.Close()
		end
		local title = element._title and element._title.Text or "Keybind"
		toast = window:Notify({ Title = title, Content = `{content} ({element.Value.Name})`, Icon = icon, Duration = 2 })
	end

	function element:SetNotify(enabled: boolean)
		notify = enabled
	end

	local function setListening(value: boolean)
		listening = value
		window._keybindListening = value
		paint()
	end

	element._maid:GiveTask(chip.Activated:Connect(function()
		setListening(not listening)
	end))

	element._maid:GiveTask(UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if listening then
			local mouseKey = (input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.MouseButton3) and input.UserInputType or nil
			if input.UserInputType ~= Enum.UserInputType.Keyboard and not mouseKey then
				return
			end
			-- Marks this input as consumed so the window toggle and other
			-- keybinds (whose handlers may run after this one) ignore it.
			window._capturedKey = input.KeyCode
			window._capturedAt = os.clock()
			setListening(false)
			if input.KeyCode == Enum.KeyCode.Escape then
				paint()
			elseif input.KeyCode == Enum.KeyCode.Backspace then
				element:Set(nil)
			else
				element:Set(mouseKey or input.KeyCode)
			end
			return
		end

		if gameProcessed or UserInputService:GetFocusedTextBox() or window:_isCapturingKey(input) then
			return
		end
		if element.Value and (input.KeyCode == element.Value or input.UserInputType == element.Value) then
			if mode == "Toggle" then
				setState(not element.State)
				fire(element.State)
				announce(if element.State then "Enabled" else "Disabled", if element.State then "toggle_on" else "toggle_off")
			elseif mode == "Hold" then
				setState(true)
				fire(true)
				announce("Holding", "keyboard")
			else
				fire()
				announce("Activated", "keyboard")
			end
		end
	end))

	if mode == "Hold" then
		element._maid:GiveTask(UserInputService.InputEnded:Connect(function(input)
			if element.State and element.Value and (input.KeyCode == element.Value or input.UserInputType == element.Value) then
				setState(false)
				fire(false)
			end
		end))
	end

	do
		local getEnv = getgenv
		local pressed = (getEnv and getEnv().iskeypressed) or iskeypressed
		if type(pressed) == "function" then
			local codes = { [Enum.KeyCode.World90] = 0x05, [Enum.KeyCode.World91] = 0x06 }
			local last = {}
			local function isDown(code)
				local ok, down = pcall(pressed, code)
				return ok and down == true
			end
			element._maid:GiveTask(game:GetService("RunService").Heartbeat:Connect(function()
				local focused = true
				if type(iswindowactive) == "function" then
					local ok, active = pcall(iswindowactive)
					focused = not ok or active ~= false
				end
				if not focused then
					for key in codes do
						last[key] = false
					end
					return
				end
				if listening then
					for key, code in codes do
						local down = isDown(code)
						if down and not last[key] then
							last[key] = true
							setListening(false)
							element:Set(key)
							return
						end
						last[key] = down
					end
					return
				end
				local key = element.Value
				local code = key and codes[key]
				for other in codes do
					if other ~= key then
						last[other] = false
					end
				end
				if not code then
					return
				end
				local down = isDown(code)
				if down == (last[key] == true) then
					return
				end
				last[key] = down
				if UserInputService:GetFocusedTextBox() then
					return
				end
				if down then
					if mode == "Toggle" then
						setState(not element.State)
						fire(element.State)
						announce(if element.State then "Enabled" else "Disabled", if element.State then "toggle_on" else "toggle_off")
					elseif mode == "Hold" then
						setState(true)
						fire(true)
						announce("Holding", "keyboard")
					else
						fire()
						announce("Activated", "keyboard")
					end
				elseif mode == "Hold" and element.State then
					setState(false)
					fire(false)
				end
			end))
		end
	end
	paint()
	window.KeybindsChanged:Fire()
	return Base.Finish(element)
end
end

-- Window/Elements/Slider.lua
loaders[newNode("Slider", N_Window_Elements)] = function(script, require)
-- Tab:AddSlider({ Title = "WalkSpeed", Min = 16, Max = 200, Default = 16, Step = 1, Suffix = "", Flag = "WS", Callback = function(v) end })
-- The value box on the right is editable: type a number and press Enter.
local Root = script.Parent.Parent.Parent
local Base = require(script.Parent.Base)
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Slider = require(Root.Components.Slider)

return function(container, props)
	local element = Base.Element(container, props, "Slider")
	local window = element._window
	local themer = window._themer

	local min = props.Min or 0
	local max = props.Max or 100
	local step = props.Step or props.Increment or props.Rounding or 1
	local suffix = props.Suffix or ""
	local decimals = step > 0 and #(tostring(step):match("%.(%d+)$") or "") or 2

	local function snap(value)
		value = tonumber(value) or min
		if step > 0 then
			value = math.round(value / step) * step
		end
		return math.clamp(value, min, max)
	end
	local function format(value)
		return string.format(`%.{decimals}f`, value) .. suffix
	end

	element.Value = snap(props.Default or props.Value or min)

	local row = Base.Row(element, props, { ControlWidth = 88, ControlHeight = 28 })

	local box = Create("TextBox") {
		Name = "Value",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ClearTextOnFocus = false,
		Text = format(element.Value),
		TextXAlignment = Enum.TextXAlignment.Right,
		Parent = row.Control,
	}
	Typography.Apply(box, "TitleSmall")
	themer:Bind(box, { TextColor3 = "Primary" })

	local extra = row.Extra()
	Create("UIPadding") {
		PaddingLeft = UDim.new(0, 6),
		PaddingRight = UDim.new(0, 6),
		Parent = extra,
	}
	local slider = Slider.new({
		Min = min,
		Max = max,
		Step = step > 0 and step or nil,
		Value = element.Value,
		Theme = window.Theme,
		Size = UDim2.new(1, 0, 0, 28),
		Parent = extra,
	})
	element._maid:GiveTask(slider)

	element._normalize = snap
	element._render = function(value)
		slider:SetValue(value, true)
		box.Text = format(value)
	end

	element._maid:GiveTask(slider.Changed:Connect(function(value)
		value = snap(value)
		element.Value = value
		box.Text = format(value)
		element:_emit(value)
	end))
	element._maid:GiveTask(box.FocusLost:Connect(function()
		local typed = tonumber((box.Text:gsub("[^%d%.%-]", "")))
		if typed then
			element:Set(typed)
		else
			box.Text = format(element.Value)
		end
	end))

	return Base.Finish(element)
end
end

-- Window/Elements/Text.lua
loaders[newNode("Text", N_Window_Elements)] = function(script, require)
-- Non-interactive elements: Label, Paragraph, Divider.
local Root = script.Parent.Parent.Parent
local Base = require(script.Parent.Base)
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Divider = require(Root.Components.Divider)

local Text = {}

-- Tab:AddLabel("Some text") / Tab:AddLabel({ Text = "...", Color = "Primary" })
function Text.Label(container, props)
	if type(props) == "string" then
		props = { Text = props }
	end
	local element = Base.Element(container, props, "Label")
	local themer = element._window._themer
	element.Flag = nil
	element.Value = tostring(props.Text or props.Title or "")

	local label = Create("TextLabel") {
		Name = "Label",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = element.Value,
		TextWrapped = true,
		RichText = false,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = container:_nextOrder(),
		[1] = Create("UIPadding") {
			PaddingLeft = UDim.new(0, 4),
			PaddingRight = UDim.new(0, 4),
		},
	}
	Typography.Apply(label, "BodyMedium")
	themer:Bind(label, { TextColor3 = props.Color or "OnSurfaceVariant" })
	label.Parent = container._holder
	element.Instance = label

	element._normalize = tostring
	element._render = function(value)
		label.Text = value
	end
	element._emit = function() end

	return element
end

-- Tab:AddParagraph({ Title = "Info", Content = "Longer text..." })
function Text.Paragraph(container, props)
	if type(props) == "string" then
		props = { Title = props }
	end
	local element = Base.Element(container, props, "Paragraph")
	element.Flag = nil
	Base.Row(element, props, {})
	element.Value = { Title = props.Title or "", Content = props.Content or props.Description or "" }

	element._render = function(value)
		element:SetTitle(value.Title or "")
		element:SetDescription(value.Content or "")
	end
	element._emit = function() end

	return element
end

-- Tab:AddDivider()
function Text.Divider(container, props)
	props = props or {}
	local element = Base.Element(container, props, "Divider")
	element.Flag = nil
	local divider = Divider.new({ Theme = element._window.Theme })
	divider.Instance.LayoutOrder = container:_nextOrder()
	divider.Instance.Parent = container._holder
	element._maid:GiveTask(divider)
	element.Instance = divider.Instance
	return element
end

return Text
end

-- Window/Elements/Toggle.lua
loaders[newNode("Toggle", N_Window_Elements)] = function(script, require)
-- Tab:AddToggle({ Title = "Auto farm", Default = false, Flag = "AutoFarm", Callback = function(on) end })
local Root = script.Parent.Parent.Parent
local Base = require(script.Parent.Base)
local Switch = require(Root.Components.Switch)

return function(container, props)
	local element = Base.Element(container, props, "Toggle")
	local window = element._window
	element.Value = (props.Default or props.Value) == true

	local row = Base.Row(element, props, { ClassName = "TextButton", ControlWidth = 52, ControlHeight = 32 })
	Base.Interactive(element, row.Frame)

	local switch = Switch.new({ Value = element.Value, Theme = window.Theme, Parent = row.Control })
	element._maid:GiveTask(switch)
	element._switch = switch

	element._normalize = function(value)
		return value == true
	end
	element._render = function(value)
		switch:SetValue(value, true)
	end

	element._maid:GiveTask(switch.Changed:Connect(function(value)
		element.Value = value
		element:_emit(value)
	end))
	-- Clicking anywhere on the row flips the switch too.
	element._maid:GiveTask(row.Frame.Activated:Connect(function()
		switch:SetValue(not switch:GetValue())
	end))

	return Base.Finish(element)
end
end

-- Window/HUD.lua
loaders[newNode("HUD", N_Window)] = function(script, require)
--[[
	On-screen HUD for executor windows: stays visible while the window is
	hidden, follows the window's theme, and every piece can be dragged.

	local wm = Window:AddWatermark({ Title = "My Hub", FPS = true, Ping = true, Clock = true })
	local block = wm:AddBlock("bolt", "Ready")   -- or wm:AddBlock({ Icon, Text, Callback })
	block:SetText("Running")

	local binds = Window:AddKeybindList()         -- lists keybinds that are switched on / held

	local auto = Window:AddIndicator({ Text = "AUTO", Icon = "bolt", Color = "Primary" })
	auto:SetColor("Error")

	Window:SetHUDVisible(false)                    -- hide every HUD piece at once
	Window:SetHUDTransparency(0.4, 0)              -- see-through background, solid text
	wm:SetTransparency(0.8)                        -- just this piece

	Transparency is the HUD's own: the theme roles HUDBackground (fills,
	outlines) and HUDText (text, icons) ??never the window's roles ??so a
	see-through window can have a solid HUD and the other way round.
]]
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Base = require(script.Parent.Elements.Base)
local makeDraggable = require(script.Parent.Draggable)

local HUD = {}

local MARGIN = 16

-- Position presets: { Position, AnchorPoint }
local PRESETS = {
	TopLeft = { UDim2.new(0, MARGIN, 0, MARGIN), Vector2.new(0, 0) },
	Top = { UDim2.new(0.5, 0, 0, MARGIN), Vector2.new(0.5, 0) },
	TopRight = { UDim2.new(1, -MARGIN, 0, MARGIN), Vector2.new(1, 0) },
	Left = { UDim2.new(0, MARGIN, 0.5, 0), Vector2.new(0, 0.5) },
	Right = { UDim2.new(1, -MARGIN, 0.5, 0), Vector2.new(1, 0.5) },
	BottomLeft = { UDim2.new(0, MARGIN, 1, -MARGIN), Vector2.new(0, 1) },
	Bottom = { UDim2.new(0.5, 0, 1, -MARGIN), Vector2.new(0.5, 1) },
	BottomRight = { UDim2.new(1, -MARGIN, 1, -MARGIN), Vector2.new(1, 1) },
}

-- `position`: a preset name or a UDim2 (top-left corner).
local function place(frame: GuiObject, position, default: string)
	if typeof(position) == "UDim2" then
		frame.AnchorPoint = Vector2.new(0, 0)
		frame.Position = position
		return
	end
	local preset = PRESETS[position] or PRESETS[default]
	frame.Position = preset[1]
	frame.AnchorPoint = preset[2]
end

local function resolve(colors, color)
	return if typeof(color) == "Color3" then color else colors[color]
end

-- Theme bindings for one HUD piece. Colors come from a theme role or a
-- Color3; transparency comes only from the HUD's own roles (HUDBackground
-- for fills and outlines, HUDText for text and icons) or the piece's own
-- :SetTransparency, never from the color's role, so window transparency
-- never leaks into the HUD.
local function painter(window, piece)
	local themer, theme = window._themer, window.Theme
	local function fillT()
		return piece._fillTransparency or theme:GetTransparency("HUDBackground") or 0
	end
	local function outlineT()
		return piece._fillTransparency or theme:GetTransparency("HUDOutline") or 0
	end
	local function contentT()
		return piece._contentTransparency or theme:GetTransparency("HUDText") or 0
	end

	local paint = {}
	function paint.Fill(inst: GuiObject, color)
		themer:Bind(inst, {
			BackgroundColor3 = function(colors)
				return resolve(colors, color)
			end,
			BackgroundTransparency = fillT,
		})
	end
	function paint.Outline(inst: Instance) -- a UIStroke or a 1 px line Frame
		local colorProp = if inst:IsA("UIStroke") then "Color" else "BackgroundColor3"
		local transparencyProp = if inst:IsA("UIStroke") then "Transparency" else "BackgroundTransparency"
		themer:Bind(inst, {
			[colorProp] = function(colors)
				return colors.HUDOutline
			end,
			[transparencyProp] = outlineT,
		})
	end
	-- Text, or an icon made by paint.Icon. color = nil keeps the color as-is
	-- (a colored logo) and only applies the transparency.
	function paint.Content(inst: GuiObject, color)
		local image = inst:IsA("ImageLabel")
		local map = { [if image then "ImageTransparency" else "TextTransparency"] = contentT }
		if color ~= nil then
			map[if image then "ImageColor3" else "TextColor3"] = function(colors)
				return resolve(colors, color)
			end
		end
		themer:Bind(inst, map)
	end
	-- `tint` = false keeps a colored image (e.g. a logo) as-is.
	function paint.Icon(name, size: number, color, parent: Instance, order: number, tint: boolean?)
		if not name or not Base.CanShowIcon(name) then
			return nil
		end
		local icon = Base.Glyph(themer, name, size, nil, parent, tint)
		icon.LayoutOrder = order
		paint.Content(icon, if tint == false and icon:IsA("ImageLabel") then nil else color)
		return icon
	end
	-- The rounded, outlined surface every HUD piece is drawn on.
	function paint.Surface(props)
		local frame = Create("Frame")(props)
		paint.Fill(frame, "HUDBackground")
		paint.Outline(Create("UIStroke") {
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			Thickness = 1,
			Parent = frame,
		})
		return frame
	end
	return paint
end

-- :SetTransparency(background, text) shared by every HUD piece: 0 = solid,
-- 1 = invisible, nil = follow the HUD setting (Window:SetHUDTransparency).
local function setTransparency(piece, background: number?, text: number?)
	piece._fillTransparency = if background then math.clamp(background, 0, 1) else nil
	piece._contentTransparency = if text then math.clamp(text, 0, 1) else nil
	piece._window._themer:Refresh()
end

-- One full-screen frame per window holding every HUD piece. It lives beside
-- the window's Main frame (not inside it), so hiding or minimizing the
-- window leaves the HUD up. Shrinks on small screens like the window does.
function HUD.Layer(window)
	if window._hudLayer then
		return window._hudLayer
	end
	local layer = Create("Frame") {
		Name = "HUD",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 0, -- under the window; the HUD shouldn't cover the menu
		Parent = window.Gui,
	}
	local scale = Create("UIScale") { Parent = layer }
	local function rescale()
		local camera = workspace.CurrentCamera
		local viewport = if camera then camera.ViewportSize else Vector2.new(1920, 1080)
		local s = math.clamp(math.min(viewport.X / 1000, viewport.Y / 600), 0.6, 1)
		scale.Scale = s
		-- UIScale shrinks the layer itself too; grow it back to cover the screen.
		layer.Size = UDim2.fromScale(1 / s, 1 / s)
	end
	rescale()
	local camera = workspace.CurrentCamera
	if camera then
		window._maid:GiveTask(camera:GetPropertyChangedSignal("ViewportSize"):Connect(rescale))
	end
	window._hudLayer = layer
	return layer
end

--== Watermark ==--

local Block = {}
Block.__index = Block

local Watermark = {}
Watermark.__index = Watermark

function HUD.Watermark(window, props)
	props = props or {}
	local self = setmetatable({
		_window = window,
		_blocks = {},
		_order = 0,
		_fast = {}, -- updaters run every 0.5 s (FPS)
		_slow = {}, -- updaters run every second (ping, clock)
		_maid = Maid.new(),
		_fillTransparency = props.BackgroundTransparency,
		_contentTransparency = props.TextTransparency,
	}, Watermark)
	self._paint = painter(window, self)

	local frame = self._paint.Surface({
		Name = "Watermark",
		BorderSizePixel = 0,
		Active = true,
		Size = UDim2.fromOffset(0, 36),
		AutomaticSize = Enum.AutomaticSize.X,
		Visible = props.Visible ~= false,
		[1] = Create("UIPadding") { PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14) },
		[2] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 10),
		},
	})
	Shape.Corner(Shape.Full, frame)
	place(frame, props.Position, "TopLeft")
	frame.Parent = HUD.Layer(window)
	self.Instance = frame
	makeDraggable(self._maid, frame, frame)
	window._maid:GiveTask(self)

	local title = props.Title
	if title == nil then
		title = window.Title
	end
	if title ~= false then
		-- Defaults to the window's own icon / logo (a logo keeps its colors).
		local icon, tint = props.Icon, true
		if icon == nil then
			icon, tint = window._appIconSource, window._appIconTint
		end
		self.TitleBlock = self:AddBlock({
			Icon = icon or nil,
			Text = title,
			IconColor = props.IconColor or "IconAccent",
			Tint = tint,
			Emphasis = true,
		})
	end
	if props.Avatar then
		self:AddAvatar()
	end
	if props.Player then
		self:AddPlayer()
	end
	if props.Game then
		self:AddGame()
	end
	if props.Executor then
		self:AddExecutor()
	end
	if props.FPS then
		self:AddFPS()
	end
	if props.Ping then
		self:AddPing()
	end
	if props.Clock then
		self:AddClock(type(props.Clock) == "string" and props.Clock or nil)
	end
	return self
end

function Watermark:AddAvatar()
	local player = Players.LocalPlayer
	local userId = player and player.UserId or 0
	return self:AddBlock({
		Icon = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(userId) .. "&w=48&h=48",
		Text = player and player.Name or "Player",
		Tint = false,
	})
end

function Watermark:AddPlayer()
	local player = Players.LocalPlayer
	return self:AddBlock({
		Icon = "account_circle",
		Text = player and player.Name or "Unknown",
	})
end

function Watermark:AddGame()
	local MarketplaceService = game:GetService("MarketplaceService")
	local gameName = "Roblox"
	pcall(function()
		local info = MarketplaceService:GetProductInfo(game.PlaceId)
		if info and info.Name then
			gameName = info.Name
		end
	end)
	return self:AddBlock({
		Icon = "syringe",
		Text = gameName,
	})
end

function Watermark:AddExecutor()
	local executor = "Unknown"
	if typeof(identifyexecutor) == "function" then
		executor = identifyexecutor()
	elseif typeof(getexecutorname) == "function" then
		executor = getexecutorname()
	end
	return self:AddBlock({
		Icon = "terminal",
		Text = executor,
	})
end

-- AddBlock(icon, text) or AddBlock({ Icon, Text, IconColor, TextColor, Callback, Tint }).
-- Returns a block with :SetText / :SetIcon / :SetVisible / :OnClick / :Destroy.
function Watermark:AddBlock(iconOrProps, text: string?)
	local props = if type(iconOrProps) == "table" then iconOrProps else { Icon = iconOrProps, Text = text }
	local paint = self._paint
	self._order += 1

	local separator = Create("Frame") {
		Name = "Separator",
		BorderSizePixel = 0,
		Size = UDim2.fromOffset(1, 16),
		LayoutOrder = self._order * 2 - 1,
		Parent = self.Instance,
	}
	paint.Outline(separator)

	local frame = Create("Frame") {
		Name = "Block",
		BackgroundTransparency = 1,
		Active = true,
		Size = UDim2.fromOffset(0, 24),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = self._order * 2,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		},
		Parent = self.Instance,
	}

	local label = Create("TextLabel") {
		Name = "Text",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = tostring(props.Text or ""),
		LayoutOrder = 2,
		Parent = frame,
	}
	Typography.Apply(label, if props.Emphasis then "TitleSmall" else "LabelLarge")
	paint.Content(label, props.TextColor or "HUDText")

	local block = setmetatable({
		Instance = frame,
		_watermark = self,
		_separator = separator,
		_label = label,
		_iconColor = props.IconColor or "Icon",
		_callbacks = {},
		_visible = true,
		_maid = Maid.new(),
	}, Block)
	block._icon = paint.Icon(props.Icon, 16, block._iconColor, frame, 1, props.Tint)
	if props.Callback then
		table.insert(block._callbacks, props.Callback)
	end

	-- Dragging a block drags the whole watermark; a click without moving
	-- runs the block's callbacks.
	makeDraggable(block._maid, frame, self.Instance, function()
		for _, fn in block._callbacks do
			self._window:_call(fn)
		end
	end)

	table.insert(self._blocks, block)
	self:_refreshSeparators()
	return block
end

-- Only separators between two visible blocks are shown.
function Watermark:_refreshSeparators()
	local first = true
	for _, block in self._blocks do
		block._separator.Visible = block._visible and not first
		if block._visible then
			first = false
		end
	end
end

function Watermark:_startTicker()
	if self._ticking then
		return
	end
	self._ticking = true
	local frames, elapsed, slowElapsed = 0, 0, 0
	self._maid:GiveTask(RunService.Heartbeat:Connect(function(dt)
		frames += 1
		elapsed += dt
		slowElapsed += dt
		if elapsed >= 0.5 then
			self.FPS = math.round(frames / elapsed)
			frames, elapsed = 0, 0
			for _, update in self._fast do
				update()
			end
		end
		if slowElapsed >= 1 then
			slowElapsed = 0
			for _, update in self._slow do
				update()
			end
		end
	end))
end

function Watermark:_addLive(list, props, update)
	local block = self:AddBlock(props)
	block._updater = { list = list, fn = function()
		block:SetText(update())
	end }
	table.insert(list, block._updater.fn)
	block._updater.fn()
	self:_startTicker()
	return block
end

-- Frames per second, updated twice a second.
function Watermark:AddFPS(props)
	props = props or {}
	return self:_addLive(self._fast, { Icon = props.Icon or "speed", IconColor = props.IconColor }, function()
		return if self.FPS then `{self.FPS} FPS` else "-- FPS"
	end)
end

-- Network ping in ms (the value the Roblox dev console shows).
function Watermark:AddPing(props)
	props = props or {}
	return self:_addLive(self._slow, { Icon = props.Icon or "wifi", IconColor = props.IconColor }, function()
		local ping = HUD.GetPing()
		return if ping then `{math.round(ping)} ms` else "-- ms"
	end)
end

-- Local time; `format` is an os.date format (default "%H:%M:%S").
function Watermark:AddClock(format: string?)
	return self:_addLive(self._slow, { Icon = "schedule" }, function()
		return os.date(format or "%H:%M:%S")
	end)
end

function Watermark:SetVisible(visible: boolean)
	self.Instance.Visible = visible
end

-- 0 = solid, 1 = invisible; nil = follow the HUD setting. Blocks share it.
Watermark.SetTransparency = setTransparency

function Watermark:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	for _, block in table.clone(self._blocks) do
		block:Destroy()
	end
	self._maid:Destroy()
	self.Instance:Destroy()
end

function Block:SetText(text)
	self._label.Text = tostring(text)
end

function Block:GetText(): string
	return self._label.Text
end

function Block:SetIcon(name)
	if self._icon then
		self._icon:Destroy()
	end
	self._icon = self._watermark._paint.Icon(name, 16, self._iconColor, self.Instance, 1)
end

-- A theme role ("Primary", "Error", ...) or a Color3.
function Block:SetIconColor(color)
	self._iconColor = color
	if self._icon then
		self._watermark._paint.Content(self._icon, color)
	end
end

function Block:SetTextColor(color)
	self._watermark._paint.Content(self._label, color)
end

function Block:SetVisible(visible: boolean)
	self._visible = visible
	self.Instance.Visible = visible
	self._watermark:_refreshSeparators()
end

-- Runs `fn` when the block is clicked (without dragging).
function Block:OnClick(fn)
	table.insert(self._callbacks, fn)
end
Block.Input = Block.OnClick -- NeverLose-style name

function Block:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	local watermark = self._watermark
	if self._updater then
		local index = table.find(self._updater.list, self._updater.fn)
		if index then
			table.remove(self._updater.list, index)
		end
	end
	local index = table.find(watermark._blocks, self)
	if index then
		table.remove(watermark._blocks, index)
	end
	self._maid:Destroy()
	self._separator:Destroy()
	self.Instance:Destroy()
	watermark:_refreshSeparators()
end

function HUD.GetPing(): number?
	local ok, value = pcall(function()
		return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
	end)
	if ok and type(value) == "number" then
		return value
	end
	ok, value = pcall(function()
		return Players.LocalPlayer:GetNetworkPing() * 1000
	end)
	if ok and type(value) == "number" then
		return value
	end
	return nil
end

--== Keybind list ==--

local KeybindList = {}
KeybindList.__index = KeybindList

--[[
	Window:AddKeybindList({
		Title = "Keybinds",
		Position = "Left",     -- preset name or UDim2
		ShowAll = false,       -- false: only keybinds switched on (Toggle) or held (Hold)
		                       -- true: every bound keybind, active ones highlighted
		Width = 200,
	})
]]
function HUD.KeybindList(window, props)
	props = props or {}
	local self = setmetatable({
		_window = window,
		_showAll = props.ShowAll == true,
		_visible = props.Visible ~= false,
		_maid = Maid.new(),
		_fillTransparency = props.BackgroundTransparency,
		_contentTransparency = props.TextTransparency,
	}, KeybindList)
	local paint = painter(window, self)
	self._paint = paint

	local frame = paint.Surface({
		Name = "Keybinds",
		BorderSizePixel = 0,
		Active = true,
		Size = UDim2.fromOffset(props.Width or 200, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		[1] = Create("UIPadding") {
			PaddingTop = UDim.new(0, 10),
			PaddingBottom = UDim.new(0, 12),
			PaddingLeft = UDim.new(0, 14),
			PaddingRight = UDim.new(0, 12),
		},
		[2] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
		},
	})
	Shape.Corner(Shape.Medium, frame)
	place(frame, props.Position, "Left")
	frame.Parent = HUD.Layer(window)
	self.Instance = frame

	local header = Create("Frame") {
		Name = "Header",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 20),
		LayoutOrder = 1,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
		},
		Parent = frame,
	}
	paint.Icon(props.Icon or "keyboard", 18, "IconAccent", header, 1)
	local title = Create("TextLabel") {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -26, 1, 0),
		Text = props.Title or "Keybinds",
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 2,
		Parent = header,
	}
	Typography.Apply(title, "TitleSmall")
	paint.Content(title, "HUDText")
	self._title = title

	local divider = Create("Frame") {
		Name = "Divider",
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 1),
		LayoutOrder = 2,
		Parent = frame,
	}
	paint.Outline(divider)

	self._rows = Create("Frame") {
		Name = "Rows",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 3,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		},
		Parent = frame,
	}

	makeDraggable(self._maid, frame, frame)
	self._maid:GiveTask(window.KeybindsChanged:Connect(function()
		self:_render()
	end))
	window._maid:GiveTask(self)
	self:_render()
	return self
end

local function keybindTitle(keybind): string
	return (keybind._title and keybind._title.Text ~= "" and keybind._title.Text) or keybind.Flag or "Keybind"
end

function KeybindList:_entries()
	local entries = {}
	for _, keybind in self._window._keybinds do
		if keybind.Value and (self._showAll or keybind.State) then
			table.insert(entries, keybind)
		end
	end
	table.sort(entries, function(a, b)
		return keybindTitle(a) < keybindTitle(b)
	end)
	return entries
end

function KeybindList:_render()
	if self._destroyed or self._window._destroyed then
		return
	end
	local paint = self._paint
	for _, child in self._rows:GetChildren() do
		if not child:IsA("UIListLayout") then
			child:Destroy()
		end
	end

	local entries = self:_entries()
	for index, keybind in entries do
		local active = keybind.State == true
		local row = Create("Frame") {
			Name = keybindTitle(keybind),
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 22),
			LayoutOrder = index,
			Parent = self._rows,
		}
		local name = Create("TextLabel") {
			Name = "Name",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, -72, 1, 0),
			Text = keybindTitle(keybind),
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Parent = row,
		}
		Typography.Apply(name, "BodyMedium")
		paint.Content(name, if active or not self._showAll then "HUDText" else "OnSurfaceVariant")

		local key = Create("TextLabel") {
			Name = "Key",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.fromScale(1, 0.5),
			Size = UDim2.fromOffset(0, 20),
			AutomaticSize = Enum.AutomaticSize.X,
			BorderSizePixel = 0,
			Text = keybind.Value.Name,
			Parent = row,
			[1] = Create("UIPadding") { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) },
		}
		Shape.Corner(Shape.Small, key)
		Typography.Apply(key, "LabelMedium")
		paint.Fill(key, if active then "PrimaryContainer" else "SurfaceContainerHighest")
		paint.Content(key, if active then "OnPrimaryContainer" else "OnSurfaceVariant")
	end

	if #entries == 0 and self._showAll then
		local empty = Create("TextLabel") {
			Name = "Empty",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 20),
			Text = "No keybinds",
			TextXAlignment = Enum.TextXAlignment.Left,
			Parent = self._rows,
		}
		Typography.Apply(empty, "BodyMedium")
		paint.Content(empty, "OnSurfaceVariant")
	end

	self.Count = #entries
	-- Active-only lists disappear when nothing is on, like a real HUD.
	self.Instance.Visible = self._visible and (self._showAll or #entries > 0)
end

function KeybindList:SetVisible(visible: boolean)
	self._visible = visible
	self:_render()
end

function KeybindList:SetShowAll(showAll: boolean)
	self._showAll = showAll
	self:_render()
end

function KeybindList:SetTitle(text: string)
	self._title.Text = text
end

KeybindList.SetTransparency = setTransparency

function KeybindList:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self._maid:Destroy()
	self.Instance:Destroy()
end

--== Indicators ==--

local Indicator = {}
Indicator.__index = Indicator

-- All indicators share one draggable stack (bottom-left by default).
local function indicatorStack(window, position)
	if window._hudIndicators then
		return window._hudIndicators
	end
	local stack = Create("Frame") {
		Name = "Indicators",
		BackgroundTransparency = 1,
		Active = true,
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		},
	}
	place(stack, position, "BottomLeft")
	stack.Parent = HUD.Layer(window)
	local maid = Maid.new()
	makeDraggable(maid, stack, stack)
	window._maid:GiveTask(maid)
	window._hudIndicators = stack
	window._hudIndicatorCount = 0
	return stack
end

--[[
	Window:AddIndicator({
		Text = "AUTO",
		Icon = "bolt",             -- Material icon name or image; optional
		Color = "Primary",         -- theme role or Color3 (text + icon)
		Visible = true,
		Position = "BottomLeft",   -- only the first indicator's Position is used (they share a stack)
	})
]]
function HUD.Indicator(window, props)
	props = props or {}
	local stack = indicatorStack(window, props.Position)
	window._hudIndicatorCount += 1
	local self = setmetatable({
		_window = window,
		_color = props.Color or "Primary",
		_maid = Maid.new(),
		_fillTransparency = props.BackgroundTransparency,
		_contentTransparency = props.TextTransparency,
	}, Indicator)
	local paint = painter(window, self)
	self._paint = paint

	local chip = paint.Surface({
		Name = props.Text or "Indicator",
		BorderSizePixel = 0,
		Active = true,
		Size = UDim2.fromOffset(0, 30),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = window._hudIndicatorCount,
		Visible = props.Visible ~= false,
		[1] = Create("UIPadding") { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 14) },
		[2] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		},
		Parent = stack,
	})
	Shape.Corner(Shape.Full, chip)
	self.Instance = chip

	local label = Create("TextLabel") {
		Name = "Text",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = tostring(props.Text or ""),
		LayoutOrder = 2,
		Parent = chip,
	}
	Typography.Apply(label, "LabelLarge")
	paint.Content(label, self._color)
	self._label = label
	self._icon = paint.Icon(props.Icon, 16, self._color, chip, 1)

	-- Dragging an indicator moves the whole stack.
	makeDraggable(self._maid, chip, stack)
	window._maid:GiveTask(self)
	return self
end

function Indicator:SetText(text)
	self._label.Text = tostring(text)
end

function Indicator:GetText(): string
	return self._label.Text
end

function Indicator:SetIcon(name)
	if self._icon then
		self._icon:Destroy()
	end
	self._icon = self._paint.Icon(name, 16, self._color, self.Instance, 1)
end

-- A theme role ("Primary", "Error", "Tertiary", ...) or a Color3.
function Indicator:SetColor(color)
	self._color = color
	self._paint.Content(self._label, color)
	if self._icon then
		self._paint.Content(self._icon, color)
	end
end

function Indicator:SetVisible(visible: boolean)
	self.Instance.Visible = visible
end
Indicator.SetRender = Indicator.SetVisible -- NeverLose-style name

Indicator.SetTransparency = setTransparency

function Indicator:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self._maid:Destroy()
	self.Instance:Destroy()
end

return HUD
end

-- Window/LoadingScreen.lua
loaders[newNode("LoadingScreen", N_Window)] = function(script, require)
--[[
	Startup loading screen for executor windows: an M3 card with the app
	icon, title, a progress bar and a status line. It waits (up to a
	timeout) for the Material icon images, then fades out and hands over to
	the window. Driven by Heartbeat rather than task.wait so it never blocks
	the script: CreateWindow returns at once and tabs are built underneath.

	Options (CreateWindow{ LoadingScreen = { ... } }; `true` = defaults):
		Title = window title, Subtitle = window subtitle,
		Icon = window icon / logo, Duration = 1.2 (minimum seconds shown)
]]
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local Base = require(script.Parent.Elements.Base)

local LoadingScreen = {}

local WIDTH = 300
local ICON_TIMEOUT = 5 -- stop waiting for the icon images after this long
local DEFAULT_DURATION = 1.2

function LoadingScreen.Run(window, opts, onDone)
	opts = if type(opts) == "table" then opts else {}
	local themer = window._themer
	local maid = Maid.new()
	window._maid:GiveTask(maid)
	local minDuration = opts.Duration or DEFAULT_DURATION

	-- A CanvasGroup so the whole card fades as one.
	local card = Create("CanvasGroup") {
		Name = "Loading",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(WIDTH, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BorderSizePixel = 0,
		GroupTransparency = 1,
		ZIndex = 80,
		[1] = Create("UIPadding") {
			PaddingTop = UDim.new(0, 28),
			PaddingBottom = UDim.new(0, 24),
			PaddingLeft = UDim.new(0, 24),
			PaddingRight = UDim.new(0, 24),
		},
		[2] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			HorizontalAlignment = Enum.HorizontalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 10),
		},
	}
	Shape.Corner(Shape.ExtraLarge, card)
	themer:Bind(card, { BackgroundColor3 = "SurfaceContainerHigh" })
	local scale = Create("UIScale") { Scale = window._uiScale.Scale * 0.92, Parent = card }
	maid:GiveTask(card)

	local iconSource = opts.Icon or window._appIconSource
	if iconSource and Base.CanShowIcon(iconSource) then
		local tint = opts.Icon ~= nil or window._appIconTint
		local icon = Base.Glyph(themer, iconSource, 40, "IconAccent", card, tint)
		icon.LayoutOrder = 1
	end

	local function text(name: string, value: string, role: string, color: string, order: number)
		local label = Create("TextLabel") {
			Name = name,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = value,
			TextWrapped = true,
			LayoutOrder = order,
			Parent = card,
		}
		Typography.Apply(label, role)
		themer:Bind(label, { TextColor3 = color })
		return label
	end
	text("Title", opts.Title or window.Title, "TitleLarge", "OnSurface", 2)
	local subtitle = opts.Subtitle or window._subtitleLabel.Text
	if subtitle ~= "" then
		text("Subtitle", subtitle, "BodyMedium", "OnSurfaceVariant", 3)
	end

	local track = Create("Frame") {
		Name = "Progress",
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 4),
		LayoutOrder = 4,
		Parent = card,
		[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
	}
	themer:Bind(track, { BackgroundColor3 = "SecondaryContainer" })
	local fill = Create("Frame") {
		Name = "Bar",
		BorderSizePixel = 0,
		Size = UDim2.fromScale(0, 1),
		Parent = track,
		[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
	}
	themer:Bind(fill, { BackgroundColor3 = "Primary" })
	local status = text("Status", "Loading icons??, "LabelMedium", "OnSurfaceVariant", 5)

	card.Parent = window.Gui

	local controller = { Instance = card, Progress = 0, Finished = false }
	local function setProgress(value: number)
		controller.Progress = value
		fill.Size = UDim2.fromScale(value, 1)
	end

	TweenService:Create(card, Motion.Emphasized(Motion.Duration.Medium2), { GroupTransparency = 0 }):Play()
	TweenService:Create(scale, Motion.Emphasized(Motion.Duration.Medium2), { Scale = window._uiScale.Scale }):Play()

	local function finish()
		if controller.Finished then
			return
		end
		controller.Finished = true
		maid:Remove(controller._stepKey)
		setProgress(1)
		status.Text = "Ready"
		local out = TweenService:Create(card, Motion.Accelerate(Motion.Duration.Short4), { GroupTransparency = 1 })
		TweenService:Create(scale, Motion.Accelerate(Motion.Duration.Short4), { Scale = window._uiScale.Scale * 1.04 }):Play()
		out:Play()
		out.Completed:Once(function()
			maid:Destroy()
			onDone()
		end)
	end
	controller.Finish = finish -- skip the rest of the wait

	-- Creeps toward 70 % while the icons load, then runs to 100 % once they
	-- are in (or the timeout passes) and the minimum time is up.
	local elapsed = 0
	controller._stepKey = maid:GiveTask(RunService.Heartbeat:Connect(function(dt)
		elapsed += dt
		local iconsReady = window._iconsReady or elapsed >= ICON_TIMEOUT
		if iconsReady then
			status.Text = "Starting??
			setProgress(math.max(controller.Progress, math.min(1, elapsed / math.max(minDuration, 1e-3))))
		else
			setProgress(0.7 * (1 - math.exp(-elapsed * 1.5)))
		end
		if iconsReady and elapsed >= minDuration then
			finish()
		end
	end))

	return controller
end

return LoadingScreen
end

-- Window/Notifier.lua
loaders[newNode("Notifier", N_Window)] = function(script, require)
-- Stacked toast notifications for executor windows (bottom-right corner).
-- Unlike Snackbar (one message at a time) these queue up and each carries
-- its own title, text, icon and countdown bar.
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local Base = require(script.Parent.Elements.Base)

local Notifier = {}
Notifier.__index = Notifier

local WIDTH = 300

function Notifier.new(parent: Instance, themer)
	local self = setmetatable({}, Notifier)
	self._themer = themer
	self._count = 0

	self.Instance = Create("Frame") {
		Name = "Notifications",
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -16, 1, -16),
		Size = UDim2.new(0, WIDTH, 1, -32),
		BackgroundTransparency = 1,
		ZIndex = 50,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			VerticalAlignment = Enum.VerticalAlignment.Bottom,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
		},
		Parent = parent,
	}
	return self
end

-- Notify({ Title = "Saved", Content = "Config written", Icon = "save", Duration = 5 })
-- IconColor: a theme role or a Color3 (default "IconAccent").
function Notifier:Notify(props)
	if type(props) == "string" then
		props = { Title = props }
	end
	local themer = self._themer
	local duration = props.Duration or 5
	self._count += 1

	-- The slot takes part in the list layout; the card inside it slides.
	local slot = Create("Frame") {
		Name = "Notification",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = self._count,
		ZIndex = 50,
		Parent = self.Instance,
	}

	local card = Create("TextButton") {
		Name = "Card",
		AutoButtonColor = false,
		Text = "",
		Position = UDim2.new(1, 24, 0, 0),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		ZIndex = 50,
		Parent = slot,
	}
	Shape.Corner(Shape.Medium, card)
	themer:Bind(card, { BackgroundColor3 = "SurfaceContainerHighest" })
	themer:Bind(Create("UIStroke") {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
		Parent = card,
	}, { Color = "OutlineVariant" })
	Create("UIPadding") {
		PaddingTop = UDim.new(0, 12),
		PaddingBottom = UDim.new(0, 12),
		PaddingLeft = UDim.new(0, 16),
		PaddingRight = UDim.new(0, 16),
		Parent = card,
	}

	-- Icon: Material icon name or image (URL / rbxassetid); Image: a colored
	-- image that isn't tinted.
	local iconName = props.Image or props.Icon or "notifications"
	local hasIcon = props.Icon ~= false and Base.CanShowIcon(iconName)
	if hasIcon then
		local icon = Base.Glyph(themer, iconName, 20, props.IconColor or "IconAccent", card, props.Image == nil)
		icon.ZIndex = 51
		if icon:IsA("ImageLabel") and not icon.Visible then
			hasIcon = false
		end
	end

	local textColumn = Create("Frame") {
		Name = "Text",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(hasIcon and 32 or 0, 0),
		Size = UDim2.new(1, hasIcon and -32 or 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		ZIndex = 51,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 2),
		},
		Parent = card,
	}

	local title = Create("TextLabel") {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = props.Title or "",
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 1,
		ZIndex = 51,
		Parent = textColumn,
	}
	Typography.Apply(title, "TitleSmall")
	themer:Bind(title, { TextColor3 = "OnSurface" })

	if props.Content and props.Content ~= "" then
		local body = Create("TextLabel") {
			Name = "Content",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = props.Content,
			TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left,
			LayoutOrder = 2,
			ZIndex = 51,
			Parent = textColumn,
		}
		Typography.Apply(body, "BodyMedium")
		themer:Bind(body, { TextColor3 = "OnSurfaceVariant" })
	end

	-- Countdown bar under the text (a layout item, so it can't feed back
	-- into the card's automatic height).
	local countdown = Create("Frame") {
		Name = "Countdown",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 11),
		LayoutOrder = 3,
		ZIndex = 51,
		Parent = textColumn,
	}
	local bar = Create("Frame") {
		Name = "Bar",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 3),
		BorderSizePixel = 0,
		ZIndex = 52,
		[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
		Parent = countdown,
	}
	themer:Bind(bar, { BackgroundColor3 = "Primary" })

	TweenService:Create(card, Motion.Emphasized(Motion.Duration.Medium2), { Position = UDim2.new() }):Play()
	TweenService:Create(bar, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Size = UDim2.new(0, 0, 0, 3) }):Play()

	local closed = false
	local function close()
		if closed then
			return
		end
		closed = true
		local out = TweenService:Create(card, Motion.Accelerate(Motion.Duration.Short4), { Position = UDim2.new(1, 24, 0, 0) })
		out:Play()
		out.Completed:Once(function()
			slot:Destroy()
		end)
	end

	card.Activated:Connect(close)
	task.delay(duration, close)

	return { Close = close, Instance = slot }
end

function Notifier:Destroy()
	self.Instance:Destroy()
end

return Notifier
end

-- Window/Tab.lua
loaders[newNode("Tab", N_Window)] = function(script, require)
-- A window tab (navigation-drawer item + scrolling page) and its Sections.
-- Both expose the element API from Container (AddToggle, AddSlider, ...).
local TweenService = game:GetService("TweenService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local StateLayer = require(Root.Core.StateLayer)
local Container = require(script.Parent.Container)
local Base = require(script.Parent.Elements.Base)

--== Section ==--

local Section = {}
Section.__index = Section
Container.extend(Section)

function Section.new(tab, title: string?)
	local self = setmetatable({}, Section)
	self._window = tab._window
	self._tab = tab
	self.Title = title or ""
	self._order = 0
	self._elements = {}
	local themer = self._window._themer

	local frame = Create("Frame") {
		Name = title or "Section",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = tab:_nextOrder(),
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		},
	}

	if title and title ~= "" then
		local header = Create("TextLabel") {
			Name = "Header",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 28),
			Text = title,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Bottom,
			LayoutOrder = 0,
			Parent = frame,
			[1] = Create("UIPadding") { PaddingLeft = UDim.new(0, 4), PaddingBottom = UDim.new(0, 2) },
		}
		Typography.Apply(header, "TitleSmall")
		themer:Bind(header, { TextColor3 = "Primary" })
		self._header = header
	end

	frame.Parent = tab._holder
	self.Instance = frame
	self._holder = frame
	return self
end

function Section:SetTitle(text: string)
	if self._header then
		self._header.Text = text
	end
end

function Section:SetVisible(visible: boolean)
	self.Instance.Visible = visible
end

function Section:Destroy()
	for _, element in self._elements do
		element:Destroy()
	end
	self.Instance:Destroy()
end

--== Tab ==--

local Tab = {}
Tab.__index = Tab
Container.extend(Tab)

function Tab.new(window, props)
	if type(props) == "string" then
		props = { Title = props }
	end
	props = props or {}
	local self = setmetatable({}, Tab)
	self._window = window
	self._order = 0
	self._elements = {}
	self._sections = {}
	self.Title = props.Title or props.Name or "Tab"
	-- nil = follow the theme's Icon / IconSelected roles; a role name or a
	-- Color3 pins the icon color (selected or not).
	self._iconColor = props.IconColor
	if props.SectionsAsSubTabs ~= nil then
		self._sectionsAsSubTabs = props.SectionsAsSubTabs
	else
		self._sectionsAsSubTabs = window._sectionsAsSubTabs
	end
	local themer = window._themer
	local theme = window.Theme

	-- Navigation drawer / top-bar tab button
	local hasIcon = props.Icon ~= nil and Base.CanShowIcon(props.Icon)
	local textLen = 0
	for _ in utf8.graphemes(self.Title) do textLen += 1 end
	local btnWidth = math.clamp((hasIcon and 38 or 20) + (textLen * 10) + 18, 80, 160)

	local button = Create("TextButton") {
		Name = self.Title,
		AutoButtonColor = false,
		Text = "",
		BorderSizePixel = 0,
		BackgroundTransparency = 1,
		Size = UDim2.new(0, btnWidth, 0, 36),
		LayoutOrder = #window.Tabs + 1,
		ZIndex = 4,
		Parent = window._navList,
	}
	Shape.Corner(Shape.Full, button)
	local stateLayer = StateLayer.new(button, theme.Colors.OnSurface, Shape.Full)

	local icon = Base.Glyph(themer, props.Icon or "circle", 20, nil, button)
	icon.AnchorPoint = Vector2.new(0, 0.5)
	icon.Position = UDim2.new(0, 10, 0.5, 0)
	icon.ZIndex = 5
	-- Reserve room for the icon even if it's still waiting for the icon images.
	if not hasIcon then
		icon.Visible = false
	end

	local label = Create("TextLabel") {
		Name = "Label",
		BackgroundTransparency = 1,
		Position = UDim2.new(0, hasIcon and 34 or 10, 0, 0),
		Size = UDim2.new(1, hasIcon and -40 or -20, 1, 0),
		Text = self.Title,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 5,
		Parent = button,
	}
	Typography.Apply(label, "LabelLarge")

	self._button = button
	self._icon = icon
	self._label = label
	self._stateLayer = stateLayer

	local page = Create("ScrollingFrame") {
		Name = self.Title,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 4,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar,
		Visible = false,
		Parent = window._pages,
		[1] = Create("UIPadding") {
			PaddingTop = UDim.new(0, 12),
			PaddingBottom = UDim.new(0, 16),
			PaddingLeft = UDim.new(0, 12),
			PaddingRight = UDim.new(0, 12),
		},
		[2] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
		},
	}
	themer:Bind(page, { ScrollBarImageColor3 = "Outline" })
	self.Instance = page
	self._holder = page

	window._maid:GiveTask(button.MouseEnter:Connect(function()
		stateLayer:SetState("Hover", true)
	end))
	window._maid:GiveTask(button.MouseLeave:Connect(function()
		stateLayer:SetState("Hover", false)
	end))
	window._maid:GiveTask(button.Activated:Connect(function()
		window:SelectTab(self)
	end))
	window._maid:GiveTask(theme.Changed:Connect(function()
		self:_paint()
	end))

	self:_paint()
	return self
end

function Tab:_paint()
	local theme = self._window.Theme
	local c = theme.Colors
	local function alpha(role)
		return theme:GetTransparency(role) or 0
	end
	local active = self._window.SelectedTab == self
	self._button.BackgroundTransparency = 1
	local textRole = if active then "OnSecondaryContainer" else "OnSurfaceVariant"
	self._label.TextColor3 = c[textRole]
	self._label.TextTransparency = alpha(textRole)
	local iconColor = self._iconColor
	if typeof(iconColor) == "Color3" then
		Base.SetIconColor(self._icon, iconColor)
	elseif type(iconColor) == "string" and c[iconColor] then
		Base.SetIconColor(self._icon, c[iconColor], alpha(iconColor))
	else
		local iconRole = if active then "IconSelected" else "Icon"
		Base.SetIconColor(self._icon, c[iconRole], alpha(iconRole))
	end
	self._stateLayer:SetColor(c.OnSurface)
end

function Tab:_setActive(active: boolean)
	local page = self.Instance
	page.Visible = active
	if active then
		page.Position = UDim2.fromOffset(0, 12)
		TweenService:Create(page, Motion.Emphasized(Motion.Duration.Medium2), { Position = UDim2.new() }):Play()
		if self._window._slideToTab then
			self._window:_slideToTab(self, false)
		end
	end
	self:_paint()
end

-- Creates a Section in `holder` (the page, or a sub-tab column).
function Tab:_addSectionIn(holder, title: string?, subName: string?)
	local origHolder = self._holder
	self._holder = holder
	local section = Section.new(self, title)
	self._holder = origHolder
	section._subTab = subName
	table.insert(self._sections, section)
	if self._window and self._window._registerSearchable then
		local path = { self.Title }
		if subName then
			table.insert(path, subName)
		end
		if not subName or (title or "Section") ~= subName then
			table.insert(path, title or "Section")
		end
		self._window:_registerSearchable({
			name = title or "Section",
			path = table.concat(path, " > "),
			tab = self,
			subTab = subName,
			target = section.Instance,
		})
	end
	return section
end

-- With SectionsAsSubTabs (on the tab or the window) every section gets its
-- own sub-tab named after it; sections sharing a title share the sub-tab.
function Tab:AddSection(title: string?)
	if self._sectionsAsSubTabs then
		local sub = self:AddSubTab(title or "Section", { Columns = 1 })
		local section = sub:AddSection(title)
		if section._header then
			section._header.Visible = false -- the sub-tab button already shows it
		end
		return section
	end
	return self:_addSectionIn(self._holder, title, nil)
end
Tab.CreateSection = Tab.AddSection

local function paintSubButton(theme, btn, selected)
	local c = theme.Colors
	local stroke = btn:FindFirstChildOfClass("UIStroke")
	if selected then
		btn.BackgroundColor3 = c.SecondaryContainer or Color3.fromRGB(74, 68, 88)
		btn.TextColor3 = c.OnSecondaryContainer or Color3.fromRGB(232, 222, 248)
		if stroke then
			stroke.Transparency = 0.2
			stroke.Color = c.Primary or Color3.fromRGB(208, 188, 255)
			stroke.Thickness = 1.5
		end
	else
		btn.BackgroundColor3 = c.SurfaceContainerHigh or Color3.fromRGB(36, 33, 43)
		btn.TextColor3 = c.OnSurfaceVariant or Color3.fromRGB(202, 196, 208)
		if stroke then
			stroke.Transparency = 0.6
			stroke.Color = c.OutlineVariant or Color3.fromRGB(73, 69, 79)
			stroke.Thickness = 1
		end
	end
	local subIcon = btn:FindFirstChild("SubIcon")
	if subIcon then
		Base.SetIconColor(subIcon, btn.TextColor3)
	end
end

function Tab:_paintSubTabs()
	local theme = self._window.Theme
	for i, sub in ipairs(self._subTabs) do
		local selected = i == self._selectedSub
		sub.Holder.Visible = selected
		paintSubButton(theme, sub.Button, selected)
	end
end

-- Shows a sub-tab, by name or index.
function Tab:SelectSubTab(which)
	local subs = self._subTabs
	if not subs then
		return
	end
	local index = which
	if type(which) ~= "number" then
		index = table.find(subs, subs[which])
	end
	if index and subs[index] then
		self._selectedSub = index
		self:_paintSubTabs()
	end
end

function Tab:_ensureSubNav()
	if self._subNav then
		return
	end
	self._subNav = Create("ScrollingFrame") {
		Name = "SubNavBar",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 42),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.X,
		ScrollBarThickness = 0,
		ScrollingDirection = Enum.ScrollingDirection.X,
		LayoutOrder = 0,
		Parent = self.Instance,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		},
		[2] = Create("UIPadding") {
			PaddingLeft = UDim.new(0, 4),
			PaddingRight = UDim.new(0, 4),
		},
	}
	self._subTabs = {} -- array of sub-tabs, also keyed by name
	self._window._maid:GiveTask(self._window.Theme.Changed:Connect(function()
		self:_paintSubTabs()
	end))
end

-- Adds one sub-tab (a button in the sub-nav bar + its own content area).
-- opts.Columns = 1 gives a single full-width column; the default is two
-- columns (AddLeftSection / AddRightSection). Adding an existing name
-- returns that sub-tab.
function Tab:AddSubTab(name: string, opts)
	opts = opts or {}
	self:_ensureSubNav()
	local subs = self._subTabs
	if subs[name] then
		return subs[name]
	end
	local index = #subs + 1
	local themer = self._window._themer
	local twoColumns = opts.Columns ~= 1

	local holder = Create("Frame") {
		Name = "SubCategory_" .. name,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = index,
		Visible = false,
		Parent = self.Instance,
	}

	local function column(colName, size, position)
		return Create("Frame") {
			Name = colName,
			BackgroundTransparency = 1,
			Size = size,
			Position = position,
			AutomaticSize = Enum.AutomaticSize.Y,
			Parent = holder,
			[1] = Create("UIListLayout") {
				FillDirection = Enum.FillDirection.Vertical,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 8),
			},
		}
	end

	local leftCol, rightCol, divider
	if twoColumns then
		leftCol = column("LeftCol", UDim2.new(0.5, -8, 0, 0), UDim2.new())
		divider = Create("Frame") {
			Name = "DividerLine",
			Size = UDim2.new(0, 1, 1, 0),
			Position = UDim2.new(0.5, 0, 0, 0),
			BackgroundColor3 = self._window.Theme.Colors.OutlineVariant,
			BackgroundTransparency = 0.4,
			BorderSizePixel = 0,
			ZIndex = 2,
			Parent = holder,
		}
		themer:Bind(divider, { BackgroundColor3 = "OutlineVariant" })
		rightCol = column("RightCol", UDim2.new(0.5, -8, 0, 0), UDim2.new(0.5, 8, 0, 0))
	else
		leftCol = column("Column", UDim2.new(1, 0, 0, 0), UDim2.new())
		rightCol = leftCol
	end

	local charCount = 0
	for _ in utf8.graphemes(name) do charCount += 1 end
	local btn = Create("TextButton") {
		Name = "SubBtn_" .. name,
		AutoButtonColor = false,
		Text = name,
		Font = Enum.Font.GothamBold,
		TextSize = 13,
		Size = UDim2.new(0, math.clamp(charCount * 9 + 32, 84, 160), 0, 32),
		LayoutOrder = index,
		BorderSizePixel = 0,
		Parent = self._subNav,
	}
	Shape.Corner(Shape.Full, btn)
	Create("UIStroke") {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
		Parent = btn,
	}
	do
		local icons = getgenv and getgenv().Lin67SubTabIcons
		local iconName = opts.Icon or (icons and icons[name])
		if iconName and Base.CanShowIcon(iconName) then
			local glyph = Base.Glyph(self._window._themer, iconName, 16, nil, btn)
			glyph.Name = "SubIcon"
			glyph.AnchorPoint = Vector2.new(0, 0.5)
			-- Children sit inside the button's padding, so the icon is placed with a
			-- negative offset; the text is left-aligned after it and the button
			-- sizes itself to the text.
			glyph.Position = UDim2.new(0, 12 - 34, 0.5, 0)
			glyph.ZIndex = btn.ZIndex + 1
			btn.TextXAlignment = Enum.TextXAlignment.Left
			btn.AutomaticSize = Enum.AutomaticSize.X
			btn.Size = UDim2.new(0, 0, 0, 32)
			Create("UIPadding") { PaddingLeft = UDim.new(0, 34), PaddingRight = UDim.new(0, 14), Parent = btn }
		end
	end
	self._window._maid:GiveTask(btn.Activated:Connect(function()
		self:SelectSubTab(index)
	end))

	local tab = self
	local sub = {
		Name = name,
		Holder = holder,
		Left = leftCol,
		Right = rightCol,
		Divider = divider,
		Button = btn,
	}
	function sub.Select()
		tab:SelectSubTab(index)
	end
	function sub:AddLeftSection(title)
		return tab:_addSectionIn(leftCol, title, name)
	end
	function sub:AddRightSection(title)
		return tab:_addSectionIn(rightCol, title, name)
	end
	function sub:AddSection(title, side)
		if side == "Right" or side == "right" then
			return self:AddRightSection(title)
		end
		return self:AddLeftSection(title)
	end

	subs[name] = sub
	table.insert(subs, sub)
	if index == 1 then
		self._selectedSub = 1
	end
	self:_paintSubTabs()
	return sub
end

function Tab:AddSubTabs(names: { string } | string, ...)
	local list = if type(names) == "table" then names else { names, ... }
	for _, name in ipairs(list) do
		self:AddSubTab(name)
	end
	return self._subTabs
end
Tab.CreateSubTabs = Tab.AddSubTabs

-- Pins the tab icon's color (theme role name or Color3); nil follows the theme.
function Tab:SetIconColor(color)
	self._iconColor = color
	self:_paint()
end

function Tab:Select()
	self._window:SelectTab(self)
end

function Tab:Destroy()
	for _, section in self._sections do
		section:Destroy()
	end
	for _, element in self._elements do
		element:Destroy()
	end
	self._button:Destroy()
	self.Instance:Destroy()
end

Tab.Section = Section
return Tab
end

-- Window/Themer.lua
loaders[newNode("Themer", N_Window)] = function(script, require)
-- Binds plain Instance properties to theme color roles so hand-built window
-- chrome recolors on Theme.Changed the same way the components do.
--
--   themer:Bind(frame, { BackgroundColor3 = "SurfaceContainerHigh" })
--   themer:Bind(label, { TextColor3 = function(c) return c.Primary end })
--   themer:Bind(label, { TextColor3 = Color3.fromRGB(255, 0, 0) }) -- fixed color
local Themer = {}
Themer.__index = Themer

-- Color property -> the transparency property that goes with it. A role's
-- theme transparency (Theme:SetTransparency / the theme editor's opacity
-- bar) is applied there too.
local TRANSPARENCY_PROP = {
	BackgroundColor3 = "BackgroundTransparency",
	TextColor3 = "TextTransparency",
	ImageColor3 = "ImageTransparency",
	Color = "Transparency", -- UIStroke
	ScrollBarImageColor3 = "ScrollBarImageTransparency",
}

-- `touched\[prop]` remembers transparency this Themer set, so it can be
-- put back to opaque when the role's transparency is removed (and is left
-- alone otherwise, e.g. a label that's transparent on purpose).
local function apply(inst, map, theme, touched)
	local colors = theme.Colors
	for prop, role in map do
		if type(role) == "function" then
			inst[prop] = role(colors)
		elseif typeof(role) == "Color3" then
			inst[prop] = role
		else
			inst[prop] = colors[role]
			local transparencyProp = TRANSPARENCY_PROP[prop]
			if transparencyProp then
				local value = theme:GetTransparency(role)
				if value then
					inst[transparencyProp] = value
					touched[transparencyProp] = true
				elseif touched[transparencyProp] then
					inst[transparencyProp] = 0
					touched[transparencyProp] = nil
				end
			end
		end
	end
end

function Themer.new(theme)
	local self = setmetatable({}, Themer)
	self.Theme = theme
	-- Strong keys on purpose: Roblox may collect and recreate an Instance's
	-- Lua wrapper, which would silently drop weak-keyed bindings. Entries
	-- are removed when the instance is destroyed instead.
	self._bindings = {}
	self._touched = {}
	self._cleanup = {}
	self._connection = theme.Changed:Connect(function()
		self:Refresh()
	end)
	return self
end

function Themer:Bind(inst: Instance, map)
	local existing = self._bindings[inst]
	if existing then
		for prop, role in map do
			existing[prop] = role
		end
	else
		self._bindings[inst] = map
		self._touched[inst] = {}
		self._cleanup[inst] = inst.Destroying:Connect(function()
			self:Unbind(inst)
		end)
	end
	apply(inst, map, self.Theme, self._touched[inst])
	return inst
end

function Themer:Unbind(inst: Instance)
	self._bindings[inst] = nil
	self._touched[inst] = nil
	local connection = self._cleanup[inst]
	if connection then
		self._cleanup[inst] = nil
		connection:Disconnect()
	end
end

function Themer:Refresh()
	for inst, map in self._bindings do
		if inst.Parent then
			apply(inst, map, self.Theme, self._touched[inst])
		end
	end
end

function Themer:Destroy()
	self._connection:Disconnect()
	for _, connection in self._cleanup do
		connection:Disconnect()
	end
	table.clear(self._cleanup)
	table.clear(self._bindings)
	table.clear(self._touched)
end

return Themer
end

-- Window/Window.lua
loaders[newNode("Window", N_Window)] = function(script, require)
--[[
	Executor-style window built from MD3 components.

	local Window = MD3:CreateWindow({
		Title = "My Hub",
		Subtitle = "v1.0",
		Icon = "widgets",                  -- Material icon name, or an image (URL / rbxassetid)
		ThemeColor = Color3.fromHex("#6750A4"), -- theme (seed) color the palette is generated from
		Preset = nil,                      -- built-in theme preset, e.g. "NeverLose" (Theme.Presets)
		IconColor = nil,                   -- color of every icon (Color3); default follows the theme
		TextColor = nil,                   -- color of all text (Color3); secondary text follows it
		AppIconColor = nil,                -- just the title-bar icon: theme role or Color3
		Logo = "https://.../logo.png",     -- colored image shown instead of Icon (not tinted)
		Size = UDim2.fromOffset(600, 420),  -- starting size; drag the bottom-right corner to resize
		RememberSize = true,               -- restore the size the user dragged to last time
		Mode = "Dark",                     -- "Light" | "Dark"
		Seed = nil,                        -- same as ThemeColor
		ToggleKey = Enum.KeyCode.RightShift,
		ConfigFolder = "MyHub",            -- where configs are saved (executor workspace)
		Icons = true,                      -- load the Material icon images (false = BuilderIcons / symbols only)
		IconStyle = "Outlined",            -- "Outlined" (default) | "Filled" | "Round" | "Sharp"
		MobileButton = nil,                -- floating open/close button; default: on touch devices
		Background = nil,                  -- background image (PNG / JPG) or WebM video: URL / rbxassetid / asset id
		BackgroundKind = nil,              -- "Video" for a Roblox video asset id (a .webm is detected by itself)
		BackgroundTransparency = 0.4,      -- how much of the window color shows through the image
		BackgroundBlur = 0,                -- blur a background image, 0-24 px
		Silent = false,                    -- true: no loading screen, start hidden, no automatic notifications
		KeybindNotify = true,              -- toast when a keybind (AddKeybind) is used; not for the UI toggle key
	})

	local Main = Window:AddTab({ Title = "Main", Icon = "home" })
	Main:AddToggle({ Title = "Auto farm", Flag = "AutoFarm", Callback = function(on) end })

	Window:Notify({ Title = "Loaded", Content = "Press RightShift to hide", Icon = "check_circle" })

	-- HUD (stays up while the window is hidden)
	Window:AddWatermark({ FPS = true, Ping = true, Clock = true })
	Window:AddKeybindList()
	Window:AddIndicator({ Text = "AUTO", Icon = "bolt" })

	-- Loading screen: on by default; LoadingScreen = false turns it off,
	-- or { Title, Subtitle, Icon, Duration } customizes it.
	if not Window.IsLoaded then Window.Loaded:Wait() end -- if you need the window on screen first
]]
local ContentProvider = game:GetService("ContentProvider")
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")

local Root = script.Parent.Parent
local Create = require(Root.Util.Create)
local Maid = require(Root.Util.Maid)
local Signal = require(Root.Util.Signal)
local Theme = require(Root.Core.Theme)
local Typography = require(Root.Core.Typography)
local Shape = require(Root.Core.Shape)
local Motion = require(Root.Core.Motion)
local Elevation = require(Root.Core.Elevation)
local StateLayer = require(Root.Core.StateLayer)
local Icons = require(Root.Core.Icons)
local Dialog = require(Root.Components.Dialog)
local Env = require(Root.Executor.Env)
local Assets = require(Root.Executor.Assets)
local IconImages = require(Root.Executor.IconImages)
local Themer = require(script.Parent.Themer)
local Config = require(script.Parent.Config)
local Notifier = require(script.Parent.Notifier)
local Tab = require(script.Parent.Tab)
local Base = require(script.Parent.Elements.Base)
local makeDraggable = require(script.Parent.Draggable)
local HUD = require(script.Parent.HUD)
local LoadingScreen = require(script.Parent.LoadingScreen)

local TOP_BAR_HEIGHT = 56
local NAV_WIDTH = 168
local DEFAULT_SIZE = UDim2.fromOffset(600, 420)
local MIN_SIZE = Vector2.new(420, 280) -- smallest size the resize handle allows

local Window = {}
Window.__index = Window

local function isPress(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function isMove(input)
	return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
end

local function toKeyCode(value)
	if typeof(value) == "EnumItem" then
		return value
	elseif type(value) == "string" then
		local ok, key = pcall(function()
			return (Enum.KeyCode :: any)[value]
		end)
		return ok and key or nil
	end
	return nil
end

local function sanitize(name: string): string
	return (tostring(name):gsub("[^%w%-_ ]", ""))
end

-- Where the copies of a blurred background image go: the image itself, then
-- two rings of 6 (half and full radius, the outer ring turned 30 degrees).
-- Averaging the copies gives a soft blur; Roblox has no blur for UI.
local MAX_BACKGROUND_BLUR = 24
local function blurOffsets(radius: number): { Vector2 }
	local offsets = { Vector2.new(0, 0) }
	if radius <= 0 then
		return offsets
	end
	for ring, distance in { radius * 0.5, radius } do
		for i = 0, 5 do
			local angle = (i / 6 + (ring - 1) / 12) * math.pi * 2
			table.insert(offsets, Vector2.new(math.cos(angle) * distance, math.sin(angle) * distance))
		end
	end
	return offsets
end

-- True for a .webm URL / file, which SetBackground plays as a video.
local function isVideoSource(source): boolean
	if type(source) ~= "string" then
		return false
	end
	local path = source:gsub("[?#].*$", "")
	return path:lower():match("%.webm$") ~= nil
end

function Window.new(props)
	props = props or {}
	local self = setmetatable({}, Window)
	self.Title = props.Title or props.Name or "MD3"
	-- Every tab's AddSection becomes its own sub-tab (Tab props can override).
	self._sectionsAsSubTabs = props.SectionsAsSubTabs == true
	self.Flags = {}
	self.Tabs = {}
	self.SelectedTab = nil
	self.Visible = true
	self.Minimized = false
	self.OnUnload = Signal.new()
	-- Fires once the loading screen is done and the window is shown (right
	-- away when there is no loading screen: check IsLoaded before waiting).
	self.Loaded = Signal.new()
	self.IsLoaded = false
	-- Every Keybind element, and a signal fired when one is added, removed,
	-- rebound or switched on/off (drives the HUD keybind list).
	self._keybinds = {}
	self.KeybindsChanged = Signal.new()
	self._maid = Maid.new()
	self._toggleKey = toKeyCode(props.ToggleKey or props.Keybind) or Enum.KeyCode.RightShift
	self._size = props.Size or DEFAULT_SIZE
	self._defaultSize = self._size
	self._rememberSize = props.RememberSize ~= false

	-- Replace the window a previous run of the same script left behind.
	local registry = Env.Registry()
	registry.Windows = registry.Windows or {}
	self._registryKey = props.Id or self.Title
	local previous = registry.Windows[self._registryKey]
	if previous and previous ~= self and props.ReplaceExisting ~= false then
		pcall(previous.Destroy, previous)
	end
	registry.Windows[self._registryKey] = self

	self._configFolder = props.ConfigFolder or props.Folder or `MD3/{sanitize(self.Title)}`

	-- The size the user resized the window to last time (window.json).
	if self._rememberSize then
		local saved = self:_readSavedSize()
		if saved then
			self._size = UDim2.fromOffset(saved.X, saved.Y)
		end
	end

	-- Material icons as a sprite-sheet image, loaded the way NeverLose loads
	-- its images (HttpGet -> writefile -> getcustomasset). Runs in the
	-- background so the window appears immediately; icons start out as
	-- BuilderIcons / symbols and switch over in place once it's ready. An
	-- explicit IconStyle always (re)loads; otherwise keep what's loaded.
	-- The loading screen waits for this.
	self._iconsReady = true
	if props.Icons ~= false and props.IconFont ~= false and (props.IconStyle ~= nil or not Icons.GetSheet()) then
		self._iconsReady = false
		task.spawn(function()
			local ok, err = IconImages.Load(props.IconStyle)
			self._iconsReady = true
			if not ok and Env.CanUseCustomAssets then
				warn(`\[MD3] could not load the icon images: {err}`)
			end
		end)
	end

	self.Theme = props.Theme or Theme.new(props.ThemeColor or props.Seed or props.Accent, props.Mode or "Dark")
	-- A preset first; explicit ThemeColor / Mode / TextColor / IconColor win over it.
	if props.Preset and not props.Theme then
		if not self.Theme:ApplyPreset(props.Preset) then
			warn(`\[MD3] unknown theme preset "{props.Preset}"`)
		end
		local seed = props.ThemeColor or props.Seed or props.Accent
		if seed then
			self.Theme:SetSeedColor(seed)
		end
		if props.Mode then
			self.Theme:SetMode(props.Mode)
		end
	end
	if props.TextColor then
		self.Theme:SetTextColor(props.TextColor)
	end
	if props.IconColor then
		self.Theme:SetIconColor(props.IconColor)
	end
	self._themer = Themer.new(self.Theme)
	local themer = self._themer

	--== ScreenGui ==--
	local gui = Create("ScreenGui") {
		Name = props.GuiName or Env.RandomName(),
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = props.DisplayOrder or 100,
	}
	Env.ProtectGui(gui)
	gui.Parent = props.Parent or Env.GetGuiParent()
	self.Gui = gui

	--== Backdrop (dark dimming overlay) ==--
	local backdrop = Create("Frame") {
		Name = "Backdrop",
		BackgroundColor3 = Color3.fromRGB(0, 0, 0),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromScale(0, 0),
		ZIndex = 0,
		Active = false,
		Visible = false,
		Parent = gui,
	}
	self._backdrop = backdrop
	self._backdropEnabled = props.Backdrop ~= false
	self._backdropTransparency = props.BackdropTransparency or 0.55

	--== Snowfall Particle Effect ==--
	local snowContainer = Create("Frame") {
		Name = "SnowContainer",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromScale(0, 0),
		ClipsDescendants = true,
		ZIndex = 0,
		Active = false,
		Visible = false,
		Parent = gui,
	}
	self._snowContainer = snowContainer
	self._snowEnabled = props.Snowfall == true
	self._snowSettings = {
		SpeedMultiplier = props.SnowSpeed or 1.0,
		BaseSize = props.SnowBaseSize or 5,
		Count = props.SnowCount or 45,
	}
	self._snowflakes = {}

	local function getScreenBounds()
		local cam = workspace.CurrentCamera
		local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
		return math.max(vp.X, 800), math.max(vp.Y, 600)
	end

	local function createFlake(i)
		local sw, sh = getScreenBounds()
		local flake = Create("Frame") {
			Name = "Flake_" .. i,
			BorderSizePixel = 0,
			BackgroundColor3 = Color3.fromRGB(240, 245, 255),
			Parent = snowContainer,
			[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
		}
		local sizeRatio = math.random(70, 140) / 100
		local curSize = math.clamp(math.round(self._snowSettings.BaseSize * sizeRatio), 2, 30)
		flake.Size = UDim2.fromOffset(curSize, curSize)
		flake.BackgroundTransparency = math.random(25, 70) / 100
		local posX = math.random(0, sw)
		local posY = math.random(0, sh)
		flake.Position = UDim2.fromOffset(posX, posY)
		return {
			inst = flake,
			x = posX,
			y = posY,
			sizeRatio = sizeRatio,
			baseSpeed = math.random(40, 100),
			swayAmp = math.random(15, 35),
			swayFreq = math.random(8, 20) / 10,
			phase = math.random() * math.pi * 2,
		}
	end
	self._createFlake = createFlake

	for i = 1, self._snowSettings.Count do
		table.insert(self._snowflakes, createFlake(i))
	end

	local snowElapsed = 0
	self._maid:GiveTask(RunService.RenderStepped:Connect(function(dt)
		if not (self.Visible and not self.Minimized and self._snowEnabled) then
			return
		end
		snowElapsed += dt
		local sw, sh = getScreenBounds()
		for _, f in ipairs(self._snowflakes) do
			f.y += f.baseSpeed * self._snowSettings.SpeedMultiplier * dt
			if f.y > sh + 10 then
				f.y = -10
				f.x = math.random(0, sw)
			end
			local currentX = (f.x + math.sin(snowElapsed * f.swayFreq + f.phase) * f.swayAmp) % sw
			f.inst.Position = UDim2.fromOffset(currentX, f.y)
		end
	end))

	--== Custom Cursor ==--
	local cursorSettings = {
		Enabled = props.CustomCursor == true,
		Scale = props.CursorScale or 100,
	}
	self._cursorSettings = cursorSettings

	local cursorGui = Create("ScreenGui") {
		Name = "CustomCursorGui",
		ResetOnSpawn = false,
		DisplayOrder = 999999,
		IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		Parent = gui.Parent or Env.GetGuiParent(),
	}
	Env.ProtectGui(cursorGui)
	self._cursorGui = cursorGui
	self._maid:GiveTask(cursorGui)

	local cursorContainer = Create("Frame") {
		Name = "CursorContainer",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromOffset(0, 0),
		Active = false,
		Visible = false,
		Parent = cursorGui,
	}
	self._cursorContainer = cursorContainer

	local cursorScale = Create("UIScale") {
		Name = "CursorScale",
		Scale = cursorSettings.Scale / 100,
		Parent = cursorContainer,
	}
	self._cursorScale = cursorScale

	local cursorPointer = Create("ImageLabel") {
		Name = "CursorPointer",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromOffset(64, 64),
		Position = UDim2.fromOffset(-31, -32),
		Image = "rbxasset://textures/Cursors/KeyboardMouse/ArrowFarCursor.png",
		ImageColor3 = self.Theme.Colors.Primary or Color3.fromRGB(220, 205, 255),
		Active = false,
		ZIndex = 1000000,
		Parent = cursorContainer,
	}
	themer:Bind(cursorPointer, { ImageColor3 = "Primary" })
	self._cursorPointer = cursorPointer

	self._maid:GiveTask(RunService.RenderStepped:Connect(function()
		if self.Visible and not self.Minimized then
			if UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default then
				UserInputService.MouseBehavior = Enum.MouseBehavior.Default
			end
			if not (self._cursorSettings and self._cursorSettings.Enabled) then
				if not UserInputService.MouseIconEnabled then
					UserInputService.MouseIconEnabled = true
				end
			end
		end
		if cursorContainer and cursorContainer.Visible then
			local mousePos = UserInputService:GetMouseLocation()
			cursorContainer.Position = UDim2.fromOffset(mousePos.X, mousePos.Y)
		end
	end))

	--== Main surface ==--
	local main = Create("Frame") {
		Name = "Main",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = self._size,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Active = true,
		Parent = gui,
	}
	Shape.Corner(Shape.Large, main)
	themer:Bind(main, { BackgroundColor3 = "Surface" })
	themer:Bind(Create("UIStroke") {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
		Parent = main,
	}, { Color = "OutlineVariant" })
	local uiScale = Create("UIScale") { Parent = main }
	self.Instance = main
	self._uiScale = uiScale

	-- Custom background (SetBackground): an image, or a looping muted WebM
	-- video, behind everything in the window and rounded like it. Its
	-- transparency lets the window color through.
	-- The image lives in a CanvasGroup: it clips the blur copies to the
	-- window's rounded shape and fades them together (GroupTransparency).
	local backgroundGroup = Create("CanvasGroup") {
		Name = "Background",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 0,
		Visible = false,
		Parent = main,
	}
	Shape.Corner(Shape.Large, backgroundGroup)
	local background = Create("ImageLabel") {
		Name = "Image",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1, 1),
		ScaleType = Enum.ScaleType.Crop,
		ZIndex = 1,
		Visible = false,
		Parent = backgroundGroup,
	}
	local video = Create("VideoFrame") {
		Name = "BackgroundVideo",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 0,
		Looped = true,
		Volume = 0,
		Visible = false,
		Parent = main,
	}
	Shape.Corner(Shape.Large, video)
	-- A VideoFrame has no transparency of its own: a window-colored veil on
	-- top does what ImageTransparency does for the image.
	local veil = Create("Frame") {
		Name = "Veil",
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		Parent = video,
	}
	Shape.Corner(Shape.Large, veil)
	themer:Bind(veil, {
		BackgroundColor3 = function(colors)
			return colors.Surface
		end,
	})
	-- Don't decode video nobody can see.
	self._maid:GiveTask(main:GetPropertyChangedSignal("Visible"):Connect(function()
		video.Playing = main.Visible and video.Visible
	end))
	self._background = background
	self._backgroundGroup = backgroundGroup
	self._backgroundLayers = { background } -- [1] is the image itself, then blur copies
	self._backgroundBlur = 0
	self._backgroundVideo = video
	self._backgroundVeil = veil
	self._backgroundSource = nil
	self._backgroundKind = nil
	self._backgroundTransparency = math.clamp(props.BackgroundTransparency or 0.4, 0, 1)
	backgroundGroup.GroupTransparency = self._backgroundTransparency
	veil.BackgroundTransparency = 1 - self._backgroundTransparency
	if props.BackgroundBlur then
		self:SetBackgroundBlur(props.BackgroundBlur)
	end

	-- The shadow is a sibling of `main`, outside its UIScale, so it gets its
	-- own UIScale kept in sync (otherwise it stays full size on phones).
	local shadowScale = nil
	local function applyShadow()
		local holder = Elevation.Apply(main, 3, self.Theme.Colors.Shadow, Shape.Large)
		shadowScale = holder and Create("UIScale") { Scale = uiScale.Scale, Parent = holder }
	end
	applyShadow()
	self._maid:GiveTask(self.Theme.Changed:Connect(applyShadow))
	self._maid:GiveTask(uiScale:GetPropertyChangedSignal("Scale"):Connect(function()
		if shadowScale then
			shadowScale.Scale = uiScale.Scale
		end
	end))

	--== Top app bar ==--
	local topBar = Create("Frame") {
		Name = "TopBar",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, TOP_BAR_HEIGHT),
		Active = true,
		Parent = main,
	}

	-- Logo = a colored image kept as-is; Icon = a tinted Material icon or image.
	local appIconSource = props.Logo or props.Icon
	local hasAppIcon = appIconSource ~= nil and Base.CanShowIcon(appIconSource)
	self._appIconSource = appIconSource -- reused by the HUD watermark
	self._appIconTint = props.Logo == nil
	if hasAppIcon then
		local appIcon = Base.Glyph(themer, appIconSource, 24, props.AppIconColor or "IconAccent", topBar, props.Logo == nil)
		appIcon.AnchorPoint = Vector2.new(0, 0.5)
		appIcon.Position = UDim2.new(0, 20, 0.5, 0)
		-- A glyph may still be waiting for the icon images; a failed image won't come back.
		if appIcon:IsA("ImageLabel") and not appIcon.Visible then
			appIcon:Destroy()
			hasAppIcon = false
		end
	end

	local titleColumn = Create("Frame") {
		Name = "Titles",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(hasAppIcon and 56 or 20, 0),
		Size = UDim2.new(1, -(hasAppIcon and 56 or 20) - 96, 1, 0),
		Parent = topBar,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Vertical,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
		},
	}
	local title = Create("TextLabel") {
		Name = "Title",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 22),
		Text = self.Title,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 1,
		Parent = titleColumn,
	}
	Typography.Apply(title, "TitleMedium")
	themer:Bind(title, { TextColor3 = "OnSurface" })
	self._titleLabel = title

	local subtitle = Create("TextLabel") {
		Name = "Subtitle",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 16),
		Text = props.Subtitle or "",
		Visible = (props.Subtitle or "") ~= "",
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 2,
		Parent = titleColumn,
	}
	Typography.Apply(subtitle, "BodySmall")
	themer:Bind(subtitle, { TextColor3 = "OnSurfaceVariant" })
	self._subtitleLabel = subtitle

	local actions = Create("Frame") {
		Name = "Actions",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -12, 0.5, 0),
		Size = UDim2.fromOffset(80, 36),
		Visible = props.Actions ~= false,
		Parent = topBar,
		[1] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 4),
		},
	}

	local function barButton(iconName: string, order: number, onActivated)
		local button = Create("TextButton") {
			Name = iconName,
			AutoButtonColor = false,
			Text = "",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(36, 36),
			LayoutOrder = order,
			Parent = actions,
		}
		Shape.Corner(Shape.Full, button)
		local glyph = Base.Glyph(themer, iconName, 20, "Icon", button)
		glyph.AnchorPoint = Vector2.new(0.5, 0.5)
		glyph.Position = UDim2.fromScale(0.5, 0.5)
		local layer = StateLayer.new(button, self.Theme.Colors.OnSurfaceVariant, Shape.Full)
		themer:Bind(layer.Instance, { BackgroundColor3 = "OnSurfaceVariant" })
		self._maid:GiveTask(button.MouseEnter:Connect(function()
			layer:SetState("Hover", true)
		end))
		self._maid:GiveTask(button.MouseLeave:Connect(function()
			layer:SetState("Hover", false)
		end))
		self._maid:GiveTask(button.Activated:Connect(onActivated))
		return button
	end

	if props.MinimizeButton ~= false then
		barButton("minimize", 1, function()
			self:Minimize()
		end)
	end
	if props.CloseButton ~= false then
		barButton("close", 2, function()
			self:_confirmClose()
		end)
	end

	makeDraggable(self._maid, topBar, main)

	--== TopBar Search Box & Settings Search Dropdown ==--
	self._searchableItems = {}
	if props.Search ~= false then
		local searchBox = Create("Frame") {
			Name = "TopLeftSearchBox",
			Size = UDim2.new(0, 210, 0, 32),
			Position = UDim2.new(0, 140, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			BackgroundColor3 = self.Theme.Colors.SurfaceContainerHigh or Color3.fromRGB(30, 28, 38),
			BackgroundTransparency = 0.2,
			BorderSizePixel = 0,
			ZIndex = 5,
			Parent = topBar,
			[1] = Create("UICorner") { CornerRadius = UDim.new(0, 8) },
			[2] = Create("UIStroke") {
				Color = self.Theme.Colors.OutlineVariant or Color3.fromRGB(65, 60, 80),
				Thickness = 1,
				Transparency = 0.4,
			},
		}
		themer:Bind(searchBox, { BackgroundColor3 = "SurfaceContainerHigh" })

		local searchIcon = Create("ImageLabel") {
			Name = "SearchIcon",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(16, 16),
			Position = UDim2.new(0, 8, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			Image = "rbxasset://textures/ui/SearchIcon.png",
			ImageColor3 = self.Theme.Colors.OnSurfaceVariant or Color3.fromRGB(160, 155, 175),
			ZIndex = 6,
			Parent = searchBox,
		}
		themer:Bind(searchIcon, { ImageColor3 = "OnSurfaceVariant" })

		local searchInput = Create("TextBox") {
			Name = "SearchInput",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, -56, 1, 0),
			Position = UDim2.new(0, 30, 0, 0),
			PlaceholderText = props.SearchPlaceholder or "Search settings...",
			PlaceholderColor3 = Color3.fromRGB(140, 135, 155),
			Text = "",
			TextColor3 = self.Theme.Colors.OnSurface or Color3.fromRGB(240, 240, 255),
			TextSize = 13,
			Font = Enum.Font.Gotham,
			TextXAlignment = Enum.TextXAlignment.Left,
			ClearTextOnFocus = false,
			ZIndex = 6,
			Parent = searchBox,
		}
		themer:Bind(searchInput, { TextColor3 = "OnSurface" })

		local clearBtn = Create("TextButton") {
			Name = "ClearBtn",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(20, 20),
			Position = UDim2.new(1, -6, 0.5, 0),
			AnchorPoint = Vector2.new(1, 0.5),
			Text = "x",
			TextColor3 = Color3.fromRGB(150, 145, 165),
			Font = Enum.Font.GothamBold,
			TextSize = 13,
			Visible = false,
			ZIndex = 6,
			Parent = searchBox,
		}

		local searchDropdown = Create("Frame") {
			Name = "SearchDropdown",
			Size = UDim2.new(0, 260, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Position = UDim2.new(0, 140, 0, TOP_BAR_HEIGHT - 4),
			BackgroundColor3 = self.Theme.Colors.SurfaceContainerHigh or Color3.fromRGB(24, 22, 30),
			BorderSizePixel = 0,
			ZIndex = 60,
			Visible = false,
			Parent = main,
			[1] = Create("UICorner") { CornerRadius = UDim.new(0, 10) },
			[2] = Create("UIStroke") {
				Color = self.Theme.Colors.OutlineVariant or Color3.fromRGB(70, 65, 85),
				Thickness = 1,
				Transparency = 0.3,
			},
			[3] = Create("UIListLayout") {
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 4),
			},
			[4] = Create("UIPadding") {
				PaddingTop = UDim.new(0, 6),
				PaddingBottom = UDim.new(0, 6),
				PaddingLeft = UDim.new(0, 6),
				PaddingRight = UDim.new(0, 6),
			},
		}
		themer:Bind(searchDropdown, { BackgroundColor3 = "SurfaceContainerHigh" })

		clearBtn.Activated:Connect(function()
			searchInput.Text = ""
			clearBtn.Visible = false
			searchDropdown.Visible = false
		end)

		local function performJump(item)
			searchDropdown.Visible = false
			if item.tab then
				self:SelectTab(item.tab)
			end
			task.wait(0.08)
			if item.subTab and item.tab then
				if item.tab._subTabs and item.tab._subTabs[item.subTab] and item.tab._subTabs[item.subTab].Select then
					item.tab._subTabs[item.subTab].Select()
				elseif item.tab.Instance then
					local subBtn = item.tab.Instance:FindFirstChild("SubBtn_" .. item.subTab, true)
					if subBtn and typeof(getconnections) == "function" then
						for _, conn in ipairs(getconnections(subBtn.Activated)) do
							conn:Fire()
						end
					end
				end
			end
			task.wait(0.08)
			local targetInst = item.target
			if targetInst and targetInst:IsDescendantOf(game) then
				local page = item.tab and item.tab.Instance
				if page and page:IsA("ScrollingFrame") then
					local relY = targetInst.AbsolutePosition.Y - page.AbsolutePosition.Y + page.CanvasPosition.Y
					page.CanvasPosition = Vector2.new(0, math.max(0, relY - 40))
				end
				local highlight = Instance.new("UIStroke")
				highlight.Name = "SearchHighlight"
				highlight.Color = self.Theme.Colors.Primary or Color3.fromRGB(180, 160, 255)
				highlight.Thickness = 2
				highlight.Transparency = 0
				highlight.Parent = targetInst
				TweenService:Create(highlight, TweenInfo.new(1.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					Transparency = 1,
					Thickness = 4,
				}):Play()
				task.delay(1.3, function()
					pcall(function() highlight:Destroy() end)
				end)
			end
		end

		searchInput:GetPropertyChangedSignal("Text"):Connect(function()
			local query = searchInput.Text:lower():match("^%s*(.-)%s*$")
			clearBtn.Visible = (searchInput.Text ~= "")
			if not query or query == "" then
				searchDropdown.Visible = false
				return
			end

			local matches = {}
			for _, item in ipairs(self._searchableItems) do
				if (item.name and string.find(item.name:lower(), query, 1, true)) or (item.path and string.find(item.path:lower(), query, 1, true)) then
					table.insert(matches, item)
					if #matches >= 8 then break end
				end
			end

			for _, child in ipairs(searchDropdown:GetChildren()) do
				if child:IsA("TextButton") or child:IsA("Frame") then
					child:Destroy()
				end
			end

			if #matches == 0 then
				local empty = Create("TextLabel") {
					Name = "EmptyLabel",
					BackgroundTransparency = 1,
					Size = UDim2.new(1, 0, 0, 28),
					Text = "No settings found",
					TextColor3 = Color3.fromRGB(140, 135, 155),
					Font = Enum.Font.Gotham,
					TextSize = 12,
					ZIndex = 61,
					Parent = searchDropdown,
				}
				searchDropdown.Visible = true
				return
			end

			for i, match in ipairs(matches) do
				local resBtn = Create("TextButton") {
					Name = "Result_" .. i,
					BackgroundTransparency = 1,
					Size = UDim2.new(1, 0, 0, 36),
					LayoutOrder = i,
					Text = "",
					AutoButtonColor = false,
					ZIndex = 61,
					Parent = searchDropdown,
					[1] = Create("UICorner") { CornerRadius = UDim.new(0, 6) },
				}
				local titleLbl = Create("TextLabel") {
					Name = "Title",
					BackgroundTransparency = 1,
					Position = UDim2.new(0, 8, 0, 3),
					Size = UDim2.new(1, -16, 0, 16),
					Text = match.name or "Setting",
					Font = Enum.Font.GothamBold,
					TextSize = 13,
					TextColor3 = Color3.fromRGB(230, 230, 245),
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					ZIndex = 62,
					Parent = resBtn,
				}
				local pathLbl = Create("TextLabel") {
					Name = "Path",
					BackgroundTransparency = 1,
					Position = UDim2.new(0, 8, 0, 19),
					Size = UDim2.new(1, -16, 0, 14),
					Text = match.path or "",
					Font = Enum.Font.Gotham,
					TextSize = 10,
					TextColor3 = Color3.fromRGB(150, 145, 170),
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					ZIndex = 62,
					Parent = resBtn,
				}

				resBtn.MouseEnter:Connect(function()
					resBtn.BackgroundTransparency = 0.8
					resBtn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
				end)
				resBtn.MouseLeave:Connect(function()
					resBtn.BackgroundTransparency = 1
				end)
				resBtn.Activated:Connect(function()
					performJump(match)
				end)
			end

			searchDropdown.Visible = true
		end)
	end

	--== Body: navigation drawer + content ==--
	local body = Create("Frame") {
		Name = "Body",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, TOP_BAR_HEIGHT),
		Size = UDim2.new(1, 0, 1, -TOP_BAR_HEIGHT),
		Parent = main,
	}
	self._body = body

	local navList = Create("ScrollingFrame") {
		Name = "Navigation",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 16, 0, 4),
		Size = UDim2.new(1, -32, 0, 42),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.X,
		ScrollBarThickness = 0,
		ScrollingDirection = Enum.ScrollingDirection.X,
		ZIndex = 3,
		Parent = body,
		[1] = Create("UIPadding") {
			PaddingLeft = UDim.new(0, 0),
			PaddingRight = UDim.new(0, 0),
			PaddingTop = UDim.new(0, 0),
			PaddingBottom = UDim.new(0, 0),
		},
		[2] = Create("UIListLayout") {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		},
	}
	self._navList = navList

	-- Floating sliding indicator pill inside body (behind navList buttons)
	local navPill = Create("Frame") {
		Name = "NavSlideIndicator",
		BackgroundColor3 = self.Theme.Colors.SecondaryContainer or Color3.fromRGB(74, 68, 88),
		BorderSizePixel = 0,
		ZIndex = 1,
		Active = false,
		Visible = false,
		Parent = body,
	}
	Shape.Corner(Shape.Full, navPill)
	local pillStroke = Create("UIStroke") {
		Thickness = 1.2,
		Color = self.Theme.Colors.Primary or Color3.fromRGB(208, 188, 255),
		Transparency = 0.5,
		Parent = navPill,
	}
	themer:Bind(navPill, { BackgroundColor3 = "SecondaryContainer" })
	themer:Bind(pillStroke, { Color = "Primary" })
	self._navPill = navPill

	local pages = Create("Frame") {
		Name = "Pages",
		BorderSizePixel = 0,
		Position = UDim2.new(0, 16, 0, 50),
		Size = UDim2.new(1, -32, 1, -60),
		ClipsDescendants = true,
		Parent = body,
	}
	Shape.Corner(Shape.Large, pages)
	themer:Bind(pages, { BackgroundColor3 = "SurfaceContainerLow" })
	self._pages = pages

	self._maid:GiveTask(navList:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
		if self._currentActiveBtn and self._currentActiveBtn:IsDescendantOf(game) and self._navPill and self._body then
			local relX = self._currentActiveBtn.AbsolutePosition.X - self._body.AbsolutePosition.X
			local relY = self._currentActiveBtn.AbsolutePosition.Y - self._body.AbsolutePosition.Y
			self._navPill.Position = UDim2.fromOffset(relX, relY)
			self._navPill.Size = UDim2.fromOffset(self._currentActiveBtn.AbsoluteSize.X, self._currentActiveBtn.AbsoluteSize.Y)
		end
	end))

	self._maid:GiveTask(body:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		if self._currentActiveBtn and self._currentActiveBtn:IsDescendantOf(game) and self._navPill and self._body then
			local relX = self._currentActiveBtn.AbsolutePosition.X - self._body.AbsolutePosition.X
			local relY = self._currentActiveBtn.AbsolutePosition.Y - self._body.AbsolutePosition.Y
			self._navPill.Position = UDim2.fromOffset(relX, relY)
			self._navPill.Size = UDim2.fromOffset(self._currentActiveBtn.AbsoluteSize.X, self._currentActiveBtn.AbsoluteSize.Y)
		end
	end))

	--== Resize handle (bottom-right corner) ==--
	local grip = Create("TextButton") {
		Name = "Resize",
		AutoButtonColor = false,
		Text = "",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.fromScale(1, 1),
		Size = UDim2.fromOffset(28, 28),
		ZIndex = 20,
		Parent = main,
	}
	-- Two diagonal strokes, the usual "drag to resize" grip: a long one and
	-- a short one nearer the corner.
	for _, spec in { { length = 12, inset = 11 }, { length = 6, inset = 7 } } do
		local stroke = Create("Frame") {
			Name = "Stroke",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(1, -spec.inset, 1, -spec.inset),
			Size = UDim2.fromOffset(spec.length, 2),
			Rotation = -45,
			BorderSizePixel = 0,
			ZIndex = 21,
			Parent = grip,
			[1] = Create("UICorner") { CornerRadius = UDim.new(1, 0) },
		}
		themer:Bind(stroke, { BackgroundColor3 = "Outline" })
	end
	self._grip = grip

	do
		local resizing, startInput, startSize, startPos = false, nil, nil, nil
		self._maid:GiveTask(grip.InputBegan:Connect(function(input)
			if isPress(input) and not self.Minimized then
				resizing = true
				startInput = input.Position
				startSize = Vector2.new(self._size.X.Offset, self._size.Y.Offset)
				startPos = main.Position
			end
		end))
		self._maid:GiveTask(UserInputService.InputChanged:Connect(function(input)
			if not resizing or not isMove(input) then
				return
			end
			-- Screen pixels -> unscaled window pixels (UIScale shrinks it on phones).
			local scale = uiScale.Scale
			local delta = (input.Position - startInput) / scale
			local camera = workspace.CurrentCamera
			local viewport = if camera then camera.ViewportSize else Vector2.new(1920, 1080)
			local width = math.clamp(startSize.X + delta.X, MIN_SIZE.X, math.max(MIN_SIZE.X, viewport.X / scale - 24))
			local height = math.clamp(startSize.Y + delta.Y, MIN_SIZE.Y, math.max(MIN_SIZE.Y, viewport.Y / scale - 24))
			self._size = UDim2.fromOffset(math.round(width), math.round(height))
			main.Size = self._size
			-- The window is centered on its Position; move it by half the growth
			-- so the top-left corner stays put and the grip follows the pointer.
			main.Position = UDim2.new(
				startPos.X.Scale,
				startPos.X.Offset + (width - startSize.X) * scale / 2,
				startPos.Y.Scale,
				startPos.Y.Offset + (height - startSize.Y) * scale / 2
			)
		end))
		self._maid:GiveTask(UserInputService.InputEnded:Connect(function(input)
			if resizing and isPress(input) then
				resizing = false
				self:_saveSize()
			end
		end))
	end

	--== Notifications ==--
	self._notifier = Notifier.new(gui, themer)

	--== Floating open/close button (for touch devices without a keyboard) ==--
	local showMobileButton = props.MobileButton
	if showMobileButton == nil then
		showMobileButton = UserInputService.TouchEnabled
	end
	if showMobileButton then
		local mobileButton = Create("TextButton") {
			Name = "Toggle",
			AutoButtonColor = false,
			Text = "",
			Position = UDim2.new(0, 16, 0.3, 0),
			Size = UDim2.fromOffset(48, 48),
			BorderSizePixel = 0,
			ZIndex = 60,
			Parent = gui,
		}
		Shape.Corner(Shape.Large, mobileButton)
		themer:Bind(mobileButton, { BackgroundColor3 = "PrimaryContainer" })
		local source = props.Logo or (props.Icon and Base.CanShowIcon(props.Icon) and props.Icon) or "menu"
		local glyph = Base.Glyph(themer, source, props.Logo and 32 or 24, "OnPrimaryContainer", mobileButton, props.Logo == nil)
		glyph.AnchorPoint = Vector2.new(0.5, 0.5)
		glyph.Position = UDim2.fromScale(0.5, 0.5)
		glyph.ZIndex = 61
		makeDraggable(self._maid, mobileButton, mobileButton, function()
			self:Toggle()
		end)
		self._mobileButton = mobileButton
	end

	--== Input: toggle key ==--
	self._maid:GiveTask(UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed or UserInputService:GetFocusedTextBox() or self:_isCapturingKey(input) then
			return
		end
		if self._toggleKey and input.KeyCode == self._toggleKey then
			self:Toggle()
		end
	end))

	--== Fit small screens (phones) ==--
	local function rescale()
		if props.Scale then
			uiScale.Scale = props.Scale
			return
		end
		local camera = workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
		local fit = math.min(1, (viewport.X - 24) / self._size.X.Offset, (viewport.Y - 24) / self._size.Y.Offset)
		uiScale.Scale = math.max(fit, 0.4)
	end
	rescale()
	local camera = workspace.CurrentCamera
	if camera then
		self._maid:GiveTask(camera:GetPropertyChangedSignal("ViewportSize"):Connect(rescale))
	end

	--== Silent start ==--
	-- Nothing pops up: no loading screen, the window starts hidden (toggle
	-- key / mobile button opens it) and autoload doesn't notify.
	self.Silent = props.Silent == true
	-- Toasts when the player's own keybinds (AddKeybind) are used; the UI
	-- toggle key never notifies. Off in Silent mode.
	self._keybindNotify = props.KeybindNotify ~= false
	if self.Silent then
		self.Visible = false
		main.Visible = false
	end

	--== Loading screen ==--
	-- On unless the script passes LoadingScreen = false (or Silent); the
	-- player can also turn it off from the settings tab (ConfigFolder/loading.txt).
	self._loadingAllowed = props.LoadingScreen ~= false and not self.Silent
	if self._loadingAllowed and self:GetLoadingScreenEnabled() then
		self._loading = true
		main.Visible = false
		self._loadingScreen = LoadingScreen.Run(self, props.LoadingScreen, function()
			self._loading = false
			self._loadingScreen = nil
			if self._destroyed then
				return
			end
			self.IsLoaded = true
			if self.Visible then
				self:SetVisible(true)
			end
			self.Loaded:Fire()
		end)
	else
		self.IsLoaded = true
	end

	if props.Background then
		-- Downloading can take a moment; don't hold up CreateWindow.
		task.spawn(function()
			local ok, err = self:SetBackground(props.Background, nil, props.BackgroundKind)
			if not ok and not self._destroyed then
				warn(`\[MD3] background: {err}`)
				if not self.Silent then
					self:Notify({ Title = "Background unavailable", Content = err or "", Icon = "error" })
				end
			end
		end)
	end

	return self
end

--== Internal helpers ==--

-- Runs a user callback without letting its errors break the UI.
function Window:_call(fn, ...)
	task.spawn(function(...)
		local ok, err = xpcall(fn, debug.traceback, ...)
		if not ok then
			warn(`\[MD3] {self.Title}: callback error: {err}`)
		end
	end, ...)
end

-- True while a Keybind element is waiting for (or has just consumed) this
-- key press, so rebinding a key doesn't also trigger whatever it's bound to.
-- Matched by key + time rather than InputObject identity, since Roblox may
-- reuse InputObjects between presses.
function Window:_isCapturingKey(input): boolean
	if self._keybindListening then
		return true
	end
	return input ~= nil
		and self._capturedKey ~= nil
		and input.KeyCode == self._capturedKey
		and os.clock() - self._capturedAt < 0.1
end

function Window:_confirmClose()
	self:Dialog({
		Title = "Close window?",
		Content = `Hide keeps the script running (press {self.\_toggleKey and self.\_toggleKey.Name or "the toggle key"} to reopen). Unload destroys the UI.`,
		Buttons = {
			{ Title = "Cancel", Variant = "Text" },
			{
				Title = "Unload",
				Variant = "Text",
				Callback = function()
					self:Destroy()
				end,
			},
			{
				Title = "Hide",
				Variant = "Filled",
				Callback = function()
					self:SetVisible(false)
				end,
			},
		},
	})
end

--== Tabs ==--

function Window:_slideToTab(tab, instant)
	if not (tab and tab._button and self._navPill and self._body) then
		return
	end
	self._currentActiveBtn = tab._button
	local btn = tab._button
	local relX = btn.AbsolutePosition.X - self._body.AbsolutePosition.X
	local relY = btn.AbsolutePosition.Y - self._body.AbsolutePosition.Y
	local targetPos = UDim2.fromOffset(relX, relY)
	local targetSize = UDim2.fromOffset(btn.AbsoluteSize.X, btn.AbsoluteSize.Y)

	if self._pillTween then
		self._pillTween:Cancel()
		self._pillTween = nil
	end

	self._navPill.Visible = true
	if instant then
		self._navPill.Position = targetPos
		self._navPill.Size = targetSize
	else
		self._pillTween = TweenService:Create(self._navPill, TweenInfo.new(0.32, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
			Position = targetPos,
			Size = targetSize,
		})
		self._pillTween:Play()
	end
end

function Window:AddTab(props)
	local tab = Tab.new(self, props)
	table.insert(self.Tabs, tab)
	if not self.SelectedTab then
		self:SelectTab(tab)
		task.defer(function()
			self:_slideToTab(tab, true)
		end)
	end
	return tab
end
Window.CreateTab = Window.AddTab

-- Accepts a Tab, its index, or its title.
function Window:SelectTab(target)
	local tab = target
	if type(target) == "number" then
		tab = self.Tabs[target]
	elseif type(target) == "string" then
		for _, candidate in self.Tabs do
			if candidate.Title == target then
				tab = candidate
			end
		end
	end
	if type(tab) ~= "table" or tab == self.SelectedTab then
		return
	end
	local previous = self.SelectedTab
	self.SelectedTab = tab
	if previous then
		previous:_setActive(false)
	end
	tab:_setActive(true)
	self:_slideToTab(tab, false)
end

--== Visibility ==--

function Window:SetVisible(visible: boolean)
	self.Visible = visible
	if self._loading then
		return -- applied when the loading screen finishes
	end
	local main = self.Instance
	if visible then
		main.Visible = true
		local target = self._uiScale.Scale
		self._uiScale.Scale = target * 0.94
		TweenService:Create(self._uiScale, Motion.Emphasized(Motion.Duration.Medium2), { Scale = target }):Play()

		if self._backdropEnabled and self._backdrop then
			self._backdrop.Visible = true
			TweenService:Create(self._backdrop, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				BackgroundTransparency = self._backdropTransparency,
			}):Play()
		end
		if self._snowEnabled and self._snowContainer then
			self._snowContainer.Visible = true
		end
		self:_updateCursorState(true)
	else
		main.Visible = false
		if self._backdrop then
			local tw = TweenService:Create(self._backdrop, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
				BackgroundTransparency = 1,
			})
			tw:Play()
			tw.Completed:Connect(function()
				if not self.Visible and self._backdrop then
					self._backdrop.Visible = false
				end
			end)
		end
		if self._snowContainer then
			self._snowContainer.Visible = false
		end
		self:_updateCursorState(false)
	end
end

function Window:_registerSearchable(item)
	table.insert(self._searchableItems, item)
end

function Window:AddSearchableSetting(item)
	self:_registerSearchable(item)
end

function Window:SetBackdrop(enabled: boolean, transparency: number?)
	self._backdropEnabled = enabled
	if transparency then
		self._backdropTransparency = transparency
	end
	if self._backdrop then
		if enabled and self.Visible and not self.Minimized then
			self._backdrop.Visible = true
			TweenService:Create(self._backdrop, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				BackgroundTransparency = self._backdropTransparency,
			}):Play()
		else
			self._backdrop.Visible = false
		end
	end
end

function Window:SetSnowfall(enabled: boolean, count: number?, speed: number?, size: number?)
	self._snowEnabled = enabled
	if count and self._snowSettings then
		self._snowSettings.Count = count
		while #self._snowflakes < count do
			table.insert(self._snowflakes, self._createFlake(#self._snowflakes + 1))
		end
		while #self._snowflakes > count do
			local f = table.remove(self._snowflakes)
			if f and f.inst then f.inst:Destroy() end
		end
	end
	if speed and self._snowSettings then self._snowSettings.SpeedMultiplier = speed end
	if size and self._snowSettings then
		self._snowSettings.BaseSize = size
		for _, f in ipairs(self._snowflakes) do
			local curSize = math.clamp(math.round(size * (f.sizeRatio or 1)), 2, 30)
			f.inst.Size = UDim2.fromOffset(curSize, curSize)
		end
	end
	if self._snowContainer then
		self._snowContainer.Visible = enabled and self.Visible and not self.Minimized
	end
end

function Window:SetCustomCursor(enabled: boolean, scale: number?)
	if self._cursorSettings then
		self._cursorSettings.Enabled = enabled
		if scale then
			self._cursorSettings.Scale = scale
			if self._cursorScale then
				self._cursorScale.Scale = scale / 100
			end
		end
	end
	self:_updateCursorState(self.Visible and not self.Minimized)
end

function Window:_updateCursorState(open: boolean)
	if open then
		pcall(function()
			UserInputService.MouseBehavior = Enum.MouseBehavior.Default
		end)
		if self._cursorSettings and self._cursorSettings.Enabled then
			UserInputService.MouseIconEnabled = false
			if self._cursorContainer then self._cursorContainer.Visible = true end
		else
			if self._cursorContainer then self._cursorContainer.Visible = false end
			UserInputService.MouseIconEnabled = true
		end
	else
		if self._cursorContainer then self._cursorContainer.Visible = false end
		UserInputService.MouseIconEnabled = true
	end
end

function Window:SetScale(scale: number)
	if self._uiScale then
		self._uiScale.Scale = scale
	end
end

function Window:GetScale(): number
	return self._uiScale and self._uiScale.Scale or 1
end

function Window:SetTransparency(transparency: number)
	if self.Instance then
		self.Instance.BackgroundTransparency = transparency
	end
	if self._pages then
		self._pages.BackgroundTransparency = math.clamp(transparency + 0.1, 0, 1)
	end
end

function Window:GetTransparency(): number
	return self.Instance and self.Instance.BackgroundTransparency or 0
end

function Window:Toggle()
	self:SetVisible(not self.Visible)
end

-- Whether keybind toasts are on for this window (off in Silent mode).
function Window:GetKeybindNotify(): boolean
	return self._keybindNotify and not self.Silent
end

function Window:SetKeybindNotify(enabled: boolean)
	self._keybindNotify = enabled
end

-- Ends the loading screen now (e.g. once your own setup is done).
function Window:SkipLoading()
	if self._loadingScreen then
		self._loadingScreen.Finish()
	end
end

-- The player's loading-screen preference, used from the next run on
-- (true unless turned off; always false when the script disabled it).
function Window:GetLoadingScreenEnabled(): boolean
	if not self._loadingAllowed then
		return false
	end
	return Env.ReadFile(`{self.\_configFolder}/loading.txt`) ~= "off"
end

function Window:SetLoadingScreenEnabled(enabled: boolean): boolean
	if not Env.CanUseFiles then
		return false
	end
	Env.MakeFolder(self._configFolder)
	return Env.WriteFile(`{self.\_configFolder}/loading.txt`, if enabled then "on" else "off")
end

function Window:Minimize(minimized: boolean?)
	if minimized == nil then
		minimized = not self.Minimized
	end
	self.Minimized = minimized
	local main = self.Instance
	local ti = Motion.Emphasized(Motion.Duration.Medium2)
	self._grip.Visible = not minimized

	local targetSize = if minimized
		then UDim2.new(self._size.X.Scale, self._size.X.Offset, 0, TOP_BAR_HEIGHT)
		else self._size
	-- `main` is anchored at its center, so resizing alone would collapse and
	-- expand around the middle. Shift the center by half the height change
	-- (in screen pixels, hence the UIScale) so the top bar stays put: the
	-- window folds up into its title bar and unfolds downward. Measured from
	-- the current size so an interrupted tween stays anchored too.
	local heightDelta = (targetSize.Y.Offset - main.Size.Y.Offset) * self._uiScale.Scale
	local position = main.Position
	local targetPosition = UDim2.new(position.X.Scale, position.X.Offset, position.Y.Scale, position.Y.Offset + heightDelta / 2)

	if not minimized then
		self._body.Visible = true
	end
	local tween = TweenService:Create(main, ti, { Size = targetSize, Position = targetPosition })
	tween:Play()
	if minimized then
		tween.Completed:Once(function()
			if self.Minimized then
				self._body.Visible = false
			end
		end)
	end
end

-- Switches the Material icon style ("Outlined" | "Filled" | "Round" |
-- "Sharp") live; every icon already on screen is redrawn. Returns the style
-- actually shown afterwards (unchanged if loading failed) and the error.
function Window:SetIconStyle(style: string): (string?, string?)
	local ok, err = IconImages.Load(style)
	if not ok then
		return IconImages.CurrentStyle, err
	end
	return IconImages.CurrentStyle
end

-- Resizes the window (unscaled pixels; the resize handle does the same).
-- Accepts a UDim2 offset size or width, height numbers.
function Window:SetSize(width, height: number?)
	if type(width) ~= "number" then -- a UDim2
		width, height = width.X.Offset, width.Y.Offset
	end
	self._size = UDim2.fromOffset(math.max(width, MIN_SIZE.X), math.max(height, MIN_SIZE.Y))
	if not self.Minimized then
		self.Instance.Size = self._size
	end
	self:_saveSize()
end

function Window:GetSize(): UDim2
	return self._size
end

-- Back to the size given in CreateWindow (or the default).
function Window:ResetSize()
	self:SetSize(self._defaultSize)
end

function Window:_sizePath(): string
	return `{self.\_configFolder}/window.json`
end

function Window:_saveSize()
	if not (self._rememberSize and Env.CanUseFiles) then
		return
	end
	Env.MakeFolder(self._configFolder)
	Env.WriteFile(self:_sizePath(), HttpService:JSONEncode({
		Width = self._size.X.Offset,
		Height = self._size.Y.Offset,
	}))
end

function Window:_readSavedSize(): Vector2?
	local json = Env.ReadFile(self:_sizePath())
	if not json then
		return nil
	end
	local ok, data = pcall(HttpService.JSONDecode, HttpService, json)
	if ok and type(data) == "table" and type(data.Width) == "number" and type(data.Height) == "number" then
		return Vector2.new(math.max(data.Width, MIN_SIZE.X), math.max(data.Height, MIN_SIZE.Y))
	end
	return nil
end

function Window:SetToggleKey(key)
	self._toggleKey = toKeyCode(key)
end

function Window:SetTitle(text: string)
	self.Title = text
	self._titleLabel.Text = text
end

function Window:SetSubtitle(text: string?)
	self._subtitleLabel.Text = text or ""
	self._subtitleLabel.Visible = (text or "") ~= ""
end

--== Feedback ==--

-- Notify({ Title, Content, Icon = "info", Duration = 5 })
function Window:Notify(props)
	return self._notifier:Notify(props)
end

-- Dialog({ Title, Content, Buttons = { { Title, Variant = "Filled", Callback } } })
function Window:Dialog(props)
	local actions = {}
	for _, button in props.Buttons or props.Actions or { { Title = "OK", Variant = "Filled" } } do
		table.insert(actions, {
			Text = button.Title or button.Text or "OK",
			Variant = button.Variant or "Text",
			OnActivated = button.Callback and function()
				self:_call(button.Callback)
			end,
		})
	end
	local dialog = Dialog.new({
		Parent = self.Instance,
		Title = props.Title or "",
		Text = props.Content or props.Text or "",
		Actions = actions,
		Theme = self.Theme,
		ZIndex = 100,
	})
	Shape.Corner(Shape.Large, dialog.Instance)
	dialog.Dismissed:Connect(function()
		dialog:Destroy()
	end)
	dialog:Show()
	return dialog
end

--== HUD (stays on screen while the window is hidden; see HUD.lua) ==--

-- AddWatermark({ Title, Icon, Position = "TopLeft", FPS, Ping, Clock })
function Window:AddWatermark(props)
	return HUD.Watermark(self, props)
end

-- AddKeybindList({ Title = "Keybinds", Position = "Left", ShowAll = false })
function Window:AddKeybindList(props)
	return HUD.KeybindList(self, props)
end

-- AddIndicator({ Text, Icon, Color = "Primary" })
function Window:AddIndicator(props)
	return HUD.Indicator(self, props)
end

function Window:SetHUDVisible(visible: boolean)
	HUD.Layer(self).Visible = visible
end

-- HUD transparency (0 = solid, 1 = invisible), separate from the window's:
-- `background` for fills and outlines, `text` for text and icons. nil leaves
-- that part as it is. Stored as the theme's HUDBackground / HUDText
-- transparency, so it's saved in configs and theme exports.
function Window:SetHUDTransparency(background: number?, text: number?)
	local transparency = self.Theme:GetTransparencies()
	if background ~= nil then
		transparency.HUDBackground = background
	end
	if text ~= nil then
		transparency.HUDText = text
	end
	self.Theme:SetOverrides(self.Theme:GetOverrides(), transparency)
end

function Window:GetHUDTransparency(): (number, number)
	return self.Theme:GetTransparency("HUDBackground") or 0, self.Theme:GetTransparency("HUDText") or 0
end

--== Custom background ==--

-- Background behind the whole window: an image (PNG / JPG) or a WebM video
-- (looping, muted), as a URL, rbxassetid://, asset id or workspace file;
-- nil or "" removes it. `transparency` (0-1, optional) also sets how much of
-- the window color shows through. `kind` ("Image" | "Video") is only needed
-- for a Roblox video asset id; otherwise a .webm is played as a video.
-- If it can't be loaded (e.g. a GIF, which Roblox can't show) the current
-- background is kept and this returns false plus the reason.
function Window:SetBackground(source: string?, transparency: number?, kind: string?): (boolean, string?)
	if transparency ~= nil then
		self:SetBackgroundTransparency(transparency)
	end
	local image, video = self._background, self._backgroundVideo
	if source == nil or source == "" then
		self._backgroundSource, self._backgroundKind = nil, nil
		image.Image = ""
		image.Visible = false
		self._backgroundGroup.Visible = false
		video.Playing = false
		video.Video = ""
		video.Visible = false
	else
		local isVideo = if kind then kind == "Video" else isVideoSource(source)
		local content, problem = Assets.ResolveWithReason(source, if isVideo then "video" else "image")
		if content == "" then
			return false, problem or `could not load {source}`
		end
		self._backgroundSource = source
		self._backgroundKind = if isVideo then "Video" else "Image"
		image.Image = if isVideo then "" else content
		image.Visible = not isVideo
		self._backgroundGroup.Visible = not isVideo
		video.Video = if isVideo then content else ""
		video.Visible = isVideo
		video.Playing = isVideo and self.Instance.Visible
		if isVideo then
			self:_checkBackgroundVideo(source)
		end
	end
	self:_layoutBackgroundBlur()
	self:_syncBackgroundControls()
	return true
end

-- A video can download fine and still be refused by Roblox (some executors'
-- getcustomasset can't serve local videos, e.g. on mobile). Ask
-- ContentProvider in the background; if it fails, drop the video and say why.
function Window:_checkBackgroundVideo(source: string)
	local video = self._backgroundVideo
	task.spawn(function()
		local failed = false
		pcall(function()
			ContentProvider:PreloadAsync({ video }, function(_, status)
				if status == Enum.AssetFetchStatus.Failure then
					failed = true
				end
			end)
		end)
		if not failed or self._destroyed or self._backgroundSource ~= source then
			return
		end
		self:SetBackground(nil)
		local reason = "Roblox couldn't play this WebM video here (this executor may not support local videos). Use a PNG / JPG image background instead."
		warn(`\[MD3] background: {reason}`)
		if not self.Silent then
			self:Notify({ Title = "Background unavailable", Content = reason, Icon = "error" })
		end
	end)
end

function Window:SetBackgroundTransparency(transparency: number)
	self._backgroundTransparency = math.clamp(transparency, 0, 1)
	self._backgroundGroup.GroupTransparency = self._backgroundTransparency
	self._backgroundVeil.BackgroundTransparency = 1 - self._backgroundTransparency
	self:_syncBackgroundControls()
end

-- Blurs a background image by `pixels` (0 = sharp, up to 24). Roblox has no
-- blur for UI, so this draws 13 offset copies of the image and averages
-- them; 0 keeps a single image. Video backgrounds aren't blurred (each copy
-- would decode the video again).
function Window:SetBackgroundBlur(pixels: number)
	self._backgroundBlur = math.clamp(pixels, 0, MAX_BACKGROUND_BLUR)
	self:_layoutBackgroundBlur()
	self:_syncBackgroundControls()
end

function Window:GetBackgroundBlur(): number
	return self._backgroundBlur
end

-- Makes the image copies match the blur amount and the current image.
function Window:_layoutBackgroundBlur()
	local layers = self._backgroundLayers
	local image = self._background
	local offsets = blurOffsets(if image.Image ~= "" then self._backgroundBlur else 0)
	for i = #layers, #offsets + 1, -1 do
		layers[i]:Destroy()
		layers[i] = nil
	end
	for i = #layers + 1, #offsets do
		layers[i] = Create("ImageLabel") {
			Name = `Blur{i}`,
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(0.5, 0.5),
			ScaleType = Enum.ScaleType.Crop,
			Parent = self._backgroundGroup,
		}
	end
	-- Copies are drawn a little bigger than the window so offsetting them
	-- never uncovers its edges; the group clips them to the window shape.
	local pad = math.ceil(if #offsets > 1 then self._backgroundBlur else 0)
	for i, layer in layers do
		local offset = offsets[i]
		layer.Position = UDim2.new(0.5, offset.X, 0.5, offset.Y)
		layer.Size = UDim2.new(1, pad * 2, 1, pad * 2)
		layer.ZIndex = i
		-- Layer i drawn over the ones below it at opacity 1/i gives every
		-- copy the same weight: an even average.
		layer.ImageTransparency = 1 - 1 / i
		if i > 1 then
			layer.Image = image.Image
		end
	end
end

-- The current background (as given to SetBackground, nil when none), its
-- transparency, and "Image" / "Video".
function Window:GetBackground(): (string?, number, string?)
	return self._backgroundSource, self._backgroundTransparency, self._backgroundKind
end

-- Keeps the settings tab's Background controls showing the real state.
function Window:_syncBackgroundControls()
	local controls = self._backgroundControls
	if not controls then
		return
	end
	local source = self._backgroundSource or ""
	if controls.Input.Value ~= source then
		controls.Input:Set(source, true)
	end
	local percent = math.round(self._backgroundTransparency * 100)
	if controls.Slider.Value ~= percent then
		controls.Slider:Set(percent, true)
	end
	if controls.Blur.Value ~= self._backgroundBlur then
		controls.Blur:Set(self._backgroundBlur, true)
	end
end

--== Configs ==--

function Window:CanSaveConfigs(): boolean
	return Env.CanUseFiles
end

function Window:_configPath(name: string): string
	return `{self.\_configFolder}/configs/{sanitize(name)}.json`
end

function Window:SaveConfig(name: string?): (boolean, string?)
	if not Env.CanUseFiles then
		return false, "this executor has no file functions"
	end
	name = name or "default"
	Env.MakeFolder(`{self.\_configFolder}/configs`)
	local ok = Env.WriteFile(self:_configPath(name), Config.Encode(self.Flags))
	return ok, (not ok) and "writefile failed" or nil
end

function Window:LoadConfig(name: string?): (boolean, string?)
	name = name or "default"
	local json = Env.ReadFile(self:_configPath(name))
	if not json then
		return false, `config "{name}" not found`
	end
	local data = Config.Decode(json)
	if not data then
		return false, `config "{name}" is corrupted`
	end
	for flag, value in data do
		local element = self.Flags[flag]
		if element then
			local ok, err = pcall(element.Set, element, value)
			if not ok then
				warn(`\[MD3] could not load flag {flag}: {err}`)
			end
		end
	end
	return true
end

function Window:DeleteConfig(name: string): boolean
	return Env.DeleteFile(self:_configPath(name))
end

function Window:ListConfigs(): { string }
	local names = {}
	for _, path in Env.ListFiles(`{self.\_configFolder}/configs`) do
		local name = tostring(path):match("([^/\\]+)%.json$")
		if name then
			table.insert(names, name)
		end
	end
	table.sort(names)
	return names
end

function Window:SetAutoLoad(name: string?)
	local path = `{self.\_configFolder}/autoload.txt`
	if name then
		Env.MakeFolder(self._configFolder)
		Env.WriteFile(path, sanitize(name))
	else
		Env.DeleteFile(path)
	end
end

function Window:GetAutoLoad(): string?
	local name = Env.ReadFile(`{self.\_configFolder}/autoload.txt`)
	return name ~= "" and name or nil
end

-- Call once at the end of your script, after every flagged element exists.
function Window:LoadAutoloadConfig(): boolean
	local name = self:GetAutoLoad()
	if not name then
		return false
	end
	local ok, err = self:LoadConfig(name)
	if ok then
		if not self.Silent then
			self:Notify({ Title = "Config loaded", Content = `Auto-loaded "{name}"`, Icon = "folder" })
		end
	else
		warn(`\[MD3] autoload failed: {err}`)
	end
	return ok
end
Window.LoadConfiguration = Window.LoadAutoloadConfig

--== Built-in settings tab ==--

-- Theme mode, accent color, toggle key, unload and (when the executor has
-- file functions) config save/load/delete/autoload.
function Window:AddSettingsTab(props)
	props = props or {}
	local tab = self:AddTab({ Title = props.Title or "Settings", Icon = props.Icon or "settings" })

	local appearance = tab:AddSection("Appearance")
	local darkMode = appearance:AddToggle({
		Title = "Dark mode",
		Default = self.Theme.Mode == "Dark",
		Flag = "MD3_DarkMode",
		Callback = function(on)
			self.Theme:SetMode(on and "Dark" or "Light")
		end,
	})
	local accent = appearance:AddColorPicker({
		Title = "Theme color",
		Description = "The whole palette is generated from this color",
		Default = self.Theme.Seed,
		Flag = "MD3_Accent",
		Callback = function(color)
			self.Theme:SetSeedColor(color)
		end,
	})

	-- Icon and text color: overrides (saved with the theme editor's
	-- MD3_ThemeOverrides flag), shown as the current color when not custom.
	local quick = {
		{ Role = "Icon", Title = "Icon color", Auto = "Follows the text color" },
		{ Role = "OnSurface", Title = "Text color", Auto = "Generated from the theme color" },
	}
	local quickPickers = {}
	local editingQuick = nil
	for _, entry in quick do
		quickPickers[entry.Role] = appearance:AddColorPicker({
			Title = entry.Title,
			Default = self.Theme.Colors[entry.Role],
			Transparency = self.Theme:GetTransparency(entry.Role) or 0,
			Callback = function(color, transparency)
				editingQuick = entry.Role
				self.Theme:SetOverride(entry.Role, color, transparency)
				editingQuick = nil
			end,
		})
	end
	appearance:AddButton({
		Title = "Reset icon & text colors",
		Icon = "refresh",
		Callback = function()
			local overrides, transparency = self.Theme:GetOverrides(), self.Theme:GetTransparencies()
			for _, entry in quick do
				overrides[entry.Role], transparency[entry.Role] = nil, nil
			end
			self.Theme:SetOverrides(overrides, transparency)
		end,
	})
	local function refreshQuick()
		for _, entry in quick do
			local picker = quickPickers[entry.Role]
			local color = self.Theme.Colors[entry.Role]
			local transparency = self.Theme:GetTransparency(entry.Role) or 0
			if editingQuick ~= entry.Role and (picker.Value ~= color or picker.Transparency ~= transparency) then
				picker:Set({ Color = color, Transparency = transparency }, true)
			end
			picker:SetDescription(if self.Theme:IsOverridden(entry.Role) then "Custom" else entry.Auto)
		end
	end
	refreshQuick()
	self._maid:GiveTask(self.Theme.Changed:Connect(refreshQuick))

	-- Icon style needs file functions + getcustomasset to load the images.
	if Env.CanUseCustomAssets then
		local iconStyle
		iconStyle = appearance:AddDropdown({
			Title = "Icon style",
			Description = "Material Icons: Outlined is the M3 default",
			Options = IconImages.StyleNames,
			Default = IconImages.CurrentStyle or IconImages.DefaultStyle,
			Flag = "MD3_IconStyle",
			Callback = function(style)
				if not style then
					return
				end
				local current, err = self:SetIconStyle(style)
				if current ~= style then
					-- Show what's really on screen (the previous style, if any).
					iconStyle:Set(current, true)
					self:Notify({ Title = "Icon style unavailable", Content = err or "", Icon = "error" })
				end
			end,
		})
	end

	-- Keep these two in sync when the theme changes elsewhere (theme editor
	-- presets, imports, config loads).
	self._maid:GiveTask(self.Theme.Changed:Connect(function(theme)
		if darkMode.Value ~= (theme.Mode == "Dark") then
			darkMode:Set(theme.Mode == "Dark", true)
		end
		if accent.Value ~= theme.Seed then
			accent:Set(theme.Seed, true)
		end
	end))

	-- Custom background (saved in configs as MD3_Background / MD3_BackgroundTransparency).
	local backgroundSection = tab:AddSection("Background")
	local backgroundInput
	backgroundInput = backgroundSection:AddInput({
		Title = "Background image",
		Description = "PNG / JPG image or WebM video: URL, rbxassetid:// or asset id. GIF isn't supported by Roblox (convert it to WebM). To see it behind the content too, make Content panel / Rows see-through in the theme editor",
		Placeholder = "https://... .png / .jpg / .webm",
		Default = self._backgroundSource or "",
		Flag = "MD3_Background",
		Callback = function(text)
			local ok, err = self:SetBackground(text)
			if not ok then
				self:Notify({ Title = "Background unavailable", Content = err or "", Icon = "error" })
				backgroundInput:Set(self._backgroundSource or "", true)
			end
		end,
	})
	local backgroundSlider = backgroundSection:AddSlider({
		Title = "Image transparency",
		Description = "How much of the window color shows through",
		Min = 0,
		Max = 100,
		Step = 1,
		Suffix = "%",
		Default = math.round(self._backgroundTransparency * 100),
		Flag = "MD3_BackgroundTransparency",
		Callback = function(percent)
			self:SetBackgroundTransparency(percent / 100)
		end,
	})
	local backgroundBlur = backgroundSection:AddSlider({
		Title = "Image blur",
		Description = "Softens a background image (not videos)",
		Min = 0,
		Max = MAX_BACKGROUND_BLUR,
		Step = 1,
		Suffix = " px",
		Default = self._backgroundBlur,
		Flag = "MD3_BackgroundBlur",
		Callback = function(pixels)
			self:SetBackgroundBlur(pixels)
		end,
	})
	backgroundSection:AddButton({
		Title = "Remove background",
		Icon = "delete",
		Callback = function()
			self:SetBackground(nil)
		end,
	})
	self._backgroundControls = { Input = backgroundInput, Slider = backgroundSlider, Blur = backgroundBlur }

	self:AddThemeEditor(tab)

	local interface = tab:AddSection("Interface")
	interface:AddKeybind({
		Title = "Toggle UI",
		Description = "Shows / hides this window",
		Default = self._toggleKey,
		Flag = "MD3_ToggleKey",
		Notify = false, -- the window toggle key never shows a toast
		ChangedCallback = function(key)
			self:SetToggleKey(key)
		end,
	})
	-- A startup setting, so it's stored outside configs (which load later).
	if self._loadingAllowed and Env.CanUseFiles then
		interface:AddToggle({
			Title = "Loading animation",
			Description = "Plays when the script starts (from the next run)",
			Default = self:GetLoadingScreenEnabled(),
			Callback = function(on)
				self:SetLoadingScreenEnabled(on)
			end,
		})
	end
	interface:AddButton({
		Title = "Reset window size",
		Description = "Drag the bottom-right corner to resize",
		Icon = "fullscreen_exit",
		Callback = function()
			self:ResetSize()
		end,
	})
	interface:AddButton({
		Title = "Unload",
		Description = "Destroys this UI",
		Icon = "close",
		Callback = function()
			self:Destroy()
		end,
	})

	-- Only when the script built some HUD before adding the settings tab.
	if self._hudLayer then
		local hud = tab:AddSection("HUD")
		hud:AddToggle({
			Title = "Show HUD",
			Description = "Watermark, keybind list and indicators",
			Default = self._hudLayer.Visible,
			Flag = "MD3_ShowHUD",
			Callback = function(on)
				self:SetHUDVisible(on)
			end,
		})
		-- Transparency lives in the theme (saved with MD3_ThemeOverrides), so
		-- these sliders have no Flag and just mirror it.
		local sliders = {
			{ Role = "HUDBackground", Title = "Background transparency", Description = "Separate from the window's" },
			{ Role = "HUDText", Title = "Text transparency", Description = "Text and icons" },
		}
		local editing = nil
		for _, entry in sliders do
			entry.Slider = hud:AddSlider({
				Title = entry.Title,
				Description = entry.Description,
				Min = 0,
				Max = 100,
				Step = 1,
				Suffix = "%",
				Default = math.round((self.Theme:GetTransparency(entry.Role) or 0) * 100),
				Callback = function(percent)
					editing = entry.Role
					if entry.Role == "HUDBackground" then
						self:SetHUDTransparency(percent / 100, nil)
					else
						self:SetHUDTransparency(nil, percent / 100)
					end
					editing = nil
				end,
			})
		end
		self._maid:GiveTask(self.Theme.Changed:Connect(function()
			for _, entry in sliders do
				local percent = math.round((self.Theme:GetTransparency(entry.Role) or 0) * 100)
				if entry.Role ~= editing and entry.Slider.Value ~= percent then
					entry.Slider:Set(percent, true)
				end
			end
		end))
	end

	if self:CanSaveConfigs() then
		local configs = tab:AddSection("Configuration")
		local nameInput = configs:AddInput({ Title = "Config name", Placeholder = "default" })
		local list = configs:AddDropdown({ Title = "Saved configs", Options = self:ListConfigs() })

		local function selectedName()
			if nameInput.Value ~= "" then
				return nameInput.Value
			end
			return list.Value or "default"
		end
		local function refresh()
			list:SetOptions(self:ListConfigs())
		end

		configs:AddButton({
			Title = "Save config",
			Icon = "save",
			Callback = function()
				local name = selectedName()
				local ok, err = self:SaveConfig(name)
				refresh()
				list:Set(name, true)
				self:Notify({ Title = ok and "Config saved" or "Save failed", Content = ok and name or err, Icon = ok and "save" or "error" })
			end,
		})
		configs:AddButton({
			Title = "Load config",
			Icon = "folder",
			Callback = function()
				local name = selectedName()
				local ok, err = self:LoadConfig(name)
				self:Notify({ Title = ok and "Config loaded" or "Load failed", Content = ok and name or err, Icon = ok and "folder" or "error" })
			end,
		})
		configs:AddButton({
			Title = "Delete config",
			Icon = "delete",
			Callback = function()
				local name = selectedName()
				self:DeleteConfig(name)
				refresh()
				self:Notify({ Title = "Config deleted", Content = name, Icon = "delete" })
			end,
		})
		local autoload
		autoload = configs:AddButton({
			Title = "Set as autoload",
			Description = `Current: {self:GetAutoLoad() or "none"}`,
			Icon = "bolt",
			Callback = function()
				local name = selectedName()
				self:SetAutoLoad(name)
				autoload:SetDescription(`Current: {name}`)
				self:Notify({ Title = "Autoload set", Content = name, Icon = "bolt" })
			end,
		})
		configs:AddButton({
			Title = "Clear autoload",
			Icon = "block",
			Callback = function()
				self:SetAutoLoad(nil)
				autoload:SetDescription("Current: none")
			end,
		})
	end

	return tab
end

--== Theme editor ==--

-- Adds a theme editor to `container` (a Tab or Section; default: a new
-- "Theme" tab): palette presets, a color picker for each editable color
-- role (Theme.EditableRoles, icon colors included), reset, and copy /
-- import as JSON. Custom colors are theme overrides on top of the seed
-- palette, saved in configs under the flag MD3_ThemeOverrides.
function Window:AddThemeEditor(container)
	local theme = self.Theme
	container = container or self:AddTab({ Title = "Theme", Icon = "palette" })
	local section = if container.AddSection then container:AddSection("Theme editor") else container

	local presetNames = {}
	for _, preset in Theme.Presets do
		table.insert(presetNames, preset.Name)
	end
	section:AddDropdown({
		Title = "Preset",
		Description = "Palette to start from. Custom colors below are kept; NeverLose also sets its own dark colors",
		Options = presetNames,
		Callback = function(name)
			if name then
				theme:ApplyPreset(name)
			end
		end,
	})

	-- One picker per color role. `editing` stops the picker being dragged
	-- from being reset by the Changed event its own edit causes.
	local pickers = {}
	local editing = nil
	for _, entry in Theme.EditableRoles do
		local role = entry.Role
		pickers[role] = section:AddColorPicker({
			Title = entry.Name,
			Description = role,
			Default = theme.Colors[role],
			Transparency = theme:GetTransparency(role) or 0,
			Callback = function(color, transparency)
				editing = role
				theme:SetOverride(role, color, transparency)
				editing = nil
			end,
		})
	end

	local function refresh()
		for role, picker in pickers do
			local color = theme.Colors[role]
			local transparency = theme:GetTransparency(role) or 0
			if role ~= editing and (picker.Value ~= color or picker.Transparency ~= transparency) then
				picker:Set({ Color = color, Transparency = transparency }, true)
			end
			picker:SetDescription(if theme:IsOverridden(role) then `{role} · custom` else role)
		end
	end
	refresh()
	self._maid:GiveTask(theme.Changed:Connect(refresh))

	section:AddButton({
		Title = "Reset custom colors",
		Description = "Back to the colors generated from the accent color",
		Icon = "refresh",
		Callback = function()
			theme:ClearOverrides()
			self:Notify({ Title = "Custom colors cleared", Icon = "refresh", Duration = 3 })
		end,
	})
	section:AddButton({
		Title = "Copy theme",
		Description = "Copies the theme as JSON to share or back up",
		Icon = "content_copy",
		Callback = function()
			local json = HttpService:JSONEncode(theme:Export())
			if Env.SetClipboard(json) then
				self:Notify({ Title = "Theme copied", Icon = "content_copy", Duration = 3 })
			else
				self:Notify({ Title = "Clipboard unavailable", Content = json, Icon = "error", Duration = 10 })
			end
		end,
	})
	section:AddInput({
		Title = "Import theme",
		Placeholder = "Paste theme JSON",
		ClearOnSubmit = true,
		Callback = function(text)
			if text == "" then
				return
			end
			local ok, data = pcall(HttpService.JSONDecode, HttpService, text)
			local imported = ok and pcall(theme.Import, theme, data)
			self:Notify({
				Title = if imported then "Theme imported" else "Invalid theme JSON",
				Icon = if imported then "palette" else "error",
				Duration = 3,
			})
		end,
	})

	-- Overrides go into configs as one flag (saving every picker would pin
	-- generated colors too and stop them following the accent color).
	-- Value: { Colors = { [role] = Color3 }, Transparency = { [role] = number } }
	local function current()
		return { Colors = theme:GetOverrides(), Transparency = theme:GetTransparencies(), Follow = theme:GetFollow() }
	end
	local overridesFlag = { Type = "ThemeOverrides", Flag = "MD3_ThemeOverrides", Value = current() }
	function overridesFlag:Set(value)
		if type(value) ~= "table" then
			theme:ClearOverrides()
		elseif value.Colors or value.Transparency then
			theme:SetOverrides(value.Colors or {}, value.Transparency or {}, value.Follow or {})
		else
			theme:SetOverrides(value, {}) -- configs saved before transparency existed
		end
	end
	function overridesFlag:Get()
		return current()
	end
	function overridesFlag:Destroy() end
	self.Flags.MD3_ThemeOverrides = overridesFlag
	self._maid:GiveTask(theme.Changed:Connect(function()
		overridesFlag.Value = current()
	end))

	return section
end

--== Teardown ==--

function Window:Destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	self.OnUnload:Fire()
	for _, tab in self.Tabs do
		pcall(tab.Destroy, tab)
	end
	self._maid:Destroy()
	self._themer:Destroy()
	Elevation.Remove(self.Instance)
	self.Gui:Destroy()

	local registry = Env.Registry()
	if registry.Windows and registry.Windows[self._registryKey] == self then
		registry.Windows[self._registryKey] = nil
	end

	pcall(function()
		UserInputService.MouseIconEnabled = true
		UserInputService.MouseBehavior = Enum.MouseBehavior.Default
	end)
end
Window.Unload = Window.Destroy

return Window
end

-- init.lua
loaders[N_root] = function(script, require)
--[[
	MD3 ??a Material Design 3 UI library for Roblox Luau.

	Executors:
		local MD3 = loadstring(game:HttpGet(
			"https://raw.githubusercontent.com/engnyg/Material-Design-3-Roblox-lua-ui/main/dist/MaterialDesign3.luau"
		))()
		local Window = MD3:CreateWindow({ Title = "My Hub" })
		local Main = Window:AddTab({ Title = "Main", Icon = "home" })
		Main:AddToggle({ Title = "Auto farm", Flag = "AutoFarm", Callback = function(on) end })

		See examples/executor.lua for every element.

	Components directly (Studio / your own game):
		local MD3 = require(path.to.MaterialDesign3)

		-- optional: recolor the whole app from one seed color (mutates the
		-- shared default theme, so every already-built component updates live)
		MD3.Theme.Default():SetSeedColor(Color3.fromHex("#006C51"))
		MD3.Theme.Default():SetMode("Dark")

		local button = MD3.Button.new({ Text = "Continue", Parent = someFrame })
		button.Activated:Connect(function() print("clicked") end)

	See example/init.client.lua for a fuller demo.
]]
local MD3 = {}

-- Core
MD3.Theme = require(script.Core.Theme)
MD3.Typography = require(script.Core.Typography)
MD3.Shape = require(script.Core.Shape)
MD3.Motion = require(script.Core.Motion)
MD3.Elevation = require(script.Core.Elevation)
MD3.StateLayer = require(script.Core.StateLayer)
MD3.Ripple = require(script.Core.Ripple)
MD3.Icons = require(script.Core.Icons)
MD3.IconSheet = require(script.Core.IconSheet)

-- Utilities (exposed in case consumers want to build custom components the same way)
MD3.Color = require(script.Util.Color)
MD3.Signal = require(script.Util.Signal)
MD3.Maid = require(script.Util.Maid)
MD3.Create = require(script.Util.Create)

-- Components
MD3.Button = require(script.Components.Button)
MD3.IconButton = require(script.Components.IconButton)
MD3.FAB = require(script.Components.FAB)
MD3.Card = require(script.Components.Card)
MD3.Switch = require(script.Components.Switch)
MD3.Checkbox = require(script.Components.Checkbox)
MD3.RadioButton = require(script.Components.RadioButton)
MD3.Slider = require(script.Components.Slider)
MD3.TextField = require(script.Components.TextField)
MD3.Chip = require(script.Components.Chip)
MD3.Dialog = require(script.Components.Dialog)
MD3.Snackbar = require(script.Components.Snackbar)
MD3.TopAppBar = require(script.Components.TopAppBar)
MD3.NavigationBar = require(script.Components.NavigationBar)
MD3.ProgressIndicator = require(script.Components.ProgressIndicator)
MD3.Divider = require(script.Components.Divider)

-- Executor layer
MD3.Env = require(script.Executor.Env)
MD3.IconFont = require(script.Executor.IconFont)
MD3.Assets = require(script.Executor.Assets)
MD3.IconImages = require(script.Executor.IconImages)
MD3.Window = require(script.Window.Window)

-- Creates an executor-style window. Works as MD3:CreateWindow{...} or
-- MD3.CreateWindow{...}.
function MD3.CreateWindow(selfOrProps, maybeProps)
	local props = if selfOrProps == MD3 then maybeProps else selfOrProps
	return MD3.Window.new(props)
end

-- The open window with this Title (or Id), also from another script:
--   local Window = MD3:GetWindow("My Hub")
-- (windows are registered in getgenv(), which every script shares). nil if none.
function MD3.GetWindow(selfOrKey, maybeKey)
	local key = if selfOrKey == MD3 then maybeKey else selfOrKey
	local windows = MD3.Env.Registry().Windows
	return windows and windows[key] or nil
end

-- Shorthand for MD3.Theme.new(seed, mode)
function MD3.new(seed: Color3?, mode: string?)
	return MD3.Theme.new(seed, mode)
end

return MD3
end

return bundleRequire(N_root)
